import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { Track, AudioClip, PlaybackState } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [] },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [] },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [] },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [] },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true
};

function App() {
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);
  const [bpm, setBpm] = useState<number>(120);
  const [recordingTrackId, setRecordingTrackId] = useState<string | null>(null);

  // Selection & Clipboard
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);

  // Track Editor
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      // We also need to apply plugins on load if we had persistence
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    // Hard Stop
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (recordingTrackId) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [recordingTrackId]);

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));

      if (playbackState.isPlaying) {
          startPlayback(time);
      }
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const finishRecording = async () => {
      if (!recordingTrackId) return;

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: recordingTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              setClips(prev => [...prev, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setRecordingTrackId(null);
  };

  const handleRecordToggle = async (trackId: string) => {
      if (recordingTrackId === trackId) {
          await handleStop();
          return;
      }
      if (recordingTrackId) return;

      try {
          await audioService.resume();
          await audioService.startRecording();
          setRecordingTrackId(trackId);
          recordStartTimeRef.current = pauseTimeRef.current;

          if (!playbackState.isPlaying) {
              startPlayback(pauseTimeRef.current);
          }
      } catch (e) {
          alert("Could not start recording. Please allow microphone access.");
      }
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, // -1 because Master is there, but close enough
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: []
    };
    // Insert before Master
    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    setTracks(newTracks);
    audioService.createTrackNodes(newTrack.id);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    setTracks(prev => prev.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    }));
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    setTracks(tracks.filter(t => t.id !== id));
    setClips(clips.filter(c => c.trackId !== id));
    if (editingTrackId === id) setEditingTrackId(null);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      setClips(prev => [...prev, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    setClips(prev => prev.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    ));
    if (playbackState.isPlaying) {
        startPlayback(playbackState.currentTime);
    }
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      setClips(prev => prev.map(c => c.id === id ? { ...c, ...updates } : c));
      if (playbackState.isPlaying) {
         startPlayback(playbackState.currentTime); 
      }
  };

  const deleteClip = (id: string) => {
      setClips(clips.filter(c => c.id !== id));
      if (selectedClipId === id) setSelectedClipId(null);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      setClips(prev => [...prev, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      setClips(prev => prev.map(c => c.id === id ? { ...c, name: newName } : c));
  };

  // --- Clipboard ---

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      setClips(prev => [...prev, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) updateClipProps(id, { loop: !clip.loop });
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* Track Headers */}
        <div 
            className="flex-shrink-0 bg-gray-900 border-r border-gray-700 overflow-y-auto custom-scrollbar z-10 shadow-xl"
            style={{ width: TRACK_HEADER_WIDTH, paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
        >
          {tracks.map(track => (
            <TrackControl 
              key={track.id} 
              track={track} 
              onUpdate={updateTrack}
              onDelete={deleteTrack}
              isRecording={recordingTrackId === track.id}
              onRecordToggle={handleRecordToggle}
              onOpenEditor={setEditingTrackId}
            />
          ))}

          <div className="p-3">
             <button 
                onClick={addTrack}
                className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
             >
                <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors">
                    <Plus size={14} /> 
                </div>
                <span>Add New Track</span>
             </button>
          </div>
        </div>

        {/* Timeline Area */}
        <Timeline 
          tracks={tracks}
          clips={clips}
          currentTime={playbackState.currentTime}
          onClipUpdate={updateClip}
          onFileDrop={handleFileDrop}
          setClips={setClips}
          onSeek={handleSeek}
          bpm={bpm}
          onDeleteClip={deleteClip}
          onDuplicateClip={duplicateClip}
          onRenameClip={renameClip}

          onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
          selectedClipId={selectedClipId}
          onCopyClip={handleCopyClip}
          onPasteClip={handlePasteClip}
          canPaste={!!clipboardClip}
          onLoopClip={handleLoopToggle}
        />
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

export default App;

import React, { useState } from 'react';
import { Track, AudioPlugin, PluginType } from '../types';
import { X, Plus, Power, Trash2, Sliders } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

interface TrackEditorProps {
  track: Track;
  onUpdate: (trackId: string, updates: Partial<Track>) => void;
  onClose: () => void;
}

export const TrackEditor: React.FC<TrackEditorProps> = ({ track, onUpdate, onClose }) => {
  const [isAdding, setIsAdding] = useState(false);

  const addPlugin = (type: PluginType) => {
    const newPlugin: AudioPlugin = {
        id: uuidv4(),
        type,
        enabled: true,
        params: {}
    };

    // Set default params
    if (type === 'DISTORTION') newPlugin.params.drive = 50;
    if (type === 'DELAY') { newPlugin.params.time = 0.3; newPlugin.params.feedback = 0.5; }
    if (type === 'HIGHPASS') newPlugin.params.frequency = 200;
    if (type === 'LOWPASS') newPlugin.params.frequency = 2000;
    if (type === 'REVERB') newPlugin.params.decay = 2.0;

    onUpdate(track.id, { plugins: [...track.plugins, newPlugin] });
    setIsAdding(false);
  };

  const updatePluginParam = (pluginId: string, param: string, value: number) => {
    const newPlugins = track.plugins.map(p => {
        if (p.id === pluginId) {
            return { ...p, params: { ...p.params, [param]: value } };
        }
        return p;
    });
    onUpdate(track.id, { plugins: newPlugins });
  };

  const togglePlugin = (pluginId: string) => {
    const newPlugins = track.plugins.map(p => 
        p.id === pluginId ? { ...p, enabled: !p.enabled } : p
    );
    onUpdate(track.id, { plugins: newPlugins });
  };

  const removePlugin = (pluginId: string) => {
     onUpdate(track.id, { plugins: track.plugins.filter(p => p.id !== pluginId) });
  };

  return (
    <div className="h-64 bg-gray-900 border-t border-gray-700 flex flex-col shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.3)] z-40 animate-slide-up">
      <div className="flex items-center justify-between px-4 py-2 border-b border-gray-800 bg-gray-850">
        <div className="flex items-center gap-2">
            <span className="text-sm font-bold text-gray-200 uppercase tracking-wider">Track Editor:</span>
            <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full" style={{ backgroundColor: track.color || '#fff' }}></div>
                <span className="text-sm text-white font-medium">{track.name}</span>
            </div>
        </div>
        <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
          <X size={16} />
        </button>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Plugin List / Chain */}
        <div className="w-64 border-r border-gray-800 bg-gray-900/50 flex flex-col p-4 gap-2 overflow-y-auto">
             <div className="text-xs text-gray-500 font-bold uppercase mb-2">Signal Chain</div>

             {track.plugins.map((plugin, index) => (
                 <div key={plugin.id} className={`p-3 rounded-lg border flex flex-col gap-2 ${plugin.enabled ? 'bg-gray-800 border-gray-700' : 'bg-gray-900 border-gray-800 opacity-60'}`}>
                     <div className="flex items-center justify-between">
                         <span className="font-semibold text-xs text-blue-400">{index + 1}. {plugin.type}</span>
                         <div className="flex items-center gap-1">
                             <button onClick={() => togglePlugin(plugin.id)} className="p-1 hover:text-white text-gray-400">
                                <Power size={12} className={plugin.enabled ? "text-green-400" : ""} />
                             </button>
                             <button onClick={() => removePlugin(plugin.id)} className="p-1 hover:text-red-400 text-gray-500">
                                <Trash2 size={12} />
                             </button>
                         </div>
                     </div>

                     {/* Simplified Controls Render */}
                     {plugin.enabled && (
                         <div className="grid grid-cols-1 gap-2">
                             {Object.entries(plugin.params).map(([key, value]) => (
                                 <div key={key} className="flex flex-col gap-1">
                                     <div className="flex justify-between text-[10px] text-gray-400 uppercase">
                                         <span>{key}</span>
                                         <span>{(value as number).toFixed(1)}</span>
                                     </div>
                                     <input 
                                        type="range"
                                        min={key === 'frequency' ? 20 : 0}
                                        max={key === 'frequency' ? 10000 : (key === 'drive' ? 100 : 2)}
                                        step={key === 'frequency' ? 10 : 0.01}
                                        value={value as number}
                                        onChange={(e) => updatePluginParam(plugin.id, key, Number(e.target.value))}
                                        className="h-1 bg-gray-700 rounded-full appearance-none accent-blue-500"
                                     />
                                 </div>
                             ))}
                         </div>
                     )}
                 </div>
             ))}

             <div className="relative">
                 <button 
                    onClick={() => setIsAdding(!isAdding)}
                    className="w-full py-2 border border-dashed border-gray-700 rounded hover:border-blue-500 hover:text-blue-400 text-gray-500 text-xs flex items-center justify-center gap-1 transition-colors"
                 >
                    <Plus size={12} /> Add Effect
                 </button>

                 {isAdding && (
                     <div className="absolute top-full left-0 w-full mt-2 bg-gray-800 border border-gray-700 rounded-lg shadow-xl z-50 overflow-hidden">
                         {['DELAY', 'REVERB', 'DISTORTION', 'HIGHPASS', 'LOWPASS'].map(type => (
                             <button
                                key={type}
                                onClick={() => addPlugin(type as PluginType)}
                                className="w-full text-left px-4 py-2 text-xs hover:bg-gray-700 text-gray-300"
                             >
                                {type}
                             </button>
                         ))}
                     </div>
                 )}
             </div>
        </div>

        {/* Visualization Area (Placeholder for now) */}
        <div className="flex-1 bg-gray-950 flex items-center justify-center text-gray-700 flex-col gap-4">
            <Sliders size={48} />
            <p className="text-sm">Select an effect on the left to adjust parameters</p>
        </div>
      </div>
    </div>
  );
};

export interface Track {
  id: string;
  name: string;
  color: string;
  volume: number; // 0.0 to 1.0
  muted: boolean;
  soloed: boolean;
  plugins: AudioPlugin[];
  isMaster?: boolean;
}

export interface AudioClip {
  id: string;
  trackId: string;
  buffer: AudioBuffer;
  name: string;
  startTime: number; // Start time in seconds on the timeline
  duration: number; // Duration in seconds (affected by playbackRate conceptually, but buffer duration is constant)
  offset: number; // Start offset within the audio file

  // New properties
  gain: number; // 1.0 is default
  pan: number; // -1.0 (L) to 1.0 (R), 0 is center
  playbackRate: number; // 1.0 is normal speed
  loop: boolean;
}

export enum DragType {
  CLIP = 'CLIP',
  FILE = 'FILE'
}

export interface DragItem {
  type: DragType;
  id?: string; // If moving an existing clip
  files?: FileList; // If dropping external files
}

export interface PlaybackState {
  isPlaying: boolean;
  currentTime: number; // Current playback time in seconds
}

export type PluginType = 'DELAY' | 'REVERB' | 'DISTORTION' | 'HIGHPASS' | 'LOWPASS';

export interface AudioPlugin {
  id: string;
  type: PluginType;
  enabled: boolean;
  params: {
    [key: string]: number;
  };
}

export type ToolType = 'MOVE' | 'BLADE';

export interface HistoryState {
  tracks: Track[];
  clips: AudioClip[];
}

import { AudioClip, Track, AudioPlugin } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     // Clips connect here
  output: GainNode;    // Post-plugin, Pre-panner
  panner: StereoPannerNode;
  fader: GainNode;     // Volume control
  analyser: AnalyserNode; // For visual metering
  pluginNodes: AudioNode[]; 
}

class AudioEngine {
  private context: AudioContext;

  // Master Chain
  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  // Map clip ID to the chain of nodes
  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  // Recording
  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    // Setup Master Bus
    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;

    // Default Chain: Input -> Output -> Panner -> Fader -> Analyser -> MasterInput
    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [] 
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => n.disconnect());
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        return delay;
      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;
      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        return hp;
      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        return lp;
      case 'REVERB':
         const convolver = context.createConvolver();
         const duration = plugin.params.decay || 2.0;
         const decay = plugin.params.decay || 2.0;
         convolver.buffer = this.impulseResponse(context, duration, decay);
         return convolver;
      default:
        return context.createGain();
    }
  }

  // --- Chain Builders ---

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => n.disconnect());
    nodes.pluginNodes = [];

    let previousNode: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const node = this.createPluginNode(this.context, plugin);
        nodes.pluginNodes.push(node);
        previousNode.connect(node);
        previousNode = node;
    });

    previousNode.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => n.disconnect());
      this.masterPluginNodes = [];

      let previousNode: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const node = this.createPluginNode(this.context, plugin);
          this.masterPluginNodes.push(node);
          previousNode.connect(node);
          previousNode = node;
      });

      previousNode.connect(this.masterFader);
  }

  // --- Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private impulseResponse(context: BaseAudioContext, duration: number, decay: number) {
    const sampleRate = context.sampleRate;
    const length = sampleRate * duration;
    const impulse = context.createBuffer(2, length, sampleRate);
    const impulseL = impulse.getChannelData(0);
    const impulseR = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        const n = length - i;
        // Simple noise decay
        impulseL[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, decay);
        impulseR[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, decay);
    }
    return impulse;
  }

  // --- Playback ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    // Playback logic reused for offline render, so extracted to helper? 
    // For now keeping it coupled but optimized.
    this.scheduleClips(this.context, clips, tracks, startTime, now, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            // Fallback (shouldn't happen for valid tracks)
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });
  }

  // Helper to schedule clips on a specific context (Realtime or Offline)
  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track || track.muted || track.isMaster) return;

          const clipStartAbsolute = clip.startTime;

          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 
          const effectiveDuration = duration / clip.playbackRate;

          // If scheduling in the past (e.g. playhead is in middle of clip)
          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > effectiveDuration && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      // 1. Calculate total duration
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1; // +1s tail
      const sampleRate = 44100;

      // 2. Create Offline Context
      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      // 3. Recreate Track Chain in Offline Context
      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      // Find Master volume
      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      // Build track chains
      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          // Recreate plugins
          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const node = this.createPluginNode(offlineCtx, p);
                  prev.connect(node);
                  prev = node;
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      // 4. Schedule Clips
      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      // 5. Render
      const renderedBuffer = await offlineCtx.startRendering();

      // 6. Convert to WAV Blob
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      // write WAVE header
      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM (uncompressed)
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit (hardcoded in this simple encoder)

      setUint32(0x61746164); // "data" - chunk
      setUint32(length - pos - 4); // chunk length

      // write interleaved data
      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); // clamp
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; // scale to 16-bit signed int
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import React, { useEffect, useRef } from 'react';
import { Track } from '../types';
import { Volume2, VolumeX, Mic, Headphones, Activity } from 'lucide-react';
import { audioService } from '../services/audioEngine';

interface TrackControlProps {
  track: Track;
  onUpdate: (id: string, updates: Partial<Track>) => void;
  onDelete: (id: string) => void;
  isRecording: boolean;
  onRecordToggle: (trackId: string) => void;
  onOpenEditor: (trackId: string) => void;
}

export const TrackControl: React.FC<TrackControlProps> = ({ 
    track, 
    onUpdate, 
    onDelete, 
    isRecording, 
    onRecordToggle,
    onOpenEditor
}) => {
  const isMaster = track.isMaster;
  const canvasRef = useRef<HTMLCanvasElement>(null);

  // Meter Animation Loop
  useEffect(() => {
    let animationId: number;
    const analyser = audioService.getTrackAnalyser(track.id);

    if (analyser && canvasRef.current) {
        const dataArray = new Uint8Array(analyser.frequencyBinCount);
        const ctx = canvasRef.current.getContext('2d');

        const draw = () => {
            if (!ctx) return;
            analyser.getByteFrequencyData(dataArray);

            // Calculate RMS roughly
            let sum = 0;
            for(let i=0; i<dataArray.length; i++) {
                sum += dataArray[i];
            }
            const average = sum / dataArray.length; // 0-255
            const level = average / 255; 

            // Draw Meter
            const width = canvasRef.current!.width;
            const height = canvasRef.current!.height;

            ctx.clearRect(0, 0, width, height);

            // Background
            ctx.fillStyle = '#1f2937';
            ctx.fillRect(0, 0, width, height);

            // Fill
            const fillWidth = width * Math.min(1, level * 2.5); // Boost sensitivity

            const gradient = ctx.createLinearGradient(0, 0, width, 0);
            gradient.addColorStop(0, '#10b981'); // Green
            gradient.addColorStop(0.6, '#f59e0b'); // Yellow
            gradient.addColorStop(1, '#ef4444'); // Red

            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, fillWidth, height);

            animationId = requestAnimationFrame(draw);
        };
        draw();
    }
    return () => cancelAnimationFrame(animationId);
  }, [track.id]);

  return (
    <div 
        className={`flex flex-col p-3 border-b ${isMaster ? 'bg-gray-900 border-t border-blue-500/30' : 'bg-gray-800 border-gray-700'} h-24 relative group select-none`}
        onDoubleClick={() => onOpenEditor(track.id)}
    >
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
            {!isMaster && <div className="w-3 h-3 rounded-full" style={{ backgroundColor: track.color }} />}
            {isMaster && <Activity size={14} className="text-blue-400" />}
            <span className={`font-semibold text-sm truncate w-24 ${isMaster ? 'text-blue-400' : 'text-gray-200'}`} title={track.name}>
            {track.name}
            </span>
        </div>
        {!isMaster && (
            <button 
                onClick={(e) => { e.stopPropagation(); onDelete(track.id); }}
                className="text-xs text-gray-500 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"
            >
                Delete
            </button>
        )}
      </div>

      <div className="flex items-center gap-2 mb-2">
        {/* Record Button */}
        {!isMaster && (
            <>
                <button
                onClick={(e) => { e.stopPropagation(); onRecordToggle(track.id); }}
                className={`p-1.5 rounded-full transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-gray-700 text-red-500 hover:bg-gray-600 hover:text-red-400'}`}
                title="Record"
                >
                <div className={`w-3 h-3 rounded-full ${isRecording ? 'bg-white' : 'bg-current'}`} />
                </button>

                <button
                onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { muted: !track.muted }); }}
                className={`p-1 rounded ${track.muted ? 'bg-red-500/20 text-red-500' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Mute"
                >
                {track.muted ? <VolumeX size={14} /> : <Volume2 size={14} />}
                </button>
                <button
                onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { soloed: !track.soloed }); }}
                className={`p-1 rounded ${track.soloed ? 'bg-yellow-500/20 text-yellow-500' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Solo"
                >
                <Headphones size={14} />
                </button>
            </>
        )}

        {isMaster && <span className="text-[10px] text-gray-500 uppercase font-bold">Vol</span>}

        <div className="flex-1" onClick={e => e.stopPropagation()}>
            <input
                type="range"
                min="0"
                max="1"
                step="0.01"
                value={track.volume}
                onChange={(e) => onUpdate(track.id, { volume: parseFloat(e.target.value) })}
                className={`w-full h-1 rounded-lg appearance-none cursor-pointer ${isMaster ? 'accent-blue-400 bg-gray-700' : 'accent-blue-500 bg-gray-600'}`}
            />
        </div>
      </div>

      {/* Visual Meter */}
      <div className="h-1.5 w-full bg-gray-900 rounded-full overflow-hidden mt-1">
          <canvas ref={canvasRef} width={200} height={6} className="w-full h-full block" />
      </div>

    </div>
  );
};

import React from 'react';
import { Play, Square, FastForward, Rewind, Activity, Scissors, MousePointer2, ZoomIn, ZoomOut, Grid, Undo, Redo, Download } from 'lucide-react';
import { ToolType } from '../types';

interface TransportProps {
  isPlaying: boolean;
  onPlay: () => void;
  onStop: () => void;
  onRewind: () => void;
  onFastForward: () => void;
  currentTime: number;
  bpm: number;
  setBpm: (bpm: number) => void;

  // New Props
  tool: ToolType;
  setTool: (t: ToolType) => void;
  zoom: number;
  setZoom: (z: number) => void;
  snap: boolean;
  setSnap: (s: boolean) => void;
  onUndo: () => void;
  onRedo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  onExport: () => void;
  isExporting: boolean;
}

const formatTime = (seconds: number) => {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  const ms = Math.floor((seconds % 1) * 100);
  return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}.${ms.toString().padStart(2, '0')}`;
};

export const Transport: React.FC<TransportProps> = ({ 
    isPlaying, 
    onPlay, 
    onStop, 
    onRewind,
    onFastForward,
    currentTime, 
    bpm, 
    setBpm,
    tool,
    setTool,
    zoom,
    setZoom,
    snap,
    setSnap,
    onUndo,
    onRedo,
    canUndo,
    canRedo,
    onExport,
    isExporting
}) => {
  return (
    <div className="h-16 bg-gray-900 border-b border-gray-700 flex items-center px-4 justify-between z-30 shadow-lg select-none">
      <div className="flex items-center gap-4">
        <div className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-500 mr-2">
            ISLdaw
        </div>

        {/* File Actions */}
        <div className="flex items-center gap-1 bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button 
                onClick={onUndo} disabled={!canUndo}
                className="p-1.5 text-gray-400 hover:text-white disabled:opacity-30 rounded hover:bg-gray-700" title="Undo"
             >
                <Undo size={16} />
             </button>
             <button 
                onClick={onRedo} disabled={!canRedo}
                className="p-1.5 text-gray-400 hover:text-white disabled:opacity-30 rounded hover:bg-gray-700" title="Redo"
             >
                <Redo size={16} />
             </button>
        </div>

        {/* Tools */}
        <div className="flex items-center gap-1 bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button 
                onClick={() => setTool('MOVE')}
                className={`p-1.5 rounded transition-all ${tool === 'MOVE' ? 'bg-blue-500 text-white shadow-sm' : 'text-gray-400 hover:text-white hover:bg-gray-700'}`}
                title="Move Tool"
             >
                <MousePointer2 size={16} />
             </button>
             <button 
                onClick={() => setTool('BLADE')}
                className={`p-1.5 rounded transition-all ${tool === 'BLADE' ? 'bg-blue-500 text-white shadow-sm' : 'text-gray-400 hover:text-white hover:bg-gray-700'}`}
                title="Blade Tool"
             >
                <Scissors size={16} />
             </button>
        </div>

        <div className="w-px h-8 bg-gray-700 mx-1"></div>

        {/* Transport */}
        <div className="flex bg-gray-800 rounded-lg p-1 gap-1 border border-gray-700">
            <button 
                onClick={onRewind}
                className="p-2 text-gray-400 hover:text-white rounded hover:bg-gray-700 active:scale-95 transition-transform"
            >
                <Rewind size={18} />
            </button>
            <button 
                onClick={isPlaying ? onStop : onPlay}
                className={`p-2 rounded transition-all active:scale-95 ${isPlaying ? 'text-yellow-400 bg-yellow-400/10' : 'text-green-400 hover:bg-green-400/10 hover:text-green-300'}`}
            >
                {isPlaying ? <Square size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" />}
            </button>
             <button 
                onClick={onFastForward}
                className="p-2 text-gray-400 hover:text-white rounded hover:bg-gray-700 active:scale-95 transition-transform"
            >
                <FastForward size={18} />
            </button>
        </div>

        {/* Time Display */}
        <div className="bg-black/40 px-3 py-1.5 rounded text-blue-400 font-mono text-lg min-w-[100px] text-center border border-blue-500/20 shadow-inner">
            {formatTime(currentTime)}
        </div>
      </div>

      <div className="flex items-center gap-4">

        {/* BPM */}
        <div className="flex items-center gap-2 bg-gray-800 rounded-lg p-1.5 border border-gray-700 group focus-within:border-blue-500/50">
            <Activity size={14} className="text-gray-500 group-focus-within:text-blue-400 ml-1" />
            <div className="flex flex-col items-start mr-1">
                <span className="text-[9px] text-gray-500 font-bold leading-none uppercase">BPM</span>
                <input 
                    type="number" 
                    value={bpm}
                    onChange={(e) => setBpm(Math.max(1, Math.min(999, Number(e.target.value))))}
                    className="w-10 bg-transparent text-sm font-mono text-blue-400 outline-none p-0 leading-none"
                />
            </div>
        </div>

        {/* Zoom & Snap */}
        <div className="flex items-center gap-2 bg-gray-800 rounded-lg p-1.5 border border-gray-700">
             <button onClick={() => setSnap(!snap)} className={`p-1 rounded ${snap ? 'text-blue-400 bg-blue-500/20' : 'text-gray-500 hover:text-gray-300'}`} title="Snap to Grid">
                 <Grid size={16} />
             </button>
             <div className="w-px h-4 bg-gray-600 mx-1"></div>
             <ZoomOut size={14} className="text-gray-500" />
             <input 
                type="range" min="10" max="200" step="5"
                value={zoom}
                onChange={(e) => setZoom(Number(e.target.value))}
                className="w-20 h-1 bg-gray-600 rounded-lg appearance-none cursor-pointer accent-blue-500"
             />
             <ZoomIn size={14} className="text-gray-500" />
        </div>

        <button 
            onClick={onExport}
            disabled={isExporting}
            className="flex items-center gap-2 bg-purple-600 hover:bg-purple-500 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
        >
            <Download size={16} />
            {isExporting ? 'Exporting...' : 'Export'}
        </button>
      </div>
    </div>
  );
};

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, Scissors } from 'lucide-react';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipUpdate: (id: string, newTime: number, newTrackId?: string) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;
  onDeleteClip: (id: string) => void;
  onDuplicateClip: (id: string) => void;
  onRenameClip: (id: string, newName: string) => void;

  onSelectClip: (id: string | null) => void;
  selectedClipId: string | null;
  onCopyClip: (id: string) => void;
  onPasteClip: (time: number, trackId: string) => void;
  canPaste: boolean;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND';
    targetId?: string; 
    time?: number; 
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  snap,
  tool,
  onClipUpdate, 
  onFileDrop,
  onSeek,
  onDeleteClip,
  onDuplicateClip,
  onRenameClip,
  onSelectClip,
  selectedClipId,
  onCopyClip,
  onPasteClip,
  canPaste,
  onLoopClip,
  onSplitClip
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<number>(0);
  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      window.addEventListener('click', closeMenu);
      return () => window.removeEventListener('click', closeMenu);
  }, []);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      const snapInterval = beat; // Snap to quarter notes
      return Math.round(time / snapInterval) * snapInterval;
  };

  // --- Handlers ---

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId) return;

    // Check if clicking on a clip for Blade Tool
    const target = e.target as HTMLElement;
    const clipElement = target.closest('[data-clip-id]');

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const scrollLeft = timelineRef.current?.scrollLeft || 0;
             const clickX = e.clientX - rect.left + scrollLeft;
             const clickTime = clickX / zoom;

             // Visual indicator logic could go here, but for now just split
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    // Normal Seek Logic
    if (!clipElement) {
        onSelectClip(null);
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;
        const scrollLeft = timelineRef.current?.scrollLeft || 0;
        const clickX = e.clientX - rect.left + scrollLeft;
        const seekTime = Math.max(0, (clickX / zoom));
        onSeek(snapToGrid(seekTime));
    }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const scrollLeft = timelineRef.current?.scrollLeft || 0;
    const clickX = e.clientX - rect.left + scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        if (file.type.startsWith('audio/')) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const adjustedTime = Math.max(0, (clickX / zoom) - dragOffset);
        onClipUpdate(draggedClipId, snapToGrid(adjustedTime), trackId);
        setDraggedClipId(null);
        setDragOffset(0);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE') {
         e.preventDefault(); // Don't drag when using blade
         return;
     }
     onSelectClip(clip.id);
     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     setDragOffset(offsetTime);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      onSelectClip(clipId);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const scrollLeft = timelineRef.current?.scrollLeft || 0;
      const clickX = e.clientX - (rect?.left || 0) + scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP' && contextMenu.targetId) {
           switch(action) {
              case 'delete': onDeleteClip(contextMenu.targetId); break;
              case 'duplicate': onDuplicateClip(contextMenu.targetId); break;
              case 'rename': 
                  const clip = clips.find(c => c.id === contextMenu.targetId);
                  if (clip) {
                      const newName = prompt("Rename clip:", clip.name);
                      if (newName) onRenameClip(contextMenu.targetId, newName);
                  }
                  break;
              case 'copy': onCopyClip(contextMenu.targetId); break;
              case 'loop': onLoopClip(contextMenu.targetId); break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClip(contextMenu.time, contextMenu.targetId);
           }
      }
      setContextMenu(null);
  };

  return (
    <div 
      className={`flex-1 overflow-auto bg-gray-950 relative custom-scrollbar flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
      ref={timelineRef}
      onClick={handleTimelineClick}
    >
        {/* Playhead */}
        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler */}
        <div className="h-8 border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex" style={{ width: `${totalBars * pixelsPerBar}px` }}>
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     {/* Quarter Beats */}
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}
        </div>

      <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
        {tracks.map(track => (
          <div 
            key={track.id}
            className="relative h-24 border-b border-gray-800 hover:bg-white/5 transition-colors"
            onDragOver={handleDragOver}
            onDrop={(e) => handleDrop(e, track.id)}
            onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
            style={{ 
                backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                backgroundSize: `${pixelsPerBar}px 100%`,
                backgroundPosition: '0 0'
              }}
          >
            <div 
                className="absolute inset-0 pointer-events-none" 
                style={{
                    backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                    backgroundSize: `${pixelsPerBeat}px 100%`,
                    opacity: 0.3
                }}
            />

            {clips.filter(c => c.trackId === track.id).map(clip => (
              <div
                key={clip.id}
                data-clip-id={clip.id}
                draggable={tool === 'MOVE'}
                onDragStart={(e) => handleDragStart(e, clip)}
                onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                onDoubleClick={() => onSelectClip(clip.id)}
                className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                ${selectedClipId === clip.id ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                style={{
                  left: `${clip.startTime * zoom}px`,
                  width: `${(clip.duration / clip.playbackRate) * zoom}px`,
                }}
              >
                <div 
                    className="absolute inset-0 opacity-60"
                    style={{ backgroundColor: track.color }}
                ></div>

                {clip.loop && (
                    <div className="absolute top-0 right-0 p-1 text-white/50">
                        <RotateCw size={10} />
                    </div>
                )}

                <div className="absolute inset-0 z-10">
                    <Waveform 
                        clip={clip} 
                        width={Math.ceil((clip.duration / clip.playbackRate) * zoom)} 
                        height={80} 
                        color="#ffffff"
                    />
                </div>

                <div className="absolute top-1 left-1 z-20 max-w-full">
                    <div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">
                        {clip.name}
                    </div>
                </div>
              </div>
            ))}
          </div>
        ))}
        <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">
             End of tracks
        </div>
      </div>

      {contextMenu && (
          <div 
              className="fixed z-50 w-48 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
              style={{ top: contextMenu.y, left: contextMenu.x }}
          >
              {contextMenu.type === 'CLIP' ? (
                  <>
                    <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Copy size={14} /> Copy
                    </button>
                     <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <RotateCw size={14} /> Toggle Loop
                    </button>
                    <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Pencil size={14} /> Rename
                    </button>
                    <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Copy size={14} /> Duplicate
                    </button>
                    <div className="h-px bg-gray-700 my-1" />
                    <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2">
                        <Trash2 size={14} /> Delete
                    </button>
                  </>
              ) : (
                  <>
                    <button 
                        onClick={(e) => handleMenuAction(e, 'paste')} 
                        disabled={!canPaste}
                        className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}
                    >
                        <ClipboardPaste size={14} /> Paste
                    </button>
                  </>
              )}
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [] },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [] },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [] },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [] },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);

  const [recordingTrackId, setRecordingTrackId] = useState<string | null>(null);
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Undo/Redo System ---

  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  // Initial History
  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          // Sync Audio Engine
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          if (playbackState.isPlaying) handleStop(); // Stop to avoid desync
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex + 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };


  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (recordingTrackId) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [recordingTrackId]);

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const finishRecording = async () => {
      if (!recordingTrackId) return;

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: recordingTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setRecordingTrackId(null);
  };

  const handleRecordToggle = async (trackId: string) => {
      if (recordingTrackId === trackId) {
          await handleStop();
          return;
      }
      if (recordingTrackId) return;

      try {
          await audioService.resume();
          await audioService.startRecording();
          setRecordingTrackId(trackId);
          recordStartTimeRef.current = pauseTimeRef.current;
          if (!playbackState.isPlaying) startPlayback(pauseTimeRef.current);
      } catch (e) {
          alert("Could not start recording. Please allow microphone access.");
      }
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: []
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    // For simple volume changes, we might skip history to prevent spam, 
    // but for now we'll just update state directly for smooth UI and snapshot on mouse up if we were fancy.
    // We'll update state directly and maybe only push history on major actions?
    // For simplicity:
    setTracks(newTracks);
    // Note: We aren't pushing history here to avoid lag on sliders
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    );
    // Don't restart playback instantly on drag, handled in Timeline
    setClips(newClips);
  };

  // Finalize drag (mouse up)
  const handleClipUpdateEnd = (newClips: AudioClip[]) => {
      // In a real app we'd pass this up, but here we just snapshot current clips state
      updateStateWithHistory(tracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      // Debounce or lazy history push?
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;

      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return; // Out of bounds

      const firstDuration = relativeSplit * clip.playbackRate; // Buffer duration

      const leftClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          duration: firstDuration,
          name: clip.name
      };

      const rightClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          startTime: splitTime,
          offset: clip.offset + firstDuration,
          duration: clip.duration - firstDuration,
          name: clip.name
      };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const newClips = clips.map(c => c.id === id ? { ...c, loop: !clip.loop } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---

  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();

      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}

        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* Track Headers */}
        <div 
            className="flex-shrink-0 bg-gray-900 border-r border-gray-700 overflow-y-auto custom-scrollbar z-10 shadow-xl"
            style={{ width: TRACK_HEADER_WIDTH, paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
        >
          {tracks.map(track => (
            <TrackControl 
              key={track.id} 
              track={track} 
              onUpdate={updateTrack}
              onDelete={deleteTrack}
              isRecording={recordingTrackId === track.id}
              onRecordToggle={handleRecordToggle}
              onOpenEditor={setEditingTrackId}
            />
          ))}

          <div className="p-3">
             <button 
                onClick={addTrack}
                className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
             >
                <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors">
                    <Plus size={14} /> 
                </div>
                <span>Add New Track</span>
             </button>
          </div>
        </div>

        {/* Timeline Area */}
        <Timeline 
          tracks={tracks}
          clips={clips}
          currentTime={playbackState.currentTime}
          onClipUpdate={updateClip}
          onFileDrop={handleFileDrop}
          setClips={setClips}
          onSeek={handleSeek}
          bpm={bpm}
          zoom={zoom}
          snap={snap}
          tool={tool}
          onDeleteClip={deleteClip}
          onDuplicateClip={duplicateClip}
          onRenameClip={renameClip}
          onSplitClip={handleSplitClip}

          onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
          selectedClipId={selectedClipId}
          onCopyClip={handleCopyClip}
          onPasteClip={handlePasteClip}
          canPaste={!!clipboardClip}
          onLoopClip={handleLoopToggle}
        />
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

export default App;

export interface Track {
  id: string;
  name: string;
  color: string;
  volume: number; // 0.0 to 1.0
  muted: boolean;
  soloed: boolean;
  plugins: AudioPlugin[];
  isMaster?: boolean;
  automation?: {
    volume?: AutomationPoint[];
    pan?: AutomationPoint[];
  };
  showAutomation?: boolean; // UI toggle state
}

export interface AutomationPoint {
  id: string;
  time: number; // Seconds
  value: number; // 0-1 for volume, -1 to 1 for pan
}

export interface AudioClip {
  id: string;
  trackId: string;
  buffer: AudioBuffer;
  name: string;
  startTime: number; // Start time in seconds on the timeline
  duration: number; // Duration in seconds (affected by playbackRate conceptually, but buffer duration is constant)
  offset: number; // Start offset within the audio file

  // New properties
  gain: number; // 1.0 is default
  pan: number; // -1.0 (L) to 1.0 (R), 0 is center
  playbackRate: number; // 1.0 is normal speed
  loop: boolean;
}

export enum DragType {
  CLIP = 'CLIP',
  FILE = 'FILE'
}

export interface DragItem {
  type: DragType;
  id?: string; // If moving an existing clip
  files?: FileList; // If dropping external files
}

export interface PlaybackState {
  isPlaying: boolean;
  currentTime: number; // Current playback time in seconds
}

export type PluginType = 'DELAY' | 'REVERB' | 'DISTORTION' | 'HIGHPASS' | 'LOWPASS';

export interface AudioPlugin {
  id: string;
  type: PluginType;
  enabled: boolean;
  params: {
    [key: string]: number;
  };
}

export type ToolType = 'MOVE' | 'BLADE';

export interface HistoryState {
  tracks: Track[];
  clips: AudioClip[];
}

import { AudioClip, Track, AudioPlugin, AutomationPoint } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     // Clips connect here
  output: GainNode;    // Post-plugin, Pre-panner
  panner: StereoPannerNode;
  fader: GainNode;     // Volume control
  analyser: AnalyserNode; // For visual metering
  pluginNodes: AudioNode[]; 
}

class AudioEngine {
  private context: AudioContext;

  // Master Chain
  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  // Map clip ID to the chain of nodes
  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  // Recording
  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    // Setup Master Bus
    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    // Default Chain: Input -> Output -> Panner -> Fader -> Analyser -> MasterInput
    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [] 
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => n.disconnect());
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      // If automation is running, this might get overridden, but for manual adjustments:
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        return delay;
      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;
      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        return hp;
      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        return lp;
      case 'REVERB':
         const convolver = context.createConvolver();
         const duration = plugin.params.decay || 2.0;
         const decay = plugin.params.decay || 2.0;
         convolver.buffer = this.impulseResponse(context, duration, decay);
         return convolver;
      default:
        return context.createGain();
    }
  }

  // --- Chain Builders ---

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => n.disconnect());
    nodes.pluginNodes = [];

    let previousNode: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const node = this.createPluginNode(this.context, plugin);
        nodes.pluginNodes.push(node);
        previousNode.connect(node);
        previousNode = node;
    });

    previousNode.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => n.disconnect());
      this.masterPluginNodes = [];

      let previousNode: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const node = this.createPluginNode(this.context, plugin);
          this.masterPluginNodes.push(node);
          previousNode.connect(node);
          previousNode = node;
      });

      previousNode.connect(this.masterFader);
  }

  // --- Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private impulseResponse(context: BaseAudioContext, duration: number, decay: number) {
    const sampleRate = context.sampleRate;
    const length = sampleRate * duration;
    const impulse = context.createBuffer(2, length, sampleRate);
    const impulseL = impulse.getChannelData(0);
    const impulseR = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        impulseL[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, decay);
        impulseR[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, decay);
    }
    return impulse;
  }

  // --- AI Stem Separation (Simulation) ---

  public async separateStems(file: File): Promise<{name: string, type: PluginType, buffer: AudioBuffer}[]> {
    const originalBuffer = await this.loadFile(file);

    // We can't do real ML separation in browser without heavy WASM.
    // We simulate it by creating copies and applying drastic EQs for the demo.

    const stems = [
        { name: 'Vocals (Stem)', type: 'HIGHPASS' as PluginType, freq: 300 }, // Remove bass
        { name: 'Bass (Stem)', type: 'LOWPASS' as PluginType, freq: 250 }, // Keep bass
        { name: 'Drums (Stem)', type: 'HIGHPASS' as PluginType, freq: 1000 }, // High hats/snares (rough approx)
        { name: 'Other (Stem)', type: 'LOWPASS' as PluginType, freq: 20000 } // Originalish
    ];

    // Return metadata, the UI will add plugins to tracks to achieve the sound
    // Since we can't burn effects into buffer easily without offline render, 
    // we return the original buffer multiple times, but the caller should add specific EQ plugins.

    return stems.map(s => ({
        name: s.name,
        type: s.type,
        buffer: originalBuffer
    }));
  }

  // --- Playback ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    // Check global solo state
    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    // Apply Automation
    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          const nodes = this.trackNodes.get(track.id);
          if (!nodes || !track.automation) return;

          // Volume Automation
          if (track.automation.volume && track.automation.volume.length > 0) {
              const param = nodes.fader.gain;
              param.cancelScheduledValues(now);
              param.setValueAtTime(track.volume, now); // Start at current fader level

              track.automation.volume.forEach(point => {
                   // Calculate absolute time for the automation point
                   // Point time is relative to timeline 0
                   // We are at `now` which corresponds to `startTime` in timeline
                   // So absolute time = now + (point.time - startTime)
                   const absoluteTime = now + (point.time - startTime);

                   if (absoluteTime >= now) {
                       param.linearRampToValueAtTime(point.value, absoluteTime);
                   }
              });
          }

          // Pan Automation
          if (track.automation.pan && track.automation.pan.length > 0) {
              const param = nodes.panner.pan;
              param.cancelScheduledValues(now);
              param.setValueAtTime(0, now);

              track.automation.pan.forEach(point => {
                   const absoluteTime = now + (point.time - startTime);
                   if (absoluteTime >= now) {
                       param.linearRampToValueAtTime(point.value, absoluteTime);
                   }
              });
          }
      });
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          // ROBUST SOLO/MUTE LOGIC
          // 1. If any track is soloed, only play soloed tracks.
          // 2. If no track is soloed, play all non-muted tracks.
          const isAudible = anySolo 
              ? track.soloed 
              : !track.muted;

          if (!isAudible) return;

          const clipStartAbsolute = clip.startTime;

          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 
          const effectiveDuration = duration / clip.playbackRate;

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > effectiveDuration && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    // Cancel automation on tracks to stop parameters from getting stuck
    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const node = this.createPluginNode(offlineCtx, p);
                  prev.connect(node);
                  prev = node;
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          // For offline render, we only use static volume, simpler than scheduling automation curves 
          // (though technically possible)
          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      // Check Solo logic for export
      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      // write WAVE header
      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM (uncompressed)
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit (hardcoded in this simple encoder)

      setUint32(0x61746164); // "data" - chunk
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import React, { useEffect, useRef, useState } from 'react';
import { Track } from '../types';
import { Volume2, VolumeX, Mic, Headphones, Activity, TrendingUp } from 'lucide-react';
import { audioService } from '../services/audioEngine';

interface TrackControlProps {
  track: Track;
  onUpdate: (id: string, updates: Partial<Track>) => void;
  onDelete: (id: string) => void;
  isRecording: boolean;
  onRecordToggle: (trackId: string) => void;
  onOpenEditor: (trackId: string) => void;
  onToggleAutomation: (trackId: string) => void;
}

export const TrackControl: React.FC<TrackControlProps> = ({ 
    track, 
    onUpdate, 
    onDelete, 
    isRecording, 
    onRecordToggle,
    onOpenEditor,
    onToggleAutomation
}) => {
  const isMaster = track.isMaster;
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [peak, setPeak] = useState(0);

  // High Performance Meter Animation Loop
  useEffect(() => {
    let animationId: number;
    const analyser = audioService.getTrackAnalyser(track.id);

    if (analyser && canvasRef.current) {
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);
        const ctx = canvasRef.current.getContext('2d');
        let localPeak = 0;
        let peakHoldTimer = 0;

        const draw = () => {
            if (!ctx) return;
            analyser.getByteTimeDomainData(dataArray);

            // Calculate RMS
            let sum = 0;
            // Find Peak in this frame
            let framePeak = 0;

            for(let i = 0; i < bufferLength; i++) {
                const sample = (dataArray[i] - 128) / 128; // Normalize -1 to 1
                sum += sample * sample;
                if (Math.abs(sample) > framePeak) framePeak = Math.abs(sample);
            }

            const rms = Math.sqrt(sum / bufferLength);

            // Peak Hold Logic
            if (framePeak > localPeak) {
                localPeak = framePeak;
                peakHoldTimer = 60; // Hold for 60 frames (~1s)
            } else {
                peakHoldTimer--;
                if (peakHoldTimer <= 0) localPeak *= 0.95; // Decay
            }

            setPeak(localPeak);

            // Draw Meter
            const width = canvasRef.current!.width;
            const height = canvasRef.current!.height;

            ctx.clearRect(0, 0, width, height);

            // Background
            ctx.fillStyle = '#111827';
            ctx.fillRect(0, 0, width, height);

            // Draw RMS (Solid Bar)
            // Logarithmic-ish scaling for better visuals: value^0.5
            const rmsWidth = width * Math.min(1, Math.pow(rms * 4, 0.6));

            const gradient = ctx.createLinearGradient(0, 0, width, 0);
            gradient.addColorStop(0, '#10b981'); // Green
            gradient.addColorStop(0.6, '#f59e0b'); // Yellow
            gradient.addColorStop(0.85, '#ef4444'); // Red

            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, rmsWidth, height);

            // Draw Peak (Line)
            const peakPos = width * Math.min(1, Math.pow(localPeak * 4, 0.6));
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(peakPos, 0, 2, height);

            // Draw Clipping Indicator
            if (localPeak >= 0.98) {
                ctx.fillStyle = '#ef4444';
                ctx.fillRect(width - 4, 0, 4, height);
            }

            animationId = requestAnimationFrame(draw);
        };
        draw();
    }
    return () => cancelAnimationFrame(animationId);
  }, [track.id]);

  return (
    <div 
        className={`flex flex-col p-3 border-b ${isMaster ? 'bg-gray-900 border-t border-blue-500/30' : 'bg-gray-800 border-gray-700'} relative group select-none transition-all`}
        style={{ height: track.showAutomation ? '160px' : '96px' }}
        onDoubleClick={() => onOpenEditor(track.id)}
    >
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
            {!isMaster && <div className="w-3 h-3 rounded-full" style={{ backgroundColor: track.color }} />}
            {isMaster && <Activity size={14} className="text-blue-400" />}
            <span className={`font-semibold text-sm truncate w-24 ${isMaster ? 'text-blue-400' : 'text-gray-200'}`} title={track.name}>
            {track.name}
            </span>
        </div>
        {!isMaster && (
            <button 
                onClick={(e) => { e.stopPropagation(); onDelete(track.id); }}
                className="text-xs text-gray-500 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"
            >
                Delete
            </button>
        )}
      </div>

      <div className="flex items-center gap-2 mb-2">
        {/* Record Button */}
        {!isMaster && (
            <>
                <button
                onClick={(e) => { e.stopPropagation(); onRecordToggle(track.id); }}
                className={`p-1.5 rounded-full transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-gray-700 text-red-500 hover:bg-gray-600 hover:text-red-400'}`}
                title="Record"
                >
                <div className={`w-3 h-3 rounded-full ${isRecording ? 'bg-white' : 'bg-current'}`} />
                </button>

                <button
                onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { muted: !track.muted }); }}
                className={`p-1 rounded ${track.muted ? 'bg-red-500/20 text-red-500' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Mute"
                >
                {track.muted ? <VolumeX size={14} /> : <Volume2 size={14} />}
                </button>
                <button
                onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { soloed: !track.soloed }); }}
                className={`p-1 rounded ${track.soloed ? 'bg-yellow-500/20 text-yellow-500' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Solo"
                >
                <Headphones size={14} />
                </button>
                <button
                onClick={(e) => { e.stopPropagation(); onToggleAutomation(track.id); }}
                className={`p-1 rounded ${track.showAutomation ? 'bg-blue-500/20 text-blue-400' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Automation"
                >
                <TrendingUp size={14} />
                </button>
            </>
        )}

        {isMaster && <span className="text-[10px] text-gray-500 uppercase font-bold">Vol</span>}

        <div className="flex-1" onClick={e => e.stopPropagation()}>
            <input
                type="range"
                min="0"
                max="1"
                step="0.01"
                value={track.volume}
                onChange={(e) => onUpdate(track.id, { volume: parseFloat(e.target.value) })}
                className={`w-full h-1 rounded-lg appearance-none cursor-pointer ${isMaster ? 'accent-blue-400 bg-gray-700' : 'accent-blue-500 bg-gray-600'}`}
                disabled={track.showAutomation} // Disable fader if automation is visible/active (visual feedback)
            />
        </div>
      </div>

      {/* Visual Meter */}
      <div className="h-2 w-full bg-gray-900 rounded overflow-hidden mt-1 relative border border-gray-800">
          <canvas ref={canvasRef} width={200} height={8} className="w-full h-full block" />

          {/* dB markers overlay */}
          <div className="absolute inset-0 flex justify-between px-2 pointer-events-none opacity-50">
               <div className="w-px h-full bg-black/50" style={{ left: '50%' }}></div>
               <div className="w-px h-full bg-black/50" style={{ left: '75%' }}></div>
          </div>
      </div>

      {isMaster && (
          <div className="flex justify-between text-[9px] text-gray-500 font-mono mt-0.5 px-1">
              <span>-inf</span>
              <span>-12</span>
              <span>-6</span>
              <span>0dB</span>
          </div>
      )}

      {/* Automation Lane Header */}
      {track.showAutomation && (
           <div className="mt-4 pt-2 border-t border-gray-700 flex items-center justify-between animate-fade-in">
               <span className="text-[10px] text-blue-400 uppercase font-bold flex items-center gap-1">
                   <TrendingUp size={10} /> Volume Automation
               </span>
               <span className="text-[10px] text-gray-500">Click in timeline to add points</span>
           </div>
      )}

    </div>
  );
};

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, Scissors } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipUpdate: (id: string, newTime: number, newTrackId?: string) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;
  onDeleteClip: (id: string) => void;
  onDuplicateClip: (id: string) => void;
  onRenameClip: (id: string, newName: string) => void;

  onSelectClip: (id: string | null) => void;
  selectedClipId: string | null;
  onCopyClip: (id: string) => void;
  onPasteClip: (time: number, trackId: string) => void;
  canPaste: boolean;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, point: AutomationPoint) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND';
    targetId?: string; 
    time?: number; 
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  snap,
  tool,
  onClipUpdate, 
  onFileDrop,
  onSeek,
  onDeleteClip,
  onDuplicateClip,
  onRenameClip,
  onSelectClip,
  selectedClipId,
  onCopyClip,
  onPasteClip,
  canPaste,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<number>(0);
  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      window.addEventListener('click', closeMenu);
      return () => window.removeEventListener('click', closeMenu);
  }, []);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      const snapInterval = beat; // Snap to quarter notes
      return Math.round(time / snapInterval) * snapInterval;
  };

  // --- Handlers ---

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId) return;

    const target = e.target as HTMLElement;
    const clipElement = target.closest('[data-clip-id]');

    // Automation Point Click
    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        if (trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const scrollLeft = timelineRef.current?.scrollLeft || 0;
                 const clickX = e.clientX - rect.left + scrollLeft;
                 const time = Math.max(0, clickX / zoom);

                 // Calculate Y value (inverted: top is 1, bottom is 0)
                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));

                 onAddAutomationPoint(trackId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; // Don't seek if adding automation
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const scrollLeft = timelineRef.current?.scrollLeft || 0;
             const clickX = e.clientX - rect.left + scrollLeft;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    // Normal Seek Logic
    if (!clipElement && !automationLane) {
        onSelectClip(null);
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;
        const scrollLeft = timelineRef.current?.scrollLeft || 0;
        const clickX = e.clientX - rect.left + scrollLeft;
        const seekTime = Math.max(0, (clickX / zoom));
        onSeek(snapToGrid(seekTime));
    }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const scrollLeft = timelineRef.current?.scrollLeft || 0;
    const clickX = e.clientX - rect.left + scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        if (file.type.startsWith('audio/')) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const adjustedTime = Math.max(0, (clickX / zoom) - dragOffset);
        onClipUpdate(draggedClipId, snapToGrid(adjustedTime), trackId);
        setDraggedClipId(null);
        setDragOffset(0);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE') {
         e.preventDefault(); 
         return;
     }
     onSelectClip(clip.id);
     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     setDragOffset(offsetTime);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      onSelectClip(clipId);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const scrollLeft = timelineRef.current?.scrollLeft || 0;
      const clickX = e.clientX - (rect?.left || 0) + scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP' && contextMenu.targetId) {
           switch(action) {
              case 'delete': onDeleteClip(contextMenu.targetId); break;
              case 'duplicate': onDuplicateClip(contextMenu.targetId); break;
              case 'rename': 
                  const clip = clips.find(c => c.id === contextMenu.targetId);
                  if (clip) {
                      const newName = prompt("Rename clip:", clip.name);
                      if (newName) onRenameClip(contextMenu.targetId, newName);
                  }
                  break;
              case 'copy': onCopyClip(contextMenu.targetId); break;
              case 'loop': onLoopClip(contextMenu.targetId); break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClip(contextMenu.time, contextMenu.targetId);
           }
      }
      setContextMenu(null);
  };

  // Helper to draw automation lines
  const renderAutomationPoints = (track: Track) => {
      if (!track.automation?.volume) return null;
      // Sort points by time
      const points = [...track.automation.volume].sort((a, b) => a.time - b.time);
      if (points.length === 0) return null;

      const pathData = points.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * 64; // Height of lane is 64px
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {points.map(p => (
                  <circle 
                    key={p.id} 
                    cx={p.time * zoom} 
                    cy={(1 - p.value) * 64} 
                    r="4" 
                    fill="#3b82f6" 
                    className="hover:r-6 transition-all cursor-pointer"
                  />
              ))}
          </>
      );
  };

  return (
    <div 
      className={`flex-1 overflow-auto bg-gray-950 relative custom-scrollbar flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
      ref={timelineRef}
      onClick={handleTimelineClick}
    >
        {/* Playhead */}
        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler */}
        <div className="h-8 border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex" style={{ width: `${totalBars * pixelsPerBar}px` }}>
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     {/* Quarter Beats */}
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}
        </div>

      <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
        {tracks.map(track => (
          <div key={track.id} className="flex flex-col">
            {/* Standard Track Lane */}
            <div 
                className="relative h-24 border-b border-gray-800 hover:bg-white/5 transition-colors"
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, track.id)}
                onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                style={{ 
                    backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                    backgroundSize: `${pixelsPerBar}px 100%`,
                    backgroundPosition: '0 0'
                }}
            >
                <div 
                    className="absolute inset-0 pointer-events-none" 
                    style={{
                        backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                        backgroundSize: `${pixelsPerBeat}px 100%`,
                        opacity: 0.3
                    }}
                />

                {clips.filter(c => c.trackId === track.id).map(clip => (
                <div
                    key={clip.id}
                    data-clip-id={clip.id}
                    draggable={tool === 'MOVE'}
                    onDragStart={(e) => handleDragStart(e, clip)}
                    onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                    onDoubleClick={() => onSelectClip(clip.id)}
                    className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                    ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                    ${selectedClipId === clip.id ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                    style={{
                    left: `${clip.startTime * zoom}px`,
                    width: `${(clip.duration / clip.playbackRate) * zoom}px`,
                    }}
                >
                    <div 
                        className="absolute inset-0 opacity-60"
                        style={{ backgroundColor: track.color }}
                    ></div>

                    {clip.loop && (
                        <div className="absolute top-0 right-0 p-1 text-white/50">
                            <RotateCw size={10} />
                        </div>
                    )}

                    <div className="absolute inset-0 z-10">
                        <Waveform 
                            clip={clip} 
                            width={Math.ceil((clip.duration / clip.playbackRate) * zoom)} 
                            height={80} 
                            color="#ffffff"
                        />
                    </div>

                    <div className="absolute top-1 left-1 z-20 max-w-full">
                        <div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">
                            {clip.name}
                        </div>
                    </div>
                </div>
                ))}
            </div>

            {/* Automation Lane */}
            {track.showAutomation && (
                <div 
                    className="h-16 bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair"
                    data-automation-track-id={track.id}
                    style={{ minWidth: `${totalBars * pixelsPerBar}px` }}
                >
                    <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                    <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>
                        {renderAutomationPoints(track)}
                    </svg>
                </div>
            )}
          </div>
        ))}
        <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">
             End of tracks
        </div>
      </div>

      {contextMenu && (
          <div 
              className="fixed z-50 w-48 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
              style={{ top: contextMenu.y, left: contextMenu.x }}
          >
              {contextMenu.type === 'CLIP' ? (
                  <>
                    <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Copy size={14} /> Copy
                    </button>
                     <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <RotateCw size={14} /> Toggle Loop
                    </button>
                    <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Pencil size={14} /> Rename
                    </button>
                    <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Copy size={14} /> Duplicate
                    </button>
                    <div className="h-px bg-gray-700 my-1" />
                    <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2">
                        <Trash2 size={14} /> Delete
                    </button>
                  </>
              ) : (
                  <>
                    <button 
                        onClick={(e) => handleMenuAction(e, 'paste')} 
                        disabled={!canPaste}
                        className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}
                    >
                        <ClipboardPaste size={14} /> Paste
                    </button>
                  </>
              )}
          </div>
      )}
    </div>
  );
};

import React, { useState } from 'react';
import { Upload, X, Loader2, Music, Layers } from 'lucide-react';
import { audioService } from '../services/audioEngine';
import { PluginType } from '../types';

interface StemSplitterProps {
  isOpen: boolean;
  onClose: () => void;
  onStemsGenerated: (stems: {name: string, type: PluginType, buffer: AudioBuffer}[]) => void;
}

export const StemSplitter: React.FC<StemSplitterProps> = ({ isOpen, onClose, onStemsGenerated }) => {
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleProcess = async () => {
    if (!file) return;
    setLoading(true);

    try {
        // Call the service (which simulates the process for this demo)
        const stems = await audioService.separateStems(file);

        // Wait a bit to simulate processing time for UX
        setTimeout(() => {
            onStemsGenerated(stems);
            setLoading(false);
            onClose();
        }, 2000);

    } catch (e) {
        console.error(e);
        alert("Failed to separate stems");
        setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl w-full max-w-md flex flex-col overflow-hidden animate-slide-up">

        <div className="p-6 border-b border-gray-800 flex justify-between items-center">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <Layers className="text-blue-400" /> AI Stem Splitter
            </h2>
            <button onClick={onClose} className="text-gray-400 hover:text-white"><X size={20} /></button>
        </div>

        <div className="p-6 space-y-6">
            <div className="border-2 border-dashed border-gray-700 rounded-xl p-8 flex flex-col items-center justify-center text-center hover:border-blue-500/50 transition-colors bg-gray-800/30">
                <input 
                    type="file" 
                    id="stem-upload" 
                    className="hidden" 
                    accept="audio/*"
                    onChange={handleFileChange}
                />

                {file ? (
                    <div className="flex flex-col items-center gap-2">
                        <div className="p-3 bg-blue-500/20 rounded-full text-blue-400">
                            <Music size={24} />
                        </div>
                        <span className="font-medium text-white">{file.name}</span>
                        <span className="text-xs text-gray-400">{(file.size / 1024 / 1024).toFixed(2)} MB</span>
                        <button onClick={() => setFile(null)} className="text-xs text-red-400 hover:underline mt-2">Remove</button>
                    </div>
                ) : (
                    <label htmlFor="stem-upload" className="cursor-pointer flex flex-col items-center gap-2">
                        <Upload size={32} className="text-gray-500" />
                        <span className="text-sm text-gray-300 font-medium">Click to upload song</span>
                        <span className="text-xs text-gray-500">Supports MP3, WAV, FLAC</span>
                    </label>
                )}
            </div>

            <div className="bg-blue-900/20 border border-blue-500/20 p-3 rounded-lg text-xs text-blue-300">
                <strong>Note:</strong> This uses a simulated AI model to approximate stem separation by frequency splitting for demonstration purposes.
            </div>

            <button 
                onClick={handleProcess}
                disabled={!file || loading}
                className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-semibold flex items-center justify-center gap-2 transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin" size={18} />
                        Processing...
                    </>
                ) : (
                    "Separate into 4 Tracks"
                )}
            </button>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { StemSplitter } from './components/StemSplitter';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, PluginType } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH } from './constants';
import { audioService } from './services/audioEngine';
import { Plus, Layers } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [], pan: [] }, showAutomation: false },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [], pan: [] }, showAutomation: false },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [], pan: [] }, showAutomation: false },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [], pan: [] }, showAutomation: false },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [], pan: [] },
    showAutomation: false
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);
  const [isStemSplitterOpen, setIsStemSplitterOpen] = useState(false);

  const [recordingTrackId, setRecordingTrackId] = useState<string | null>(null);
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Undo/Redo System ---

  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  // Initial History
  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          // Sync Audio Engine
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          if (playbackState.isPlaying) handleStop(); // Stop to avoid desync
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex + 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };


  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (recordingTrackId) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [recordingTrackId]);

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const finishRecording = async () => {
      if (!recordingTrackId) return;

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: recordingTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setRecordingTrackId(null);
  };

  const handleRecordToggle = async (trackId: string) => {
      if (recordingTrackId === trackId) {
          await handleStop();
          return;
      }
      if (recordingTrackId) return;

      try {
          await audioService.resume();
          await audioService.startRecording();
          setRecordingTrackId(trackId);
          recordStartTimeRef.current = pauseTimeRef.current;
          if (!playbackState.isPlaying) startPlayback(pauseTimeRef.current);
      } catch (e) {
          alert("Could not start recording. Please allow microphone access.");
      }
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [], pan: [] },
      showAutomation: false
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.volume ? [...t.automation.volume] : [];
             // Insert point
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) {
                 points[existingIdx] = point;
             } else {
                 points.push(point);
             }
             return { ...t, automation: { ...t.automation, volume: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    );
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;

      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return; // Out of bounds

      const firstDuration = relativeSplit * clip.playbackRate; // Buffer duration

      const leftClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          duration: firstDuration,
          name: clip.name
      };

      const rightClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          startTime: splitTime,
          offset: clip.offset + firstDuration,
          duration: clip.duration - firstDuration,
          name: clip.name
      };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const newClips = clips.map(c => c.id === id ? { ...c, loop: !clip.loop } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Stem Separation ---

  const handleStemsGenerated = (stems: {name: string, type: PluginType, buffer: AudioBuffer}[]) => {
      const newTracks = [...tracks];
      // Remove master for a sec
      const master = newTracks.pop();
      const generatedClips: AudioClip[] = [];

      stems.forEach((stem, i) => {
          const newTrack: Track = {
              id: uuidv4(),
              name: stem.name,
              color: TRACK_COLORS[(tracks.length + i) % TRACK_COLORS.length],
              volume: 0.8,
              muted: false,
              soloed: false,
              plugins: [
                  { id: uuidv4(), type: stem.type, enabled: true, params: { frequency: (stem.type === 'HIGHPASS' ? 300 : 250) } }
              ],
              automation: { volume: [], pan: [] },
              showAutomation: false
          };

          if (stem.name.includes("Vocals")) newTrack.plugins[0].params.frequency = 300;
          if (stem.name.includes("Bass")) newTrack.plugins[0].params.frequency = 300; // Lowpass at 300
          if (stem.name.includes("Drums")) newTrack.plugins[0].params.frequency = 1000;

          newTracks.push(newTrack);
          audioService.createTrackNodes(newTrack.id);
          audioService.updateTrackPlugins(newTrack.id, newTrack.plugins);

          generatedClips.push({
              id: uuidv4(),
              trackId: newTrack.id,
              buffer: stem.buffer,
              name: stem.name,
              startTime: 0,
              duration: stem.buffer.duration,
              offset: 0,
              gain: 1,
              pan: 0,
              playbackRate: 1,
              loop: false
          });
      });

      if (master) newTracks.push(master);

      updateStateWithHistory(newTracks, [...clips, ...generatedClips]);
  };

  // --- Export ---

  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();

      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}

        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
