export default App;

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     // Clips connect here
  output: GainNode;    // Post-plugin, Pre-panner
  panner: StereoPannerNode;
  fader: GainNode;     // Volume control
  analyser: AnalyserNode; // For visual metering
  pluginNodes: AudioNode[]; 
}

class AudioEngine {
  private context: AudioContext;

  // Master Chain
  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  // Map clip ID to the chain of nodes
  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  // Recording
  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    // Setup Master Bus
    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    // Default Chain: Input -> Output -> Panner -> Fader -> Analyser -> MasterInput
    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [] 
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => n.disconnect());
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      // If automation is running, this might get overridden, but for manual adjustments:
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        return delay;
      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;
      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        return hp;
      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        return lp;
      case 'REVERB':
         const convolver = context.createConvolver();
         const duration = plugin.params.decay || 2.0;
         const decay = plugin.params.decay || 2.0;
         convolver.buffer = this.impulseResponse(context, duration, decay);
         return convolver;
      default:
        return context.createGain();
    }
  }

  // --- Chain Builders ---

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => n.disconnect());
    nodes.pluginNodes = [];

    let previousNode: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const node = this.createPluginNode(this.context, plugin);
        nodes.pluginNodes.push(node);
        previousNode.connect(node);
        previousNode = node;
    });

    previousNode.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => n.disconnect());
      this.masterPluginNodes = [];

      let previousNode: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const node = this.createPluginNode(this.context, plugin);
          this.masterPluginNodes.push(node);
          previousNode.connect(node);
          previousNode = node;
      });

      previousNode.connect(this.masterFader);
  }

  // --- Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private impulseResponse(context: BaseAudioContext, duration: number, decay: number) {
    const sampleRate = context.sampleRate;
    const length = sampleRate * duration;
    const impulse = context.createBuffer(2, length, sampleRate);
    const impulseL = impulse.getChannelData(0);
    const impulseR = impulse.getChannelData(1);

    for (let i = 0; i < length; i++) {
        impulseL[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, decay);
        impulseR[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / length, decay);
    }
    return impulse;
  }

  // --- AI Stem Separation (Simulation) ---

  public async separateStems(file: File): Promise<{name: string, type: PluginType, buffer: AudioBuffer}[]> {
    const originalBuffer = await this.loadFile(file);

    // We can't do real ML separation in browser without heavy WASM.
    // We simulate it by creating copies and applying drastic EQs for the demo.

    const stems = [
        { name: 'Vocals (Stem)', type: 'HIGHPASS' as PluginType, freq: 300 }, // Remove bass
        { name: 'Bass (Stem)', type: 'LOWPASS' as PluginType, freq: 250 }, // Keep bass
        { name: 'Drums (Stem)', type: 'HIGHPASS' as PluginType, freq: 1000 }, // High hats/snares (rough approx)
        { name: 'Other (Stem)', type: 'LOWPASS' as PluginType, freq: 20000 } // Originalish
    ];

    // Return metadata, the UI will add plugins to tracks to achieve the sound
    // Since we can't burn effects into buffer easily without offline render, 
    // we return the original buffer multiple times, but the caller should add specific EQ plugins.

    return stems.map(s => ({
        name: s.name,
        type: s.type,
        buffer: originalBuffer
    }));
  }

  // --- Playback ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    // Check global solo state
    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    // Apply Automation
    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          const nodes = this.trackNodes.get(track.id);
          if (!nodes || !track.automation) return;

          // Volume Automation
          if (track.automation.volume && track.automation.volume.length > 0) {
              const param = nodes.fader.gain;
              param.cancelScheduledValues(now);
              param.setValueAtTime(track.volume, now); // Start at current fader level

              track.automation.volume.forEach(point => {
                   // Calculate absolute time for the automation point
                   // Point time is relative to timeline 0
                   // We are at `now` which corresponds to `startTime` in timeline
                   // So absolute time = now + (point.time - startTime)
                   const absoluteTime = now + (point.time - startTime);

                   if (absoluteTime >= now) {
                       param.linearRampToValueAtTime(point.value, absoluteTime);
                   }
              });
          }

          // Pan Automation
          if (track.automation.pan && track.automation.pan.length > 0) {
              const param = nodes.panner.pan;
              param.cancelScheduledValues(now);
              param.setValueAtTime(0, now);

              track.automation.pan.forEach(point => {
                   const absoluteTime = now + (point.time - startTime);
                   if (absoluteTime >= now) {
                       param.linearRampToValueAtTime(point.value, absoluteTime);
                   }
              });
          }
      });
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          // ROBUST SOLO/MUTE LOGIC
          // 1. If any track is soloed, only play soloed tracks.
          // 2. If no track is soloed, play all non-muted tracks.
          const isAudible = anySolo 
              ? track.soloed 
              : !track.muted;

          if (!isAudible) return;

          const clipStartAbsolute = clip.startTime;

          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 
          const effectiveDuration = duration / clip.playbackRate;

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > effectiveDuration && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    // Cancel automation on tracks to stop parameters from getting stuck
    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const node = this.createPluginNode(offlineCtx, p);
                  prev.connect(node);
                  prev = node;
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          // For offline render, we only use static volume, simpler than scheduling automation curves 
          // (though technically possible)
          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      // Check Solo logic for export
      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      // write WAVE header
      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM (uncompressed)
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit (hardcoded in this simple encoder)

      setUint32(0x61746164); // "data" - chunk
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  // We keep a reference to reverb wet/dry nodes to update them dynamically if needed
  reverbMix?: { dry: GainNode, wet: GainNode };
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [] 
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => n.disconnect());
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      // We apply volume to the fader. 
      // Note: Real-time solo/mute logic might override this momentarily, 
      // so this sets the "base" volume.
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  // --- Real-time Solo/Mute Logic ---

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          // If audible, restore volume. If not, mute.
          const targetGain = isAudible ? track.volume : 0;

          // Snap immediately to avoid long fades when toggling solo
          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Advanced Plugin Creation ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        // Simple feedback loop would require external routing, strictly simple delay here
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        return lp;

      case 'REVERB':
         // Complex Reverb with Wet/Dry mix
         const inputNode = context.createGain();
         const outputNode = context.createGain();

         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5; // 0 to 1
         const type = plugin.params.type ?? 0; // 0: Hall, 1: Room, 2: Plate
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         // Routing: Input -> Dry -> Output
         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         // Routing: Input -> Convolver -> Wet -> Output
         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { input: inputNode, output: outputNode };

      default:
        return context.createGain();
    }
  }

  // --- Chain Builders ---

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    // Disconnect everything
    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            // It's a graph (like our Reverb)
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            // Store reference to output to disconnect later
            nodes.pluginNodes.push(output); 
        }

        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  // Improved Reverb Generation
  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      // 0: Hall (smooth, dense), 1: Room (short, echoey), 2: Plate (metallic, fast attack)
      for (let i = 0; i < length; i++) {
          const n = length - i;
          let decay = 0;

          if (type === 0) { // Hall
             // Slower attack, long tail
             decay = Math.pow(1 - i / length, decayTime * 1.5);
          } else if (type === 1) { // Room
             // Fast exponential decay
             decay = Math.pow(1 - i / length, decayTime * 4);
          } else { // Plate
             // Linear-ish decay but high density
             decay = Math.pow(1 - i / length, decayTime * 2);
          }

          // Add some noise burst
          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Improved AI Stem Separation (Simulation) ---

  public async separateStems(file: File): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);

    // We improve isolation by stacking filters.
    // Note: In a real app with WASM, we'd use FFT masking. Here we use distinct EQ profiles.

    return [
        { 
            name: 'Vocals', 
            type: 'HIGHPASS', 
            buffer: originalBuffer,
            plugins: [
                { id: 'v-hp', type: 'HIGHPASS', enabled: true, params: { frequency: 350 } }, // Cut mud
                { id: 'v-lp', type: 'LOWPASS', enabled: true, params: { frequency: 8000 } }  // Cut hiss
            ]
        },
        { 
            name: 'Bass', 
            type: 'LOWPASS', 
            buffer: originalBuffer,
            plugins: [
                { id: 'b-lp', type: 'LOWPASS', enabled: true, params: { frequency: 250 } }, // Isolate low end
                { id: 'b-dist', type: 'DISTORTION', enabled: true, params: { drive: 5 } } // Add harmonics to make it audible
            ]
        },
        { 
            name: 'Drums', 
            type: 'HIGHPASS', 
            buffer: originalBuffer,
            plugins: [
                // "Scoop" the mids where vocals sit
                { id: 'd-hp', type: 'HIGHPASS', enabled: true, params: { frequency: 50 } }, // Sub cut
                { id: 'd-lp', type: 'LOWPASS', enabled: true, params: { frequency: 12000 } } // Air cut
            ]
        },
        { 
            name: 'Backing', 
            type: 'LOWPASS', 
            buffer: originalBuffer,
            plugins: [
                 // Mid range focus
                 { id: 'o-hp', type: 'HIGHPASS', enabled: true, params: { frequency: 250 } },
                 { id: 'o-lp', type: 'LOWPASS', enabled: true, params: { frequency: 4000 } }
            ] 
        }
    ];
  }

  // --- Playback ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    // Check global solo state
    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    // Apply Automation
    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          const nodes = this.trackNodes.get(track.id);
          if (!nodes || !track.automation) return;

          // Volume Automation
          if (track.automation.volume && track.automation.volume.length > 0) {
              const param = nodes.fader.gain;
              param.cancelScheduledValues(now);
              param.setValueAtTime(track.volume, now); 

              track.automation.volume.forEach(point => {
                   const absoluteTime = now + (point.time - startTime);
                   if (absoluteTime >= now) {
                       param.linearRampToValueAtTime(point.value, absoluteTime);
                   }
              });
          }

          // Pan Automation
          if (track.automation.pan && track.automation.pan.length > 0) {
              const param = nodes.panner.pan;
              param.cancelScheduledValues(now);
              param.setValueAtTime(0, now);

              track.automation.pan.forEach(point => {
                   const absoluteTime = now + (point.time - startTime);
                   if (absoluteTime >= now) {
                       param.linearRampToValueAtTime(point.value, absoluteTime);
                   }
              });
          }
      });
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          // Initial audibility check for scheduling. 
          // Real-time toggling is handled by applyRealtimeSoloMute
          const isAudible = anySolo 
              ? track.soloed 
              : !track.muted;

          // Note: We still schedule even if muted, but set gain to 0, 
          // so we can unmute instantly without restarting.

          const clipStartAbsolute = clip.startTime;

          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          // Apply initial track-level mute state to fader if needed (done in creation, but enforced here)
          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      // write WAVE header
      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM (uncompressed)
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit (hardcoded in this simple encoder)

      setUint32(0x61746164); // "data" - chunk
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import React, { useState } from 'react';
import { Track, AudioPlugin, PluginType } from '../types';
import { X, Plus, Power, Trash2, Sliders, Waves, Box, Disc } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

interface TrackEditorProps {
  track: Track;
  onUpdate: (trackId: string, updates: Partial<Track>) => void;
  onClose: () => void;
}

export const TrackEditor: React.FC<TrackEditorProps> = ({ track, onUpdate, onClose }) => {
  const [isAdding, setIsAdding] = useState(false);

  const addPlugin = (type: PluginType) => {
    const newPlugin: AudioPlugin = {
        id: uuidv4(),
        type,
        enabled: true,
        params: {}
    };

    // Set default params
    if (type === 'DISTORTION') newPlugin.params.drive = 50;
    if (type === 'DELAY') { newPlugin.params.time = 0.3; newPlugin.params.feedback = 0.5; }
    if (type === 'HIGHPASS') newPlugin.params.frequency = 200;
    if (type === 'LOWPASS') newPlugin.params.frequency = 2000;
    if (type === 'REVERB') {
        newPlugin.params.decay = 2.0;
        newPlugin.params.mix = 0.5;
        newPlugin.params.type = 0; // Hall
    }

    onUpdate(track.id, { plugins: [...track.plugins, newPlugin] });
    setIsAdding(false);
  };

  const updatePluginParam = (pluginId: string, param: string, value: number) => {
    const newPlugins = track.plugins.map(p => {
        if (p.id === pluginId) {
            return { ...p, params: { ...p.params, [param]: value } };
        }
        return p;
    });
    onUpdate(track.id, { plugins: newPlugins });
  };

  const togglePlugin = (pluginId: string) => {
    const newPlugins = track.plugins.map(p => 
        p.id === pluginId ? { ...p, enabled: !p.enabled } : p
    );
    onUpdate(track.id, { plugins: newPlugins });
  };

  const removePlugin = (pluginId: string) => {
     onUpdate(track.id, { plugins: track.plugins.filter(p => p.id !== pluginId) });
  };

  return (
    <div className="h-64 bg-gray-900 border-t border-gray-700 flex flex-col shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.3)] z-40 animate-slide-up">
      <div className="flex items-center justify-between px-4 py-2 border-b border-gray-800 bg-gray-850">
        <div className="flex items-center gap-2">
            <span className="text-sm font-bold text-gray-200 uppercase tracking-wider">Track Editor:</span>
            <div className="flex items-center gap-2">
                <div className="w-3 h-3 rounded-full" style={{ backgroundColor: track.color || '#fff' }}></div>
                <span className="text-sm text-white font-medium">{track.name}</span>
            </div>
        </div>
        <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors">
          <X size={16} />
        </button>
      </div>

      <div className="flex-1 flex overflow-hidden">
        {/* Plugin List / Chain */}
        <div className="w-64 border-r border-gray-800 bg-gray-900/50 flex flex-col p-4 gap-2 overflow-y-auto custom-scrollbar">
             <div className="text-xs text-gray-500 font-bold uppercase mb-2">Signal Chain</div>

             {track.plugins.map((plugin, index) => (
                 <div key={plugin.id} className={`p-3 rounded-lg border flex flex-col gap-2 ${plugin.enabled ? 'bg-gray-800 border-gray-700' : 'bg-gray-900 border-gray-800 opacity-60'}`}>
                     <div className="flex items-center justify-between">
                         <span className="font-semibold text-xs text-blue-400">{index + 1}. {plugin.type}</span>
                         <div className="flex items-center gap-1">
                             <button onClick={() => togglePlugin(plugin.id)} className="p-1 hover:text-white text-gray-400">
                                <Power size={12} className={plugin.enabled ? "text-green-400" : ""} />
                             </button>
                             <button onClick={() => removePlugin(plugin.id)} className="p-1 hover:text-red-400 text-gray-500">
                                <Trash2 size={12} />
                             </button>
                         </div>
                     </div>

                     {/* Dynamic Controls Render */}
                     {plugin.enabled && (
                         <div className="grid grid-cols-1 gap-3">
                             {/* Special UI for Reverb */}
                             {plugin.type === 'REVERB' ? (
                                <>
                                    <div className="flex gap-1 justify-between bg-gray-900 p-1 rounded">
                                        {[
                                            {id: 0, icon: Waves, label: 'Hall'},
                                            {id: 1, icon: Box, label: 'Room'},
                                            {id: 2, icon: Disc, label: 'Plate'}
                                        ].map(t => (
                                            <button 
                                                key={t.id}
                                                onClick={() => updatePluginParam(plugin.id, 'type', t.id)}
                                                className={`flex-1 p-1 rounded flex flex-col items-center justify-center gap-1 ${plugin.params.type === t.id ? 'bg-blue-600 text-white' : 'hover:bg-gray-700 text-gray-400'}`}
                                                title={t.label}
                                            >
                                                <t.icon size={12} />
                                            </button>
                                        ))}
                                    </div>
                                    <div className="flex flex-col gap-1">
                                         <div className="flex justify-between text-[10px] text-gray-400 uppercase">
                                             <span>Decay</span>
                                             <span>{(plugin.params.decay).toFixed(1)}s</span>
                                         </div>
                                         <input 
                                            type="range" min="0.1" max="10" step="0.1"
                                            value={plugin.params.decay}
                                            onChange={(e) => updatePluginParam(plugin.id, 'decay', Number(e.target.value))}
                                            className="h-1 bg-gray-700 rounded-full appearance-none accent-blue-500"
                                         />
                                     </div>
                                     <div className="flex flex-col gap-1">
                                         <div className="flex justify-between text-[10px] text-gray-400 uppercase">
                                             <span>Mix</span>
                                             <span>{(plugin.params.mix * 100).toFixed(0)}%</span>
                                         </div>
                                         <input 
                                            type="range" min="0" max="1" step="0.01"
                                            value={plugin.params.mix}
                                            onChange={(e) => updatePluginParam(plugin.id, 'mix', Number(e.target.value))}
                                            className="h-1 bg-gray-700 rounded-full appearance-none accent-blue-500"
                                         />
                                     </div>
                                </>
                             ) : (
                                 /* Generic Param Render */
                                 Object.entries(plugin.params).map(([key, value]) => (
                                     <div key={key} className="flex flex-col gap-1">
                                         <div className="flex justify-between text-[10px] text-gray-400 uppercase">
                                             <span>{key}</span>
                                             <span>{(value as number).toFixed(1)}</span>
                                         </div>
                                         <input 
                                            type="range"
                                            min={key === 'frequency' ? 20 : 0}
                                            max={key === 'frequency' ? 10000 : (key === 'drive' ? 100 : 2)}
                                            step={key === 'frequency' ? 10 : 0.01}
                                            value={value as number}
                                            onChange={(e) => updatePluginParam(plugin.id, key, Number(e.target.value))}
                                            className="h-1 bg-gray-700 rounded-full appearance-none accent-blue-500"
                                         />
                                     </div>
                                 ))
                             )}
                         </div>
                     )}
                 </div>
             ))}

             <div className="relative mt-2">
                 <button 
                    onClick={() => setIsAdding(!isAdding)}
                    className="w-full py-2 border border-dashed border-gray-700 rounded hover:border-blue-500 hover:text-blue-400 text-gray-500 text-xs flex items-center justify-center gap-1 transition-colors"
                 >
                    <Plus size={12} /> Add Effect
                 </button>

                 {isAdding && (
                     <div className="absolute top-full left-0 w-full mt-2 bg-gray-800 border border-gray-700 rounded-lg shadow-xl z-50 overflow-hidden">
                         {['DELAY', 'REVERB', 'DISTORTION', 'HIGHPASS', 'LOWPASS'].map(type => (
                             <button
                                key={type}
                                onClick={() => addPlugin(type as PluginType)}
                                className="w-full text-left px-4 py-2 text-xs hover:bg-gray-700 text-gray-300"
                             >
                                {type}
                             </button>
                         ))}
                     </div>
                 )}
             </div>
        </div>

        {/* Visualization Area */}
        <div className="flex-1 bg-gray-950 flex items-center justify-center text-gray-700 flex-col gap-4 relative overflow-hidden">
            {/* Background Aesthetic */}
            <div className="absolute inset-0 opacity-5 grid grid-cols-12 gap-4 pointer-events-none">
                 {Array.from({length: 12}).map((_, i) => (
                     <div key={i} className="h-full bg-blue-500 blur-3xl"></div>
                 ))}
            </div>

            <Sliders size={48} className="text-gray-800" />
            <p className="text-sm z-10">Select an effect on the left to adjust parameters</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { Upload, X, Loader2, Music, Layers } from 'lucide-react';
import { audioService } from '../services/audioEngine';
import { PluginType, AudioPlugin } from '../types';

interface StemSplitterProps {
  isOpen: boolean;
  onClose: () => void;
  onStemsGenerated: (stems: {name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]) => void;
}

export const StemSplitter: React.FC<StemSplitterProps> = ({ isOpen, onClose, onStemsGenerated }) => {
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleProcess = async () => {
    if (!file) return;
    setLoading(true);

    try {
        const stems = await audioService.separateStems(file);

        // Wait a bit to simulate processing time for UX
        setTimeout(() => {
            onStemsGenerated(stems);
            setLoading(false);
            onClose();
        }, 2000);

    } catch (e) {
        console.error(e);
        alert("Failed to separate stems");
        setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl w-full max-w-md flex flex-col overflow-hidden animate-slide-up">

        <div className="p-6 border-b border-gray-800 flex justify-between items-center">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <Layers className="text-blue-400" /> AI Stem Splitter
            </h2>
            <button onClick={onClose} className="text-gray-400 hover:text-white"><X size={20} /></button>
        </div>

        <div className="p-6 space-y-6">
            <div className="border-2 border-dashed border-gray-700 rounded-xl p-8 flex flex-col items-center justify-center text-center hover:border-blue-500/50 transition-colors bg-gray-800/30">
                <input 
                    type="file" 
                    id="stem-upload" 
                    className="hidden" 
                    accept="audio/*"
                    onChange={handleFileChange}
                />

                {file ? (
                    <div className="flex flex-col items-center gap-2">
                        <div className="p-3 bg-blue-500/20 rounded-full text-blue-400">
                            <Music size={24} />
                        </div>
                        <span className="font-medium text-white">{file.name}</span>
                        <span className="text-xs text-gray-400">{(file.size / 1024 / 1024).toFixed(2)} MB</span>
                        <button onClick={() => setFile(null)} className="text-xs text-red-400 hover:underline mt-2">Remove</button>
                    </div>
                ) : (
                    <label htmlFor="stem-upload" className="cursor-pointer flex flex-col items-center gap-2">
                        <Upload size={32} className="text-gray-500" />
                        <span className="text-sm text-gray-300 font-medium">Click to upload song</span>
                        <span className="text-xs text-gray-500">Supports MP3, WAV, FLAC</span>
                    </label>
                )}
            </div>

            <div className="bg-blue-900/20 border border-blue-500/20 p-3 rounded-lg text-xs text-blue-300">
                <strong>Note:</strong> We've improved the separation logic using multi-stage filtering, but this is still a browser-based simulation.
            </div>

            <button 
                onClick={handleProcess}
                disabled={!file || loading}
                className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-semibold flex items-center justify-center gap-2 transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin" size={18} />
                        Processing...
                    </>
                ) : (
                    "Separate into 4 Tracks"
                )}
            </button>
        </div>

      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { StemSplitter } from './components/StemSplitter';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, PluginType, AudioPlugin } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH } from './constants';
import { audioService } from './services/audioEngine';
import { Plus, Layers } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [], pan: [] }, showAutomation: false },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [], pan: [] }, showAutomation: false },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [], pan: [] }, showAutomation: false },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [], pan: [] }, showAutomation: false },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [], pan: [] },
    showAutomation: false
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);
  const [isStemSplitterOpen, setIsStemSplitterOpen] = useState(false);

  const [recordingTrackId, setRecordingTrackId] = useState<string | null>(null);
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Scroll Synchronization Refs ---
  const trackHeaderRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Scroll Sync ---
  const handleTimelineScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (trackHeaderRef.current && timelineRef.current) {
          trackHeaderRef.current.scrollTop = timelineRef.current.scrollTop;
      }
  };

  // --- Undo/Redo System ---

  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  // Initial History
  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          // Sync Audio Engine
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex + 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };


  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (recordingTrackId) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [recordingTrackId]);

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const finishRecording = async () => {
      if (!recordingTrackId) return;

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: recordingTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setRecordingTrackId(null);
  };

  const handleRecordToggle = async (trackId: string) => {
      if (recordingTrackId === trackId) {
          await handleStop();
          return;
      }
      if (recordingTrackId) return;

      try {
          await audioService.resume();
          await audioService.startRecording();
          setRecordingTrackId(trackId);
          recordStartTimeRef.current = pauseTimeRef.current;
          if (!playbackState.isPlaying) startPlayback(pauseTimeRef.current);
      } catch (e) {
          alert("Could not start recording. Please allow microphone access.");
      }
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [], pan: [] },
      showAutomation: false
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);

    // Check if Solo/Mute logic changed, apply real-time update
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.volume ? [...t.automation.volume] : [];
             // Insert point
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) {
                 points[existingIdx] = point;
             } else {
                 points.push(point);
             }
             return { ...t, automation: { ...t.automation, volume: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    );
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;

      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return; // Out of bounds

      const firstDuration = relativeSplit * clip.playbackRate; // Buffer duration

      const leftClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          duration: firstDuration,
          name: clip.name
      };

      const rightClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          startTime: splitTime,
          offset: clip.offset + firstDuration,
          duration: clip.duration - firstDuration,
          name: clip.name
      };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const newClips = clips.map(c => c.id === id ? { ...c, loop: !clip.loop } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Stem Separation ---

  const handleStemsGenerated = (stems: {name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]) => {
      const newTracks = [...tracks];
      const master = newTracks.pop();
      const generatedClips: AudioClip[] = [];

      stems.forEach((stem, i) => {
          const newTrack: Track = {
              id: uuidv4(),
              name: stem.name,
              color: TRACK_COLORS[(tracks.length + i) % TRACK_COLORS.length],
              volume: 0.8,
              muted: false,
              soloed: false,
              plugins: stem.plugins,
              automation: { volume: [], pan: [] },
              showAutomation: false
          };

          newTracks.push(newTrack);
          audioService.createTrackNodes(newTrack.id);
          audioService.updateTrackPlugins(newTrack.id, newTrack.plugins);

          generatedClips.push({
              id: uuidv4(),
              trackId: newTrack.id,
              buffer: stem.buffer,
              name: stem.name,
              startTime: 0,
              duration: stem.buffer.duration,
              offset: 0,
              gain: 1,
              pan: 0,
              playbackRate: 1,
              loop: false
          });
      });

      if (master) newTracks.push(master);

      updateStateWithHistory(newTracks, [...clips, ...generatedClips]);
  };

  // --- Export ---

  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();

      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}

        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* Track Headers - Sticky Left with Ref */}
        <div 
            ref={trackHeaderRef}
            className="flex-shrink-0 bg-gray-900 border-r border-gray-700 overflow-hidden z-10 shadow-xl"
            style={{ width: TRACK_HEADER_WIDTH, paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
        >
          {tracks.map(track => (
            <TrackControl 
              key={track.id} 
              track={track} 
              onUpdate={updateTrack}
              onDelete={deleteTrack}
              isRecording={recordingTrackId === track.id}
              onRecordToggle={handleRecordToggle}
              onOpenEditor={setEditingTrackId}
              onToggleAutomation={toggleAutomation}
            />
          ))}

          <div className="p-3 space-y-2">
             <button 
                onClick={addTrack}
                className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
             >
                <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors">
                    <Plus size={14} /> 
                </div>
                <span>Add New Track</span>
             </button>

             <button 
                onClick={() => setIsStemSplitterOpen(true)}
                className="w-full py-2 bg-gradient-to-r from-blue-900/50 to-purple-900/50 hover:from-blue-900 hover:to-purple-900 border border-blue-500/30 rounded-lg text-blue-300 text-xs flex items-center justify-center gap-2 transition-all"
             >
                 <Layers size={14} /> AI Stem Splitter
             </button>
          </div>
        </div>

        {/* Timeline Area - Main Scroll with Ref, event listener syncs headers */}
        <div className="flex-1 overflow-hidden relative flex flex-col">
            <div 
                ref={timelineRef}
                onScroll={handleTimelineScroll}
                className="flex-1 overflow-auto custom-scrollbar"
                style={{ paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
            >
                <Timeline 
                    tracks={tracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipUpdate={updateClip}
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    snap={snap}
                    tool={tool}
                    onDeleteClip={deleteClip}
                    onDuplicateClip={duplicateClip}
                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}

                    onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
                    selectedClipId={selectedClipId}
                    onCopyClip={handleCopyClip}
                    onPasteClip={handlePasteClip}
                    canPaste={!!clipboardClip}
                    onLoopClip={handleLoopToggle}
                />
            </div>
        </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}

      <StemSplitter 
        isOpen={isStemSplitterOpen} 
        onClose={() => setIsStemSplitterOpen(false)}
        onStemsGenerated={handleStemsGenerated}
      />
    </div>
  );
}

export default App;

