  name: string;
  color: string;
  volume: number; // 0.0 to 1.0
  muted: boolean;
  soloed: boolean;
  plugins: AudioPlugin[];
  isMaster?: boolean;
  // Key is the parameter ID (e.g., 'volume', 'pan', 'pluginId:paramName')
  automation: Record<string, AutomationPoint[]>; 
  showAutomation?: boolean; 
  selectedAutomationId?: string; // Which lane is currently visible/editable
}

export interface AutomationPoint {
  id: string;
  time: number; 
  value: number; // Normalized 0-1
}

export interface AudioClip {
  id: string;
  trackId: string;
  buffer: AudioBuffer;
  name: string;
  startTime: number; 
  duration: number; 
  offset: number; 

  gain: number; 
  pan: number; 
  playbackRate: number; 
  loop: boolean;
}

export enum DragType {
  CLIP = 'CLIP',
  FILE = 'FILE'
}

export interface DragItem {
  type: DragType;
  id?: string; 
  files?: FileList; 
}

export interface PlaybackState {
  isPlaying: boolean;
  currentTime: number; 
}

export type PluginType = 'DELAY' | 'REVERB' | 'DISTORTION' | 'HIGHPASS' | 'LOWPASS';

export interface AudioPlugin {
  id: string;
  type: PluginType;
  enabled: boolean;
  params: {
    [key: string]: number;
  };
}

export type ToolType = 'MOVE' | 'BLADE';

export interface HistoryState {
  tracks: Track[];
  clips: AudioClip[];
}

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  // Map plugin ID to its nodes for automation targeting
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        // Expose param for automation
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         // Expose params
         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, // Simplification: automates wet gain
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Offline Stem Separation (Improved) ---

  public async separateStems(file: File): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);
    const duration = originalBuffer.duration;
    const sampleRate = originalBuffer.sampleRate;

    // We create an OfflineAudioContext to render the separation physics
    const offlineCtx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);

    // Helper to create a source node
    const createSource = () => {
        const src = offlineCtx.createBufferSource();
        src.buffer = originalBuffer;
        return src;
    };

    // 1. Bass Stem (Lowpass steep)
    // We simulate by rendering specific passes
    const renderStem = async (setup: (ctx: OfflineAudioContext, src: AudioBufferSourceNode) => AudioNode) => {
        const ctx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);
        const src = ctx.createBufferSource();
        src.buffer = originalBuffer;
        const out = setup(ctx, src);
        out.connect(ctx.destination);
        src.start(0);
        return await ctx.startRendering();
    };

    // -- Vocals (Center + Mid Range) --
    const vocalsBuffer = await renderStem((ctx, src) => {
        // Highpass to remove bass, Lowpass to remove air
        const hp = ctx.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = 250;
        hp.Q.value = 1; // Slight resonance to keep body

        const lp = ctx.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = 8000;

        src.connect(hp);
        hp.connect(lp);
        return lp;
    });

    // -- Bass (Low End) --
    const bassBuffer = await renderStem((ctx, src) => {
        const lp = ctx.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = 200;
        // Stack filters for 24dB/oct slope
        const lp2 = ctx.createBiquadFilter();
        lp2.type = 'lowpass';
        lp2.frequency.value = 200;

        src.connect(lp);
        lp.connect(lp2);
        return lp2;
    });

    // -- Backing/Instrumental (Phase Cancellation) --
    // This removes anything panned DEAD CENTER (usually vocals + kick + bass)
    // We mix it back with bass stem later in UI? No, just give them the raw instrumental
    const backingBuffer = await renderStem((ctx, src) => {
        // We need to implement L - R
        const splitter = ctx.createChannelSplitter(2);
        const merger = ctx.createChannelMerger(2);
        const inverter = ctx.createGain();
        inverter.gain.value = -1;

        src.connect(splitter);

        // Left Channel: L + (-R)
        // Right Channel: R + (-L) 

        // This is tricky in WebAudio graph without a script processor, 
        // Simple karaoke is often L = L-R, R = R-L

        const L = ctx.createGain();
        const R = ctx.createGain();

        splitter.connect(L, 0); // L
        splitter.connect(R, 1); // R

        // To destination L: L - R
        L.connect(merger, 0, 0);
        R.connect(inverter);
        inverter.connect(merger, 0, 0);

        // To destination R: R - L
        const inverterL = ctx.createGain();
        inverterL.gain.value = -1;
        L.connect(inverterL);
        inverterL.connect(merger, 0, 1);
        R.connect(merger, 0, 1);

        return merger;
    });

    // -- Drums (High Pass + Notch on Vocals) --
    const drumsBuffer = await renderStem((ctx, src) => {
         const hp = ctx.createBiquadFilter();
         hp.type = 'highpass';
         hp.frequency.value = 150;

         const notch = ctx.createBiquadFilter();
         notch.type = 'notch';
         notch.frequency.value = 1000; // Cut Vocal fundamental

         src.connect(hp);
         hp.connect(notch);
         return notch;
    });

    return [
        { name: 'Vocals', type: 'HIGHPASS', buffer: vocalsBuffer, plugins: [] },
        { name: 'Bass', type: 'LOWPASS', buffer: bassBuffer, plugins: [] },
        { name: 'Instrumental', type: 'LOWPASS', buffer: backingBuffer, plugins: [] },
        { name: 'Drums', type: 'HIGHPASS', buffer: drumsBuffer, plugins: [] }
    ];
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              // Map paramId to actual AudioParam
              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  // Plugin Parameter: "pluginId:paramName"
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);

                  // Map friendly name to internal node property if needed
                  // We stored them as _frequency, _time, _mix etc in factory
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      // Set start value based on current track settings (bit complex to find specific start value, default to current)
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          // Scale Normalized Value (0-1) to Actual Parameter Range
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      // Scaling logic based on parameter type
      if (paramName === 'frequency') {
          // Logarithmic scale 20Hz to 10kHz
          // min * (max/min)^v
          return 20 * Math.pow(10000/20, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; // 0 to 1s delay
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        // Clear plugin schedules
        nodes.pluginMap.forEach(node => {
            // Cancel all potential params
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import React, { useEffect, useRef, useState } from 'react';
import { Track } from '../types';
import { Volume2, VolumeX, Mic, Headphones, Activity, TrendingUp, ChevronDown } from 'lucide-react';
import { audioService } from '../services/audioEngine';

interface TrackControlProps {
  track: Track;
  onUpdate: (id: string, updates: Partial<Track>) => void;
  onDelete: (id: string) => void;
  isRecording: boolean;
  onRecordToggle: (trackId: string) => void;
  onOpenEditor: (trackId: string) => void;
  onToggleAutomation: (trackId: string) => void;
}

export const TrackControl: React.FC<TrackControlProps> = ({ 
    track, 
    onUpdate, 
    onDelete, 
    isRecording, 
    onRecordToggle,
    onOpenEditor,
    onToggleAutomation
}) => {
  const isMaster = track.isMaster;
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [peak, setPeak] = useState(0);

  // Meter Animation
  useEffect(() => {
    let animationId: number;
    const analyser = audioService.getTrackAnalyser(track.id);

    if (analyser && canvasRef.current) {
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);
        const ctx = canvasRef.current.getContext('2d');
        let localPeak = 0;
        let peakHoldTimer = 0;

        const draw = () => {
            if (!ctx) return;
            analyser.getByteTimeDomainData(dataArray);

            let sum = 0;
            let framePeak = 0;

            for(let i = 0; i < bufferLength; i++) {
                const sample = (dataArray[i] - 128) / 128; 
                sum += sample * sample;
                if (Math.abs(sample) > framePeak) framePeak = Math.abs(sample);
            }

            const rms = Math.sqrt(sum / bufferLength);

            if (framePeak > localPeak) {
                localPeak = framePeak;
                peakHoldTimer = 60; 
            } else {
                peakHoldTimer--;
                if (peakHoldTimer <= 0) localPeak *= 0.95; 
            }

            setPeak(localPeak);

            const width = canvasRef.current!.width;
            const height = canvasRef.current!.height;

            ctx.clearRect(0, 0, width, height);

            ctx.fillStyle = '#111827';
            ctx.fillRect(0, 0, width, height);

            const rmsWidth = width * Math.min(1, Math.pow(rms * 4, 0.6));

            const gradient = ctx.createLinearGradient(0, 0, width, 0);
            gradient.addColorStop(0, '#10b981'); 
            gradient.addColorStop(0.6, '#f59e0b'); 
            gradient.addColorStop(0.85, '#ef4444'); 

            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, rmsWidth, height);

            const peakPos = width * Math.min(1, Math.pow(localPeak * 4, 0.6));
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(peakPos, 0, 2, height);

            if (localPeak >= 0.98) {
                ctx.fillStyle = '#ef4444';
                ctx.fillRect(width - 4, 0, 4, height);
            }

            animationId = requestAnimationFrame(draw);
        };
        draw();
    }
    return () => cancelAnimationFrame(animationId);
  }, [track.id]);

  return (
    <div 
        className={`flex flex-col p-3 border-b ${isMaster ? 'bg-gray-900 border-t border-blue-500/30' : 'bg-gray-800 border-gray-700'} relative group select-none transition-all`}
        style={{ height: track.showAutomation ? '160px' : '96px' }}
        onDoubleClick={() => onOpenEditor(track.id)}
    >
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
            {!isMaster && <div className="w-3 h-3 rounded-full" style={{ backgroundColor: track.color }} />}
            {isMaster && <Activity size={14} className="text-blue-400" />}
            <span className={`font-semibold text-sm truncate w-24 ${isMaster ? 'text-blue-400' : 'text-gray-200'}`} title={track.name}>
            {track.name}
            </span>
        </div>
        {!isMaster && (
            <button 
                onClick={(e) => { e.stopPropagation(); onDelete(track.id); }}
                className="text-xs text-gray-500 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"
            >
                Delete
            </button>
        )}
      </div>

      <div className="flex items-center gap-2 mb-2">
        {!isMaster && (
            <>
                <button
                onClick={(e) => { e.stopPropagation(); onRecordToggle(track.id); }}
                className={`p-1.5 rounded-full transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-gray-700 text-red-500 hover:bg-gray-600 hover:text-red-400'}`}
                title="Record"
                >
                <div className={`w-3 h-3 rounded-full ${isRecording ? 'bg-white' : 'bg-current'}`} />
                </button>

                <button
                onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { muted: !track.muted }); }}
                className={`p-1 rounded ${track.muted ? 'bg-red-500/20 text-red-500' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Mute"
                >
                {track.muted ? <VolumeX size={14} /> : <Volume2 size={14} />}
                </button>
                <button
                onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { soloed: !track.soloed }); }}
                className={`p-1 rounded ${track.soloed ? 'bg-yellow-500/20 text-yellow-500' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Solo"
                >
                <Headphones size={14} />
                </button>
                <button
                onClick={(e) => { e.stopPropagation(); onToggleAutomation(track.id); }}
                className={`p-1 rounded ${track.showAutomation ? 'bg-blue-500/20 text-blue-400' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Automation"
                >
                <TrendingUp size={14} />
                </button>
            </>
        )}

        {isMaster && <span className="text-[10px] text-gray-500 uppercase font-bold">Vol</span>}

        <div className="flex-1" onClick={e => e.stopPropagation()}>
            <input
                type="range"
                min="0"
                max="1"
                step="0.01"
                value={track.volume}
                onChange={(e) => onUpdate(track.id, { volume: parseFloat(e.target.value) })}
                className={`w-full h-1 rounded-lg appearance-none cursor-pointer ${isMaster ? 'accent-blue-400 bg-gray-700' : 'accent-blue-500 bg-gray-600'}`}
                disabled={track.showAutomation && track.selectedAutomationId === 'volume'}
            />
        </div>
      </div>

      <div className="h-2 w-full bg-gray-900 rounded overflow-hidden mt-1 relative border border-gray-800">
          <canvas ref={canvasRef} width={200} height={8} className="w-full h-full block" />
          <div className="absolute inset-0 flex justify-between px-2 pointer-events-none opacity-50">
               <div className="w-px h-full bg-black/50" style={{ left: '50%' }}></div>
               <div className="w-px h-full bg-black/50" style={{ left: '75%' }}></div>
          </div>
      </div>

      {isMaster && (
          <div className="flex justify-between text-[9px] text-gray-500 font-mono mt-0.5 px-1">
              <span>-inf</span>
              <span>-12</span>
              <span>-6</span>
              <span>0dB</span>
          </div>
      )}

      {/* Improved Automation Header with Dropdown */}
      {track.showAutomation && (
           <div className="mt-4 pt-2 border-t border-gray-700 flex flex-col gap-1 animate-fade-in">
               <div className="flex items-center justify-between">
                   <div className="flex items-center gap-1 text-blue-400 text-[10px] font-bold uppercase">
                       <TrendingUp size={10} /> Auto:
                   </div>
                   {/* Automation Type Selector */}
                   <div className="relative">
                       <select 
                        className="bg-gray-900 text-[10px] text-gray-300 border border-gray-700 rounded px-1 py-0.5 outline-none focus:border-blue-500 w-32 appearance-none"
                        value={track.selectedAutomationId || 'volume'}
                        onChange={(e) => onUpdate(track.id, { selectedAutomationId: e.target.value })}
                        onClick={(e) => e.stopPropagation()}
                       >
                           <option value="volume">Volume</option>
                           <option value="pan">Pan</option>
                           {/* Dynamic Plugin Params */}
                           {track.plugins.map(p => {
                               if (p.type === 'REVERB') return (
                                   <React.Fragment key={p.id}>
                                        <option value={`${p.id}:mix`}>Reverb Mix</option>
                                        <option value={`${p.id}:decay`}>Reverb Decay</option>
                                   </React.Fragment>
                               );
                               if (p.type === 'DELAY') return <option key={p.id} value={`${p.id}:time`}>Delay Time</option>;
                               if (p.type === 'DISTORTION') return <option key={p.id} value={`${p.id}:drive`}>Distortion</option>;
                               if (p.type === 'HIGHPASS' || p.type === 'LOWPASS') return <option key={p.id} value={`${p.id}:frequency`}>{p.type} Freq</option>;
                               return null;
                           })}
                       </select>
                       <ChevronDown size={10} className="absolute right-1 top-1.5 text-gray-500 pointer-events-none" />
                   </div>
               </div>
               <span className="text-[9px] text-gray-500 text-right">Click timeline to add points</span>
           </div>
      )}

    </div>
  );
};

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, Scissors } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipUpdate: (id: string, newTime: number, newTrackId?: string) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;
  onDeleteClip: (id: string) => void;
  onDuplicateClip: (id: string) => void;
  onRenameClip: (id: string, newName: string) => void;

  onSelectClip: (id: string | null) => void;
  selectedClipId: string | null;
  onCopyClip: (id: string) => void;
  onPasteClip: (time: number, trackId: string) => void;
  canPaste: boolean;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND';
    targetId?: string; 
    time?: number; 
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  snap,
  tool,
  onClipUpdate, 
  onFileDrop,
  onSeek,
  onDeleteClip,
  onDuplicateClip,
  onRenameClip,
  onSelectClip,
  selectedClipId,
  onCopyClip,
  onPasteClip,
  canPaste,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<number>(0);
  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      window.addEventListener('click', closeMenu);
      return () => window.removeEventListener('click', closeMenu);
  }, []);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      const snapInterval = beat; // Snap to quarter notes
      return Math.round(time / snapInterval) * snapInterval;
  };

  // --- Handlers ---

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId) return;

    const target = e.target as HTMLElement;
    const clipElement = target.closest('[data-clip-id]');

    // Automation Point Click
    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const scrollLeft = timelineRef.current?.scrollLeft || 0;
                 const clickX = e.clientX - rect.left + scrollLeft;
                 const time = Math.max(0, clickX / zoom);

                 // Calculate Y value (inverted: top is 1, bottom is 0)
                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));

                 // Default to 'volume' if undefined, otherwise use selected
                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const scrollLeft = timelineRef.current?.scrollLeft || 0;
             const clickX = e.clientX - rect.left + scrollLeft;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    // Normal Seek Logic
    if (!clipElement && !automationLane) {
        onSelectClip(null);
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;
        const scrollLeft = timelineRef.current?.scrollLeft || 0;
        const clickX = e.clientX - rect.left + scrollLeft;
        const seekTime = Math.max(0, (clickX / zoom));
        onSeek(snapToGrid(seekTime));
    }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const scrollLeft = timelineRef.current?.scrollLeft || 0;
    const clickX = e.clientX - rect.left + scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        if (file.type.startsWith('audio/')) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const adjustedTime = Math.max(0, (clickX / zoom) - dragOffset);
        onClipUpdate(draggedClipId, snapToGrid(adjustedTime), trackId);
        setDraggedClipId(null);
        setDragOffset(0);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE') {
         e.preventDefault(); 
         return;
     }
     onSelectClip(clip.id);
     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     setDragOffset(offsetTime);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      onSelectClip(clipId);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const scrollLeft = timelineRef.current?.scrollLeft || 0;
      const clickX = e.clientX - (rect?.left || 0) + scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP' && contextMenu.targetId) {
           switch(action) {
              case 'delete': onDeleteClip(contextMenu.targetId); break;
              case 'duplicate': onDuplicateClip(contextMenu.targetId); break;
              case 'rename': 
                  const clip = clips.find(c => c.id === contextMenu.targetId);
                  if (clip) {
                      const newName = prompt("Rename clip:", clip.name);
                      if (newName) onRenameClip(contextMenu.targetId, newName);
                  }
                  break;
              case 'copy': onCopyClip(contextMenu.targetId); break;
              case 'loop': onLoopClip(contextMenu.targetId); break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClip(contextMenu.time, contextMenu.targetId);
           }
      }
      setContextMenu(null);
  };

  // Helper to draw automation lines
  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];

      if (!points || points.length === 0) return null;

      // Sort points by time
      const sortedPoints = [...points].sort((a, b) => a.time - b.time);

      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * 64; // Height of lane is 64px
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <circle 
                    key={p.id} 
                    cx={p.time * zoom} 
                    cy={(1 - p.value) * 64} 
                    r="4" 
                    fill="#3b82f6" 
                    className="hover:r-6 transition-all cursor-pointer"
                  />
              ))}
          </>
      );
  };

  return (
    <div 
      className={`flex-1 overflow-auto bg-gray-950 relative custom-scrollbar flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
      ref={timelineRef}
      onClick={handleTimelineClick}
    >
        {/* Playhead */}
        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler */}
        <div className="h-8 border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex" style={{ width: `${totalBars * pixelsPerBar}px` }}>
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     {/* Quarter Beats */}
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}
        </div>

      <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
        {tracks.map(track => (
          <div key={track.id} className="flex flex-col">
            {/* Standard Track Lane */}
            <div 
                className="relative h-24 border-b border-gray-800 hover:bg-white/5 transition-colors"
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, track.id)}
                onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                style={{ 
                    backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                    backgroundSize: `${pixelsPerBar}px 100%`,
                    backgroundPosition: '0 0'
                }}
            >
                <div 
                    className="absolute inset-0 pointer-events-none" 
                    style={{
                        backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                        backgroundSize: `${pixelsPerBeat}px 100%`,
                        opacity: 0.3
                    }}
                />

                {clips.filter(c => c.trackId === track.id).map(clip => (
                <div
                    key={clip.id}
                    data-clip-id={clip.id}
                    draggable={tool === 'MOVE'}
                    onDragStart={(e) => handleDragStart(e, clip)}
                    onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                    onDoubleClick={() => onSelectClip(clip.id)}
                    className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                    ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                    ${selectedClipId === clip.id ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                    style={{
                    left: `${clip.startTime * zoom}px`,
                    width: `${(clip.duration / clip.playbackRate) * zoom}px`,
                    }}
                >
                    <div 
                        className="absolute inset-0 opacity-60"
                        style={{ backgroundColor: track.color }}
                    ></div>

                    {clip.loop && (
                        <div className="absolute top-0 right-0 p-1 text-white/50">
                            <RotateCw size={10} />
                        </div>
                    )}

                    <div className="absolute inset-0 z-10">
                        <Waveform 
                            clip={clip} 
                            width={Math.ceil((clip.duration / clip.playbackRate) * zoom)} 
                            height={80} 
                            color="#ffffff"
                        />
                    </div>

                    <div className="absolute top-1 left-1 z-20 max-w-full">
                        <div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">
                            {clip.name}
                        </div>
                    </div>
                </div>
                ))}
            </div>

            {/* Automation Lane */}
            {track.showAutomation && (
                <div 
                    className="h-16 bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair"
                    data-automation-track-id={track.id}
                    style={{ minWidth: `${totalBars * pixelsPerBar}px` }}
                >
                    <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                    <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">
                        {track.selectedAutomationId === 'pan' ? 'Pan' : 
                         track.selectedAutomationId === 'volume' ? 'Vol' : 
                         track.selectedAutomationId?.split(':')[1].toUpperCase()}
                    </div>
                    <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>
                        {renderAutomationPoints(track)}
                    </svg>
                </div>
            )}
          </div>
        ))}
        <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">
             End of tracks
        </div>
      </div>

      {contextMenu && (
          <div 
              className="fixed z-50 w-48 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
              style={{ top: contextMenu.y, left: contextMenu.x }}
          >
              {contextMenu.type === 'CLIP' ? (
                  <>
                    <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Copy size={14} /> Copy
                    </button>
                     <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <RotateCw size={14} /> Toggle Loop
                    </button>
                    <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Pencil size={14} /> Rename
                    </button>
                    <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Copy size={14} /> Duplicate
                    </button>
                    <div className="h-px bg-gray-700 my-1" />
                    <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2">
                        <Trash2 size={14} /> Delete
                    </button>
                  </>
              ) : (
                  <>
                    <button 
                        onClick={(e) => handleMenuAction(e, 'paste')} 
                        disabled={!canPaste}
                        className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}
                    >
                        <ClipboardPaste size={14} /> Paste
                    </button>
                  </>
              )}
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { StemSplitter } from './components/StemSplitter';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, PluginType, AudioPlugin } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH } from './constants';
import { audioService } from './services/audioEngine';
import { Plus, Layers } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);
  const [isStemSplitterOpen, setIsStemSplitterOpen] = useState(false);

  const [recordingTrackId, setRecordingTrackId] = useState<string | null>(null);
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Scroll Synchronization Refs ---
  const trackHeaderRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Scroll Sync ---
  const handleTimelineScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (trackHeaderRef.current && timelineRef.current) {
          trackHeaderRef.current.scrollTop = timelineRef.current.scrollTop;
      }
  };

  // --- Undo/Redo System ---

  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  // Initial History
  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          // Sync Audio Engine
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex + 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };


  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (recordingTrackId) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [recordingTrackId]);

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const finishRecording = async () => {
      if (!recordingTrackId) return;

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: recordingTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setRecordingTrackId(null);
  };

  const handleRecordToggle = async (trackId: string) => {
      if (recordingTrackId === trackId) {
          await handleStop();
          return;
      }
      if (recordingTrackId) return;

      try {
          await audioService.resume();
          await audioService.startRecording();
          setRecordingTrackId(trackId);
          recordStartTimeRef.current = pauseTimeRef.current;
          if (!playbackState.isPlaying) startPlayback(pauseTimeRef.current);
      } catch (e) {
          alert("Could not start recording. Please allow microphone access.");
      }
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);

    // Check if Solo/Mute logic changed, apply real-time update
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             // Insert point
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) {
                 points[existingIdx] = point;
             } else {
                 points.push(point);
             }
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    );
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;

      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return; // Out of bounds

      const firstDuration = relativeSplit * clip.playbackRate; // Buffer duration

      const leftClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          duration: firstDuration,
          name: clip.name
      };

      const rightClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          startTime: splitTime,
          offset: clip.offset + firstDuration,
          duration: clip.duration - firstDuration,
          name: clip.name
      };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const newClips = clips.map(c => c.id === id ? { ...c, loop: !clip.loop } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Stem Separation ---

  const handleStemsGenerated = (stems: {name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]) => {
      const newTracks = [...tracks];
      const master = newTracks.pop();
      const generatedClips: AudioClip[] = [];

      stems.forEach((stem, i) => {
          const newTrack: Track = {
              id: uuidv4(),
              name: stem.name,
              color: TRACK_COLORS[(tracks.length + i) % TRACK_COLORS.length],
              volume: 0.8,
              muted: false,
              soloed: false,
              plugins: stem.plugins,
              automation: { volume: [] },
              showAutomation: false,
              selectedAutomationId: 'volume'
          };

          newTracks.push(newTrack);
          audioService.createTrackNodes(newTrack.id);
          audioService.updateTrackPlugins(newTrack.id, newTrack.plugins);

          generatedClips.push({
              id: uuidv4(),
              trackId: newTrack.id,
              buffer: stem.buffer,
              name: stem.name,
              startTime: 0,
              duration: stem.buffer.duration,
              offset: 0,
              gain: 1,
              pan: 0,
              playbackRate: 1,
              loop: false
          });
      });

      if (master) newTracks.push(master);

      updateStateWithHistory(newTracks, [...clips, ...generatedClips]);
  };

  // --- Export ---

  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();

      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}

        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* Track Headers - Sticky Left with Ref */}
        <div 
            ref={trackHeaderRef}
            className="flex-shrink-0 bg-gray-900 border-r border-gray-700 overflow-hidden z-10 shadow-xl"
            style={{ width: TRACK_HEADER_WIDTH, paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
        >
          {tracks.map(track => (
            <TrackControl 
              key={track.id} 
              track={track} 
              onUpdate={updateTrack}
              onDelete={deleteTrack}
              isRecording={recordingTrackId === track.id}
              onRecordToggle={handleRecordToggle}
              onOpenEditor={setEditingTrackId}
              onToggleAutomation={toggleAutomation}
            />
          ))}

          <div className="p-3 space-y-2">
             <button 
                onClick={addTrack}
                className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
             >
                <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors">
                    <Plus size={14} /> 
                </div>
                <span>Add New Track</span>
             </button>

             <button 
                onClick={() => setIsStemSplitterOpen(true)}
                className="w-full py-2 bg-gradient-to-r from-blue-900/50 to-purple-900/50 hover:from-blue-900 hover:to-purple-900 border border-blue-500/30 rounded-lg text-blue-300 text-xs flex items-center justify-center gap-2 transition-all"
             >
                 <Layers size={14} /> AI Stem Splitter
             </button>
          </div>
        </div>

        {/* Timeline Area - Main Scroll with Ref, event listener syncs headers */}
        <div className="flex-1 overflow-hidden relative flex flex-col">
            <div 
                ref={timelineRef}
                onScroll={handleTimelineScroll}
                className="flex-1 overflow-auto custom-scrollbar"
                style={{ paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
            >
                <Timeline 
                    tracks={tracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipUpdate={updateClip}
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    snap={snap}
                    tool={tool}
                    onDeleteClip={deleteClip}
                    onDuplicateClip={duplicateClip}
                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}

                    onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
                    selectedClipId={selectedClipId}
                    onCopyClip={handleCopyClip}
                    onPasteClip={handlePasteClip}
                    canPaste={!!clipboardClip}
                    onLoopClip={handleLoopToggle}
                />
            </div>
        </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}

      <StemSplitter 
        isOpen={isStemSplitterOpen} 
        onClose={() => setIsStemSplitterOpen(false)}
        onStemsGenerated={handleStemsGenerated}
      />
    </div>
  );
}

export default App;

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- "Serato-Style" Analytical Stem Separation ---

  public async separateStems(file: File): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);
    const duration = originalBuffer.duration;
    const sampleRate = originalBuffer.sampleRate;

    // Helper to render an offline context
    const render = async (setup: (ctx: OfflineAudioContext, src: AudioBufferSourceNode) => void) => {
        const ctx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);
        const src = ctx.createBufferSource();
        src.buffer = originalBuffer;
        setup(ctx, src);
        src.start(0);
        return await ctx.startRendering();
    };

    // 1. Bass: Aggressive Lowpass with steep slope (simulating 24dB/oct)
    const bassBuffer = await render((ctx, src) => {
        const lp1 = ctx.createBiquadFilter();
        lp1.type = 'lowpass';
        lp1.frequency.value = 180;
        lp1.Q.value = 0.7; // Butterworth

        const lp2 = ctx.createBiquadFilter();
        lp2.type = 'lowpass';
        lp2.frequency.value = 180;

        // Force Mono for Bass
        const merger = ctx.createChannelMerger(2);

        src.connect(lp1);
        lp1.connect(lp2);
        lp2.connect(merger, 0, 0); // L -> L
        lp2.connect(merger, 0, 1); // L -> R (Mono)

        merger.connect(ctx.destination);
    });

    // 2. Instrumental (Backing): Mid-Side Subtraction (Phase Cancellation)
    // This removes the "Center" channel where vocals/kick/snare usually sit.
    // Algorithm: Side = (L - R).
    const backingBuffer = await render((ctx, src) => {
        // Highpass to remove bass mud from the sides
        const hp = ctx.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = 200;

        const splitter = ctx.createChannelSplitter(2);
        const inverter = ctx.createGain();
        inverter.gain.value = -1;
        const merger = ctx.createChannelMerger(2);

        src.connect(hp);
        hp.connect(splitter);

        // L - R logic
        // We want Side content on both L and R speakers
        const leftGain = ctx.createGain();
        const rightGain = ctx.createGain();

        // L -> LeftGain
        splitter.connect(leftGain, 0);
        // R -> Inverter -> LeftGain
        splitter.connect(inverter, 1);
        inverter.connect(leftGain);

        // Connect the result (L-R) to both outputs
        leftGain.connect(merger, 0, 0);
        leftGain.connect(merger, 0, 1);

        merger.connect(ctx.destination);
    });

    // 3. Vocals: Center Channel Extraction + Filtering
    // Algorithm: Center = (L + R) / 2. Then filtering to remove kick/snare lows and hi-hat highs.
    const vocalBuffer = await render((ctx, src) => {
        // 1. Get Center
        const merger = ctx.createChannelMerger(1); // Sum to mono
        src.connect(merger, 0, 0);
        src.connect(merger, 1, 0);

        // 2. Filter Chain for Vocals
        const hp = ctx.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = 300; // Cut kick/bass

        const lp = ctx.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = 8000; // Cut air/cymbals

        // Boost presence
        const presence = ctx.createBiquadFilter();
        presence.type = 'peaking';
        presence.frequency.value = 3000;
        presence.gain.value = 4;
        presence.Q.value = 1;

        merger.connect(hp);
        hp.connect(lp);
        lp.connect(presence);

        // Split mono back to stereo
        const stereo = ctx.createChannelSplitter(2);
        presence.connect(stereo);

        const finalMerger = ctx.createChannelMerger(2);
        stereo.connect(finalMerger, 0, 0);
        stereo.connect(finalMerger, 0, 1);

        finalMerger.connect(ctx.destination);
    });

    // 4. Drums: Transient Isolation (Simulation)
    // Highpass the original + Gate.
    // We assume drums are the loudest transient peaks in the signal.
    const drumBuffer = await render((ctx, src) => {
        const hp = ctx.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = 100;

        // Dynamics Compressor acting as an expander/transient shaper
        const shaper = ctx.createDynamicsCompressor();
        shaper.threshold.value = -20;
        shaper.knee.value = 0;
        shaper.ratio.value = 20; // Hard limit
        shaper.attack.value = 0; // Instant
        shaper.release.value = 0.1; // Fast release

        // We actually want the inverse (the peaks), so we mix dry but aggressive EQ
        // Better strategy for "Analysis" without ML:
        // Drums = Original - Vocals - Backing (Roughly)

        // Let's do Phase Inversion subtraction: Original + (-Vocal)
        const vocalSrc = ctx.createBufferSource();
        vocalSrc.buffer = vocalBuffer; // Use the vocal buffer we just generated
        const vocalInv = ctx.createGain();
        vocalInv.gain.value = -1; // Invert phase

        const backingSrc = ctx.createBufferSource();
        backingSrc.buffer = backingBuffer;
        const backingInv = ctx.createGain();
        backingInv.gain.value = -0.8; // Subtract backing too

        src.connect(ctx.destination);
        vocalSrc.connect(vocalInv);
        vocalInv.connect(ctx.destination);
        backingSrc.connect(backingInv);
        backingInv.connect(ctx.destination);

        vocalSrc.start(0);
        backingSrc.start(0);
    });

    return [
        { name: 'Vocals (Center)', type: 'HIGHPASS', buffer: vocalBuffer, plugins: [] },
        { name: 'Instrumental (Side)', type: 'LOWPASS', buffer: backingBuffer, plugins: [] },
        { name: 'Bass (Low)', type: 'LOWPASS', buffer: bassBuffer, plugins: [] },
        { name: 'Drums (Residue)', type: 'HIGHPASS', buffer: drumBuffer, plugins: [] }
    ];
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, Scissors } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipUpdate: (id: string, newTime: number, newTrackId?: string) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;
  onDeleteClip: (id: string) => void;
  onDuplicateClip: (id: string) => void;
  onRenameClip: (id: string, newName: string) => void;

  onSelectClip: (id: string | null) => void;
  selectedClipId: string | null;
  onCopyClip: (id: string) => void;
  onPasteClip: (time: number, trackId: string) => void;
  canPaste: boolean;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND';
    targetId?: string; 
    time?: number; 
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  snap,
  tool,
  onClipUpdate, 
  onFileDrop,
  onSeek,
  onDeleteClip,
  onDuplicateClip,
  onRenameClip,
  onSelectClip,
  selectedClipId,
  onCopyClip,
  onPasteClip,
  canPaste,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<number>(0);
  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      window.addEventListener('click', closeMenu);
      return () => window.removeEventListener('click', closeMenu);
  }, []);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      const snapInterval = beat; // Snap to quarter notes
      return Math.round(time / snapInterval) * snapInterval;
  };

  // --- Handlers ---

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId) return;

    const target = e.target as HTMLElement;
    const clipElement = target.closest('[data-clip-id]');

    // Automation Point Click
    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const scrollLeft = timelineRef.current?.scrollLeft || 0;
                 const clickX = e.clientX - rect.left + scrollLeft;
                 const time = Math.max(0, clickX / zoom);

                 // Calculate Y value (inverted: top is 1, bottom is 0)
                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));

                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const scrollLeft = timelineRef.current?.scrollLeft || 0;
             const clickX = e.clientX - rect.left + scrollLeft;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    // Normal Seek Logic
    if (!clipElement && !automationLane) {
        onSelectClip(null);
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;
        const scrollLeft = timelineRef.current?.scrollLeft || 0;
        const clickX = e.clientX - rect.left + scrollLeft;
        const seekTime = Math.max(0, (clickX / zoom));
        onSeek(snapToGrid(seekTime));
    }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const scrollLeft = timelineRef.current?.scrollLeft || 0;
    const clickX = e.clientX - rect.left + scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        if (file.type.startsWith('audio/')) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const adjustedTime = Math.max(0, (clickX / zoom) - dragOffset);
        onClipUpdate(draggedClipId, snapToGrid(adjustedTime), trackId);
        setDraggedClipId(null);
        setDragOffset(0);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE') {
         e.preventDefault(); 
         return;
     }
     onSelectClip(clip.id);
     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     setDragOffset(offsetTime);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      onSelectClip(clipId);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const scrollLeft = timelineRef.current?.scrollLeft || 0;
      const clickX = e.clientX - (rect?.left || 0) + scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP' && contextMenu.targetId) {
           switch(action) {
              case 'delete': onDeleteClip(contextMenu.targetId); break;
              case 'duplicate': onDuplicateClip(contextMenu.targetId); break;
              case 'rename': 
                  const clip = clips.find(c => c.id === contextMenu.targetId);
                  if (clip) {
                      const newName = prompt("Rename clip:", clip.name);
                      if (newName) onRenameClip(contextMenu.targetId, newName);
                  }
                  break;
              case 'copy': onCopyClip(contextMenu.targetId); break;
              case 'loop': onLoopClip(contextMenu.targetId); break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClip(contextMenu.time, contextMenu.targetId);
           }
      }
      setContextMenu(null);
  };

  // Helper to draw automation lines
  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];

      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);

      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * 64; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    {/* Invisible hit area for easier clicking */}
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * 64} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    {/* Visible point */}
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * 64} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  return (
    <div 
      className={`flex-1 overflow-auto bg-gray-950 relative custom-scrollbar flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
      ref={timelineRef}
      onClick={handleTimelineClick}
    >
        {/* Playhead */}
        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler */}
        <div className="h-8 border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex" style={{ width: `${totalBars * pixelsPerBar}px` }}>
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     {/* Quarter Beats */}
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}
        </div>

      <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
        {tracks.map(track => (
          <div key={track.id} className="flex flex-col">
            {/* Standard Track Lane */}
            <div 
                className="relative h-24 border-b border-gray-800 hover:bg-white/5 transition-colors"
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, track.id)}
                onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                style={{ 
                    backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                    backgroundSize: `${pixelsPerBar}px 100%`,
                    backgroundPosition: '0 0'
                }}
            >
                <div 
                    className="absolute inset-0 pointer-events-none" 
                    style={{
                        backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                        backgroundSize: `${pixelsPerBeat}px 100%`,
                        opacity: 0.3
                    }}
                />

                {clips.filter(c => c.trackId === track.id).map(clip => (
                <div
                    key={clip.id}
                    data-clip-id={clip.id}
                    draggable={tool === 'MOVE'}
                    onDragStart={(e) => handleDragStart(e, clip)}
                    onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                    onDoubleClick={() => onSelectClip(clip.id)}
                    className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                    ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                    ${selectedClipId === clip.id ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                    style={{
                    left: `${clip.startTime * zoom}px`,
                    width: `${(clip.duration / clip.playbackRate) * zoom}px`,
                    }}
                >
                    <div 
                        className="absolute inset-0 opacity-60"
                        style={{ backgroundColor: track.color }}
                    ></div>

                    {clip.loop && (
                        <div className="absolute top-0 right-0 p-1 text-white/50">
                            <RotateCw size={10} />
                        </div>
                    )}

                    <div className="absolute inset-0 z-10">
                        <Waveform 
                            clip={clip} 
                            width={Math.ceil((clip.duration / clip.playbackRate) * zoom)} 
                            height={80} 
                            color="#ffffff"
                        />
                    </div>

                    <div className="absolute top-1 left-1 z-20 max-w-full">
                        <div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">
                            {clip.name}
                        </div>
                    </div>
                </div>
                ))}
            </div>

            {/* Automation Lane */}
            {track.showAutomation && (
                <div 
                    className="h-16 bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair"
                    data-automation-track-id={track.id}
                    style={{ minWidth: `${totalBars * pixelsPerBar}px` }}
                >
                    <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                    <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">
                        {track.selectedAutomationId === 'pan' ? 'Pan' : 
                         track.selectedAutomationId === 'volume' ? 'Vol' : 
                         track.selectedAutomationId?.split(':')[1].toUpperCase()}
                    </div>
                    <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>
                        {renderAutomationPoints(track)}
                    </svg>
                </div>
            )}
          </div>
        ))}
        <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">
             End of tracks
        </div>
      </div>

      {contextMenu && (
          <div 
              className="fixed z-50 w-48 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
              style={{ top: contextMenu.y, left: contextMenu.x }}
          >
              {/* Menu items same as before */}
              {contextMenu.type === 'CLIP' ? (
                  <>
                    <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Copy size={14} /> Copy
                    </button>
                     <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <RotateCw size={14} /> Toggle Loop
                    </button>
                    <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Pencil size={14} /> Rename
                    </button>
                    <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Copy size={14} /> Duplicate
                    </button>
                    <div className="h-px bg-gray-700 my-1" />
                    <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2">
                        <Trash2 size={14} /> Delete
                    </button>
                  </>
              ) : (
                  <>
                    <button 
                        onClick={(e) => handleMenuAction(e, 'paste')} 
                        disabled={!canPaste}
                        className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}
                    >
                        <ClipboardPaste size={14} /> Paste
                    </button>
                  </>
              )}
          </div>
      )}
    </div>
  );
};

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Granular Spectral Separation ---

  public async separateStems(file: File): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);
    const duration = originalBuffer.duration;
    const sampleRate = originalBuffer.sampleRate;

    // We break the spectrum into multiple overlapping bands to isolate different instruments.
    // This assumes specific instruments dominate specific frequency ranges.
    // 1. Sub (<100Hz): Kick, Sub Bass
    // 2. Low Mids (100-300Hz): Bass Guitar, Snare body
    // 3. Mids (300-1500Hz): Rhythm Guitar, Piano, Vocals body
    // 4. High Mids (1500-4000Hz): Trumpet, Horns, Lead Vocals, Snare Snap
    // 5. Highs (4000-8000Hz): Percussion, Vocal Air
    // 6. Air (>8000Hz): Cymbals, Hiss

    const bands = [
        { name: 'Kick / Sub', min: 0, max: 100, type: 'LOWPASS' as PluginType },
        { name: 'Bass Line', min: 100, max: 300, type: 'LOWPASS' as PluginType },
        { name: 'Rhythm / Keys', min: 300, max: 1500, type: 'LOWPASS' as PluginType },
        { name: 'Leads / Horns', min: 1500, max: 4000, type: 'HIGHPASS' as PluginType },
        { name: 'Vocals / Snap', min: 4000, max: 8000, type: 'HIGHPASS' as PluginType },
        { name: 'Air / Cymbals', min: 8000, max: 20000, type: 'HIGHPASS' as PluginType }
    ];

    const results = [];

    // Helper to render a specific band pass
    const renderBand = async (min: number, max: number) => {
        // Use a new context for each render to avoid memory limits or garbage collection issues
        const ctx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);
        const src = ctx.createBufferSource();
        src.buffer = originalBuffer;

        const hp = ctx.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = min;
        hp.Q.value = 0.7; // Butterworth

        const lp = ctx.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = max;
        lp.Q.value = 0.7;

        // For the ends of spectrum
        if (min <= 20) {
             src.connect(lp);
             lp.connect(ctx.destination);
        } else if (max >= 18000) {
             src.connect(hp);
             hp.connect(ctx.destination);
        } else {
             src.connect(hp);
             hp.connect(lp);
             lp.connect(ctx.destination);
        }

        src.start(0);
        return await ctx.startRendering();
    };

    // Parallel Processing (careful with memory, but browsers handle promises well)
    const renderPromises = bands.map(async (band) => {
         const buffer = await renderBand(band.min, band.max);
         // Heuristic: Check if buffer actually has energy. If it's silent, don't return a track.
         // This helps avoiding empty tracks for simple songs.
         if (this.hasEnergy(buffer)) {
             return {
                 name: band.name,
                 type: band.type,
                 buffer: buffer,
                 plugins: []
             };
         }
         return null;
    });

    const stems = await Promise.all(renderPromises);
    return stems.filter((s): s is NonNullable<typeof s> => s !== null);
  }

  private hasEnergy(buffer: AudioBuffer): boolean {
      // Check middle of buffer for non-zero data
      const data = buffer.getChannelData(0);
      const len = data.length;
      // Check 100 samples every 1/10th of second
      const step = Math.floor(buffer.sampleRate / 10);
      let energy = 0;
      for (let i = 0; i < len; i += step) {
          energy += Math.abs(data[i]);
          if (energy > 0.1) return true; // Early exit
      }
      return energy > 0.1;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import React, { useState } from 'react';
import { Upload, X, Loader2, Music, Layers } from 'lucide-react';
import { audioService } from '../services/audioEngine';
import { PluginType, AudioPlugin } from '../types';

interface StemSplitterProps {
  isOpen: boolean;
  onClose: () => void;
  onStemsGenerated: (stems: {name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]) => void;
}

export const StemSplitter: React.FC<StemSplitterProps> = ({ isOpen, onClose, onStemsGenerated }) => {
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<string>("");

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleProcess = async () => {
    if (!file) return;
    setLoading(true);
    setStatus("Analyzing audio spectrum...");

    try {
        // Ensure AudioContext is running before processing
        await audioService.resume();

        const stems = await audioService.separateStems(file);

        if (stems.length === 0) {
            alert("Could not separate audio. The file might be silent or corrupt.");
            setLoading(false);
            return;
        }

        setStatus("Generating tracks...");

        // Immediate update instead of arbitrary timeout
        onStemsGenerated(stems);
        setLoading(false);
        setFile(null);
        setStatus("");
        onClose();

    } catch (e) {
        console.error(e);
        alert("Failed to separate stems. Check console for details.");
        setLoading(false);
        setStatus("");
    }
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl w-full max-w-md flex flex-col overflow-hidden animate-slide-up">

        <div className="p-6 border-b border-gray-800 flex justify-between items-center">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <Layers className="text-blue-400" /> AI Stem Splitter
            </h2>
            <button onClick={onClose} className="text-gray-400 hover:text-white"><X size={20} /></button>
        </div>

        <div className="p-6 space-y-6">
            <div className="border-2 border-dashed border-gray-700 rounded-xl p-8 flex flex-col items-center justify-center text-center hover:border-blue-500/50 transition-colors bg-gray-800/30">
                <input 
                    type="file" 
                    id="stem-upload" 
                    className="hidden" 
                    accept="audio/*"
                    onChange={handleFileChange}
                />

                {file ? (
                    <div className="flex flex-col items-center gap-2">
                        <div className="p-3 bg-blue-500/20 rounded-full text-blue-400">
                            <Music size={24} />
                        </div>
                        <span className="font-medium text-white">{file.name}</span>
                        <span className="text-xs text-gray-400">{(file.size / 1024 / 1024).toFixed(2)} MB</span>
                        <button onClick={() => setFile(null)} className="text-xs text-red-400 hover:underline mt-2">Remove</button>
                    </div>
                ) : (
                    <label htmlFor="stem-upload" className="cursor-pointer flex flex-col items-center gap-2">
                        <Upload size={32} className="text-gray-500" />
                        <span className="text-sm text-gray-300 font-medium">Click to upload song</span>
                        <span className="text-xs text-gray-500">Supports MP3, WAV, FLAC</span>
                    </label>
                )}
            </div>

            <div className="bg-blue-900/20 border border-blue-500/20 p-3 rounded-lg text-xs text-blue-300">
                <strong>Smart Analysis:</strong> Now breaks down audio into 6 frequency bands to isolate instruments like Horns, Guitars, and Keys more effectively.
            </div>

            <button 
                onClick={handleProcess}
                disabled={!file || loading}
                className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-semibold flex items-center justify-center gap-2 transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin" size={18} />
                        {status || "Processing..."}
                    </>
                ) : (
                    "Analyze & Separate Tracks"
                )}
            </button>
        </div>

      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

export const generateSongIdeas = async (genre: string, mood: string, existingLyrics?: string): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Error: API_KEY not found in environment.";
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let prompt = `Act as a professional songwriter and music producer. 
    I need creative ideas for a ${mood} ${genre} song.

    Please provide:
    1. A catchy song title.
    2. A structure (Intro, Verse, Chorus, etc.).
    3. 4 lines of lyrics for the chorus.

    Keep it concise and inspiring.`;

    if (existingLyrics) {
      prompt += `\n\nHere are some existing lyrics or themes I have: "${existingLyrics}". Incorporate or expand on these.`;
    }

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "No response generated.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Failed to generate ideas. Please check your API key or connection.";
  }
};

export const analyzeAudioContent = async (base64Audio: string): Promise<string[]> => {
  if (!process.env.API_KEY) return ["Vocals", "Drums", "Bass", "Other"]; // Fallback

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash', // Flash is fast and good for audio analysis
      contents: {
        parts: [
          { inlineData: { mimeType: 'audio/wav', data: base64Audio } },
          { text: `Listen to this audio snippet carefully. Identify the distinct instruments or stems present. 
          Return ONLY a JSON array of strings. 
          Common stems include: "Vocals", "Drums", "Bass", "Guitar", "Piano", "Synth", "Strings", "Horns".
          If there are vocals, definitely include "Vocals".
          Limit to the 4-6 most prominent elements.` }
        ]
      },
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) return ["Vocals", "Drums", "Bass", "Other"];

    try {
      // Clean up potential markdown formatting if Gemini adds it
      const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
      return JSON.parse(cleanJson);
    } catch (e) {
      console.warn("Failed to parse Gemini JSON", text);
      return ["Vocals", "Drums", "Bass", "Other"];
    }

  } catch (error) {
    console.error("Gemini Audio Analysis Error:", error);
    return ["Vocals", "Drums", "Bass", "Other"];
  }
};

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';
import { analyzeAudioContent } from './geminiService';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- AI-Enhanced Stem Separation ---

  public async getAudioSnippetBase64(file: File): Promise<string> {
      const originalBuffer = await this.loadFile(file);

      // Extract first 15 seconds to send to Gemini
      const sampleRate = originalBuffer.sampleRate;
      const snippetDuration = Math.min(originalBuffer.duration, 15);
      const offlineCtx = new OfflineAudioContext(originalBuffer.numberOfChannels, snippetDuration * sampleRate, sampleRate);
      const src = offlineCtx.createBufferSource();
      src.buffer = originalBuffer;
      src.connect(offlineCtx.destination);
      src.start(0);

      const snippetBuffer = await offlineCtx.startRendering();
      const snippetBlob = this.bufferToWav(snippetBuffer);

      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () => {
              const base64 = (reader.result as string).split(',')[1];
              resolve(base64);
          };
          reader.onerror = reject;
          reader.readAsDataURL(snippetBlob);
      });
  }

  public async separateStems(file: File, instruments: string[]): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);
    const duration = originalBuffer.duration;
    const sampleRate = originalBuffer.sampleRate;

    // Helper to render an extraction strategy
    const renderStem = async (strategy: (ctx: OfflineAudioContext, src: AudioBufferSourceNode) => void) => {
        const ctx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);
        const src = ctx.createBufferSource();
        src.buffer = originalBuffer;
        strategy(ctx, src);
        src.start(0);
        return await ctx.startRendering();
    };

    const results = [];

    // --- DSP Strategies based on Instrument Type ---

    // 1. Clean Vocal Isolation (Center Channel + Range Focus)
    const strategyVocals = async () => {
        return await renderStem((ctx, src) => {
            // Vocals are almost always panned center.
            // Center = (Left + Right) / 2
            // We optimize this by creating a mono sum, then filtering out non-vocal frequencies

            const merger = ctx.createChannelMerger(1);
            src.connect(merger, 0, 0); // L -> Mono
            src.connect(merger, 1, 0); // R -> Mono

            const hp = ctx.createBiquadFilter();
            hp.type = 'highpass';
            hp.frequency.value = 250; // Remove Kick/Bass
            hp.Q.value = 0.5;

            const lp = ctx.createBiquadFilter();
            lp.type = 'lowpass';
            lp.frequency.value = 8000; // Remove Hi-hats/Air

            // Presence boost for clarity
            const peak = ctx.createBiquadFilter();
            peak.type = 'peaking';
            peak.frequency.value = 2500;
            peak.gain.value = 3;
            peak.Q.value = 1;

            merger.connect(hp);
            hp.connect(lp);
            lp.connect(peak);

            // Expand back to stereo for the track
            const splitter = ctx.createChannelSplitter(2);
            peak.connect(splitter);
            const finalMerger = ctx.createChannelMerger(2);
            splitter.connect(finalMerger, 0, 0);
            splitter.connect(finalMerger, 0, 1);

            finalMerger.connect(ctx.destination);
        });
    };

    // 2. Drums (Transient Heavy)
    const strategyDrums = async () => {
         return await renderStem((ctx, src) => {
            // Emphasis on Lows (Kick) and Highs (Cymbals)
            const lows = ctx.createBiquadFilter();
            lows.type = 'lowshelf';
            lows.frequency.value = 150;
            lows.gain.value = 6;

            const highs = ctx.createBiquadFilter();
            highs.type = 'highshelf';
            highs.frequency.value = 6000;
            highs.gain.value = 6;

            // Cut mids where vocals/guitars sit
            const midCut = ctx.createBiquadFilter();
            midCut.type = 'notch';
            midCut.frequency.value = 1000;
            midCut.Q.value = 1;

            src.connect(lows);
            lows.connect(highs);
            highs.connect(midCut);
            midCut.connect(ctx.destination);
         });
    };

    // 3. Bass (Mono Low End)
    const strategyBass = async () => {
        return await renderStem((ctx, src) => {
            const lp = ctx.createBiquadFilter();
            lp.type = 'lowpass';
            lp.frequency.value = 200;
            lp.Q.value = 0.8;

            // Force Mono
            const merger = ctx.createChannelMerger(2);
            src.connect(lp);
            lp.connect(merger, 0, 0);
            lp.connect(merger, 0, 1);

            merger.connect(ctx.destination);
        });
    };

    // 4. Other/Backing (Side Channel Info + Mids)
    const strategyOther = async () => {
        return await renderStem((ctx, src) => {
             // Side channel extraction (L - R) captures stereo width instruments (synths, guitars, reverb)
             // while canceling out the center (vocals/kick).
             const splitter = ctx.createChannelSplitter(2);
             src.connect(splitter);

             const inverter = ctx.createGain();
             inverter.gain.value = -1;

             const merger = ctx.createChannelMerger(2);

             // L - R
             const L = ctx.createGain();
             splitter.connect(L, 0);
             splitter.connect(inverter, 1);
             inverter.connect(L);

             // R - L (Inverted side)
             const R = ctx.createGain();
             splitter.connect(R, 1);
             const invL = ctx.createGain();
             invL.gain.value = -1;
             splitter.connect(invL, 0);
             invL.connect(R);

             L.connect(merger, 0, 0);
             R.connect(merger, 0, 1);

             // Add back some low-mids that might have been lost in center (Guitars)
             // We can't perfectly recover center instruments without vocals, but Side is usually good for backing.
             merger.connect(ctx.destination);
        });
    };

    // Map discovered instruments to strategies
    for (const inst of instruments) {
        const name = inst.toLowerCase();
        let buffer: AudioBuffer;
        let type: PluginType = 'LOWPASS'; // Default plugin visual

        if (name.includes('vocal') || name.includes('voice') || name.includes('singer')) {
            buffer = await strategyVocals();
            type = 'HIGHPASS';
        } else if (name.includes('drum') || name.includes('beat') || name.includes('percussion')) {
            buffer = await strategyDrums();
            type = 'LOWPASS';
        } else if (name.includes('bass') || name.includes('808')) {
            buffer = await strategyBass();
            type = 'LOWPASS';
        } else {
            // Guitars, Synths, Strings, Keys -> Treat as "Other" (Wide stereo info)
            // Or specific band pass if we wanted to get fancy, but Side channel is safer for clean separation from vocals
            buffer = await strategyOther();
            type = 'HIGHPASS';
        }

        // Safety check for silence
        if (this.hasEnergy(buffer)) {
             results.push({
                 name: inst,
                 type: type,
                 buffer: buffer,
                 plugins: []
             });
        }
    }

    // Fallback if AI didn't find anything or DSP failed
    if (results.length === 0) {
        results.push({
            name: 'Original',
            type: 'LOWPASS',
            buffer: originalBuffer,
            plugins: []
        });
    }

    return results;
  }

  private hasEnergy(buffer: AudioBuffer): boolean {
      const data = buffer.getChannelData(0);
      const len = data.length;
      const step = Math.floor(buffer.sampleRate / 10);
      let energy = 0;
      for (let i = 0; i < len; i += step) {
          energy += Math.abs(data[i]);
          if (energy > 0.05) return true; 
      }
      return energy > 0.05;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import React, { useState } from 'react';
import { Upload, X, Loader2, Music, Layers, Sparkles } from 'lucide-react';
import { audioService } from '../services/audioEngine';
import { PluginType, AudioPlugin } from '../types';
import { analyzeAudioContent } from '../services/geminiService';

interface StemSplitterProps {
  isOpen: boolean;
  onClose: () => void;
  onStemsGenerated: (stems: {name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]) => void;
}

export const StemSplitter: React.FC<StemSplitterProps> = ({ isOpen, onClose, onStemsGenerated }) => {
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<string>("");

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleProcess = async () => {
    if (!file) return;
    setLoading(true);
    setStatus("Extracting audio snippet...");

    try {
        await audioService.resume();

        // 1. Get Snippet
        const base64Audio = await audioService.getAudioSnippetBase64(file);

        // 2. Identify Instruments
        setStatus("AI Identifying Instruments (Gemini)...");
        const detectedInstruments = await analyzeAudioContent(base64Audio);

        // 3. Separate based on detection
        setStatus(`Separating: ${detectedInstruments.join(", ")}...`);
        const stems = await audioService.separateStems(file, detectedInstruments);

        if (stems.length === 0) {
            alert("Could not separate audio. The file might be silent or corrupt.");
            setLoading(false);
            return;
        }

        onStemsGenerated(stems);
        setLoading(false);
        setFile(null);
        setStatus("");
        onClose();

    } catch (e) {
        console.error(e);
        alert("Failed to separate stems. Check console for details.");
        setLoading(false);
        setStatus("");
    }
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl w-full max-w-md flex flex-col overflow-hidden animate-slide-up">

        <div className="p-6 border-b border-gray-800 flex justify-between items-center">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <Layers className="text-blue-400" /> AI Stem Splitter
            </h2>
            <button onClick={onClose} className="text-gray-400 hover:text-white"><X size={20} /></button>
        </div>

        <div className="p-6 space-y-6">
            <div className="border-2 border-dashed border-gray-700 rounded-xl p-8 flex flex-col items-center justify-center text-center hover:border-blue-500/50 transition-colors bg-gray-800/30">
                <input 
                    type="file" 
                    id="stem-upload" 
                    className="hidden" 
                    accept="audio/*"
                    onChange={handleFileChange}
                />

                {file ? (
                    <div className="flex flex-col items-center gap-2">
                        <div className="p-3 bg-blue-500/20 rounded-full text-blue-400">
                            <Music size={24} />
                        </div>
                        <span className="font-medium text-white">{file.name}</span>
                        <span className="text-xs text-gray-400">{(file.size / 1024 / 1024).toFixed(2)} MB</span>
                        <button onClick={() => setFile(null)} className="text-xs text-red-400 hover:underline mt-2">Remove</button>
                    </div>
                ) : (
                    <label htmlFor="stem-upload" className="cursor-pointer flex flex-col items-center gap-2">
                        <Upload size={32} className="text-gray-500" />
                        <span className="text-sm text-gray-300 font-medium">Click to upload song</span>
                        <span className="text-xs text-gray-500">Supports MP3, WAV, FLAC</span>
                    </label>
                )}
            </div>

            <div className="bg-gradient-to-r from-blue-900/30 to-purple-900/30 border border-blue-500/20 p-3 rounded-lg text-xs text-blue-200 flex gap-2">
                <Sparkles size={16} className="text-yellow-400 shrink-0" />
                <div>
                    <strong>Gemini AI Analysis:</strong> The AI will listen to your song, identify the exact instruments (Horns, Guitars, Vocals, etc.), and configure a custom separation engine for cleaner results.
                </div>
            </div>

            <button 
                onClick={handleProcess}
                disabled={!file || loading}
                className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-semibold flex items-center justify-center gap-2 transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin" size={18} />
                        {status || "Processing..."}
                    </>
                ) : (
                    "Analyze & Separate Tracks"
                )}
            </button>
        </div>

      </div>
    </div>
  );
};

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';
import { analyzeAudioContent } from './geminiService';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- AI-Enhanced Stem Separation (Robust & Sequential) ---

  public async getAudioSnippetBase64(file: File): Promise<string> {
      const originalBuffer = await this.loadFile(file);

      // Resample to 16kHz Mono to save token/bandwidth limit for Gemini
      // This makes the upload much faster and less prone to failure
      const offlineCtx = new OfflineAudioContext(1, 15 * 16000, 16000);
      const src = offlineCtx.createBufferSource();
      src.buffer = originalBuffer;
      src.connect(offlineCtx.destination);
      src.start(0);

      const snippetBuffer = await offlineCtx.startRendering();
      const snippetBlob = this.bufferToWav(snippetBuffer);

      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result as string;
              if (result.includes(',')) {
                  resolve(result.split(',')[1]);
              } else {
                  resolve(result);
              }
          };
          reader.onerror = reject;
          reader.readAsDataURL(snippetBlob);
      });
  }

  public async separateStems(
    file: File, 
    instruments: string[],
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);
    const duration = originalBuffer.duration;
    const sampleRate = originalBuffer.sampleRate;

    // Helper to render an extraction strategy
    // We create a FRESH context for each stem to avoid Memory OOM on large files
    const renderStem = async (name: string, strategy: (ctx: OfflineAudioContext, src: AudioBufferSourceNode) => void) => {
        onProgress(`Processing ${name}...`);
        const ctx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);
        const src = ctx.createBufferSource();
        src.buffer = originalBuffer;
        strategy(ctx, src);
        src.start(0);
        return await ctx.startRendering();
    };

    const results = [];

    // --- Subtractive Strategies ---
    // We try to ensure that when summed, we don't get phase cancellation artifacts.
    // However, for individual stem listening, we want isolation.

    // 1. Bass
    // Standard Lowpass + Mono sum
    const strategyBass = (ctx: OfflineAudioContext, src: AudioBufferSourceNode) => {
        const lp = ctx.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = 180;
        lp.Q.value = 0.7; // Butterworth

        // Force Mono for Bass to tighten it
        const merger = ctx.createChannelMerger(2);
        src.connect(lp);
        lp.connect(merger, 0, 0);
        lp.connect(merger, 0, 1);

        merger.connect(ctx.destination);
    };

    // 2. Vocals
    // Center Channel Extraction + Range Filtering
    const strategyVocals = (ctx: OfflineAudioContext, src: AudioBufferSourceNode) => {
         // Mid-Side extraction: Mid = L+R. 
         // True Center Isolation is complex, but (L+R) - (L-R) gives us common signal.

         const splitter = ctx.createChannelSplitter(2);
         src.connect(splitter);

         const merger = ctx.createChannelMerger(1);
         splitter.connect(merger, 0, 0); // L
         splitter.connect(merger, 1, 0); // R

         // Mid Channel (Mono)
         const hp = ctx.createBiquadFilter();
         hp.type = 'highpass';
         hp.frequency.value = 250;

         const lp = ctx.createBiquadFilter();
         lp.type = 'lowpass';
         lp.frequency.value = 10000;

         // Vocal Presence Boost
         const peak = ctx.createBiquadFilter();
         peak.type = 'peaking';
         peak.frequency.value = 2000;
         peak.gain.value = 4;
         peak.Q.value = 0.8;

         merger.connect(hp);
         hp.connect(lp);
         lp.connect(peak);

         // Fan out to stereo
         const finalMerger = ctx.createChannelMerger(2);
         peak.connect(finalMerger, 0, 0);
         peak.connect(finalMerger, 0, 1);

         finalMerger.connect(ctx.destination);
    };

    // 3. Drums
    // Transient emphasis + EQ Scoop
    const strategyDrums = (ctx: OfflineAudioContext, src: AudioBufferSourceNode) => {
        // Drums usually have high transient energy.
        // We use a compressor with negative attack? No.
        // We boost Kick and Highs.

        const lowShelf = ctx.createBiquadFilter();
        lowShelf.type = 'lowshelf';
        lowShelf.frequency.value = 150;
        lowShelf.gain.value = 6;

        const highShelf = ctx.createBiquadFilter();
        highShelf.type = 'highshelf';
        highShelf.frequency.value = 6000;
        highShelf.gain.value = 6;

        // Scoop mids (where vocals/guitars are)
        const notch = ctx.createBiquadFilter();
        notch.type = 'peaking';
        notch.frequency.value = 1000;
        notch.gain.value = -12;
        notch.Q.value = 1.5;

        // Dynamics: Expand transients
        // This is hard with standard nodes, but a Compressor with high ratio and threshold can tame sustain
        // leaving transients relative to sustain? No, that limits peaks.
        // We just stick to EQ for stability in client-side.

        src.connect(lowShelf);
        lowShelf.connect(highShelf);
        highShelf.connect(notch);
        notch.connect(ctx.destination);
    };

    // 4. Other (Side Channel / Backing)
    const strategyOther = (ctx: OfflineAudioContext, src: AudioBufferSourceNode) => {
         // Isolate Side Channel (L - R)
         const splitter = ctx.createChannelSplitter(2);
         src.connect(splitter);

         const inverter = ctx.createGain();
         inverter.gain.value = -1;

         const L = ctx.createGain();
         const R = ctx.createGain();

         // L_out = L_in + (-R_in)
         splitter.connect(L, 0); // L
         splitter.connect(inverter, 1); // R -> Inv
         inverter.connect(L);

         // R_out = R_in + (-L_in)
         splitter.connect(R, 1); // R
         const invL = ctx.createGain();
         invL.gain.value = -1;
         splitter.connect(invL, 0);
         invL.connect(R);

         const merger = ctx.createChannelMerger(2);
         L.connect(merger, 0, 0);
         R.connect(merger, 0, 1);

         merger.connect(ctx.destination);
    };

    // SEQUENTIAL EXECUTION
    // This prevents browser crashes by processing one stem at a time.
    for (const inst of instruments) {
        const name = inst.toLowerCase();
        let buffer: AudioBuffer;
        let type: PluginType = 'LOWPASS';

        try {
            if (name.includes('vocal') || name.includes('voice')) {
                buffer = await renderStem(inst, strategyVocals);
                type = 'HIGHPASS';
            } else if (name.includes('drum') || name.includes('beat') || name.includes('perc')) {
                buffer = await renderStem(inst, strategyDrums);
                type = 'LOWPASS';
            } else if (name.includes('bass') || name.includes('808')) {
                buffer = await renderStem(inst, strategyBass);
                type = 'LOWPASS';
            } else {
                buffer = await renderStem(inst, strategyOther);
                type = 'HIGHPASS';
            }

            if (this.hasEnergy(buffer)) {
                results.push({
                    name: inst,
                    type,
                    buffer,
                    plugins: []
                });
            }
        } catch (e) {
            console.error(`Failed to separate stem: ${inst}`, e);
            // Continue to next stem even if one fails
        }
    }

    // Phase Cancellation Check:
    // If we only found Vocals, create an "Instrumental" automatically
    const hasVocals = results.some(r => r.name.toLowerCase().includes('vocal'));
    const hasInst = results.some(r => r.name.toLowerCase().includes('inst') || r.name.toLowerCase().includes('other'));

    if (hasVocals && !hasInst) {
        // Create instrumental by Phase Inversion: Original - Vocals
        try {
            const vocalStem = results.find(r => r.name.toLowerCase().includes('vocal'));
            if (vocalStem) {
                onProgress("Generating Instrumental (Phase Cancellation)...");
                const instBuffer = await this.subtractStem(originalBuffer, vocalStem.buffer);
                 results.push({
                    name: 'Instrumental',
                    type: 'LOWPASS',
                    buffer: instBuffer,
                    plugins: []
                });
            }
        } catch (e) {}
    }

    return results;
  }

  // Create a new buffer that is A - B
  private async subtractStem(original: AudioBuffer, subtract: AudioBuffer): Promise<AudioBuffer> {
      const ctx = new OfflineAudioContext(2, original.length, original.sampleRate);

      const srcOriginal = ctx.createBufferSource();
      srcOriginal.buffer = original;

      const srcSub = ctx.createBufferSource();
      srcSub.buffer = subtract;

      const inverter = ctx.createGain();
      inverter.gain.value = -1;

      srcOriginal.connect(ctx.destination);
      srcSub.connect(inverter);
      inverter.connect(ctx.destination);

      srcOriginal.start(0);
      srcSub.start(0);

      return await ctx.startRendering();
  }

  private hasEnergy(buffer: AudioBuffer): boolean {
      const data = buffer.getChannelData(0);
      const len = data.length;
      const step = Math.floor(buffer.sampleRate / 10);
      let energy = 0;
      for (let i = 0; i < len; i += step) {
          energy += Math.abs(data[i]);
          if (energy > 0.05) return true; 
      }
      return energy > 0.05;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import React, { useState } from 'react';
import { Upload, X, Loader2, Music, Layers, Sparkles } from 'lucide-react';
import { audioService } from '../services/audioEngine';
import { PluginType, AudioPlugin } from '../types';
import { analyzeAudioContent } from '../services/geminiService';

interface StemSplitterProps {
  isOpen: boolean;
  onClose: () => void;
  onStemsGenerated: (stems: {name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]) => void;
}

export const StemSplitter: React.FC<StemSplitterProps> = ({ isOpen, onClose, onStemsGenerated }) => {
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<string>("");

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleProcess = async () => {
    if (!file) return;
    setLoading(true);
    setStatus("Analyzing...");

    try {
        await audioService.resume();

        // 1. Get Snippet
        const base64Audio = await audioService.getAudioSnippetBase64(file);

        // 2. Identify Instruments
        setStatus("AI Identifying Instruments...");
        const detectedInstruments = await analyzeAudioContent(base64Audio);

        // 3. Separate based on detection (Pass progress callback)
        const stems = await audioService.separateStems(file, detectedInstruments, (msg) => {
            setStatus(msg);
        });

        if (stems.length === 0) {
            alert("Could not separate audio. The file might be silent or corrupt.");
            setLoading(false);
            return;
        }

        setStatus("Finalizing...");
        onStemsGenerated(stems);
        setLoading(false);
        setFile(null);
        setStatus("");
        onClose();

    } catch (e) {
        console.error(e);
        alert("Failed to separate stems. The file might be too large or the format unsupported.");
        setLoading(false);
        setStatus("");
    }
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl w-full max-w-md flex flex-col overflow-hidden animate-slide-up">

        <div className="p-6 border-b border-gray-800 flex justify-between items-center">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <Layers className="text-blue-400" /> AI Stem Splitter
            </h2>
            <button onClick={onClose} className="text-gray-400 hover:text-white"><X size={20} /></button>
        </div>

        <div className="p-6 space-y-6">
            <div className="border-2 border-dashed border-gray-700 rounded-xl p-8 flex flex-col items-center justify-center text-center hover:border-blue-500/50 transition-colors bg-gray-800/30">
                <input 
                    type="file" 
                    id="stem-upload" 
                    className="hidden" 
                    accept="audio/*"
                    onChange={handleFileChange}
                />

                {file ? (
                    <div className="flex flex-col items-center gap-2">
                        <div className="p-3 bg-blue-500/20 rounded-full text-blue-400">
                            <Music size={24} />
                        </div>
                        <span className="font-medium text-white">{file.name}</span>
                        <span className="text-xs text-gray-400">{(file.size / 1024 / 1024).toFixed(2)} MB</span>
                        <button onClick={() => setFile(null)} className="text-xs text-red-400 hover:underline mt-2">Remove</button>
                    </div>
                ) : (
                    <label htmlFor="stem-upload" className="cursor-pointer flex flex-col items-center gap-2">
                        <Upload size={32} className="text-gray-500" />
                        <span className="text-sm text-gray-300 font-medium">Click to upload song</span>
                        <span className="text-xs text-gray-500">Supports MP3, WAV, FLAC</span>
                    </label>
                )}
            </div>

            <div className="bg-gradient-to-r from-blue-900/30 to-purple-900/30 border border-blue-500/20 p-3 rounded-lg text-xs text-blue-200 flex gap-2">
                <Sparkles size={16} className="text-yellow-400 shrink-0" />
                <div>
                    <strong>Pro Separation Mode:</strong> This uses a high-quality sequential separation engine. It analyzes the full song structure and extracts instruments one-by-one to preserve maximum quality. This may take a minute.
                </div>
            </div>

            <button 
                onClick={handleProcess}
                disabled={!file || loading}
                className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-semibold flex items-center justify-center gap-2 transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin" size={18} />
                        {status || "Processing..."}
                    </>
                ) : (
                    "Analyze & Separate Tracks"
                )}
            </button>
        </div>

      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

export interface InstrumentAnalysis {
  name: string;
  frequencyRange: { min: number; max: number };
  role: 'vocals' | 'drums' | 'bass' | 'other';
  activeSegments: { start: number; end: number }[];
}

export const generateSongIdeas = async (genre: string, mood: string, existingLyrics?: string): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Error: API_KEY not found in environment.";
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let prompt = `Act as a professional songwriter and music producer. 
    I need creative ideas for a ${mood} ${genre} song.

    Please provide:
    1. A catchy song title.
    2. A structure (Intro, Verse, Chorus, etc.).
    3. 4 lines of lyrics for the chorus.

    Keep it concise and inspiring.`;

    if (existingLyrics) {
      prompt += `\n\nHere are some existing lyrics or themes I have: "${existingLyrics}". Incorporate or expand on these.`;
    }

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "No response generated.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Failed to generate ideas. Please check your API key or connection.";
  }
};

export const analyzeAudioStructure = async (base64Audio: string): Promise<InstrumentAnalysis[]> => {
  if (!process.env.API_KEY) return getFallbackAnalysis();

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Analyze this audio file in depth for a stem separation task.
    I need you to identify every distinct instrument.
    For each instrument, determine:
    1. The name (e.g., "Lead Vocals", "Kick Drum", "Trumpet", "Synth Pad").
    2. The approximate frequency range in Hz (min and max) where it is most dominant.
    3. Its role (choose one: "vocals", "drums", "bass", "other").
    4. Time segments (start/end seconds) where it is clearly audible. If it plays the whole time, use 0 to 999.

    Return the result as a raw JSON array. Do not use Markdown.
    Example: [{"name": "Trumpet", "frequencyRange": {"min": 500, "max": 4000}, "role": "other", "activeSegments": [{"start": 10, "end": 45}]}]`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'audio/wav', data: base64Audio } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) return getFallbackAnalysis();

    const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const data = JSON.parse(cleanJson);
    return data;

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return getFallbackAnalysis();
  }
};

function getFallbackAnalysis(): InstrumentAnalysis[] {
    return [
        { name: "Vocals", frequencyRange: { min: 300, max: 10000 }, role: 'vocals', activeSegments: [{start: 0, end: 999}] },
        { name: "Drums", frequencyRange: { min: 20, max: 15000 }, role: 'drums', activeSegments: [{start: 0, end: 999}] },
        { name: "Bass", frequencyRange: { min: 20, max: 300 }, role: 'bass', activeSegments: [{start: 0, end: 999}] },
        { name: "Other Instruments", frequencyRange: { min: 200, max: 12000 }, role: 'other', activeSegments: [{start: 0, end: 999}] }
    ];
}

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';
import { analyzeAudioStructure, InstrumentAnalysis } from './geminiService';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- High Fidelity Stem Separation (Sequential) ---

  public async getAudioAnalysisInput(file: File): Promise<string> {
      const originalBuffer = await this.loadFile(file);

      // Downsample to 16kHz Mono specifically for Gemini Analysis
      // This is NOT the file we will process, just the one we send for "Instructions"
      const snippetDuration = Math.min(originalBuffer.duration, 60); // Analyze up to 60s
      const offlineCtx = new OfflineAudioContext(1, snippetDuration * 16000, 16000);
      const src = offlineCtx.createBufferSource();
      src.buffer = originalBuffer;
      src.connect(offlineCtx.destination);
      src.start(0);

      const snippetBuffer = await offlineCtx.startRendering();
      const snippetBlob = this.bufferToWav(snippetBuffer);

      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result as string;
              resolve(result.includes(',') ? result.split(',')[1] : result);
          };
          reader.onerror = reject;
          reader.readAsDataURL(snippetBlob);
      });
  }

  public async separateStemsAdvanced(
    file: File, 
    instruments: InstrumentAnalysis[],
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);
    const duration = originalBuffer.duration;
    const sampleRate = originalBuffer.sampleRate;

    // We will render stems sequentially to avoid OOM
    const results = [];

    for (const inst of instruments) {
        onProgress(`Processing ${inst.name} (${inst.role})...`);

        // Fresh context for each track
        const ctx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);
        const src = ctx.createBufferSource();
        src.buffer = originalBuffer;

        // --- DSP Chain Construction ---
        // 1. Frequency Isolation (Crossovers)
        const filtered = this.createBandpassIsolation(ctx, src, inst.frequencyRange.min, inst.frequencyRange.max);

        let processed: AudioNode = filtered;

        // 2. Role-Based Processing
        if (inst.role === 'vocals') {
            // Vocals: Isolate Center Channel + Gate
            processed = this.applyCenterIsolation(ctx, processed);
        } else if (inst.role === 'drums') {
            // Drums: Transient Extraction
            processed = this.applyTransientShaper(ctx, processed);
        } else if (inst.role === 'bass') {
            // Bass: Mono Sum
            processed = this.applyMono(ctx, processed);
        } else {
            // Other: Side Channel Emphasis (usually where instruments live vs vocals)
            // But we mix it back with some center to not lose solos
            processed = this.applySideEmphasis(ctx, processed);
        }

        // 3. AI Gating (Time Segmentation)
        // We use a GainNode to mute sections where Gemini said the instrument is silent
        const gater = ctx.createGain();
        // Default to silent if we have segments, else full volume
        const hasSegments = inst.activeSegments.length > 0 && !(inst.activeSegments.length === 1 && inst.activeSegments[0].end > 900);

        if (hasSegments) {
            gater.gain.value = 0;
            inst.activeSegments.forEach(seg => {
                const fadeTime = 0.1; // 100ms fade
                gater.gain.setTargetAtTime(1, seg.start, fadeTime);
                gater.gain.setTargetAtTime(0, seg.end, fadeTime);
            });
        }

        processed.connect(gater);
        gater.connect(ctx.destination);

        src.start(0);
        const buffer = await ctx.startRendering();

        if (this.hasEnergy(buffer)) {
             results.push({
                 name: inst.name,
                 type: inst.role === 'bass' || inst.role === 'drums' ? 'LOWPASS' : 'HIGHPASS' as PluginType,
                 buffer,
                 plugins: []
             });
        }
    }

    return results;
  }

  // --- Advanced DSP Helpers ---

  // Linkwitz-Riley Crossover Approximation (Cascaded Butterworth)
  private createBandpassIsolation(ctx: OfflineAudioContext, input: AudioNode, minHz: number, maxHz: number): AudioNode {
      // Highpass (Cut below min)
      const hp1 = ctx.createBiquadFilter(); hp1.type = 'highpass'; hp1.frequency.value = minHz; hp1.Q.value = 0.707;
      const hp2 = ctx.createBiquadFilter(); hp2.type = 'highpass'; hp2.frequency.value = minHz; hp2.Q.value = 0.707;

      // Lowpass (Cut above max)
      const lp1 = ctx.createBiquadFilter(); lp1.type = 'lowpass'; lp1.frequency.value = maxHz; lp1.Q.value = 0.707;
      const lp2 = ctx.createBiquadFilter(); lp2.type = 'lowpass'; lp2.frequency.value = maxHz; lp2.Q.value = 0.707;

      input.connect(hp1);
      hp1.connect(hp2);
      hp2.connect(lp1);
      lp1.connect(lp2);

      return lp2;
  }

  private applyCenterIsolation(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
      // (L+R) - (L-R) approximation logic via Channel Math
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      const merger = ctx.createChannelMerger(2);

      // Sum to Mono (L+R)
      const mono = ctx.createGain();
      splitter.connect(mono, 0);
      splitter.connect(mono, 1);

      // We assume center is dominant in mono sum.
      // We route mono back to L and R
      mono.connect(merger, 0, 0);
      mono.connect(merger, 0, 1);

      return merger;
  }

  private applySideEmphasis(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
      // Extract Side: L - R
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      const inverter = ctx.createGain();
      inverter.gain.value = -1;

      const sideL = ctx.createGain();
      splitter.connect(sideL, 0); // L
      splitter.connect(inverter, 1); // R
      inverter.connect(sideL); // L - R

      const merger = ctx.createChannelMerger(2);
      sideL.connect(merger, 0, 0); // Side to L
      sideL.connect(merger, 0, 1); // Side to R (inverted phase? No, just dual mono side)

      // Mix a bit of dry signal back in so it's not hollow
      const dry = ctx.createGain();
      dry.gain.value = 0.5;
      input.connect(dry);
      dry.connect(merger);

      return merger;
  }

  private applyMono(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
      const merger = ctx.createChannelMerger(2);
      const gain = ctx.createGain();
      // Mono sum logic happens if we connect stereo source to mono dest?
      // Actually simpler:
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      splitter.connect(gain, 0);
      splitter.connect(gain, 1);

      gain.connect(merger, 0, 0);
      gain.connect(merger, 0, 1);
      return merger;
  }

  private applyTransientShaper(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
      // Use DynamicsCompressor to emphasize transients?
      // Actually, to KEEP transients and reduce sustain, we want an Expander.
      // Web Audio only has Compressor.
      // Trick: Use Compressor to crush transients, invert that, mix with dry. 
      // Result = Dry - CrushedTransients = Just Transients.

      const dry = ctx.createGain();
      const wet = ctx.createGain();
      const inverter = ctx.createGain();
      inverter.gain.value = -1;

      const compressor = ctx.createDynamicsCompressor();
      compressor.threshold.value = -20;
      compressor.knee.value = 0;
      compressor.ratio.value = 20; // Hard limiting
      compressor.attack.value = 0; // Fast attack to catch transient
      compressor.release.value = 0.1;

      input.connect(dry);

      input.connect(compressor);
      compressor.connect(inverter);

      // If we subtract the compressed signal from the dry, we are subtracting the "Body" (sustain)
      // leaving the peaks?
      // No, Compressor REDUCES peaks. So Dry - Compressed(reduced peaks) = Peaks?
      // Example: Input 1.0. Compressed to 0.5. Dry(1.0) - Compressed(0.5) = 0.5 (Peak remains).
      // Input 0.2. Compressed to 0.2. Dry(0.2) - Compressed(0.2) = 0.0 (Sustain removed).
      // This works as a transient shaper!

      const merger = ctx.createGain();
      dry.connect(merger);
      inverter.connect(merger);

      // Boost result
      const makeup = ctx.createGain();
      makeup.gain.value = 2;
      merger.connect(makeup);

      return makeup;
  }

  private hasEnergy(buffer: AudioBuffer): boolean {
      const data = buffer.getChannelData(0);
      const len = data.length;
      const step = Math.floor(buffer.sampleRate / 10);
      let energy = 0;
      for (let i = 0; i < len; i += step) {
          energy += Math.abs(data[i]);
          if (energy > 0.02) return true; 
      }
      return energy > 0.02;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import React, { useState } from 'react';
import { Upload, X, Loader2, Music, Layers, Sparkles, Server } from 'lucide-react';
import { audioService } from '../services/audioEngine';
import { PluginType, AudioPlugin } from '../types';
import { analyzeAudioStructure } from '../services/geminiService';

interface StemSplitterProps {
  isOpen: boolean;
  onClose: () => void;
  onStemsGenerated: (stems: {name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]) => void;
}

export const StemSplitter: React.FC<StemSplitterProps> = ({ isOpen, onClose, onStemsGenerated }) => {
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);
  const [status, setStatus] = useState<string>("");

  if (!isOpen) return null;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      setFile(e.target.files[0]);
    }
  };

  const handleProcess = async () => {
    if (!file) return;
    setLoading(true);
    setStatus("Preparing for upload...");

    try {
        await audioService.resume();

        // 1. Get Snippet
        setStatus("Encoding for Google Cloud...");
        const base64Audio = await audioService.getAudioAnalysisInput(file);

        // 2. Identify Instruments
        setStatus("Gemini AI Analyzing Structure...");
        const detectedInstruments = await analyzeAudioStructure(base64Audio);

        // 3. Separate based on detection (Pass progress callback)
        const stems = await audioService.separateStemsAdvanced(file, detectedInstruments, (msg) => {
            setStatus(msg);
        });

        if (stems.length === 0) {
            alert("Could not separate audio. The file might be silent or corrupt.");
            setLoading(false);
            return;
        }

        setStatus("Finalizing...");
        onStemsGenerated(stems);
        setLoading(false);
        setFile(null);
        setStatus("");
        onClose();

    } catch (e) {
        console.error(e);
        alert("Failed to separate stems. The file might be too large or the format unsupported.");
        setLoading(false);
        setStatus("");
    }
  };

  return (
    <div className="fixed inset-0 bg-black/70 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl w-full max-w-md flex flex-col overflow-hidden animate-slide-up">

        <div className="p-6 border-b border-gray-800 flex justify-between items-center">
            <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <Layers className="text-blue-400" /> AI Stem Splitter
            </h2>
            <button onClick={onClose} className="text-gray-400 hover:text-white"><X size={20} /></button>
        </div>

        <div className="p-6 space-y-6">
            <div className="border-2 border-dashed border-gray-700 rounded-xl p-8 flex flex-col items-center justify-center text-center hover:border-blue-500/50 transition-colors bg-gray-800/30">
                <input 
                    type="file" 
                    id="stem-upload" 
                    className="hidden" 
                    accept="audio/*"
                    onChange={handleFileChange}
                />

                {file ? (
                    <div className="flex flex-col items-center gap-2">
                        <div className="p-3 bg-blue-500/20 rounded-full text-blue-400">
                            <Music size={24} />
                        </div>
                        <span className="font-medium text-white">{file.name}</span>
                        <span className="text-xs text-gray-400">{(file.size / 1024 / 1024).toFixed(2)} MB</span>
                        <button onClick={() => setFile(null)} className="text-xs text-red-400 hover:underline mt-2">Remove</button>
                    </div>
                ) : (
                    <label htmlFor="stem-upload" className="cursor-pointer flex flex-col items-center gap-2">
                        <Upload size={32} className="text-gray-500" />
                        <span className="text-sm text-gray-300 font-medium">Click to upload song</span>
                        <span className="text-xs text-gray-500">Supports MP3, WAV, FLAC</span>
                    </label>
                )}
            </div>

            <div className="bg-gray-800 p-4 rounded-lg space-y-2">
                 <div className="flex gap-2 items-start">
                    <Server size={16} className="text-purple-400 shrink-0 mt-0.5" />
                    <div className="text-xs text-gray-300">
                        <strong>Deep Analysis:</strong> Audio is sent to Google's Gemini AI to identify instruments, timestamps, and frequency maps.
                    </div>
                 </div>
                 <div className="flex gap-2 items-start">
                    <Sparkles size={16} className="text-yellow-400 shrink-0 mt-0.5" />
                    <div className="text-xs text-gray-300">
                        <strong>Hi-Fi Engine:</strong> Uses Linkwitz-Riley crossovers and transient shapers for professional-grade isolation. Processing may take 1-2 minutes.
                    </div>
                 </div>
            </div>

            <button 
                onClick={handleProcess}
                disabled={!file || loading}
                className="w-full py-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-50 disabled:cursor-not-allowed rounded-lg text-white font-semibold flex items-center justify-center gap-2 transition-all"
            >
                {loading ? (
                    <>
                        <Loader2 className="animate-spin" size={18} />
                        {status || "Processing..."}
                    </>
                ) : (
                    "Upload & Separate"
                )}
            </button>
        </div>

      </div>
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";

export interface InstrumentAnalysis {
  name: string;
  frequencyRange: { min: number; max: number };
  role: 'vocals' | 'drums' | 'bass' | 'other';
  panning: 'center' | 'stereo' | 'left' | 'right'; // New field for spatial extraction
  activeSegments: { start: number; end: number }[];
}

export const generateSongIdeas = async (genre: string, mood: string, existingLyrics?: string): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Error: API_KEY not found in environment.";
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let prompt = `Act as a professional songwriter and music producer. 
    I need creative ideas for a ${mood} ${genre} song.

    Please provide:
    1. A catchy song title.
    2. A structure (Intro, Verse, Chorus, etc.).
    3. 4 lines of lyrics for the chorus.

    Keep it concise and inspiring.`;

    if (existingLyrics) {
      prompt += `\n\nHere are some existing lyrics or themes I have: "${existingLyrics}". Incorporate or expand on these.`;
    }

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "No response generated.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Failed to generate ideas. Please check your API key or connection.";
  }
};

export const analyzeAudioStructure = async (base64Audio: string): Promise<InstrumentAnalysis[]> => {
  if (!process.env.API_KEY) return getFallbackAnalysis();

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `You are an expert Audio Engineer. Analyze this audio file for Stem Separation.
    I need you to identify every distinct instrument (Vocals, Saxophone, Electric Guitar, Kick Drum, etc.).

    For each instrument, determine:
    1. "name": The specific name (e.g., "Lead Vocals", "Saxophone").
    2. "frequencyRange": The core frequency range in Hz (min and max).
    3. "role": one of ["vocals", "drums", "bass", "other"]. Use "other" for Sax, Guitar, Piano.
    4. "panning": Where does this instrument sit in the stereo field? Choose ["center", "stereo", "left", "right"].
       - Vocals, Kick, Bass, Snare, and Solos (like Sax) are usually "center".
       - Rhythm Guitars, Pads, Overheads are usually "stereo" or hard panned.
    5. "activeSegments": Time segments (start/end seconds) where it is audible. 
       - CRITICAL: If the instrument plays until the end of the snippet, set the 'end' to 9999.

    Return ONLY a JSON array.
    Example: [{"name": "Saxophone", "frequencyRange": {"min": 300, "max": 8000}, "role": "other", "panning": "center", "activeSegments": [{"start": 15, "end": 9999}]}]`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'audio/wav', data: base64Audio } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) return getFallbackAnalysis();

    const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const data = JSON.parse(cleanJson);
    return data;

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return getFallbackAnalysis();
  }
};

function getFallbackAnalysis(): InstrumentAnalysis[] {
    return [
        { name: "Vocals", frequencyRange: { min: 250, max: 12000 }, role: 'vocals', panning: 'center', activeSegments: [{start: 0, end: 9999}] },
        { name: "Drums", frequencyRange: { min: 20, max: 15000 }, role: 'drums', panning: 'center', activeSegments: [{start: 0, end: 9999}] },
        { name: "Bass", frequencyRange: { min: 20, max: 300 }, role: 'bass', panning: 'center', activeSegments: [{start: 0, end: 9999}] },
        { name: "Other", frequencyRange: { min: 200, max: 12000 }, role: 'other', panning: 'stereo', activeSegments: [{start: 0, end: 9999}] }
    ];
}

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';
import { analyzeAudioStructure, InstrumentAnalysis } from './geminiService';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Pro-Grade Stem Separation (Sequential & Spatial) ---

  public async getAudioAnalysisInput(file: File): Promise<string> {
      const originalBuffer = await this.loadFile(file);

      // We increase analysis duration to 240s (4 mins) to capture more of the song
      // but downsample to 12kHz Mono to keep payload small for Gemini
      const analysisLimit = 240; 
      const snippetDuration = Math.min(originalBuffer.duration, analysisLimit);
      const targetSampleRate = 12000;

      const offlineCtx = new OfflineAudioContext(1, snippetDuration * targetSampleRate, targetSampleRate);
      const src = offlineCtx.createBufferSource();
      src.buffer = originalBuffer;
      src.connect(offlineCtx.destination);
      src.start(0);

      const snippetBuffer = await offlineCtx.startRendering();
      const snippetBlob = this.bufferToWav(snippetBuffer);

      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result as string;
              resolve(result.includes(',') ? result.split(',')[1] : result);
          };
          reader.onerror = reject;
          reader.readAsDataURL(snippetBlob);
      });
  }

  public async separateStemsAdvanced(
    file: File, 
    instruments: InstrumentAnalysis[],
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);
    const duration = originalBuffer.duration;
    const sampleRate = originalBuffer.sampleRate;

    const results = [];

    for (const inst of instruments) {
        onProgress(`Separating ${inst.name} (${inst.role})...`);

        const ctx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);
        const src = ctx.createBufferSource();
        src.buffer = originalBuffer;

        // --- 1. Frequency Band Isolation (Crossovers) ---
        // Basic filtering based on AI detected range
        let processed: AudioNode = this.createBandpassIsolation(ctx, src, inst.frequencyRange.min, inst.frequencyRange.max);

        // --- 2. Spatial & Role Processing ---

        if (inst.role === 'vocals') {
            // Vocals are almost always Center.
            // We need to aggressively remove Side content (Stereo Guitars/Keys)
            processed = this.applyVocalIsolation(ctx, processed);
        } 
        else if (inst.role === 'bass') {
            // Bass is strictly Mono
            processed = this.applyMono(ctx, processed);
        }
        else if (inst.name.toLowerCase().includes('sax') || inst.name.toLowerCase().includes('horn')) {
            // Saxophone Logic:
            if (inst.panning === 'center') {
                 // Center Panned Sax fights with Vocals. 
                 // We rely on the Bandpass to distinguish, but keep it mono-focused.
                 processed = this.applyCenterFocus(ctx, processed);
            } else {
                 // Stereo Sax? Extract Side.
                 processed = this.applySideEmphasis(ctx, processed);
            }
        }
        else if (inst.name.toLowerCase().includes('guitar')) {
             if (inst.panning === 'stereo' || inst.panning === 'left' || inst.panning === 'right') {
                 // Guitars are often doubled hard L/R.
                 // Extracting SIDE channel (L-R) removes vocals/kick/snare efficiently.
                 processed = this.applySideEmphasis(ctx, processed);
             } else {
                 // Center guitar (Solo)? Treat as standard mono source
                 processed = this.applyCenterFocus(ctx, processed);
             }
        }
        else {
             // General Logic based on panning
             if (inst.panning === 'center') processed = this.applyCenterFocus(ctx, processed);
             else processed = this.applySideEmphasis(ctx, processed);
        }

        // --- 3. AI Gating (Fixing the 1-minute bug) ---
        const gater = ctx.createGain();
        const hasSegments = inst.activeSegments.length > 0;

        if (hasSegments) {
            gater.gain.value = 0;
            // IMPORTANT: If the last segment ends near the analysis limit (240s) or > 60s, 
            // assume it continues to end of file to prevent cutting off.
            const lastSegment = inst.activeSegments[inst.activeSegments.length - 1];
            if (lastSegment.end > 50 || lastSegment.end > 9000) {
                 lastSegment.end = duration; // Extrapolate to full song
            }

            inst.activeSegments.forEach(seg => {
                // Ensure we don't gate beyond actual duration
                const start = Math.min(seg.start, duration);
                const end = Math.min(seg.end, duration);

                const fadeTime = 0.05; 
                gater.gain.setTargetAtTime(1, start, fadeTime);
                gater.gain.setTargetAtTime(0, end, fadeTime);
            });
        }

        processed.connect(gater);
        gater.connect(ctx.destination);

        src.start(0);
        const buffer = await ctx.startRendering();

        // Only add if not silent
        if (this.hasEnergy(buffer)) {
             results.push({
                 name: inst.name,
                 type: inst.role === 'bass' || inst.role === 'drums' ? 'LOWPASS' : 'HIGHPASS' as PluginType,
                 buffer,
                 plugins: []
             });
        }
    }

    return results;
  }

  // --- Advanced DSP Helpers ---

  private createBandpassIsolation(ctx: OfflineAudioContext, input: AudioNode, minHz: number, maxHz: number): AudioNode {
      // 4th Order Linkwitz-Riley implementation (Cascaded Biquads)
      const hp1 = ctx.createBiquadFilter(); hp1.type = 'highpass'; hp1.frequency.value = minHz; hp1.Q.value = 0.707;
      const hp2 = ctx.createBiquadFilter(); hp2.type = 'highpass'; hp2.frequency.value = minHz; hp2.Q.value = 0.707;

      const lp1 = ctx.createBiquadFilter(); lp1.type = 'lowpass'; lp1.frequency.value = maxHz; lp1.Q.value = 0.707;
      const lp2 = ctx.createBiquadFilter(); lp2.type = 'lowpass'; lp2.frequency.value = maxHz; lp2.Q.value = 0.707;

      input.connect(hp1);
      hp1.connect(hp2);
      hp2.connect(lp1);
      lp1.connect(lp2);

      return lp2;
  }

  private applyVocalIsolation(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
      // 1. Mono Sum (L+R)
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);
      const mono = ctx.createGain();
      splitter.connect(mono, 0);
      splitter.connect(mono, 1);
      mono.gain.value = 0.5; // Compensate gain

      // 2. Subtract Side Information: (L+R) - k * |L-R|
      // This is complex in WebAudio without AudioWorklet, but we can approximate:
      // Vocals are Center. Guitars are Side.
      // If we take Mono, we get Vocals + Guitars(weakly).
      // We rely on EQ to clean up the rest.

      // Vocal Presence Boost (Formant Range)
      const presence = ctx.createBiquadFilter();
      presence.type = 'peaking';
      presence.frequency.value = 3500; // Human ear sensitive area
      presence.gain.value = 3; 
      presence.Q.value = 1.0;

      // Low Cut for Pop cleanliness
      const lowCut = ctx.createBiquadFilter();
      lowCut.type = 'highpass';
      lowCut.frequency.value = 220; // Remove mud/snare body

      mono.connect(presence);
      presence.connect(lowCut);

      // Fan out to stereo
      const merger = ctx.createChannelMerger(2);
      lowCut.connect(merger, 0, 0);
      lowCut.connect(merger, 0, 1);

      return merger;
  }

  private applyCenterFocus(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
      // Extracts (L+R) and keeps it mono-centered
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      const merger = ctx.createChannelMerger(2);
      const mono = ctx.createGain();

      splitter.connect(mono, 0);
      splitter.connect(mono, 1);

      mono.connect(merger, 0, 0);
      mono.connect(merger, 0, 1);

      return merger;
  }

  private applySideEmphasis(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
      // Extract Side: L - R
      // Good for Stereo Guitars, Synths, Reverb tails
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      const inverter = ctx.createGain();
      inverter.gain.value = -1;

      const sideL = ctx.createGain();
      splitter.connect(sideL, 0); // L
      splitter.connect(inverter, 1); // R
      inverter.connect(sideL); // L - R

      const merger = ctx.createChannelMerger(2);
      sideL.connect(merger, 0, 0); 
      sideL.connect(merger, 0, 1); 

      // Mix a bit of center back in (25%) so it's not totally hollow
      const center = ctx.createGain();
      center.gain.value = 0.25;
      input.connect(center);
      center.connect(merger);

      return merger;
  }

  private applyMono(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
      const merger = ctx.createChannelMerger(2);
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      const gain = ctx.createGain();
      splitter.connect(gain, 0);
      splitter.connect(gain, 1);

      gain.connect(merger, 0, 0);
      gain.connect(merger, 0, 1);
      return merger;
  }

  private hasEnergy(buffer: AudioBuffer): boolean {
      const data = buffer.getChannelData(0);
      const len = data.length;
      const step = Math.floor(buffer.sampleRate / 10);
      let energy = 0;
      for (let i = 0; i < len; i += step) {
          energy += Math.abs(data[i]);
          if (energy > 0.02) return true; 
      }
      return energy > 0.02;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import { GoogleGenAI } from "@google/genai";

export interface InstrumentAnalysis {
  name: string;
  frequencyRange: { min: number; max: number };
  role: 'vocals' | 'drums' | 'bass' | 'other';
}

export const generateSongIdeas = async (genre: string, mood: string, existingLyrics?: string): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Error: API_KEY not found in environment.";
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let prompt = `Act as a professional songwriter and music producer. 
    I need creative ideas for a ${mood} ${genre} song.

    Please provide:
    1. A catchy song title.
    2. A structure (Intro, Verse, Chorus, etc.).
    3. 4 lines of lyrics for the chorus.

    Keep it concise and inspiring.`;

    if (existingLyrics) {
      prompt += `\n\nHere are some existing lyrics or themes I have: "${existingLyrics}". Incorporate or expand on these.`;
    }

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "No response generated.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Failed to generate ideas. Please check your API key or connection.";
  }
};

export const analyzeAudioStructure = async (base64Audio: string): Promise<InstrumentAnalysis[]> => {
  if (!process.env.API_KEY) return getFallbackAnalysis();

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // We strictly ask for frequency ranges now, dropping timestamps to avoid "2 second" bugs
    const prompt = `Analyze this audio file for EQ-based Stem Separation.
    Identify the 4 main components: Vocals, Bass, Drums, Other.

    For each, return a JSON object with:
    1. "name": "Vocals", "Bass", "Drums", or "Other".
    2. "role": same as name (lowercase).
    3. "frequencyRange": The core dominant frequency range in Hz (min/max).
       - Vocals usually 250-4000.
       - Bass usually 20-250.
       - Drums usually 20-15000 (Full spectrum but focus on transient punch).
       - Other (Guitars/Keys) usually 200-8000.

    Return ONLY a JSON array.
    Example: [{"name": "Vocals", "role": "vocals", "frequencyRange": {"min": 300, "max": 3500}}]`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'audio/wav', data: base64Audio } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) return getFallbackAnalysis();

    const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const data = JSON.parse(cleanJson);
    return data;

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return getFallbackAnalysis();
  }
};

function getFallbackAnalysis(): InstrumentAnalysis[] {
    return [
        { name: "Vocals", role: 'vocals', frequencyRange: { min: 300, max: 4000 } },
        { name: "Bass", role: 'bass', frequencyRange: { min: 20, max: 200 } },
        { name: "Drums", role: 'drums', frequencyRange: { min: 20, max: 12000 } },
        { name: "Backing", role: 'other', frequencyRange: { min: 200, max: 10000 } }
    ];
}

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';
import { analyzeAudioStructure, InstrumentAnalysis } from './geminiService';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Safe & Robust Stem Separation (EQ-Based) ---

  public async getAudioAnalysisInput(file: File): Promise<string> {
      const originalBuffer = await this.loadFile(file);

      // Analyze first 60 seconds. Enough for Gemini to know the instrument ranges.
      const snippetDuration = Math.min(originalBuffer.duration, 60);
      const targetSampleRate = 12000;

      const offlineCtx = new OfflineAudioContext(1, snippetDuration * targetSampleRate, targetSampleRate);
      const src = offlineCtx.createBufferSource();
      src.buffer = originalBuffer;
      src.connect(offlineCtx.destination);
      src.start(0);

      const snippetBuffer = await offlineCtx.startRendering();
      const snippetBlob = this.bufferToWav(snippetBuffer);

      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result as string;
              resolve(result.includes(',') ? result.split(',')[1] : result);
          };
          reader.onerror = reject;
          reader.readAsDataURL(snippetBlob);
      });
  }

  public async separateStemsAdvanced(
    file: File, 
    instruments: InstrumentAnalysis[],
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);
    const duration = originalBuffer.duration;
    const sampleRate = originalBuffer.sampleRate;

    const results = [];

    // Ensure we process the FULL duration.
    // The previous bug was caused by relying on AI timestamps which were short.
    // We now force the duration to be the full song length.

    for (const inst of instruments) {
        onProgress(`Processing ${inst.name}...`);

        // Critical: Use full duration
        const ctx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);
        const src = ctx.createBufferSource();
        src.buffer = originalBuffer;

        let processed: AudioNode = src;

        if (inst.role === 'vocals') {
            // Vocals: Mid Channel + Bandpass
            // 1. Extract Mid (L+R)
            // 2. Highpass 250Hz (remove mud/bass)
            // 3. Lowpass 10kHz (remove hiss/air)
            processed = this.extractVocals(ctx, src, inst.frequencyRange.min, inst.frequencyRange.max);
        } else if (inst.role === 'bass') {
            // Bass: Steep Lowpass
            processed = this.extractBass(ctx, src, 200);
        } else if (inst.role === 'drums') {
             // Drums: Full spectrum but transient emphasis + EQ Scoop
             processed = this.extractDrums(ctx, src);
        } else {
             // Backing/Other: Side Channel + Mid with Vocal Cut
             processed = this.extractBacking(ctx, src, 300, 3000);
        }

        processed.connect(ctx.destination);
        src.start(0);

        // Render
        const buffer = await ctx.startRendering();

        results.push({
            name: inst.name,
            type: inst.role === 'bass' ? 'LOWPASS' : 'HIGHPASS' as PluginType,
            buffer,
            plugins: []
        });
    }

    return results;
  }

  // --- DSP Strategy Implementations ---

  // 1. Vocal Extraction (Mid Channel + Range)
  private extractVocals(ctx: OfflineAudioContext, input: AudioNode, min: number, max: number): AudioNode {
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      const merger = ctx.createChannelMerger(2);
      const mid = ctx.createGain();

      // Mono Sum (Mid)
      splitter.connect(mid, 0);
      splitter.connect(mid, 1);

      // 8th Order Bandpass (Steepest possible in WebAudio without instability)
      // Highpass Chain
      const hp1 = ctx.createBiquadFilter(); hp1.type = 'highpass'; hp1.frequency.value = min;
      const hp2 = ctx.createBiquadFilter(); hp2.type = 'highpass'; hp2.frequency.value = min;
      const hp3 = ctx.createBiquadFilter(); hp3.type = 'highpass'; hp3.frequency.value = min;
      const hp4 = ctx.createBiquadFilter(); hp4.type = 'highpass'; hp4.frequency.value = min;

      // Lowpass Chain
      const lp1 = ctx.createBiquadFilter(); lp1.type = 'lowpass'; lp1.frequency.value = max;
      const lp2 = ctx.createBiquadFilter(); lp2.type = 'lowpass'; lp2.frequency.value = max;

      mid.connect(hp1);
      hp1.connect(hp2);
      hp2.connect(hp3);
      hp3.connect(hp4);
      hp4.connect(lp1);
      lp1.connect(lp2);

      // Restore to Dual Mono
      lp2.connect(merger, 0, 0);
      lp2.connect(merger, 0, 1);

      return merger;
  }

  // 2. Bass Extraction (Steep Lowpass)
  private extractBass(ctx: OfflineAudioContext, input: AudioNode, cutoff: number): AudioNode {
      const merger = ctx.createChannelMerger(2);

      // Mono conversion for tighter bass
      const splitter = ctx.createChannelSplitter(2);
      const mono = ctx.createGain();
      input.connect(splitter);
      splitter.connect(mono, 0);
      splitter.connect(mono, 1);

      // Steep Lowpass (8th Order)
      const lp1 = ctx.createBiquadFilter(); lp1.type = 'lowpass'; lp1.frequency.value = cutoff;
      const lp2 = ctx.createBiquadFilter(); lp2.type = 'lowpass'; lp2.frequency.value = cutoff;
      const lp3 = ctx.createBiquadFilter(); lp3.type = 'lowpass'; lp3.frequency.value = cutoff;
      const lp4 = ctx.createBiquadFilter(); lp4.type = 'lowpass'; lp4.frequency.value = cutoff;

      mono.connect(lp1);
      lp1.connect(lp2);
      lp2.connect(lp3);
      lp3.connect(lp4);

      lp4.connect(merger, 0, 0);
      lp4.connect(merger, 0, 1);

      return merger;
  }

  // 3. Backing (Side Channel + Notched Mid)
  private extractBacking(ctx: OfflineAudioContext, input: AudioNode, vocalMin: number, vocalMax: number): AudioNode {
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      // Path A: Side Channel (L - R) -- Preserves stereo guitars, synths, reverb
      const sideL = ctx.createGain();
      const inverter = ctx.createGain();
      inverter.gain.value = -1;

      splitter.connect(sideL, 0); // L
      splitter.connect(inverter, 1); // R
      inverter.connect(sideL); // Side = L - R

      // Path B: Mid Channel (L+R) but with Vocals NOTCHED out
      const mid = ctx.createGain();
      splitter.connect(mid, 0);
      splitter.connect(mid, 1);

      // Notch Filter Chain (Remove vocal fundmentals)
      const notch1 = ctx.createBiquadFilter(); notch1.type = 'peaking'; notch1.frequency.value = 1000; notch1.gain.value = -20; notch1.Q.value = 1;
      const notch2 = ctx.createBiquadFilter(); notch2.type = 'peaking'; notch2.frequency.value = 400; notch2.gain.value = -10; notch2.Q.value = 1;

      mid.connect(notch1);
      notch1.connect(notch2);

      // Combine Side + Notched Mid
      const merger = ctx.createChannelMerger(2);

      // Reconstruct: L = (Side + Mid)/2, R = (Mid - Side)/2
      // We approximate by just layering them. 
      sideL.connect(merger, 0, 0);
      sideL.connect(merger, 0, 1); // Side to both (Pseudo stereo width)

      notch2.connect(merger, 0, 0);
      notch2.connect(merger, 0, 1);

      return merger;
  }

  // 4. Drums
  private extractDrums(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
       // Drums are full spectrum. We can't filter them easily.
       // We use EQ Smile Curve (Boost Lows, Boost Highs, Cut Mids)

       const lowShelf = ctx.createBiquadFilter(); 
       lowShelf.type = 'lowshelf'; 
       lowShelf.frequency.value = 150; 
       lowShelf.gain.value = 6;

       const highShelf = ctx.createBiquadFilter();
       highShelf.type = 'highshelf';
       highShelf.frequency.value = 8000;
       highShelf.gain.value = 6;

       const midScoop = ctx.createBiquadFilter();
       midScoop.type = 'peaking';
       midScoop.frequency.value = 1000;
       midScoop.gain.value = -6; // Scoop out vocals/guitars

       input.connect(lowShelf);
       lowShelf.connect(highShelf);
       highShelf.connect(midScoop);

       return midScoop;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import { GoogleGenAI } from "@google/genai";

export interface InstrumentAnalysis {
  name: string;
  frequencyRange: { min: number; max: number };
  role: 'vocals' | 'drums' | 'bass' | 'other';
  interferenceRanges?: { min: number; max: number }[]; // New field for notches
}

export const generateSongIdeas = async (genre: string, mood: string, existingLyrics?: string): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Error: API_KEY not found in environment.";
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let prompt = `Act as a professional songwriter and music producer. 
    I need creative ideas for a ${mood} ${genre} song.

    Please provide:
    1. A catchy song title.
    2. A structure (Intro, Verse, Chorus, etc.).
    3. 4 lines of lyrics for the chorus.

    Keep it concise and inspiring.`;

    if (existingLyrics) {
      prompt += `\n\nHere are some existing lyrics or themes I have: "${existingLyrics}". Incorporate or expand on these.`;
    }

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "No response generated.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Failed to generate ideas. Please check your API key or connection.";
  }
};

export const analyzeAudioStructure = async (base64Audio: string): Promise<InstrumentAnalysis[]> => {
  if (!process.env.API_KEY) return getFallbackAnalysis();

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Analyze this audio for Stem Separation. I need to isolate the Vocals cleanly.

    1. Identify the 4 main components: Vocals, Bass, Drums, Other.
    2. For 'Vocals' specifically, identify 'interferenceRanges': areas where Guitars or Snare drums are bleeding in.
       - Example: If guitars are heavy at 400-600Hz, add that to interferenceRanges.
       - Example: If snare is loud at 2000-2500Hz, add that.

    Return a JSON array with objects:
    {
      "name": string,
      "role": "vocals" | "bass" | "drums" | "other",
      "frequencyRange": { "min": number, "max": number },
      "interferenceRanges": [{ "min": number, "max": number }] (Only for vocals)
    }

    Return ONLY JSON.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'audio/wav', data: base64Audio } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) return getFallbackAnalysis();

    const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const data = JSON.parse(cleanJson);
    return data;

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return getFallbackAnalysis();
  }
};

function getFallbackAnalysis(): InstrumentAnalysis[] {
    return [
        { 
            name: "Vocals", 
            role: 'vocals', 
            frequencyRange: { min: 300, max: 6000 },
            interferenceRanges: [{ min: 400, max: 600 }, { min: 2000, max: 3000 }] // Default cuts for mud/snare
        },
        { name: "Bass", role: 'bass', frequencyRange: { min: 20, max: 200 } },
        { name: "Drums", role: 'drums', frequencyRange: { min: 20, max: 12000 } },
        { name: "Backing", role: 'other', frequencyRange: { min: 200, max: 10000 } }
    ];
}

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';
import { analyzeAudioStructure, InstrumentAnalysis } from './geminiService';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Safe & Robust Stem Separation (EQ-Based) ---

  public async getAudioAnalysisInput(file: File): Promise<string> {
      const originalBuffer = await this.loadFile(file);

      const snippetDuration = Math.min(originalBuffer.duration, 60);
      const targetSampleRate = 12000;

      const offlineCtx = new OfflineAudioContext(1, snippetDuration * targetSampleRate, targetSampleRate);
      const src = offlineCtx.createBufferSource();
      src.buffer = originalBuffer;
      src.connect(offlineCtx.destination);
      src.start(0);

      const snippetBuffer = await offlineCtx.startRendering();
      const snippetBlob = this.bufferToWav(snippetBuffer);

      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result as string;
              resolve(result.includes(',') ? result.split(',')[1] : result);
          };
          reader.onerror = reject;
          reader.readAsDataURL(snippetBlob);
      });
  }

  public async separateStemsAdvanced(
    file: File, 
    instruments: InstrumentAnalysis[],
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);
    const duration = originalBuffer.duration;
    const sampleRate = originalBuffer.sampleRate;

    const results = [];

    for (const inst of instruments) {
        onProgress(`Processing ${inst.name}...`);

        const ctx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);
        const src = ctx.createBufferSource();
        src.buffer = originalBuffer;

        let processed: AudioNode = src;

        if (inst.role === 'vocals') {
            // Vocals: Aggressive Bandpass + Notch Filters
            processed = this.extractVocals(ctx, src, inst.frequencyRange.min, inst.frequencyRange.max, inst.interferenceRanges);
        } else if (inst.role === 'bass') {
            processed = this.extractBass(ctx, src, 200);
        } else if (inst.role === 'drums') {
             processed = this.extractDrums(ctx, src);
        } else {
             processed = this.extractBacking(ctx, src, 300, 3000);
        }

        processed.connect(ctx.destination);
        src.start(0);

        const buffer = await ctx.startRendering();

        results.push({
            name: inst.name,
            type: inst.role === 'bass' ? 'LOWPASS' : 'HIGHPASS' as PluginType,
            buffer,
            plugins: []
        });
    }

    return results;
  }

  // --- DSP Strategy Implementations ---

  // 1. Vocal Extraction (Mid Channel + Range + Notch Interferences)
  private extractVocals(
      ctx: OfflineAudioContext, 
      input: AudioNode, 
      min: number, 
      max: number, 
      notches: {min: number, max: number}[] = []
  ): AudioNode {
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      const merger = ctx.createChannelMerger(2);
      const mid = ctx.createGain();

      // Mono Sum (Mid)
      splitter.connect(mid, 0);
      splitter.connect(mid, 1);

      // Strict Bandpass for Vocals (300Hz - 6000Hz is safer to avoid kick/cymbals)
      const safeMin = Math.max(min, 300);
      const safeMax = Math.min(max, 6000);

      // Highpass Chain (Steep)
      const hp1 = ctx.createBiquadFilter(); hp1.type = 'highpass'; hp1.frequency.value = safeMin;
      const hp2 = ctx.createBiquadFilter(); hp2.type = 'highpass'; hp2.frequency.value = safeMin;
      const hp3 = ctx.createBiquadFilter(); hp3.type = 'highpass'; hp3.frequency.value = safeMin;

      // Lowpass Chain (Steep)
      const lp1 = ctx.createBiquadFilter(); lp1.type = 'lowpass'; lp1.frequency.value = safeMax;
      const lp2 = ctx.createBiquadFilter(); lp2.type = 'lowpass'; lp2.frequency.value = safeMax;

      mid.connect(hp1);
      hp1.connect(hp2);
      hp2.connect(hp3);
      hp3.connect(lp1);
      lp1.connect(lp2);

      // Notch Filters for Interfering Instruments (Guitar/Snare)
      let prevNode: AudioNode = lp2;

      notches.forEach(range => {
          const centerFreq = (range.min + range.max) / 2;
          // Peaking filter with negative gain acts as a Notch but smoother
          const notch = ctx.createBiquadFilter();
          notch.type = 'peaking';
          notch.frequency.value = centerFreq;
          notch.Q.value = 1.5; 
          notch.gain.value = -12; // Cut 12dB

          prevNode.connect(notch);
          prevNode = notch;
      });

      // Restore to Dual Mono
      prevNode.connect(merger, 0, 0);
      prevNode.connect(merger, 0, 1);

      return merger;
  }

  // 2. Bass Extraction (Steep Lowpass)
  private extractBass(ctx: OfflineAudioContext, input: AudioNode, cutoff: number): AudioNode {
      const merger = ctx.createChannelMerger(2);

      // Mono conversion for tighter bass
      const splitter = ctx.createChannelSplitter(2);
      const mono = ctx.createGain();
      input.connect(splitter);
      splitter.connect(mono, 0);
      splitter.connect(mono, 1);

      // Steep Lowpass (8th Order)
      const lp1 = ctx.createBiquadFilter(); lp1.type = 'lowpass'; lp1.frequency.value = cutoff;
      const lp2 = ctx.createBiquadFilter(); lp2.type = 'lowpass'; lp2.frequency.value = cutoff;
      const lp3 = ctx.createBiquadFilter(); lp3.type = 'lowpass'; lp3.frequency.value = cutoff;
      const lp4 = ctx.createBiquadFilter(); lp4.type = 'lowpass'; lp4.frequency.value = cutoff;

      mono.connect(lp1);
      lp1.connect(lp2);
      lp2.connect(lp3);
      lp3.connect(lp4);

      lp4.connect(merger, 0, 0);
      lp4.connect(merger, 0, 1);

      return merger;
  }

  // 3. Backing (Side Channel + Notched Mid)
  private extractBacking(ctx: OfflineAudioContext, input: AudioNode, vocalMin: number, vocalMax: number): AudioNode {
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      // Path A: Side Channel (L - R) -- Preserves stereo guitars, synths, reverb
      const sideL = ctx.createGain();
      const inverter = ctx.createGain();
      inverter.gain.value = -1;

      splitter.connect(sideL, 0); // L
      splitter.connect(inverter, 1); // R
      inverter.connect(sideL); // Side = L - R

      // Path B: Mid Channel (L+R) but with Vocals NOTCHED out
      const mid = ctx.createGain();
      splitter.connect(mid, 0);
      splitter.connect(mid, 1);

      // Notch Filter Chain (Remove vocal fundmentals)
      const notch1 = ctx.createBiquadFilter(); notch1.type = 'peaking'; notch1.frequency.value = 1000; notch1.gain.value = -20; notch1.Q.value = 1;
      const notch2 = ctx.createBiquadFilter(); notch2.type = 'peaking'; notch2.frequency.value = 400; notch2.gain.value = -10; notch2.Q.value = 1;

      mid.connect(notch1);
      notch1.connect(notch2);

      // Combine Side + Notched Mid
      const merger = ctx.createChannelMerger(2);

      // Reconstruct: L = (Side + Mid)/2, R = (Mid - Side)/2
      // We approximate by just layering them. 
      sideL.connect(merger, 0, 0);
      sideL.connect(merger, 0, 1); // Side to both (Pseudo stereo width)

      notch2.connect(merger, 0, 0);
      notch2.connect(merger, 0, 1);

      return merger;
  }

  // 4. Drums
  private extractDrums(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
       // Drums are full spectrum. We can't filter them easily.
       // We use EQ Smile Curve (Boost Lows, Boost Highs, Cut Mids)

       const lowShelf = ctx.createBiquadFilter(); 
       lowShelf.type = 'lowshelf'; 
       lowShelf.frequency.value = 150; 
       lowShelf.gain.value = 6;

       const highShelf = ctx.createBiquadFilter();
       highShelf.type = 'highshelf';
       highShelf.frequency.value = 8000;
       highShelf.gain.value = 6;

       const midScoop = ctx.createBiquadFilter();
       midScoop.type = 'peaking';
       midScoop.frequency.value = 1000;
       midScoop.gain.value = -6; // Scoop out vocals/guitars

       input.connect(lowShelf);
       lowShelf.connect(highShelf);
       highShelf.connect(midScoop);

       return midScoop;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import { GoogleGenAI } from "@google/genai";

export interface InstrumentAnalysis {
  name: string;
  frequencyRange: { min: number; max: number };
  role: 'vocals' | 'drums' | 'bass' | 'other';
  activeSegments?: { start: number; end: number }[]; // Re-introduced for clean gating
}

export const generateSongIdeas = async (genre: string, mood: string, existingLyrics?: string): Promise<string> => {
  if (!process.env.API_KEY) {
    return "Error: API_KEY not found in environment.";
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let prompt = `Act as a professional songwriter and music producer. 
    I need creative ideas for a ${mood} ${genre} song.

    Please provide:
    1. A catchy song title.
    2. A structure (Intro, Verse, Chorus, etc.).
    3. 4 lines of lyrics for the chorus.

    Keep it concise and inspiring.`;

    if (existingLyrics) {
      prompt += `\n\nHere are some existing lyrics or themes I have: "${existingLyrics}". Incorporate or expand on these.`;
    }

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
    });

    return response.text || "No response generated.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Failed to generate ideas. Please check your API key or connection.";
  }
};

export const analyzeAudioStructure = async (base64Audio: string): Promise<InstrumentAnalysis[]> => {
  if (!process.env.API_KEY) return getFallbackAnalysis();

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `Analyze this audio for Stem Separation.

    1. Identify 4 components: Vocals, Bass, Drums, Other.
    2. For 'Vocals', identifying 'activeSegments' is CRITICAL. 
       - List every timestamp interval where vocals are audible.
       - Merge short pauses. 
       - If vocals are present throughout most of the song, reflect that.
    3. Frequency Ranges for EQ.

    Return JSON array:
    {
      "name": string,
      "role": "vocals" | "bass" | "drums" | "other",
      "frequencyRange": { "min": number, "max": number },
      "activeSegments": [{ "start": number, "end": number }] (Optional, mainly for Vocals)
    }

    Return ONLY JSON.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: {
        parts: [
          { inlineData: { mimeType: 'audio/wav', data: base64Audio } },
          { text: prompt }
        ]
      },
      config: {
        responseMimeType: "application/json"
      }
    });

    const text = response.text;
    if (!text) return getFallbackAnalysis();

    const cleanJson = text.replace(/```json/g, '').replace(/```/g, '').trim();
    const data = JSON.parse(cleanJson);
    return data;

  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    return getFallbackAnalysis();
  }
};

function getFallbackAnalysis(): InstrumentAnalysis[] {
    return [
        { 
            name: "Vocals", 
            role: 'vocals', 
            frequencyRange: { min: 250, max: 8000 },
            activeSegments: [{ start: 0, end: 9999 }]
        },
        { name: "Bass", role: 'bass', frequencyRange: { min: 20, max: 200 } },
        { name: "Drums", role: 'drums', frequencyRange: { min: 20, max: 12000 } },
        { name: "Backing", role: 'other', frequencyRange: { min: 200, max: 10000 } }
    ];
}

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';
import { analyzeAudioStructure, InstrumentAnalysis } from './geminiService';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- High-Fidelity Stem Separation (Hybrid DSP) ---

  public async getAudioAnalysisInput(file: File): Promise<string> {
      const originalBuffer = await this.loadFile(file);

      const snippetDuration = Math.min(originalBuffer.duration, 60);
      const targetSampleRate = 12000;

      const offlineCtx = new OfflineAudioContext(1, snippetDuration * targetSampleRate, targetSampleRate);
      const src = offlineCtx.createBufferSource();
      src.buffer = originalBuffer;
      src.connect(offlineCtx.destination);
      src.start(0);

      const snippetBuffer = await offlineCtx.startRendering();
      const snippetBlob = this.bufferToWav(snippetBuffer);

      return new Promise((resolve, reject) => {
          const reader = new FileReader();
          reader.onloadend = () => {
              const result = reader.result as string;
              resolve(result.includes(',') ? result.split(',')[1] : result);
          };
          reader.onerror = reject;
          reader.readAsDataURL(snippetBlob);
      });
  }

  public async separateStemsAdvanced(
    file: File, 
    instruments: InstrumentAnalysis[],
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
    const originalBuffer = await this.loadFile(file);
    const duration = originalBuffer.duration;
    const sampleRate = originalBuffer.sampleRate;

    const results = [];

    for (const inst of instruments) {
        onProgress(`Processing ${inst.name}...`);

        // 1. Initial EQ Pass (Broad strokes)
        const ctx = new OfflineAudioContext(2, duration * sampleRate, sampleRate);
        const src = ctx.createBufferSource();
        src.buffer = originalBuffer;

        let processed: AudioNode = src;

        // Apply Basic Frequency Filtering First
        if (inst.role === 'vocals') {
            // Highpass at 200Hz to remove Bass/Kick fundamentally
            const hp = ctx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 200;
            const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 10000;
            src.connect(hp);
            hp.connect(lp);
            processed = lp;
        } else if (inst.role === 'bass') {
            processed = this.extractBass(ctx, src, 200);
        } else if (inst.role === 'drums') {
             processed = this.extractDrums(ctx, src);
        } else {
             // Backing: Remove Vocal frequencies slightly
             processed = this.extractBacking(ctx, src);
        }

        processed.connect(ctx.destination);
        src.start(0);

        let filteredBuffer = await ctx.startRendering();

        // 2. Advanced Sample-Level Processing (Spatial & Time Gating)
        if (inst.role === 'vocals') {
             filteredBuffer = this.processVocalSamples(filteredBuffer, inst.activeSegments);
        }

        results.push({
            name: inst.name,
            type: inst.role === 'bass' ? 'LOWPASS' : 'HIGHPASS' as PluginType,
            buffer: filteredBuffer,
            plugins: []
        });
    }

    return results;
  }

  // --- Direct Sample Manipulation DSP ---

  private processVocalSamples(buffer: AudioBuffer, activeSegments?: {start: number, end: number}[]): AudioBuffer {
      const channels = buffer.numberOfChannels;
      const length = buffer.length;
      const sampleRate = buffer.sampleRate;

      // We modify the buffer in place
      const left = buffer.getChannelData(0);
      const right = channels > 1 ? buffer.getChannelData(1) : left;

      // Prepare Gating Map if segments exist
      // Safety: If total active time is < 5 seconds, assume AI error and ignore gating.
      let useGating = false;
      if (activeSegments && activeSegments.length > 0) {
          const totalDuration = activeSegments.reduce((acc, seg) => acc + (seg.end - seg.start), 0);
          if (totalDuration > 5) {
              useGating = true;
          }
      }

      for (let i = 0; i < length; i++) {
          const l = left[i];
          const r = right[i];

          // 1. Spatial Isolation (Center Extraction)
          // Vocals are usually Center (Mid). Guitars are Side.
          const mid = (l + r) / 2;
          const side = (l - r) / 2;

          // Ratio of Side Energy to Total Energy
          // If Side energy is high, it's likely panned (guitar). 
          // If Side energy is low, it's center (vocal/kick).
          const absMid = Math.abs(mid);
          const absSide = Math.abs(side);

          // Heuristic: If Side is louder than 50% of Mid, attenuate heavily.
          // This removes wide stereo guitars/synths.
          let stereoFactor = 1.0;
          if (absMid > 0.0001) {
              const ratio = absSide / absMid;
              // If ratio > 0.5, dampen. 
              // Curve: 1.0 at ratio 0, dropping to 0 at ratio 1.
              stereoFactor = Math.max(0, 1.0 - (ratio * 1.5)); 
          }

          // Apply Spatial Gate
          // We keep 'mid' (Center) and apply the factor
          const isolatedSample = mid * stereoFactor;

          // 2. Time Gating (AI Guided)
          let timeGate = 1.0;
          if (useGating && activeSegments) {
              const time = i / sampleRate;
              // Simple linear search is slow for 10M samples, but acceptable for offline render of 3 mins
              // Optimization: Assuming segments are sorted, could track index, but simple .some is safe for < 20 segments
              const isActive = activeSegments.some(s => time >= s.start && time <= s.end);
              if (!isActive) {
                  timeGate = 0.05; // Don't silence completely to keep room tone natural
              }
          }

          const finalSample = isolatedSample * timeGate;

          left[i] = finalSample;
          if (channels > 1) right[i] = finalSample;
      }

      return buffer;
  }

  // --- Legacy Filter Chains (Still used for Pre-processing) ---

  private extractBass(ctx: OfflineAudioContext, input: AudioNode, cutoff: number): AudioNode {
      const merger = ctx.createChannelMerger(2);
      const splitter = ctx.createChannelSplitter(2);
      const mono = ctx.createGain();
      input.connect(splitter);
      splitter.connect(mono, 0);
      splitter.connect(mono, 1);

      const lp1 = ctx.createBiquadFilter(); lp1.type = 'lowpass'; lp1.frequency.value = cutoff;
      const lp2 = ctx.createBiquadFilter(); lp2.type = 'lowpass'; lp2.frequency.value = cutoff;

      mono.connect(lp1);
      lp1.connect(lp2);

      lp2.connect(merger, 0, 0);
      lp2.connect(merger, 0, 1);
      return merger;
  }

  private extractDrums(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
       const lowShelf = ctx.createBiquadFilter(); 
       lowShelf.type = 'lowshelf'; 
       lowShelf.frequency.value = 150; 
       lowShelf.gain.value = 4;

       const midScoop = ctx.createBiquadFilter();
       midScoop.type = 'peaking';
       midScoop.frequency.value = 500;
       midScoop.gain.value = -4; 

       input.connect(lowShelf);
       lowShelf.connect(midScoop);
       return midScoop;
  }

  private extractBacking(ctx: OfflineAudioContext, input: AudioNode): AudioNode {
      // Remove Center (Vocal) info slightly to make room
      const splitter = ctx.createChannelSplitter(2);
      input.connect(splitter);

      const sideL = ctx.createGain();
      const inverter = ctx.createGain();
      inverter.gain.value = -1;

      splitter.connect(sideL, 0); 
      splitter.connect(inverter, 1); 
      inverter.connect(sideL); 

      const merger = ctx.createChannelMerger(2);
      sideL.connect(merger, 0, 0);
      sideL.connect(merger, 0, 1);

      // Mix in some original but dipped at vocal range
      const midDip = ctx.createBiquadFilter();
      midDip.type = 'peaking';
      midDip.frequency.value = 1000;
      midDip.gain.value = -6;
      input.connect(midDip);

      const sum = ctx.createGain();
      midDip.connect(sum);
      merger.connect(sum);

      return sum;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

export const audioService = new AudioEngine();

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, PluginType, AudioPlugin } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);

  const [recordingTrackId, setRecordingTrackId] = useState<string | null>(null);
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Scroll Synchronization Refs ---
  const trackHeaderRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Scroll Sync ---
  const handleTimelineScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (trackHeaderRef.current && timelineRef.current) {
          trackHeaderRef.current.scrollTop = timelineRef.current.scrollTop;
      }
  };

  // --- Undo/Redo System ---

  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  // Initial History
  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          // Sync Audio Engine
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex + 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };


  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (recordingTrackId) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [recordingTrackId]);

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const finishRecording = async () => {
      if (!recordingTrackId) return;

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: recordingTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setRecordingTrackId(null);
  };

  const handleRecordToggle = async (trackId: string) => {
      if (recordingTrackId === trackId) {
          await handleStop();
          return;
      }
      if (recordingTrackId) return;

      try {
          await audioService.resume();
          await audioService.startRecording();
          setRecordingTrackId(trackId);
          recordStartTimeRef.current = pauseTimeRef.current;
          if (!playbackState.isPlaying) startPlayback(pauseTimeRef.current);
      } catch (e) {
          alert("Could not start recording. Please allow microphone access.");
      }
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);

    // Check if Solo/Mute logic changed, apply real-time update
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             // Insert point
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) {
                 points[existingIdx] = point;
             } else {
                 points.push(point);
             }
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    );
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;

      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return; // Out of bounds

      const firstDuration = relativeSplit * clip.playbackRate; // Buffer duration

      const leftClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          duration: firstDuration,
          name: clip.name
      };

      const rightClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          startTime: splitTime,
          offset: clip.offset + firstDuration,
          duration: clip.duration - firstDuration,
          name: clip.name
      };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const newClips = clips.map(c => c.id === id ? { ...c, loop: !clip.loop } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---

  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();

      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}

        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* Track Headers - Sticky Left with Ref */}
        <div 
            ref={trackHeaderRef}
            className="flex-shrink-0 bg-gray-900 border-r border-gray-700 overflow-hidden z-10 shadow-xl"
            style={{ width: TRACK_HEADER_WIDTH, paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
        >
          {tracks.map(track => (
            <TrackControl 
              key={track.id} 
              track={track} 
              onUpdate={updateTrack}
              onDelete={deleteTrack}
              isRecording={recordingTrackId === track.id}
              onRecordToggle={handleRecordToggle}
              onOpenEditor={setEditingTrackId}
              onToggleAutomation={toggleAutomation}
            />
          ))}

          <div className="p-3 space-y-2">
             <button 
                onClick={addTrack}
                className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
             >
                <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors">
                    <Plus size={14} /> 
                </div>
                <span>Add New Track</span>
             </button>
          </div>
        </div>

        {/* Timeline Area - Main Scroll with Ref, event listener syncs headers */}
        <div className="flex-1 overflow-hidden relative flex flex-col">
            <div 
                ref={timelineRef}
                onScroll={handleTimelineScroll}
                className="flex-1 overflow-auto custom-scrollbar"
                style={{ paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
            >
                <Timeline 
                    tracks={tracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipUpdate={updateClip}
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    snap={snap}
                    tool={tool}
                    onDeleteClip={deleteClip}
                    onDuplicateClip={duplicateClip}
                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}

                    onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
                    selectedClipId={selectedClipId}
                    onCopyClip={handleCopyClip}
                    onPasteClip={handlePasteClip}
                    canPaste={!!clipboardClip}
                    onLoopClip={handleLoopToggle}
                />
            </div>
        </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

export default App;

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;
          let duration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > duration / clip.playbackRate && !clip.loop) return;

            const offsetAdj = timePassed * clip.playbackRate;
            if (clip.loop) {
                 offset = (offset + offsetAdj) % clip.buffer.duration;
            } else {
                 offset += offsetAdj;
                 duration -= (offsetAdj / clip.playbackRate);
            }
            whenToPlay = now;
          }

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              source.start(whenToPlay, offset);
          } else {
              if (duration > 0) source.start(whenToPlay, offset, duration);
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + (c.duration / c.playbackRate))) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }
}

