function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);

  const [recordingTrackId, setRecordingTrackId] = useState<string | null>(null);
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Scroll Synchronization Refs ---
  const trackHeaderRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Scroll Sync ---
  const handleTimelineScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (trackHeaderRef.current && timelineRef.current) {
          trackHeaderRef.current.scrollTop = timelineRef.current.scrollTop;
      }
  };

  // --- Undo/Redo System ---

  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  // Initial History
  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          // Sync Audio Engine
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex + 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };


  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (recordingTrackId) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [recordingTrackId]);

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const finishRecording = async () => {
      if (!recordingTrackId) return;

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: recordingTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setRecordingTrackId(null);
  };

  const handleRecordToggle = async (trackId: string) => {
      if (recordingTrackId === trackId) {
          await handleStop();
          return;
      }
      if (recordingTrackId) return;

      try {
          await audioService.resume();
          await audioService.startRecording();
          setRecordingTrackId(trackId);
          recordStartTimeRef.current = pauseTimeRef.current;
          if (!playbackState.isPlaying) startPlayback(pauseTimeRef.current);
      } catch (e) {
          alert("Could not start recording. Please allow microphone access.");
      }
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);

    // Check if Solo/Mute logic changed, apply real-time update
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             // Insert point
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) {
                 points[existingIdx] = point;
             } else {
                 points.push(point);
             }
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    );
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;

      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return; // Out of bounds

      const firstDuration = relativeSplit * clip.playbackRate; // Buffer duration

      const leftClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          duration: firstDuration,
          name: clip.name
      };

      const rightClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          startTime: splitTime,
          offset: clip.offset + firstDuration,
          duration: clip.duration - firstDuration,
          name: clip.name
      };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          // If enabling loop, instantly extend duration by one loop length so user sees effect
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;

          const newClips = clips.map(c => 
            c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c
          );
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---

  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();

      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}

        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* Track Headers - Sticky Left with Ref */}
        <div 
            ref={trackHeaderRef}
            className="flex-shrink-0 bg-gray-900 border-r border-gray-700 overflow-hidden z-10 shadow-xl"
            style={{ width: TRACK_HEADER_WIDTH, paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
        >
          {tracks.map(track => (
            <TrackControl 
              key={track.id} 
              track={track} 
              onUpdate={updateTrack}
              onDelete={deleteTrack}
              isRecording={recordingTrackId === track.id}
              onRecordToggle={handleRecordToggle}
              onOpenEditor={setEditingTrackId}
              onToggleAutomation={toggleAutomation}
            />
          ))}

          <div className="p-3 space-y-2">
             <button 
                onClick={addTrack}
                className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
             >
                <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors">
                    <Plus size={14} /> 
                </div>
                <span>Add New Track</span>
             </button>
          </div>
        </div>

        {/* Timeline Area - Main Scroll with Ref, event listener syncs headers */}
        <div className="flex-1 overflow-hidden relative flex flex-col">
            <div 
                ref={timelineRef}
                onScroll={handleTimelineScroll}
                className="flex-1 overflow-auto custom-scrollbar"
                style={{ paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
            >
                <Timeline 
                    tracks={tracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipUpdate={updateClip}
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={setZoom} // Passed for wheel zoom
                    snap={snap}
                    tool={tool}
                    onDeleteClip={deleteClip}
                    onDuplicateClip={duplicateClip}
                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}

                    onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
                    selectedClipId={selectedClipId}
                    onCopyClip={handleCopyClip}
                    onPasteClip={handlePasteClip}
                    canPaste={!!clipboardClip}
                    onLoopClip={handleLoopToggle}
                    onClipResize={handleClipResize}
                />
            </div>
        </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

export default App;

import React, { useEffect, useRef, useState } from 'react';
import { Track } from '../types';
import { Volume2, VolumeX, Mic, Headphones, Activity, TrendingUp, ChevronDown } from 'lucide-react';
import { audioService } from '../services/audioEngine';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT } from '../constants';

interface TrackControlProps {
  track: Track;
  onUpdate: (id: string, updates: Partial<Track>) => void;
  onDelete: (id: string) => void;
  isRecording: boolean;
  onRecordToggle: (trackId: string) => void;
  onOpenEditor: (trackId: string) => void;
  onToggleAutomation: (trackId: string) => void;
}

export const TrackControl: React.FC<TrackControlProps> = ({ 
    track, 
    onUpdate, 
    onDelete, 
    isRecording, 
    onRecordToggle,
    onOpenEditor,
    onToggleAutomation
}) => {
  const isMaster = track.isMaster;
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [peak, setPeak] = useState(0);

  // Meter Animation
  useEffect(() => {
    let animationId: number;
    const analyser = audioService.getTrackAnalyser(track.id);

    if (analyser && canvasRef.current) {
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);
        const ctx = canvasRef.current.getContext('2d');
        let localPeak = 0;
        let peakHoldTimer = 0;

        const draw = () => {
            if (!ctx) return;
            analyser.getByteTimeDomainData(dataArray);

            let sum = 0;
            let framePeak = 0;

            for(let i = 0; i < bufferLength; i++) {
                const sample = (dataArray[i] - 128) / 128; 
                sum += sample * sample;
                if (Math.abs(sample) > framePeak) framePeak = Math.abs(sample);
            }

            const rms = Math.sqrt(sum / bufferLength);

            if (framePeak > localPeak) {
                localPeak = framePeak;
                peakHoldTimer = 60; 
            } else {
                peakHoldTimer--;
                if (peakHoldTimer <= 0) localPeak *= 0.95; 
            }

            setPeak(localPeak);

            const width = canvasRef.current!.width;
            const height = canvasRef.current!.height;

            ctx.clearRect(0, 0, width, height);

            ctx.fillStyle = '#111827';
            ctx.fillRect(0, 0, width, height);

            const rmsWidth = width * Math.min(1, Math.pow(rms * 4, 0.6));

            const gradient = ctx.createLinearGradient(0, 0, width, 0);
            gradient.addColorStop(0, '#10b981'); 
            gradient.addColorStop(0.6, '#f59e0b'); 
            gradient.addColorStop(0.85, '#ef4444'); 

            ctx.fillStyle = gradient;
            ctx.fillRect(0, 0, rmsWidth, height);

            const peakPos = width * Math.min(1, Math.pow(localPeak * 4, 0.6));
            ctx.fillStyle = '#ffffff';
            ctx.fillRect(peakPos, 0, 2, height);

            if (localPeak >= 0.98) {
                ctx.fillStyle = '#ef4444';
                ctx.fillRect(width - 4, 0, 4, height);
            }

            animationId = requestAnimationFrame(draw);
        };
        draw();
    }
    return () => cancelAnimationFrame(animationId);
  }, [track.id]);

  const height = track.showAutomation ? TRACK_HEIGHT + AUTOMATION_HEIGHT : TRACK_HEIGHT;

  return (
    <div 
        className={`flex flex-col p-3 border-b box-border ${isMaster ? 'bg-gray-900 border-t border-blue-500/30' : 'bg-gray-800 border-gray-700'} relative group select-none transition-all`}
        style={{ height: `${height}px` }}
        onDoubleClick={() => onOpenEditor(track.id)}
    >
      <div className="flex items-center justify-between mb-2">
        <div className="flex items-center gap-2">
            {!isMaster && <div className="w-3 h-3 rounded-full" style={{ backgroundColor: track.color }} />}
            {isMaster && <Activity size={14} className="text-blue-400" />}
            <span className={`font-semibold text-sm truncate w-24 ${isMaster ? 'text-blue-400' : 'text-gray-200'}`} title={track.name}>
            {track.name}
            </span>
        </div>
        {!isMaster && (
            <button 
                onClick={(e) => { e.stopPropagation(); onDelete(track.id); }}
                className="text-xs text-gray-500 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"
            >
                Delete
            </button>
        )}
      </div>

      <div className="flex items-center gap-2 mb-2">
        {!isMaster && (
            <>
                <button
                onClick={(e) => { e.stopPropagation(); onRecordToggle(track.id); }}
                className={`p-1.5 rounded-full transition-all ${isRecording ? 'bg-red-500 text-white animate-pulse' : 'bg-gray-700 text-red-500 hover:bg-gray-600 hover:text-red-400'}`}
                title="Record"
                >
                <div className={`w-3 h-3 rounded-full ${isRecording ? 'bg-white' : 'bg-current'}`} />
                </button>

                <button
                onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { muted: !track.muted }); }}
                className={`p-1 rounded ${track.muted ? 'bg-red-500/20 text-red-500' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Mute"
                >
                {track.muted ? <VolumeX size={14} /> : <Volume2 size={14} />}
                </button>
                <button
                onClick={(e) => { e.stopPropagation(); onUpdate(track.id, { soloed: !track.soloed }); }}
                className={`p-1 rounded ${track.soloed ? 'bg-yellow-500/20 text-yellow-500' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Solo"
                >
                <Headphones size={14} />
                </button>
                <button
                onClick={(e) => { e.stopPropagation(); onToggleAutomation(track.id); }}
                className={`p-1 rounded ${track.showAutomation ? 'bg-blue-500/20 text-blue-400' : 'bg-gray-700 text-gray-400 hover:text-gray-200'}`}
                title="Automation"
                >
                <TrendingUp size={14} />
                </button>
            </>
        )}

        {isMaster && <span className="text-[10px] text-gray-500 uppercase font-bold">Vol</span>}

        <div className="flex-1" onClick={e => e.stopPropagation()}>
            <input
                type="range"
                min="0"
                max="1"
                step="0.01"
                value={track.volume}
                onChange={(e) => onUpdate(track.id, { volume: parseFloat(e.target.value) })}
                className={`w-full h-1 rounded-lg appearance-none cursor-pointer ${isMaster ? 'accent-blue-400 bg-gray-700' : 'accent-blue-500 bg-gray-600'}`}
                disabled={track.showAutomation && track.selectedAutomationId === 'volume'}
            />
        </div>
      </div>

      <div className="h-2 w-full bg-gray-900 rounded overflow-hidden mt-1 relative border border-gray-800">
          <canvas ref={canvasRef} width={200} height={8} className="w-full h-full block" />
          <div className="absolute inset-0 flex justify-between px-2 pointer-events-none opacity-50">
               <div className="w-px h-full bg-black/50" style={{ left: '50%' }}></div>
               <div className="w-px h-full bg-black/50" style={{ left: '75%' }}></div>
          </div>
      </div>

      {isMaster && (
          <div className="flex justify-between text-[9px] text-gray-500 font-mono mt-0.5 px-1">
              <span>-inf</span>
              <span>-12</span>
              <span>-6</span>
              <span>0dB</span>
          </div>
      )}

      {/* Improved Automation Header with Dropdown */}
      {track.showAutomation && (
           <div 
             className="absolute bottom-0 left-0 right-0 bg-gray-850 border-t border-gray-700 p-2 flex flex-col gap-1 animate-fade-in"
             style={{ height: `${AUTOMATION_HEIGHT}px` }}
           >
               <div className="flex items-center justify-between">
                   <div className="flex items-center gap-1 text-blue-400 text-[10px] font-bold uppercase">
                       <TrendingUp size={10} /> Auto:
                   </div>
                   {/* Automation Type Selector */}
                   <div className="relative">
                       <select 
                        className="bg-gray-900 text-[10px] text-gray-300 border border-gray-700 rounded px-1 py-0.5 outline-none focus:border-blue-500 w-32 appearance-none"
                        value={track.selectedAutomationId || 'volume'}
                        onChange={(e) => onUpdate(track.id, { selectedAutomationId: e.target.value })}
                        onClick={(e) => e.stopPropagation()}
                       >
                           <option value="volume">Volume</option>
                           <option value="pan">Pan</option>
                           {/* Dynamic Plugin Params */}
                           {track.plugins.map(p => {
                               if (p.type === 'REVERB') return (
                                   <React.Fragment key={p.id}>
                                        <option value={`${p.id}:mix`}>Reverb Mix</option>
                                        <option value={`${p.id}:decay`}>Reverb Decay</option>
                                   </React.Fragment>
                               );
                               if (p.type === 'DELAY') return <option key={p.id} value={`${p.id}:time`}>Delay Time</option>;
                               if (p.type === 'DISTORTION') return <option key={p.id} value={`${p.id}:drive`}>Distortion</option>;
                               if (p.type === 'HIGHPASS' || p.type === 'LOWPASS') return <option key={p.id} value={`${p.id}:frequency`}>{p.type} Freq</option>;
                               return null;
                           })}
                       </select>
                       <ChevronDown size={10} className="absolute right-1 top-1.5 text-gray-500 pointer-events-none" />
                   </div>
               </div>
               <span className="text-[9px] text-gray-500 text-right">Click timeline to add points</span>
           </div>
      )}

    </div>
  );
};

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, Scissors, GripVertical } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipUpdate: (id: string, newTime: number, newTrackId?: string) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;
  onDeleteClip: (id: string) => void;
  onDuplicateClip: (id: string) => void;
  onRenameClip: (id: string, newName: string) => void;

  onSelectClip: (id: string | null) => void;
  selectedClipId: string | null;
  onCopyClip: (id: string) => void;
  onPasteClip: (time: number, trackId: string) => void;
  canPaste: boolean;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND';
    targetId?: string; 
    time?: number; 
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipUpdate, 
  onFileDrop,
  onSeek,
  onDeleteClip,
  onDuplicateClip,
  onRenameClip,
  onSelectClip,
  selectedClipId,
  onCopyClip,
  onPasteClip,
  canPaste,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<number>(0);
  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) setDraggedClipId(null);
           if (resizingClipId) setResizingClipId(null);
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId]);

  // Global Mouse Move for dragging/resizing outside container bounds
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;
          const rect = timelineRef.current.getBoundingClientRect();
          const scrollLeft = timelineRef.current.scrollLeft || 0;
          const currentX = e.clientX - rect.left + scrollLeft;
          // const currentTimePos = Math.max(0, currentX / zoom); // Unused

          // RESIZING LOGIC
          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); // Min 0.1s

             // Optional: Snap duration to grid if snap is enabled
             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;

             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize]);

  // Wheel Zoom Listener
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              // Calculate zoom factor
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom)); // Clamp zoom
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);


  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      const snapInterval = beat; // Snap to quarter notes
      return Math.round(time / snapInterval) * snapInterval;
  };

  // --- Handlers ---

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId) return;

    const target = e.target as HTMLElement;
    const clipElement = target.closest('[data-clip-id]');

    // Automation Point Click
    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const scrollLeft = timelineRef.current?.scrollLeft || 0;
                 const clickX = e.clientX - rect.left + scrollLeft;
                 const time = Math.max(0, clickX / zoom);

                 // Calculate Y value (inverted: top is 1, bottom is 0)
                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));

                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const scrollLeft = timelineRef.current?.scrollLeft || 0;
             const clickX = e.clientX - rect.left + scrollLeft;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    // Normal Seek Logic
    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        onSelectClip(null);
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;
        const scrollLeft = timelineRef.current?.scrollLeft || 0;
        const clickX = e.clientX - rect.left + scrollLeft;
        const seekTime = Math.max(0, (clickX / zoom));
        onSeek(snapToGrid(seekTime));
    }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const scrollLeft = timelineRef.current?.scrollLeft || 0;
    const clickX = e.clientX - rect.left + scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        if (file.type.startsWith('audio/')) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const adjustedTime = Math.max(0, (clickX / zoom) - dragOffset);
        onClipUpdate(draggedClipId, snapToGrid(adjustedTime), trackId);
        setDraggedClipId(null);
        setDragOffset(0);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }
     onSelectClip(clip.id);
     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     setDragOffset(offsetTime);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      onSelectClip(clip.id);
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      onSelectClip(clipId);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const scrollLeft = timelineRef.current?.scrollLeft || 0;
      const clickX = e.clientX - (rect?.left || 0) + scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP' && contextMenu.targetId) {
           switch(action) {
              case 'delete': onDeleteClip(contextMenu.targetId); break;
              case 'duplicate': onDuplicateClip(contextMenu.targetId); break;
              case 'rename': 
                  const clip = clips.find(c => c.id === contextMenu.targetId);
                  if (clip) {
                      const newName = prompt("Rename clip:", clip.name);
                      if (newName) onRenameClip(contextMenu.targetId, newName);
                  }
                  break;
              case 'copy': onCopyClip(contextMenu.targetId); break;
              case 'loop': onLoopClip(contextMenu.targetId); break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClip(contextMenu.time, contextMenu.targetId);
           }
      }
      setContextMenu(null);
  };

  // Helper to draw automation lines
  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];

      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);

      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          // Scale to automation lane height minus padding
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  // Render waveforms with loop support
  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ 
                        left: i * singleLoopWidth, 
                        width: singleLoopWidth 
                    }}
                 >
                     <Waveform 
                        clip={clip} 
                        width={singleLoopWidth} 
                        height={TRACK_HEIGHT - 10} 
                        color={i === 0 ? "#ffffff" : "#ffffffaa"} 
                     />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <div 
      className={`flex-1 overflow-auto bg-gray-950 relative custom-scrollbar flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
      ref={timelineRef}
      onClick={handleTimelineClick}
    >
        {/* Playhead */}
        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler */}
        <div 
          className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex" 
          style={{ width: `${totalBars * pixelsPerBar}px`, height: `${TIMELINE_RULER_HEIGHT}px` }}
        >
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     {/* Quarter Beats */}
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}
        </div>

      <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
        {tracks.map(track => (
          <div key={track.id} className="flex flex-col">
            {/* Standard Track Lane */}
            <div 
                className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, track.id)}
                onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                style={{ 
                    height: `${TRACK_HEIGHT}px`,
                    backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                    backgroundSize: `${pixelsPerBar}px 100%`,
                    backgroundPosition: '0 0'
                }}
            >
                <div 
                    className="absolute inset-0 pointer-events-none" 
                    style={{
                        backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                        backgroundSize: `${pixelsPerBeat}px 100%`,
                        opacity: 0.1
                    }}
                />

                {clips.filter(c => c.trackId === track.id).map(clip => (
                <div
                    key={clip.id}
                    data-clip-id={clip.id}
                    draggable={tool === 'MOVE'}
                    onDragStart={(e) => handleDragStart(e, clip)}
                    onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                    onClick={(e) => e.stopPropagation()} 
                    onMouseDown={(e) => {
                        if (tool === 'MOVE') onSelectClip(clip.id);
                    }}
                    className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                    ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                    ${selectedClipId === clip.id ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                    style={{
                        left: `${clip.startTime * zoom}px`,
                        width: `${clip.duration * zoom}px`, // Use timeline duration, not buffer duration
                    }}
                >
                    <div 
                        className="absolute inset-0 opacity-60"
                        style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}
                    ></div>

                    {clip.loop && (
                        <div className="absolute top-0 right-4 p-1 text-white/70 z-30">
                            <RotateCw size={10} />
                        </div>
                    )}

                    <div className="absolute inset-0 z-10">
                        {renderClipContent(clip, track)}
                    </div>

                    <div className="absolute top-1 left-1 z-20 max-w-full">
                        <div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">
                            {clip.name}
                        </div>
                    </div>

                    {/* Resize Handle */}
                    {tool === 'MOVE' && (
                        <div 
                            className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle"
                            onMouseDown={(e) => handleResizeStart(e, clip)}
                        >
                            <GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" />
                        </div>
                    )}
                </div>
                ))}
            </div>

            {/* Automation Lane */}
            {track.showAutomation && (
                <div 
                    className="bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair box-border"
                    data-automation-track-id={track.id}
                    style={{ 
                        minWidth: `${totalBars * pixelsPerBar}px`,
                        height: `${AUTOMATION_HEIGHT}px`
                    }}
                >
                    <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                    <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">
                        {track.selectedAutomationId === 'pan' ? 'Pan' : 
                         track.selectedAutomationId === 'volume' ? 'Vol' : 
                         track.selectedAutomationId?.split(':')[1].toUpperCase()}
                    </div>
                    <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>
                        {renderAutomationPoints(track)}
                    </svg>
                </div>
            )}
          </div>
        ))}
        <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">
             End of tracks
        </div>
      </div>

      {contextMenu && (
          <div 
              className="fixed z-50 w-48 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
              style={{ top: contextMenu.y, left: contextMenu.x }}
          >
              {/* Menu items same as before */}
              {contextMenu.type === 'CLIP' ? (
                  <>
                    <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Copy size={14} /> Copy
                    </button>
                     <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <RotateCw size={14} /> Toggle Loop
                    </button>
                    <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Pencil size={14} /> Rename
                    </button>
                    <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2">
                        <Copy size={14} /> Duplicate
                    </button>
                    <div className="h-px bg-gray-700 my-1" />
                    <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2">
                        <Trash2 size={14} /> Delete
                    </button>
                  </>
              ) : (
                  <>
                    <button 
                        onClick={(e) => handleMenuAction(e, 'paste')} 
                        disabled={!canPaste}
                        className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}
                    >
                        <ClipboardPaste size={14} /> Paste
                    </button>
                  </>
              )}
          </div>
      )}
    </div>
  );
};

import React from 'react';
import { Play, Square, FastForward, Rewind, Activity, Scissors, MousePointer2, ZoomIn, ZoomOut, Grid, Undo, Redo, Download } from 'lucide-react';
import { ToolType } from '../types';

interface TransportProps {
  isPlaying: boolean;
  onPlay: () => void;
  onStop: () => void;
  onRewind: () => void;
  onFastForward: () => void;
  currentTime: number;
  bpm: number;
  setBpm: (bpm: number) => void;

  // New Props
  tool: ToolType;
  setTool: (t: ToolType) => void;
  zoom: number;
  setZoom: (z: number) => void;
  snap: boolean;
  setSnap: (s: boolean) => void;
  onUndo: () => void;
  onRedo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  onExport: () => void;
  isExporting: boolean;
}

const formatTime = (seconds: number) => {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  const ms = Math.floor((seconds % 1) * 100);
  return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}.${ms.toString().padStart(2, '0')}`;
};

export const Transport: React.FC<TransportProps> = ({ 
    isPlaying, 
    onPlay, 
    onStop, 
    onRewind,
    onFastForward,
    currentTime, 
    bpm, 
    setBpm,
    tool,
    setTool,
    zoom,
    setZoom,
    snap,
    setSnap,
    onUndo,
    onRedo,
    canUndo,
    canRedo,
    onExport,
    isExporting
}) => {
  return (
    <div className="h-16 bg-gray-900 border-b border-gray-700 flex items-center px-4 justify-between z-30 shadow-lg select-none">
      <div className="flex items-center gap-4">
        <div className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-500 mr-2">
            ISLdaw
        </div>

        {/* File Actions */}
        <div className="flex items-center gap-1 bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button 
                onClick={onUndo} disabled={!canUndo}
                className="p-1.5 text-gray-400 hover:text-white disabled:opacity-30 rounded hover:bg-gray-700" title="Undo"
             >
                <Undo size={16} />
             </button>
             <button 
                onClick={onRedo} disabled={!canRedo}
                className="p-1.5 text-gray-400 hover:text-white disabled:opacity-30 rounded hover:bg-gray-700" title="Redo"
             >
                <Redo size={16} />
             </button>
        </div>

        {/* Tools */}
        <div className="flex items-center gap-1 bg-gray-800 rounded-lg p-1 border border-gray-700">
             <button 
                onClick={() => setTool('MOVE')}
                className={`p-1.5 rounded transition-all ${tool === 'MOVE' ? 'bg-blue-500 text-white shadow-sm' : 'text-gray-400 hover:text-white hover:bg-gray-700'}`}
                title="Move Tool"
             >
                <MousePointer2 size={16} />
             </button>
             <button 
                onClick={() => setTool('BLADE')}
                className={`p-1.5 rounded transition-all ${tool === 'BLADE' ? 'bg-blue-500 text-white shadow-sm' : 'text-gray-400 hover:text-white hover:bg-gray-700'}`}
                title="Blade Tool"
             >
                <Scissors size={16} />
             </button>
        </div>

        <div className="w-px h-8 bg-gray-700 mx-1"></div>

        {/* Transport */}
        <div className="flex bg-gray-800 rounded-lg p-1 gap-1 border border-gray-700">
            <button 
                onClick={onRewind}
                className="p-2 text-gray-400 hover:text-white rounded hover:bg-gray-700 active:scale-95 transition-transform"
            >
                <Rewind size={18} />
            </button>
            <button 
                onClick={isPlaying ? onStop : onPlay}
                className={`p-2 rounded transition-all active:scale-95 ${isPlaying ? 'text-yellow-400 bg-yellow-400/10' : 'text-green-400 hover:bg-green-400/10 hover:text-green-300'}`}
            >
                {isPlaying ? <Square size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" />}
            </button>
             <button 
                onClick={onFastForward}
                className="p-2 text-gray-400 hover:text-white rounded hover:bg-gray-700 active:scale-95 transition-transform"
            >
                <FastForward size={18} />
            </button>
        </div>

        {/* Time Display */}
        <div className="bg-black/40 px-3 py-1.5 rounded text-blue-400 font-mono text-lg min-w-[100px] text-center border border-blue-500/20 shadow-inner">
            {formatTime(currentTime)}
        </div>
      </div>

      <div className="flex items-center gap-4">

        {/* BPM */}
        <div className="flex items-center gap-2 bg-gray-800 rounded-lg p-1.5 border border-gray-700 group focus-within:border-blue-500/50">
            <Activity size={14} className="text-gray-500 group-focus-within:text-blue-400 ml-1" />
            <div className="flex flex-col items-start mr-1">
                <span className="text-[9px] text-gray-500 font-bold leading-none uppercase">BPM</span>
                <input 
                    type="number" 
                    value={bpm}
                    onChange={(e) => setBpm(Math.max(1, Math.min(999, Number(e.target.value))))}
                    className="w-12 bg-transparent text-sm font-mono text-blue-400 outline-none p-0 leading-none"
                />
            </div>
        </div>

        {/* Zoom & Snap */}
        <div className="flex items-center gap-2 bg-gray-800 rounded-lg p-1.5 border border-gray-700">
             <button onClick={() => setSnap(!snap)} className={`p-1 rounded ${snap ? 'text-blue-400 bg-blue-500/20' : 'text-gray-500 hover:text-gray-300'}`} title="Snap to Grid">
                 <Grid size={16} />
             </button>
             <div className="w-px h-4 bg-gray-600 mx-1"></div>
             <ZoomOut size={14} className="text-gray-500" />
             <input 
                type="range" min="10" max="500" step="10"
                value={zoom}
                onChange={(e) => setZoom(Number(e.target.value))}
                className="w-24 h-1 bg-gray-600 rounded-lg appearance-none cursor-pointer accent-blue-500"
            />
             <ZoomIn size={14} className="text-gray-500" />
        </div>

        <button 
            onClick={onExport}
            disabled={isExporting}
            className="flex items-center gap-2 bg-purple-600 hover:bg-purple-500 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50"
        >
            <Download size={16} />
            {isExporting ? 'Exporting...' : 'Export'}
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, PluginType, AudioPlugin } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);

  const [recordingTrackId, setRecordingTrackId] = useState<string | null>(null);
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Scroll Synchronization Refs ---
  const trackHeaderRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Scroll Sync ---
  const handleTimelineScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (trackHeaderRef.current && timelineRef.current) {
          trackHeaderRef.current.scrollTop = timelineRef.current.scrollTop;
      }
  };

  const handleHeaderWheel = (e: React.WheelEvent) => {
      if (timelineRef.current) {
          timelineRef.current.scrollTop += e.deltaY;
      }
  };

  // --- Undo/Redo System ---

  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  // Initial History
  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          // Sync Audio Engine
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex + 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };


  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (recordingTrackId) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [recordingTrackId]);

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const finishRecording = async () => {
      if (!recordingTrackId) return;

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: recordingTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setRecordingTrackId(null);
  };

  const handleRecordToggle = async (trackId: string) => {
      if (recordingTrackId === trackId) {
          await handleStop();
          return;
      }
      if (recordingTrackId) return;

      try {
          await audioService.resume();
          await audioService.startRecording();
          setRecordingTrackId(trackId);
          recordStartTimeRef.current = pauseTimeRef.current;
          if (!playbackState.isPlaying) startPlayback(pauseTimeRef.current);
      } catch (e) {
          alert("Could not start recording. Please allow microphone access.");
      }
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);

    // Check if Solo/Mute logic changed, apply real-time update
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             // Insert point
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) {
                 points[existingIdx] = point;
             } else {
                 points.push(point);
             }
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    );
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;

      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return; // Out of bounds

      const firstDuration = relativeSplit * clip.playbackRate; // Buffer duration

      const leftClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          duration: firstDuration,
          name: clip.name
      };

      const rightClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          startTime: splitTime,
          offset: clip.offset + firstDuration,
          duration: clip.duration - firstDuration,
          name: clip.name
      };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          // If enabling loop, instantly extend duration by one loop length so user sees effect
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;

          const newClips = clips.map(c => 
            c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c
          );
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---

  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();

      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}

        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* Track Headers - Sticky Left with Ref */}
        <div 
            ref={trackHeaderRef}
            onWheel={handleHeaderWheel}
            className="flex-shrink-0 bg-gray-900 border-r border-gray-700 overflow-hidden z-10 shadow-xl"
            style={{ width: TRACK_HEADER_WIDTH, paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
        >
          {/* Spacer to align with Timeline Ruler */}
          <div className="flex-shrink-0 bg-gray-900 border-b border-gray-700 box-border z-20 sticky top-0 flex items-end pb-1 px-3" style={{ height: TIMELINE_RULER_HEIGHT }}>
              <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">Tracks</span>
          </div>

          {tracks.map(track => (
            <TrackControl 
              key={track.id} 
              track={track} 
              onUpdate={updateTrack}
              onDelete={deleteTrack}
              isRecording={recordingTrackId === track.id}
              onRecordToggle={handleRecordToggle}
              onOpenEditor={setEditingTrackId}
              onToggleAutomation={toggleAutomation}
            />
          ))}

          <div className="p-3 space-y-2">
             <button 
                onClick={addTrack}
                className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
             >
                <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors">
                    <Plus size={14} /> 
                </div>
                <span>Add New Track</span>
             </button>
          </div>
        </div>

        {/* Timeline Area - Main Scroll with Ref, event listener syncs headers */}
        <div className="flex-1 overflow-hidden relative flex flex-col">
            <div 
                ref={timelineRef}
                onScroll={handleTimelineScroll}
                className="flex-1 overflow-auto custom-scrollbar"
                style={{ paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
            >
                <Timeline 
                    tracks={tracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipUpdate={updateClip}
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={setZoom} // Passed for wheel zoom
                    snap={snap}
                    tool={tool}
                    onDeleteClip={deleteClip}
                    onDuplicateClip={duplicateClip}
                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}

                    onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
                    selectedClipId={selectedClipId}
                    onCopyClip={handleCopyClip}
                    onPasteClip={handlePasteClip}
                    canPaste={!!clipboardClip}
                    onLoopClip={handleLoopToggle}
                    onClipResize={handleClipResize}
                />
            </div>
        </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, Scissors, GripVertical } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipUpdate: (id: string, newTime: number, newTrackId?: string) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;
  onDeleteClip: (id: string) => void;
  onDuplicateClip: (id: string) => void;
  onRenameClip: (id: string, newName: string) => void;

  onSelectClip: (id: string | null) => void;
  selectedClipId: string | null;
  onCopyClip: (id: string) => void;
  onPasteClip: (time: number, trackId: string) => void;
  canPaste: boolean;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;
  showRuler?: boolean;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND';
    targetId?: string; 
    time?: number; 
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipUpdate, 
  onFileDrop,
  onSeek,
  onDeleteClip,
  onDuplicateClip,
  onRenameClip,
  onSelectClip,
  selectedClipId,
  onCopyClip,
  onPasteClip,
  canPaste,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize,
  showRuler = true
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<number>(0);
  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) setDraggedClipId(null);
           if (resizingClipId) setResizingClipId(null);
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId]);

  // Global Mouse Move for dragging/resizing outside container bounds
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;
          // No internal scroll calc needed here, resizing is based on screen delta

          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); 

             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;

             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize]);

  // Wheel Zoom Listener
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom)); 
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);


  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      const snapInterval = beat; 
      return Math.round(time / snapInterval) * snapInterval;
  };

  // --- Handlers ---

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId) return;

    const target = e.target as HTMLElement;
    const clipElement = target.closest('[data-clip-id]');

    // Automation Point Click
    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const clickX = e.clientX - rect.left;
                 const time = Math.max(0, clickX / zoom);

                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));

                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const clickX = e.clientX - rect.left;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        onSelectClip(null);
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;

        // We use clientX relative to the rect. 
        // Since this div scrolls with the parent, rect.left moves left (becomes negative).
        // e.clientX - rect.left CORRECTLY calculates the offset from the start of the div.
        const clickX = e.clientX - rect.left;
        const seekTime = Math.max(0, (clickX / zoom));
        onSeek(snapToGrid(seekTime));
    }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const clickX = e.clientX - rect.left;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        if (file.type.startsWith('audio/')) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        // dragOffset is in time
        const adjustedTime = Math.max(0, rawTime - dragOffset);
        onClipUpdate(draggedClipId, snapToGrid(adjustedTime), trackId);
        setDraggedClipId(null);
        setDragOffset(0);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }
     onSelectClip(clip.id);

     // Calculate offset from start of clip
     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     setDragOffset(offsetTime);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      onSelectClip(clip.id);
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      onSelectClip(clipId);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0);
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP' && contextMenu.targetId) {
           switch(action) {
              case 'delete': onDeleteClip(contextMenu.targetId); break;
              case 'duplicate': onDuplicateClip(contextMenu.targetId); break;
              case 'rename': 
                  const clip = clips.find(c => c.id === contextMenu.targetId);
                  if (clip) {
                      const newName = prompt("Rename clip:", clip.name);
                      if (newName) onRenameClip(contextMenu.targetId, newName);
                  }
                  break;
              case 'copy': onCopyClip(contextMenu.targetId); break;
              case 'loop': onLoopClip(contextMenu.targetId); break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClip(contextMenu.time, contextMenu.targetId);
           }
      }
      setContextMenu(null);
  };

  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];
      if (!points || points.length === 0) return null;
      const sortedPoints = [...points].sort((a, b) => a.time - b.time);

      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle cx={p.time * zoom} cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} r="12" fill="transparent" className="cursor-pointer"/>
                    <circle cx={p.time * zoom} cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} r="4" fill="#3b82f6" className="pointer-events-none"/>
                  </g>
              ))}
          </>
      );
  };

  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ left: i * singleLoopWidth, width: singleLoopWidth }}
                 >
                     <Waveform clip={clip} width={singleLoopWidth} height={TRACK_HEIGHT - 10} color={i === 0 ? "#ffffff" : "#ffffffaa"} />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <div 
      className={`relative bg-gray-950 select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
      style={{ width: `${totalBars * pixelsPerBar}px` }} // Explicit width to force scroll in parent
      ref={timelineRef}
      onClick={handleTimelineClick}
    >
        {/* Playhead */}
        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler */}
        {showRuler && (
            <div 
            className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex" 
            style={{ width: '100%', height: `${TIMELINE_RULER_HEIGHT}px` }}
            >
                {barsArray.map((_, i) => (
                    <div key={i} className="relative h-full border-l border-gray-600/50" style={{ width: `${pixelsPerBar}px` }}>
                        <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                        <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                        <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                        <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                    </div>
                ))}
            </div>
        )}

      <div className="flex flex-col relative w-full">
        {tracks.map(track => (
          <div key={track.id} className="flex flex-col">
            {/* Standard Track Lane */}
            <div 
                className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                onDragOver={handleDragOver}
                onDrop={(e) => handleDrop(e, track.id)}
                onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                style={{ 
                    height: `${TRACK_HEIGHT}px`,
                    backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                    backgroundSize: `${pixelsPerBar}px 100%`,
                    backgroundPosition: '0 0'
                }}
            >
                <div 
                    className="absolute inset-0 pointer-events-none" 
                    style={{
                        backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                        backgroundSize: `${pixelsPerBeat}px 100%`,
                        opacity: 0.1
                    }}
                />

                {clips.filter(c => c.trackId === track.id).map(clip => (
                <div
                    key={clip.id}
                    data-clip-id={clip.id}
                    draggable={tool === 'MOVE'}
                    onDragStart={(e) => handleDragStart(e, clip)}
                    onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                    onClick={(e) => e.stopPropagation()} 
                    onMouseDown={(e) => { if (tool === 'MOVE') onSelectClip(clip.id); }}
                    className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                    ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                    ${selectedClipId === clip.id ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                    style={{
                        left: `${clip.startTime * zoom}px`,
                        width: `${clip.duration * zoom}px`, 
                    }}
                >
                    <div className="absolute inset-0 opacity-60" style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}></div>
                    {clip.loop && <div className="absolute top-0 right-4 p-1 text-white/70 z-30"><RotateCw size={10} /></div>}
                    <div className="absolute inset-0 z-10">{renderClipContent(clip, track)}</div>
                    <div className="absolute top-1 left-1 z-20 max-w-full">
                        <div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">{clip.name}</div>
                    </div>
                    {tool === 'MOVE' && (
                        <div 
                            className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle"
                            onMouseDown={(e) => handleResizeStart(e, clip)}
                        >
                            <GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" />
                        </div>
                    )}
                </div>
                ))}
            </div>

            {/* Automation Lane */}
            {track.showAutomation && (
                <div 
                    className="bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair box-border"
                    data-automation-track-id={track.id}
                    style={{ height: `${AUTOMATION_HEIGHT}px` }}
                >
                    <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                    <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">
                        {track.selectedAutomationId === 'pan' ? 'Pan' : track.selectedAutomationId === 'volume' ? 'Vol' : track.selectedAutomationId?.split(':')[1].toUpperCase()}
                    </div>
                    <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>{renderAutomationPoints(track)}</svg>
                </div>
            )}
          </div>
        ))}
      </div>

      {contextMenu && (
          <div 
              className="fixed z-50 w-48 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
              style={{ top: contextMenu.y, left: contextMenu.x }}
          >
              {contextMenu.type === 'CLIP' ? (
                  <>
                    <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Copy</button>
                    <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><RotateCw size={14} /> Toggle Loop</button>
                    <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Pencil size={14} /> Rename</button>
                    <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Duplicate</button>
                    <div className="h-px bg-gray-700 my-1" />
                    <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2"><Trash2 size={14} /> Delete</button>
                  </>
              ) : (
                  <button onClick={(e) => handleMenuAction(e, 'paste')} disabled={!canPaste} className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}><ClipboardPaste size={14} /> Paste</button>
              )}
          </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, PluginType, AudioPlugin } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);

  const [recordingTrackId, setRecordingTrackId] = useState<string | null>(null);
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Scroll Synchronization Refs ---
  const trackHeaderRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);
  const masterLaneRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Scroll Sync ---
  const handleTimelineScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (timelineRef.current) {
          const { scrollTop, scrollLeft } = timelineRef.current;

          // Sync Vertical Scroll to Headers
          if (trackHeaderRef.current) {
              trackHeaderRef.current.scrollTop = scrollTop;
          }
          // Sync Horizontal Scroll to Master Lane
          if (masterLaneRef.current) {
              masterLaneRef.current.scrollLeft = scrollLeft;
          }
      }
  };

  const handleHeaderWheel = (e: React.WheelEvent) => {
      if (timelineRef.current) {
          timelineRef.current.scrollTop += e.deltaY;
      }
  };

  // --- Undo/Redo System ---

  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  // Initial History
  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          // Sync Audio Engine
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex + 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };


  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (recordingTrackId) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [recordingTrackId]);

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const finishRecording = async () => {
      if (!recordingTrackId) return;

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: recordingTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setRecordingTrackId(null);
  };

  const handleRecordToggle = async (trackId: string) => {
      if (recordingTrackId === trackId) {
          await handleStop();
          return;
      }
      if (recordingTrackId) return;

      try {
          await audioService.resume();
          await audioService.startRecording();
          setRecordingTrackId(trackId);
          recordStartTimeRef.current = pauseTimeRef.current;
          if (!playbackState.isPlaying) startPlayback(pauseTimeRef.current);
      } catch (e) {
          alert("Could not start recording. Please allow microphone access.");
      }
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);

    // Check if Solo/Mute logic changed, apply real-time update
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             // Insert point
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) {
                 points[existingIdx] = point;
             } else {
                 points.push(point);
             }
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    );
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;

      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return; // Out of bounds

      const firstDuration = relativeSplit * clip.playbackRate; // Buffer duration

      const leftClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          duration: firstDuration,
          name: clip.name
      };

      const rightClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          startTime: splitTime,
          offset: clip.offset + firstDuration,
          duration: clip.duration - firstDuration,
          name: clip.name
      };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          // If enabling loop, instantly extend duration by one loop length so user sees effect
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;

          const newClips = clips.map(c => 
            c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c
          );
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---

  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();

      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const masterTrack = tracks.find(t => t.isMaster);
  const regularTracks = tracks.filter(t => !t.isMaster);

  // Common Props for Timeline Instances
  const timelineProps = {
    clips,
    currentTime: playbackState.currentTime,
    onClipUpdate: updateClip,
    onFileDrop: handleFileDrop,
    setClips,
    onSeek: handleSeek,
    bpm,
    zoom,
    setZoom,
    snap,
    tool,
    onDeleteClip: deleteClip,
    onDuplicateClip: duplicateClip,
    onRenameClip: renameClip,
    onSplitClip: handleSplitClip,
    onAddAutomationPoint: handleAddAutomationPoint,
    onSelectClip: (id: string | null) => { setSelectedClipId(id); if (id) setEditingTrackId(null); },
    selectedClipId,
    onCopyClip: handleCopyClip,
    onPasteClip: handlePasteClip,
    canPaste: !!clipboardClip,
    onLoopClip: handleLoopToggle,
    onClipResize: handleClipResize
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}

        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* LEFT COLUMN: HEADERS */}
        <div 
            className="flex flex-col bg-gray-900 border-r border-gray-700 z-10 shadow-xl"
            style={{ width: TRACK_HEADER_WIDTH }}
        >
          {/* Scrollable Header List */}
          <div 
             ref={trackHeaderRef}
             onWheel={handleHeaderWheel}
             className="flex-1 overflow-hidden relative"
          >
             {/* Spacer */}
             <div className="flex-shrink-0 bg-gray-900 border-b border-gray-700 box-border z-20 sticky top-0 flex items-end pb-1 px-3" style={{ height: TIMELINE_RULER_HEIGHT }}>
                 <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">Tracks</span>
             </div>

             {regularTracks.map(track => (
                <TrackControl 
                  key={track.id} 
                  track={track} 
                  onUpdate={updateTrack}
                  onDelete={deleteTrack}
                  isRecording={recordingTrackId === track.id}
                  onRecordToggle={handleRecordToggle}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={toggleAutomation}
                />
             ))}

             <div className="p-3 space-y-2">
                 <button 
                    onClick={addTrack}
                    className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                 >
                    <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors">
                        <Plus size={14} /> 
                    </div>
                    <span>Add New Track</span>
                 </button>
             </div>

             {/* Spacer for bottom scrolling padding if needed */}
             <div className="h-48"></div>
          </div>

          {/* Master Header - Fixed Bottom */}
          {masterTrack && (
             <div className="flex-shrink-0 border-t border-gray-700 z-20">
                <TrackControl 
                  track={masterTrack} 
                  onUpdate={updateTrack}
                  onDelete={deleteTrack}
                  isRecording={recordingTrackId === masterTrack.id}
                  onRecordToggle={handleRecordToggle}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={toggleAutomation}
                />
             </div>
          )}
        </div>

        {/* RIGHT COLUMN: TIMELINE */}
        <div className="flex-1 flex flex-col overflow-hidden relative">
            {/* Scrollable Timeline Area */}
            <div 
                ref={timelineRef}
                onScroll={handleTimelineScroll}
                className="flex-1 overflow-auto custom-scrollbar"
            >
                <Timeline 
                    {...timelineProps}
                    tracks={regularTracks}
                    showRuler={true}
                />
                {/* Spacer matching bottom padding */}
                <div className="h-48"></div>
            </div>

            {/* Master Timeline Lane - Fixed Bottom */}
            {masterTrack && (
                <div 
                    ref={masterLaneRef}
                    className="flex-shrink-0 border-t border-gray-700 bg-gray-950 overflow-hidden relative"
                >
                     <Timeline 
                        {...timelineProps}
                        tracks={[masterTrack]}
                        showRuler={false}
                     />
                </div>
            )}
        </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

export default App;

import React, { useEffect, useRef } from 'react';
import { audioService } from '../services/audioEngine';

interface MasterVisualizationProps {
  width?: number; // Optional override
  height: number;
}

export const MasterVisualization: React.FC<MasterVisualizationProps> = ({ width, height }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    let animationId: number;
    const analyser = audioService.getTrackAnalyser('master');
    const canvas = canvasRef.current;

    if (analyser && canvas) {
        const ctx = canvas.getContext('2d');
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);

        const draw = () => {
            if (!ctx) return;

            // Handle resizing if container changes
            const rect = canvas.parentElement?.getBoundingClientRect();
            if (rect && (canvas.width !== rect.width || canvas.height !== rect.height)) {
                canvas.width = rect.width;
                canvas.height = rect.height;
            }

            const w = canvas.width;
            const h = canvas.height;

            analyser.getByteFrequencyData(dataArray);

            ctx.clearRect(0, 0, w, h);

            // Draw Background Grid
            ctx.fillStyle = '#111827';
            ctx.fillRect(0, 0, w, h);

            ctx.strokeStyle = '#1f2937';
            ctx.beginPath();
            for(let i=0; i<w; i+= 50) { ctx.moveTo(i, 0); ctx.lineTo(i, h); }
            ctx.stroke();

            // Draw Spectrum
            const barWidth = (w / bufferLength) * 2.5;
            let barHeight;
            let x = 0;

            for(let i = 0; i < bufferLength; i++) {
                barHeight = (dataArray[i] / 255) * h;

                // Gradient color based on frequency/height
                const hue = (i / bufferLength) * 260 + 180; // Blue to Pink range
                ctx.fillStyle = `hsla(${hue}, 80%, 60%, 0.8)`;

                // Draw bar
                ctx.fillRect(x, h - barHeight, barWidth, barHeight);

                // Draw reflection/glow
                ctx.fillStyle = `hsla(${hue}, 80%, 60%, 0.1)`;
                ctx.fillRect(x, 0, barWidth, h);

                x += barWidth + 1;
            }

            animationId = requestAnimationFrame(draw);
        };
        draw();
    }

    return () => cancelAnimationFrame(animationId);
  }, []);

  return (
    <canvas 
        ref={canvasRef} 
        className="w-full h-full block"
        height={height}
    />
  );
};

import React, { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { MasterVisualization } from './components/MasterVisualization';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, PluginType, AudioPlugin } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT, TRACK_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);

  const [recordingTrackId, setRecordingTrackId] = useState<string | null>(null);
  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Scroll Synchronization Refs ---
  const trackHeaderRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);
  const masterLaneRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Layout Calculations ---
  // Calculate total width for scrollbar logic
  const totalDuration = useMemo(() => {
      const maxClipTime = Math.max(0, ...clips.map(c => c.startTime + c.duration));
      return Math.max(300, maxClipTime + 10); // Minimum 300s or clips + buffer
  }, [clips]);

  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4;
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const pixelsPerBar = secondsPerBar * zoom;
  const totalWidth = totalBars * pixelsPerBar;

  // --- Scroll Sync ---

  // 1. Timeline Vertical Scroll -> Headers Vertical Scroll
  const handleTimelineVerticalScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (trackHeaderRef.current) {
          trackHeaderRef.current.scrollTop = e.currentTarget.scrollTop;
      }
  };

  // 2. Master Lane Horizontal Scroll -> Timeline Horizontal Scroll
  const handleMasterHorizontalScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (timelineRef.current) {
          timelineRef.current.scrollLeft = e.currentTarget.scrollLeft;
      }
  };

  const handleHeaderWheel = (e: React.WheelEvent) => {
      if (timelineRef.current) {
          timelineRef.current.scrollTop += e.deltaY;
      }
  };

  // --- Undo/Redo System ---

  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  // Initial History
  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          // Sync Audio Engine
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex + 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };


  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (recordingTrackId) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [recordingTrackId]);

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const finishRecording = async () => {
      if (!recordingTrackId) return;

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: recordingTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setRecordingTrackId(null);
  };

  const handleRecordToggle = async (trackId: string) => {
      if (recordingTrackId === trackId) {
          await handleStop();
          return;
      }
      if (recordingTrackId) return;

      try {
          await audioService.resume();
          await audioService.startRecording();
          setRecordingTrackId(trackId);
          recordStartTimeRef.current = pauseTimeRef.current;
          if (!playbackState.isPlaying) startPlayback(pauseTimeRef.current);
      } catch (e) {
          alert("Could not start recording. Please allow microphone access.");
      }
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);

    // Check if Solo/Mute logic changed, apply real-time update
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             // Insert point
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) {
                 points[existingIdx] = point;
             } else {
                 points.push(point);
             }
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    );
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;

      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return; // Out of bounds

      const firstDuration = relativeSplit * clip.playbackRate; // Buffer duration

      const leftClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          duration: firstDuration,
          name: clip.name
      };

      const rightClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          startTime: splitTime,
          offset: clip.offset + firstDuration,
          duration: clip.duration - firstDuration,
          name: clip.name
      };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          // If enabling loop, instantly extend duration by one loop length so user sees effect
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;

          const newClips = clips.map(c => 
            c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c
          );
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---

  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();

      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const masterTrack = tracks.find(t => t.isMaster);
  const regularTracks = tracks.filter(t => !t.isMaster);

  // Common Props for Timeline Instances
  const timelineProps = {
    clips,
    currentTime: playbackState.currentTime,
    onClipUpdate: updateClip,
    onFileDrop: handleFileDrop,
    setClips,
    onSeek: handleSeek,
    bpm,
    zoom,
    setZoom,
    snap,
    tool,
    onDeleteClip: deleteClip,
    onDuplicateClip: duplicateClip,
    onRenameClip: renameClip,
    onSplitClip: handleSplitClip,
    onAddAutomationPoint: handleAddAutomationPoint,
    onSelectClip: (id: string | null) => { setSelectedClipId(id); if (id) setEditingTrackId(null); },
    selectedClipId,
    onCopyClip: handleCopyClip,
    onPasteClip: handlePasteClip,
    canPaste: !!clipboardClip,
    onLoopClip: handleLoopToggle,
    onClipResize: handleClipResize
  };

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}

        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* LEFT COLUMN: HEADERS */}
        <div 
            className="flex flex-col bg-gray-900 border-r border-gray-700 z-10 shadow-xl"
            style={{ width: TRACK_HEADER_WIDTH }}
        >
          {/* Scrollable Header List */}
          <div 
             ref={trackHeaderRef}
             onWheel={handleHeaderWheel}
             className="flex-1 overflow-hidden relative"
          >
             {/* Spacer */}
             <div className="flex-shrink-0 bg-gray-900 border-b border-gray-700 box-border z-20 sticky top-0 flex items-end pb-1 px-3" style={{ height: TIMELINE_RULER_HEIGHT }}>
                 <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">Tracks</span>
             </div>

             {regularTracks.map(track => (
                <TrackControl 
                  key={track.id} 
                  track={track} 
                  onUpdate={updateTrack}
                  onDelete={deleteTrack}
                  isRecording={recordingTrackId === track.id}
                  onRecordToggle={handleRecordToggle}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={toggleAutomation}
                />
             ))}

             <div className="p-3 space-y-2">
                 <button 
                    onClick={addTrack}
                    className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                 >
                    <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors">
                        <Plus size={14} /> 
                    </div>
                    <span>Add New Track</span>
                 </button>
             </div>

             {/* Spacer for bottom scrolling padding if needed */}
             <div className="h-48"></div>
          </div>

          {/* Master Header - Fixed Bottom */}
          {masterTrack && (
             <div className="flex-shrink-0 border-t border-gray-700 z-20 bg-gray-900">
                <TrackControl 
                  track={masterTrack} 
                  onUpdate={updateTrack}
                  onDelete={deleteTrack}
                  isRecording={recordingTrackId === masterTrack.id}
                  onRecordToggle={handleRecordToggle}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={toggleAutomation}
                />
             </div>
          )}
        </div>

        {/* RIGHT COLUMN: TIMELINE & MASTER VIS */}
        <div className="flex-1 flex flex-col overflow-hidden relative">

            {/* Top Area: Tracks & Clips (Vertical Scroll, NO Horizontal Scroll) */}
            <div 
                ref={timelineRef}
                onScroll={handleTimelineVerticalScroll}
                className="flex-1 overflow-y-auto overflow-x-hidden custom-scrollbar"
                style={{ scrollbarWidth: 'none' }} // Hide scrollbar for cleaner look
            >
                <Timeline 
                    {...timelineProps}
                    tracks={regularTracks}
                    showRuler={true}
                />
                {/* Spacer matching bottom padding */}
                <div className="h-48"></div>
            </div>

            {/* Bottom Area: Master Visualization & Main Horizontal Scrollbar */}
            {masterTrack && (
                <div 
                    ref={masterLaneRef}
                    onScroll={handleMasterHorizontalScroll}
                    className="flex-shrink-0 border-t border-gray-700 bg-gray-950 overflow-x-auto overflow-y-hidden custom-scrollbar relative"
                    style={{ height: TRACK_HEIGHT }} // Match standard track height
                >
                     {/* Sticky Container for Visualization so it always shows on screen */}
                     <div className="sticky left-0 w-full h-full pointer-events-none z-10">
                        <MasterVisualization height={TRACK_HEIGHT} />
                     </div>

                     {/* Invisible Spacer to force scroll width matching song duration */}
                     <div style={{ width: `${totalWidth}px`, height: '1px' }} />
                </div>
            )}
        </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

export default App;

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;

          // CRITICAL: use the timeline duration for playback stopping, but buffer logic for looping
          let playDuration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > playDuration && !clip.loop) return;

            // Adjust offset for start
            // Note: For looped clips, we need to mod the offset by buffer duration
            if (clip.loop) {
                 const bufferDur = clip.buffer.duration / clip.playbackRate;
                 offset = (offset + (timePassed * clip.playbackRate)) % clip.buffer.duration;
            } else {
                 offset += timePassed * clip.playbackRate;
            }

            playDuration -= timePassed;
            whenToPlay = now;
          }

          if (playDuration <= 0 && !clip.loop) return;

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;

          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              // Play indefinitely (looping) but stop exactly at clip duration end
              source.start(whenToPlay, offset);
              // Stop it when the timeline block ends
              source.stop(whenToPlay + playDuration);
          } else {
              if (playDuration > 0) source.start(whenToPlay, offset, playDuration * clip.playbackRate); // playDuration is in timeline time, start() duration arg is somewhat tricky with playbackRate, but usually safe to omit if not looping or rely on stop()
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + c.duration)) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async getInputDevices(): Promise<MediaDeviceInfo[]> {
      // Ensure we have access to labels by requesting access first if needed
      // Note: This might trigger a permission prompt if not already granted
      try {
        await navigator.mediaDevices.getUserMedia({ audio: true });
        const devices = await navigator.mediaDevices.enumerateDevices();
        return devices.filter(d => d.kind === 'audioinput');
      } catch(e) {
          console.error("Permission denied or error fetching devices", e);
          return [];
      }
  }

  public async startRecording(deviceId?: string): Promise<void> {
    try {
        const constraints: MediaStreamConstraints = {
            audio: deviceId ? { deviceId: { exact: deviceId } } : true
        };

        this.recordingStream = await navigator.mediaDevices.getUserMedia(constraints);
        this.mediaRecorder = new MediaRecorder(this.recordingStream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }

  // --- Analysis & Stem Splitting ---

  public async getAudioAnalysisInput(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  }

  public async separateStemsAdvanced(
    file: File, 
    instruments: string[], 
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
      onProgress("Decoding audio for processing...");
      const originalBuffer = await this.loadFile(file);

      const results: {name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[] = [];

      for (const inst of instruments) {
          const lowerName = inst.toLowerCase();
          onProgress(`Extracting ${inst}...`);

          let buffer: AudioBuffer;
          let type: PluginType = 'LOWPASS'; 
          const plugins: AudioPlugin[] = [];

          if (lowerName.includes('bass')) {
             buffer = await this.renderFiltered(originalBuffer, 'LOW');
             type = 'LOWPASS';
          } else if (lowerName.includes('drum') || lowerName.includes('percussion')) {
             buffer = await this.renderFiltered(originalBuffer, 'DRUMS');
             type = 'DISTORTION'; // Just using as a placeholder for track type or similar
          } else if (lowerName.includes('vocal')) {
             buffer = await this.renderFiltered(originalBuffer, 'MID');
             type = 'REVERB';
             plugins.push({
                 id: Math.random().toString(36).substr(2, 9),
                 type: 'REVERB',
                 enabled: true,
                 params: { mix: 0.3, decay: 1.5, type: 0 }
             });
          } else {
             buffer = await this.renderFiltered(originalBuffer, 'HIGH');
             type = 'HIGHPASS';
          }

          results.push({
              name: inst,
              type: type,
              buffer: buffer,
              plugins: plugins
          });
      }

      return results;
  }

  private async renderFiltered(sourceBuffer: AudioBuffer, profile: 'LOW' | 'MID' | 'HIGH' | 'DRUMS'): Promise<AudioBuffer> {
        const length = sourceBuffer.length;
        const sampleRate = sourceBuffer.sampleRate;
        const offlineCtx = new OfflineAudioContext(sourceBuffer.numberOfChannels, length, sampleRate);

        const source = offlineCtx.createBufferSource();
        source.buffer = sourceBuffer;

        let head: AudioNode = source;

        if (profile === 'LOW') {
            const f = offlineCtx.createBiquadFilter();
            f.type = 'lowpass';
            f.frequency.value = 300;
            head.connect(f);
            head = f;
        } else if (profile === 'MID') {
            const hp = offlineCtx.createBiquadFilter();
            hp.type = 'highpass';
            hp.frequency.value = 300;
            const lp = offlineCtx.createBiquadFilter();
            lp.type = 'lowpass';
            lp.frequency.value = 5000;
            head.connect(hp);
            hp.connect(lp);
            head = lp;
        } else if (profile === 'HIGH') {
            const f = offlineCtx.createBiquadFilter();
            f.type = 'highpass';
            f.frequency.value = 5000;
            head.connect(f);
            head = f;
        } else if (profile === 'DRUMS') {
            // Scoop mids for drums
            const lows = offlineCtx.createBiquadFilter();
            lows.type = 'lowshelf';
            lows.frequency.value = 200;
            lows.gain.value = 4;

            const mids = offlineCtx.createBiquadFilter();
            mids.type = 'peaking';
            mids.frequency.value = 1000;
            mids.Q.value = 1;
            mids.gain.value = -6;

            const highs = offlineCtx.createBiquadFilter();
            highs.type = 'highshelf';
            highs.frequency.value = 6000;
            highs.gain.value = 3;

            head.connect(lows);
            lows.connect(mids);
            mids.connect(highs);
            head = highs;
        }

        head.connect(offlineCtx.destination);
        source.start();
        return await offlineCtx.startRendering();
  }
}

