import React, { useEffect, useRef } from 'react';
import { audioService } from '../services/audioEngine';

interface MasterVisualizationProps {
  width?: number; // Optional override
  height: number;
}

export const MasterVisualization: React.FC<MasterVisualizationProps> = ({ width, height }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    let animationId: number;
    const analyser = audioService.getTrackAnalyser('master');
    const canvas = canvasRef.current;

    if (analyser && canvas) {
        const ctx = canvas.getContext('2d');
        const bufferLength = analyser.frequencyBinCount;
        const dataArray = new Uint8Array(bufferLength);

        const draw = () => {
            if (!ctx) return;

            // Handle resizing if container changes
            const rect = canvas.parentElement?.getBoundingClientRect();
            if (rect && (canvas.width !== rect.width || canvas.height !== rect.height)) {
                canvas.width = rect.width;
                canvas.height = rect.height;
            }

            const w = canvas.width;
            const h = canvas.height;

            analyser.getByteFrequencyData(dataArray);

            ctx.clearRect(0, 0, w, h);

            // Draw Background (No Grid)
            ctx.fillStyle = '#111827';
            ctx.fillRect(0, 0, w, h);

            // Draw Spectrum
            const barWidth = (w / bufferLength) * 2.5;
            let barHeight;
            let x = 0;

            for(let i = 0; i < bufferLength; i++) {
                barHeight = (dataArray[i] / 255) * h;

                // Gradient color based on frequency/height
                const hue = (i / bufferLength) * 260 + 180; // Blue to Pink range
                ctx.fillStyle = `hsla(${hue}, 80%, 60%, 0.8)`;

                // Draw bar
                ctx.fillRect(x, h - barHeight, barWidth, barHeight);

                // Draw reflection/glow
                ctx.fillStyle = `hsla(${hue}, 80%, 60%, 0.1)`;
                ctx.fillRect(x, 0, barWidth, h);

                x += barWidth + 1;
            }

            animationId = requestAnimationFrame(draw);
        };
        draw();
    }

    return () => cancelAnimationFrame(animationId);
  }, []);

  return (
    <canvas 
        ref={canvasRef} 
        className="w-full h-full block"
        height={height}
    />
  );
};

