                                         <input 
                                            type="range" min="0" max="1" step="0.01"
                                            value={plugin.params.mix}
                                            onChange={(e) => updatePluginParam(plugin.id, 'mix', Number(e.target.value))}
                                            className="h-1 bg-gray-700 rounded-full appearance-none accent-blue-500"
                                            title="Dry/Wet Mix"
                                         />
                                     </div>
