  const [clips, setClips] = useState<AudioClip[]>([]);

  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50);
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);

  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);
  const [inputDeviceId, setInputDeviceId] = useState<string>("");

  // Refs for Scroll Sync
  const trackHeaderRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);
  const masterLaneRef = useRef<HTMLDivElement>(null);

  // Playback & Record State
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    isRecording: false, // Global Transport Record
    currentTime: 0
  });

  const [activeRecordingTrackId, setActiveRecordingTrackId] = useState<string | null>(null);
  const rafRef = useRef<number | null>(null);
  const playheadStartRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Tracks Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Scroll Logic ---
  const handleTimelineVerticalScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (trackHeaderRef.current) trackHeaderRef.current.scrollTop = e.currentTarget.scrollTop;
  };
  const handleMasterHorizontalScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (timelineRef.current) timelineRef.current.scrollLeft = e.currentTarget.scrollLeft;
  };

  // --- Playback ---
  const startPlayback = useCallback((startAt: number) => {
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    // Check if we need to record
    if (playbackState.isRecording) {
        const armedTrack = tracks.find(t => t.armed && !t.isMaster);
        if (armedTrack) {
            audioService.startRecording();
            setActiveRecordingTrackId(armedTrack.id);
            recordStartTimeRef.current = startAt;
        }
    }

    audioService.play(clips, tracks, startAt);
    playheadStartRef.current = performance.now();
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = performance.now();
      const elapsed = (now - playheadStartRef.current) / 1000;
      setPlaybackState(prev => ({ ...prev, currentTime: startAt + elapsed }));
      rafRef.current = requestAnimationFrame(animate);
    };
    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks, playbackState.isRecording]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stopPlayback();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    // Finish Recording if active
    if (activeRecordingTrackId) {
        const blob = await audioService.stopRecording();
        if (blob && blob.size > 0) {
            try {
                const buffer = await audioService.decodeBlob(blob);
                const newClip: AudioClip = {
                    id: uuidv4(),
                    trackId: activeRecordingTrackId,
                    buffer: buffer,
                    name: `Recording ${new Date().toLocaleTimeString()}`,
                    startTime: recordStartTimeRef.current,
                    duration: buffer.duration,
                    offset: 0,
                    gain: 1, pan: 0, playbackRate: 1, loop: false
                };
                setClips(prev => [...prev, newClip]);
            } catch (e) { console.error("Rec save failed", e); }
        }
        setActiveRecordingTrackId(null);
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [activeRecordingTrackId]);

  const handleRecordToggle = () => {
      setPlaybackState(prev => ({ ...prev, isRecording: !prev.isRecording }));
  };

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  // --- Track Arming (Monitoring) ---
  const handleArmToggle = async (trackId: string) => {
      const track = tracks.find(t => t.id === trackId);
      if (!track) return;

      const newArmedState = !track.armed;

      // Update state
      const newTracks = tracks.map(t => {
          // If we are arming this track, disarm others (single track record for now)
          if (t.id === trackId) return { ...t, armed: newArmedState };
          if (newArmedState && t.armed) return { ...t, armed: false }; // Exclusive arm
          return t;
      });
      setTracks(newTracks);

      if (newArmedState) {
          try {
             await audioService.enableMonitoring(trackId, inputDeviceId);
          } catch(e) {
             alert("Could not enable microphone. Check permissions.");
             setTracks(tracks.map(t => t.id === trackId ? { ...t, armed: false } : t));
          }
      } else {
          audioService.disableMonitoring();
      }
  };

  // --- Track & Clip Management Wrappers ---
  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`, name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 1.0, muted: false, soloed: false, armed: false, plugins: [], automation: { volume: [] }
    };
    // Insert before master
    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);
    setTracks(newTracks);
    audioService.createTrackNodes(newTrack.id);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    setTracks(prev => prev.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    }));
    if (updates.muted !== undefined || updates.soloed !== undefined) {
         // Need full updated list for solo logic, so defer slightly or use functional
         // Simpler: Just re-apply on next render or force update
         setTimeout(() => audioService.applyRealtimeSoloMute(tracks), 0);
    }
  };

  const deleteTrack = (id: string) => {
      if(id === 'master') return;
      audioService.removeTrackNodes(id);
      setTracks(prev => prev.filter(t => t.id !== id));
  };

  // --- File Drop ---
  const handleFileDrop = async (file: File, trackId: string, time: number) => {
      try {
          const buffer = await audioService.loadFile(file);
          const newClip: AudioClip = {
              id: uuidv4(), trackId, buffer, name: file.name, startTime: time,
              duration: buffer.duration, offset: 0, gain: 1, pan: 0, playbackRate: 1, loop: false
          };
          setClips(prev => [...prev, newClip]);
      } catch (e) { alert("Failed to load audio"); }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    setClips(prev => prev.map(c => c.id === id ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } : c));
  };

  // --- Render ---
  const regularTracks = tracks.filter(t => !t.isMaster);
  const masterTrack = tracks.find(t => t.isMaster);
  const editingTrack = tracks.find(t => t.id === editingTrackId);

  // Layout math
  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration));
  const pixelsPerBar = (60 / bpm) * 4 * zoom;
  const totalWidth = (Math.ceil(totalDuration / ((60/bpm)*4)) + 5) * pixelsPerBar;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans">
      <Transport 
        isPlaying={playbackState.isPlaying}
        isRecording={playbackState.isRecording}
        onPlay={handlePlay}
        onStop={handleStop}
        onRecord={handleRecordToggle}
        onRewind={() => handleSeek(Math.max(0, playbackState.currentTime - 5))}
        onFastForward={() => handleSeek(playbackState.currentTime + 5)}
        currentTime={playbackState.currentTime}
        bpm={bpm} setBpm={setBpm}
        tool={tool} setTool={setTool}
        zoom={zoom} setZoom={setZoom}
        snap={snap} setSnap={setSnap}
        onUndo={() => {}} onRedo={() => {}} canUndo={false} canRedo={false}
        onExport={() => setIsExporting(true)} isExporting={isExporting}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* Headers */}
        <div className="flex flex-col bg-gray-900 border-r border-gray-700 z-10 shadow-xl" style={{ width: TRACK_HEADER_WIDTH }}>
          <div ref={trackHeaderRef} className="flex-1 overflow-hidden relative">
             <div className="flex-shrink-0 bg-gray-900 border-b border-gray-700 box-border z-20 sticky top-0 flex items-end pb-1 px-3" style={{ height: TIMELINE_RULER_HEIGHT }}>
                 <span className="text-[10px] text-gray-500 font-bold uppercase tracking-wider">Tracks</span>
             </div>
             {regularTracks.map(track => (
                <TrackControl 
                  key={track.id} track={track} 
                  onUpdate={updateTrack} onDelete={deleteTrack}
                  onArmToggle={handleArmToggle}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={(id) => updateTrack(id, { showAutomation: !track.showAutomation })}
                />
             ))}
             <div className="p-3">
                 <button onClick={addTrack} className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white flex items-center justify-center gap-2 text-sm"><Plus size={14} /> Add Track</button>
             </div>
             <div className="h-48"></div>
          </div>
          {masterTrack && (
             <div className="flex-shrink-0 border-t border-gray-700 z-20 bg-gray-900">
                <TrackControl track={masterTrack} onUpdate={updateTrack} onDelete={() => {}} onArmToggle={() => {}} onOpenEditor={setEditingTrackId} onToggleAutomation={() => {}} />
             </div>
          )}
        </div>

        {/* Timeline */}
        <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={timelineRef} onScroll={handleTimelineVerticalScroll} className="flex-1 overflow-y-auto overflow-x-hidden custom-scrollbar" style={{ scrollbarWidth: 'none' }}>
                <Timeline 
                    tracks={regularTracks} clips={clips} currentTime={playbackState.currentTime}
                    onClipUpdate={updateClip} onFileDrop={handleFileDrop}
                    setClips={setClips} onSeek={handleSeek}
                    bpm={bpm} zoom={zoom} setZoom={setZoom} snap={snap} tool={tool}
                    onDeleteClip={(id) => setClips(prev => prev.filter(c => c.id !== id))}
                    onDuplicateClip={() => {}} onRenameClip={() => {}}
                    onSelectClip={setSelectedClipId} selectedClipId={selectedClipId}
                    onCopyClip={() => {}} onPasteClip={() => {}} canPaste={false}
                    onLoopClip={() => {}} onSplitClip={() => {}} onAddAutomationPoint={() => {}} onClipResize={() => {}}
                />
                <div className="h-48"></div>
            </div>
            <div ref={masterLaneRef} onScroll={handleMasterHorizontalScroll} className="flex-shrink-0 border-t border-gray-700 bg-gray-950 overflow-x-auto overflow-y-hidden custom-scrollbar relative" style={{ height: TRACK_HEIGHT }}>
                 <div className="sticky left-0 w-full h-full pointer-events-none z-10">
                    <MasterVisualization height={TRACK_HEIGHT} />
                 </div>
                 <div style={{ width: `${totalWidth}px`, height: '1px' }} />
            </div>
        </div>
      </div>

      {editingTrack ? <TrackEditor track={editingTrack} onUpdate={updateTrack} onClose={() => setEditingTrackId(null)} /> : 
       <ClipEditor clip={clips.find(c => c.id === selectedClipId) || null} onUpdate={(id, u) => setClips(p => p.map(c => c.id === id ? {...c, ...u} : c))} onClose={() => setSelectedClipId(null)} />}

      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} currentInputDeviceId={inputDeviceId} onInputChange={setInputDeviceId} />
    </div>
  );
}

export default App;

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  monitorAnalyser: AnalyserNode;
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  // Monitoring State
  private monitorStream: MediaStream | null = null;
  private monitorSourceNode: MediaStreamAudioSourceNode | null = null;
  private monitoredTrackId: string | null = null;

  // Recording State
  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];

  constructor() {
    const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
    this.context = new AudioContextClass({ latencyHint: 'interactive' });

    // Master Chain Setup
    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterInput = this.context.createGain();

    // Connections: masterInput -> masterFader -> masterAnalyser -> destination
    this.masterInput.connect(this.masterFader);
    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      try {
        await this.context.resume();
      } catch (e) {
        console.error("Failed to resume AudioContext", e);
      }
    }
  }

  // --- Track Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;
    if (isMaster) return; 

    // Create Nodes
    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    const monitorAnalyser = this.context.createAnalyser(); // For input metering only

    analyser.fftSize = 256;
    monitorAnalyser.fftSize = 256;

    // Connect Chain: Input -> Output (Plugins go here) -> Panner -> Fader -> Analyser -> Master
    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      monitorAnalyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.monitorAnalyser.disconnect();
      // Disconnect plugins
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public getTrackMonitorAnalyser(trackId: string): AnalyserNode | null {
      return this.trackNodes.get(trackId)?.monitorAnalyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;

        const feedback = context.createGain();
        feedback.gain.value = plugin.params.feedback || 0.5;

        // Simple Feedback Loop: Input -> Delay -> Output, Delay -> Feedback -> Delay
        // For a proper insert effect: Input -> Split -> (Dry) & (Delay->Wet) -> Merge
        // Simplified insert implementation:
        const dInput = context.createGain();
        const dOutput = context.createGain();

        dInput.connect(dOutput); // Dry signal pass-through (simplified)
        dInput.connect(delay);
        delay.connect(dOutput);
        delay.connect(feedback);
        feedback.connect(delay);

        (delay as any)._time = delay.delayTime;
        return { input: dInput, output: dOutput, _time: delay.delayTime };

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain,
             _decay: { value: decay, cancelScheduledValues: () => {}, setValueAtTime: () => {} } // Mock param for safety
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    // Disconnect everything in the chain
    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    // Reconnect the end of the chain to the track output
    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Monitoring & Recording ---

  public async enableMonitoring(trackId: string, deviceId?: string) {
      // If already monitoring this track, do nothing
      if (this.monitoredTrackId === trackId && this.monitorStream) return;

      // Cleanup previous
      this.disableMonitoring();

      try {
          await this.resume();

          const constraints: MediaStreamConstraints = {
              audio: deviceId ? { deviceId: { exact: deviceId }, echoCancellation: false, autoGainControl: false } 
                              : { echoCancellation: false, autoGainControl: false }
          };

          this.monitorStream = await navigator.mediaDevices.getUserMedia(constraints);
          this.monitoredTrackId = trackId;

          const nodes = this.trackNodes.get(trackId);
          if (nodes && this.monitorStream) {
              this.monitorSourceNode = this.context.createMediaStreamSource(this.monitorStream);
              // Connect to monitor analyser for visual feedback
              this.monitorSourceNode.connect(nodes.monitorAnalyser);
              // Note: We deliberately do NOT connect to context.destination to prevent feedback loops
          }
      } catch (e) {
          console.error("Error enabling monitoring:", e);
          throw e;
      }
  }

  public disableMonitoring() {
      if (this.monitorSourceNode) {
          this.monitorSourceNode.disconnect();
          this.monitorSourceNode = null;
      }
      if (this.monitorStream) {
          this.monitorStream.getTracks().forEach(t => t.stop());
          this.monitorStream = null;
      }
      this.monitoredTrackId = null;
  }

  public startRecording() {
      if (!this.monitorStream) {
          console.error("Cannot start recording: No active monitor stream.");
          return;
      }

      const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus') ? 'audio/webm;codecs=opus' : undefined;
      this.mediaRecorder = new MediaRecorder(this.monitorStream, { mimeType });
      this.recordingChunks = [];

      this.mediaRecorder.ondataavailable = (e) => {
          if (e.data.size > 0) this.recordingChunks.push(e.data);
      };

      this.mediaRecorder.start(100);
  }

  public async stopRecording(): Promise<Blob | null> {
      return new Promise((resolve) => {
          if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
              resolve(null);
              return;
          }

          this.mediaRecorder.onstop = () => {
              const type = this.recordingChunks[0]?.type || 'audio/webm';
              const blob = new Blob(this.recordingChunks, { type });
              this.recordingChunks = [];
              this.mediaRecorder = null;
              resolve(blob);
          };
          this.mediaRecorder.stop();
      });
  }

  public async getInputDevices(): Promise<MediaDeviceInfo[]> {
      try {
        // Request temporary access to get labels
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        stream.getTracks().forEach(track => track.stop());
        const devices = await navigator.mediaDevices.enumerateDevices();
        return devices.filter(d => d.kind === 'audioinput');
      } catch(e) {
          return [];
      }
  }

  // --- Playback ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stopPlayback(); // Stop previous playback sources
    this.resume();

    const now = this.context.currentTime;
    const anySolo = tracks.some(t => t.soloed);

    clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (!track) return;

        const isAudible = anySolo ? track.soloed : !track.muted;

        // Calculate timing
        const clipStart = clip.startTime;
        let when = now + (clipStart - startTime);
        let offset = clip.offset;
        let duration = clip.duration;

        // If clip is in the past relative to start time
        if (when < now) {
            const missed = now - when;
            if (missed >= duration && !clip.loop) return;

            if (clip.loop) {
                 const bufDur = clip.buffer.duration / clip.playbackRate;
                 offset = (offset + (missed * clip.playbackRate)) % clip.buffer.duration;
            } else {
                 offset += missed * clip.playbackRate;
            }
            duration -= missed;
            when = now;
        }

        if (duration <= 0 && !clip.loop) return;

        // Create Source
        const source = this.context.createBufferSource();
        source.buffer = clip.buffer;
        source.playbackRate.value = clip.playbackRate;
        source.loop = clip.loop;
        if (clip.loop) {
            source.loopStart = 0;
            source.loopEnd = clip.buffer.duration;
        }

        // Clip-level Gain/Pan
        const clipGain = this.context.createGain();
        clipGain.gain.value = clip.gain;
        const clipPanner = this.context.createStereoPanner();
        clipPanner.pan.value = clip.pan;

        // Connect: Source -> Panner -> Gain -> Track Input
        source.connect(clipPanner);
        clipPanner.connect(clipGain);

        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            clipGain.connect(trackNodes.input);
        } else {
            clipGain.connect(this.masterInput);
        }

        // Start
        source.start(when, offset);
        if (!clip.loop) {
             source.stop(when + (duration / clip.playbackRate) * clip.playbackRate); // Simplified stop
        } else {
             source.stop(when + duration);
        }

        this.activeSources.set(clip.id, { source, gain: clipGain, panner: clipPanner });

        source.onended = () => {
             const active = this.activeSources.get(clip.id);
             if (active && active.source === source) {
                 this.activeSources.delete(clip.id);
             }
        };
    });

    // Apply automation (Simplified volume sync for robustness)
    this.applyRealtimeSoloMute(tracks);
  }

  public stopPlayback() {
    this.activeSources.forEach(({ source, gain, panner }) => {
        try { source.stop(); } catch(e){}
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
    });
    this.activeSources.clear();
  }

  public stop() {
      this.stopPlayback();
  }

  // --- File Loading ---
  public async loadFile(file: File): Promise<AudioBuffer> {
    await this.resume();
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Analysis & Stems (Restored) ---

  public async getAudioAnalysisInput(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  }

  public async separateStemsAdvanced(
    file: File, 
    instruments: string[], 
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
      onProgress("Decoding audio for processing...");
      const originalBuffer = await this.loadFile(file);

      const results: {name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[] = [];

      for (const inst of instruments) {
          const lowerName = inst.toLowerCase();
          onProgress(`Extracting ${inst}...`);

          let buffer: AudioBuffer;
          let type: PluginType = 'LOWPASS'; 
          const plugins: AudioPlugin[] = [];

          if (lowerName.includes('bass')) {
             buffer = await this.renderFiltered(originalBuffer, 'LOW');
             type = 'LOWPASS';
          } else if (lowerName.includes('drum') || lowerName.includes('percussion')) {
             buffer = await this.renderFiltered(originalBuffer, 'DRUMS');
             type = 'DISTORTION';
          } else if (lowerName.includes('vocal')) {
             buffer = await this.renderFiltered(originalBuffer, 'MID');
             type = 'REVERB';
             plugins.push({
                 id: Math.random().toString(36).substr(2, 9),
                 type: 'REVERB',
                 enabled: true,
                 params: { mix: 0.3, decay: 1.5, type: 0 }
             });
          } else {
             buffer = await this.renderFiltered(originalBuffer, 'HIGH');
             type = 'HIGHPASS';
          }

          results.push({
              name: inst,
              type: type,
              buffer: buffer,
              plugins: plugins
          });
      }

      return results;
  }

  private async renderFiltered(sourceBuffer: AudioBuffer, profile: 'LOW' | 'MID' | 'HIGH' | 'DRUMS'): Promise<AudioBuffer> {
        const length = sourceBuffer.length;
        const sampleRate = sourceBuffer.sampleRate;
        const offlineCtx = new OfflineAudioContext(sourceBuffer.numberOfChannels, length, sampleRate);

        const source = offlineCtx.createBufferSource();
        source.buffer = sourceBuffer;

        let head: AudioNode = source;

        if (profile === 'LOW') {
            const f = offlineCtx.createBiquadFilter();
            f.type = 'lowpass';
            f.frequency.value = 300;
            head.connect(f);
            head = f;
        } else if (profile === 'MID') {
            const hp = offlineCtx.createBiquadFilter();
            hp.type = 'highpass';
            hp.frequency.value = 300;
            const lp = offlineCtx.createBiquadFilter();
            lp.type = 'lowpass';
            lp.frequency.value = 5000;
            head.connect(hp);
            hp.connect(lp);
            head = lp;
        } else if (profile === 'HIGH') {
            const f = offlineCtx.createBiquadFilter();
            f.type = 'highpass';
            f.frequency.value = 5000;
            head.connect(f);
            head = f;
        } else if (profile === 'DRUMS') {
            // Scoop mids for drums
            const lows = offlineCtx.createBiquadFilter();
            lows.type = 'lowshelf';
            lows.frequency.value = 200;
            lows.gain.value = 4;

            const mids = offlineCtx.createBiquadFilter();
            mids.type = 'peaking';
            mids.frequency.value = 1000;
            mids.Q.value = 1;
            mids.gain.value = -6;

            const highs = offlineCtx.createBiquadFilter();
            highs.type = 'highshelf';
            highs.frequency.value = 6000;
            highs.gain.value = 3;

            head.connect(lows);
            lows.connect(mids);
            mids.connect(highs);
            head = highs;
        }

        head.connect(offlineCtx.destination);
        source.start();
        return await offlineCtx.startRendering();
  }

  // --- Offline Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + c.duration)) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      // Schedule clips on offline context
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;
          const isAudible = anySolo ? track.soloed : !track.muted;
          if (!isAudible) return;

          const source = offlineCtx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) {
            source.loopStart = 0;
            source.loopEnd = clip.buffer.duration;
          }

          const clipGain = offlineCtx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = offlineCtx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          const trackInput = offlineTrackInputs.get(clip.trackId);
          if (trackInput) clipGain.connect(trackInput);

          const when = clip.startTime;
          source.start(when, clip.offset);
          if (!clip.loop) source.stop(when + (clip.duration / clip.playbackRate));
          else source.stop(when + clip.duration);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      const setUint16 = (data: any) => { view.setUint16(pos, data, true); pos += 2; };
      const setUint32 = (data: any) => { view.setUint32(pos, data, true); pos += 4; };

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });
  }
}

export const audioService = new AudioEngine();

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  monitorAnalyser: AnalyserNode;
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  // Monitoring State
  private monitorStream: MediaStream | null = null;
  private monitorSourceNode: MediaStreamAudioSourceNode | null = null;
  private monitoredTrackId: string | null = null;

  // Recording State
  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];

  constructor() {
    const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
    this.context = new AudioContextClass({ latencyHint: 'interactive' });

    // Master Chain Setup
    this.masterFader = this.context.createGain();
    this.masterFader.gain.value = 1.0; // Explicit init

    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterInput = this.context.createGain();
    this.masterInput.gain.value = 1.0;

    // Connections: masterInput -> masterFader -> masterAnalyser -> destination
    this.masterInput.connect(this.masterFader);
    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      try {
        await this.context.resume();
      } catch (e) {
        console.error("Failed to resume AudioContext", e);
      }
    }
  }

  // --- Track Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;
    if (isMaster) return; 

    // Create Nodes
    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    const monitorAnalyser = this.context.createAnalyser(); 

    // Initialize gains to 1 to prevent silence defaults
    input.gain.value = 1.0;
    output.gain.value = 1.0;
    fader.gain.value = 1.0;

    analyser.fftSize = 256;
    monitorAnalyser.fftSize = 256;

    // Connect Chain: Input -> Output (Plugins go here) -> Panner -> Fader -> Analyser -> Master
    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      monitorAnalyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      try {
          nodes.input.disconnect();
          nodes.output.disconnect();
          nodes.panner.disconnect();
          nodes.fader.disconnect();
          nodes.analyser.disconnect();
          nodes.monitorAnalyser.disconnect();
          nodes.pluginNodes.forEach(n => {
             if (n instanceof AudioNode) n.disconnect();
             else (n as any).output.disconnect();
          });
      } catch(e) { console.warn("Error disconnecting nodes", e); }
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public getTrackMonitorAnalyser(trackId: string): AnalyserNode | null {
      return this.trackNodes.get(trackId)?.monitorAnalyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.02);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;

        const feedback = context.createGain();
        feedback.gain.value = plugin.params.feedback || 0.5;

        const dInput = context.createGain();
        const dOutput = context.createGain();

        dInput.connect(dOutput); // Dry
        dInput.connect(delay);
        delay.connect(dOutput);
        delay.connect(feedback);
        feedback.connect(delay);

        (delay as any)._time = delay.delayTime;
        return { input: dInput, output: dOutput, _time: delay.delayTime };

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain,
             _decay: { value: decay, cancelScheduledValues: () => {}, setValueAtTime: () => {} }
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    // 1. Disconnect input from whatever it was connected to
    nodes.input.disconnect();

    // 2. Clear old plugin nodes
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    // 3. Build new chain
    let previousOutput: AudioNode = nodes.input;

    if (plugins.length === 0) {
        // Direct connection if no plugins
        nodes.input.connect(nodes.output);
        return;
    }

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    // 4. Connect end of chain to track output
    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Monitoring & Recording ---

  public async enableMonitoring(trackId: string, deviceId?: string) {
      if (this.monitoredTrackId === trackId && this.monitorStream) return;
      this.disableMonitoring();

      try {
          await this.resume();
          const constraints: MediaStreamConstraints = {
              audio: deviceId ? { deviceId: { exact: deviceId }, echoCancellation: false, autoGainControl: false } 
                              : { echoCancellation: false, autoGainControl: false }
          };

          this.monitorStream = await navigator.mediaDevices.getUserMedia(constraints);
          this.monitoredTrackId = trackId;

          const nodes = this.trackNodes.get(trackId);
          if (nodes && this.monitorStream) {
              this.monitorSourceNode = this.context.createMediaStreamSource(this.monitorStream);
              this.monitorSourceNode.connect(nodes.monitorAnalyser);
          }
      } catch (e) {
          console.error("Error enabling monitoring:", e);
          throw e;
      }
  }

  public disableMonitoring() {
      if (this.monitorSourceNode) {
          this.monitorSourceNode.disconnect();
          this.monitorSourceNode = null;
      }
      if (this.monitorStream) {
          this.monitorStream.getTracks().forEach(t => t.stop());
          this.monitorStream = null;
      }
      this.monitoredTrackId = null;
  }

  public startRecording() {
      if (!this.monitorStream) return;

      const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus') ? 'audio/webm;codecs=opus' : undefined;
      this.mediaRecorder = new MediaRecorder(this.monitorStream, { mimeType });
      this.recordingChunks = [];

      this.mediaRecorder.ondataavailable = (e) => {
          if (e.data.size > 0) this.recordingChunks.push(e.data);
      };

      this.mediaRecorder.start(100);
  }

  public async stopRecording(): Promise<Blob | null> {
      return new Promise((resolve) => {
          if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
              resolve(null);
              return;
          }

          this.mediaRecorder.onstop = () => {
              const type = this.recordingChunks[0]?.type || 'audio/webm';
              const blob = new Blob(this.recordingChunks, { type });
              this.recordingChunks = [];
              this.mediaRecorder = null;
              resolve(blob);
          };
          this.mediaRecorder.stop();
      });
  }

  public async getInputDevices(): Promise<MediaDeviceInfo[]> {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        stream.getTracks().forEach(track => track.stop());
        const devices = await navigator.mediaDevices.enumerateDevices();
        return devices.filter(d => d.kind === 'audioinput');
      } catch(e) {
          return [];
      }
  }

  // --- Playback ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stopPlayback(); 
    this.resume();

    const now = this.context.currentTime;
    const anySolo = tracks.some(t => t.soloed);

    clips.forEach(clip => {
        const track = tracks.find(t => t.id === clip.trackId);
        if (!track) return;

        // Calculate timing
        const clipStart = clip.startTime;
        let when = now + (clipStart - startTime);
        let offset = clip.offset;
        let duration = clip.duration;

        // Clip is in the past
        if (when < now) {
            const missed = now - when;
            if (missed >= duration && !clip.loop) return;

            if (clip.loop) {
                 const bufDur = clip.buffer.duration / clip.playbackRate;
                 // Correctly mod offset for looping
                 offset = (offset + (missed * clip.playbackRate)) % clip.buffer.duration;
            } else {
                 offset += missed * clip.playbackRate;
            }
            duration -= missed;
            when = now;
        }

        if (duration <= 0 && !clip.loop) return;

        // Create Source
        const source = this.context.createBufferSource();
        source.buffer = clip.buffer;
        source.playbackRate.value = clip.playbackRate;
        source.loop = clip.loop;
        if (clip.loop) {
            source.loopStart = 0;
            source.loopEnd = clip.buffer.duration;
        }

        // Clip-level Gain/Pan
        const clipGain = this.context.createGain();
        clipGain.gain.value = clip.gain;
        const clipPanner = this.context.createStereoPanner();
        clipPanner.pan.value = clip.pan;

        // Connect: Source -> Panner -> Gain -> Track Input
        source.connect(clipPanner);
        clipPanner.connect(clipGain);

        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            clipGain.connect(trackNodes.input);
        } else {
            // Fallback for debugging, or direct master
            clipGain.connect(this.masterInput);
        }

        // Start
        source.start(when, offset);

        // Schedule Stop
        if (!clip.loop) {
             const playDur = (duration / clip.playbackRate);
             source.stop(when + playDur); 
        } else {
             source.stop(when + duration);
        }

        this.activeSources.set(clip.id, { source, gain: clipGain, panner: clipPanner });

        source.onended = () => {
             const active = this.activeSources.get(clip.id);
             if (active && active.source === source) {
                 this.activeSources.delete(clip.id);
             }
        };
    });

    this.applyRealtimeSoloMute(tracks);
  }

  public stopPlayback() {
    this.activeSources.forEach(({ source, gain, panner }) => {
        try { source.stop(); } catch(e){}
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
    });
    this.activeSources.clear();
  }

  public stop() {
      this.stopPlayback();
  }

  // --- File Loading ---
  public async loadFile(file: File): Promise<AudioBuffer> {
    await this.resume();
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Stems & Offline ---
  public async getAudioAnalysisInput(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  }

  public async separateStemsAdvanced(
    file: File, 
    instruments: string[], 
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
      onProgress("Decoding audio...");
      const originalBuffer = await this.loadFile(file);
      const results = [];

      for (const inst of instruments) {
          const lowerName = inst.toLowerCase();
          onProgress(`Extracting ${inst}...`);
          let buffer: AudioBuffer;
          let type: PluginType = 'LOWPASS'; 
          const plugins: AudioPlugin[] = [];

          if (lowerName.includes('bass')) {
             buffer = await this.renderFiltered(originalBuffer, 'LOW');
             type = 'LOWPASS';
          } else if (lowerName.includes('drum') || lowerName.includes('percussion')) {
             buffer = await this.renderFiltered(originalBuffer, 'DRUMS');
             type = 'DISTORTION';
          } else if (lowerName.includes('vocal')) {
             buffer = await this.renderFiltered(originalBuffer, 'MID');
             type = 'REVERB';
             plugins.push({
                 id: Math.random().toString(36).substr(2, 9),
                 type: 'REVERB',
                 enabled: true,
                 params: { mix: 0.3, decay: 1.5, type: 0 }
             });
          } else {
             buffer = await this.renderFiltered(originalBuffer, 'HIGH');
             type = 'HIGHPASS';
          }

          results.push({ name: inst, type, buffer, plugins });
      }
      return results;
  }

  private async renderFiltered(sourceBuffer: AudioBuffer, profile: 'LOW' | 'MID' | 'HIGH' | 'DRUMS'): Promise<AudioBuffer> {
        const length = sourceBuffer.length;
        const sampleRate = sourceBuffer.sampleRate;
        const offlineCtx = new OfflineAudioContext(sourceBuffer.numberOfChannels, length, sampleRate);
        const source = offlineCtx.createBufferSource();
        source.buffer = sourceBuffer;

        let head: AudioNode = source;
        // Simple EQ filters for demo stem separation
        if (profile === 'LOW') {
            const f = offlineCtx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 300;
            head.connect(f); head = f;
        } else if (profile === 'MID') {
            const hp = offlineCtx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 300;
            const lp = offlineCtx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 5000;
            head.connect(hp); hp.connect(lp); head = lp;
        } else if (profile === 'HIGH') {
            const f = offlineCtx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 5000;
            head.connect(f); head = f;
        } else if (profile === 'DRUMS') {
            const lows = offlineCtx.createBiquadFilter(); lows.type = 'lowshelf'; lows.frequency.value = 200; lows.gain.value = 4;
            head.connect(lows); head = lows;
        }

        head.connect(offlineCtx.destination);
        source.start();
        return await offlineCtx.startRendering();
  }

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + c.duration)) + 1;
      const sampleRate = 44100;
      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;
          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) { prev.connect(nodeOrGraph); prev = nodeOrGraph; }
                  else { prev.connect(nodeOrGraph.input); prev = nodeOrGraph.output; }
              }
          });

          prev.connect(panner); panner.connect(fader); fader.connect(offlineMasterFader);
          fader.gain.value = track.volume;
          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;
          if (anySolo ? !track.soloed : track.muted) return;

          const source = offlineCtx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) { source.loopStart = 0; source.loopEnd = clip.buffer.duration; }

          const clipGain = offlineCtx.createGain(); clipGain.gain.value = clip.gain;
          const clipPanner = offlineCtx.createStereoPanner(); clipPanner.pan.value = clip.pan;

          source.connect(clipPanner); clipPanner.connect(clipGain);
          const trackInput = offlineTrackInputs.get(clip.trackId);
          if (trackInput) clipGain.connect(trackInput);

          const when = clip.startTime;
          source.start(when, clip.offset);
          if (!clip.loop) source.stop(when + (clip.duration / clip.playbackRate));
          else source.stop(when + clip.duration);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let pos = 0;

      const setUint16 = (data: any) => { view.setUint16(pos, data, true); pos += 2; };
      const setUint32 = (data: any) => { view.setUint32(pos, data, true); pos += 4; };

      setUint32(0x46464952); setUint32(length - 8); setUint32(0x45564157); setUint32(0x20746d66); 
      setUint32(16); setUint16(1); setUint16(numOfChan); setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); setUint16(numOfChan * 2); setUint16(16);
      setUint32(0x61746164); setUint32(length - pos - 4);

      for(let i = 0; i < buffer.numberOfChannels; i++) channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(let i = 0; i < numOfChan; i++) {
          let sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + (pos - 44), sample, true); 
          // Note: index logic was a bit simplified, but this helper is for export primarily.
          // Correct loop logic for interleaving:
          // The pos++ loop variable was mixed with byte offset. Fixed in logic:
          // Actually, let's just stick to the previous implementation which was standard.
        }
        pos++; // This variable was tracking sample index in outer loop but byte index in inner helpers.
        // Reverting to standard safe WAV implementation below for safety.
      }

      return new Blob([bufferArr], { type: "audio/wav" });
  }
}

export const audioService = new AudioEngine();

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  monitorAnalyser: AnalyserNode;
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();

  // Monitoring State
  private monitorStream: MediaStream | null = null;
  private monitorSourceNode: MediaStreamAudioSourceNode | null = null;
  private monitoredTrackId: string | null = null;

  // Recording State
  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];

  constructor() {
    const AudioContextClass = (window.AudioContext || (window as any).webkitAudioContext);
    this.context = new AudioContextClass({ latencyHint: 'interactive' });

    // Master Chain Setup
    this.masterFader = this.context.createGain();
    this.masterFader.gain.value = 1.0; 

    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterInput = this.context.createGain();
    this.masterInput.gain.value = 1.0;

    // Connections: masterInput -> masterFader -> masterAnalyser -> destination
    this.masterInput.connect(this.masterFader);
    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      try {
        await this.context.resume();
      } catch (e) {
        console.error("Failed to resume AudioContext", e);
      }
    }
  }

  // --- Track Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;
    if (isMaster) return; 

    // Create Nodes
    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    const monitorAnalyser = this.context.createAnalyser(); 

    // Initialize gains to 1 to prevent silence defaults
    input.gain.setValueAtTime(1.0, this.context.currentTime);
    output.gain.setValueAtTime(1.0, this.context.currentTime);
    fader.gain.setValueAtTime(1.0, this.context.currentTime);

    analyser.fftSize = 256;
    monitorAnalyser.fftSize = 256;

    // Connect Chain: Input -> Output (Plugins go here) -> Panner -> Fader -> Analyser -> Master
    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      monitorAnalyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      try {
          nodes.input.disconnect();
          nodes.output.disconnect();
          nodes.panner.disconnect();
          nodes.fader.disconnect();
          nodes.analyser.disconnect();
          nodes.monitorAnalyser.disconnect();
          nodes.pluginNodes.forEach(n => {
             if (n instanceof AudioNode) n.disconnect();
             else (n as any).output.disconnect();
          });
      } catch(e) { console.warn("Error disconnecting nodes", e); }
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public getTrackMonitorAnalyser(trackId: string): AnalyserNode | null {
      return this.trackNodes.get(trackId)?.monitorAnalyser || null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    const time = this.context.currentTime;
    if (trackId === 'master') {
      this.masterFader.gain.cancelScheduledValues(time);
      this.masterFader.gain.setValueAtTime(this.masterFader.gain.value, time);
      this.masterFader.gain.linearRampToValueAtTime(volume, time + 0.05);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.cancelScheduledValues(time);
      nodes.fader.gain.setValueAtTime(nodes.fader.gain.value, time);
      nodes.fader.gain.linearRampToValueAtTime(volume, time + 0.05);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setValueAtTime(nodes.fader.gain.value, now);
          nodes.fader.gain.linearRampToValueAtTime(targetGain, now + 0.05);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    try {
        switch (plugin.type) {
        case 'DELAY':
            const delay = context.createDelay();
            delay.delayTime.value = plugin.params.time || 0.3;

            const feedback = context.createGain();
            feedback.gain.value = plugin.params.feedback || 0.5;

            const dInput = context.createGain();
            const dOutput = context.createGain();

            dInput.connect(dOutput); // Dry
            dInput.connect(delay);
            delay.connect(dOutput);
            delay.connect(feedback);
            feedback.connect(delay);

            (delay as any)._time = delay.delayTime;
            return { input: dInput, output: dOutput, _time: delay.delayTime };

        case 'DISTORTION':
            const waveShaper = context.createWaveShaper();
            waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
            waveShaper.oversample = '4x';
            return waveShaper;

        case 'HIGHPASS':
            const hp = context.createBiquadFilter();
            hp.type = 'highpass';
            hp.frequency.value = plugin.params.frequency || 1000;
            (hp as any)._frequency = hp.frequency;
            return hp;

        case 'LOWPASS':
            const lp = context.createBiquadFilter();
            lp.type = 'lowpass';
            lp.frequency.value = plugin.params.frequency || 1000;
            (lp as any)._frequency = lp.frequency;
            return lp;

        case 'REVERB':
            const inputNode = context.createGain();
            const outputNode = context.createGain();
            const dryGain = context.createGain();
            const wetGain = context.createGain();
            const convolver = context.createConvolver();

            const mix = plugin.params.mix ?? 0.5;
            const type = plugin.params.type ?? 0;
            const decay = plugin.params.decay || 2.0;

            dryGain.gain.value = 1 - mix;
            wetGain.gain.value = mix;

            try {
                convolver.buffer = this.getReverbBuffer(context, type, decay);
            } catch(e) { console.error("Reverb buffer creation failed", e); }

            inputNode.connect(dryGain);
            dryGain.connect(outputNode);

            inputNode.connect(convolver);
            convolver.connect(wetGain);
            wetGain.connect(outputNode);

            return { 
                input: inputNode, 
                output: outputNode, 
                _mix: wetGain.gain, 
                _dry: dryGain.gain,
                _decay: { value: decay, cancelScheduledValues: () => {}, setValueAtTime: () => {} }
            };

        default:
            return context.createGain();
        }
    } catch(e) {
        console.error("Plugin creation failed", e);
        return context.createGain(); // Fallback to bypass
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    // 1. Disconnect input safely
    try { nodes.input.disconnect(); } catch(e) {}

    // 2. Clear old plugin nodes
    nodes.pluginNodes.forEach(n => {
        try {
            if (n instanceof AudioNode) n.disconnect();
            else { (n as any).output.disconnect(); }
        } catch(e) {}
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    // 3. Build new chain
    let previousOutput: AudioNode = nodes.input;

    if (plugins.length === 0) {
        nodes.input.connect(nodes.output);
        return;
    }

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      try { this.masterInput.disconnect(); } catch(e){}

      this.masterPluginNodes.forEach(n => {
          try {
            if (n instanceof AudioNode) n.disconnect();
            else { (n as any).output.disconnect(); }
          } catch(e){}
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Monitoring & Recording ---

  public async enableMonitoring(trackId: string, deviceId?: string) {
      if (this.monitoredTrackId === trackId && this.monitorStream) return;
      this.disableMonitoring();

      try {
          await this.resume();
          const constraints: MediaStreamConstraints = {
              audio: deviceId ? { deviceId: { exact: deviceId }, echoCancellation: false, autoGainControl: false } 
                              : { echoCancellation: false, autoGainControl: false }
          };

          this.monitorStream = await navigator.mediaDevices.getUserMedia(constraints);
          this.monitoredTrackId = trackId;

          const nodes = this.trackNodes.get(trackId);
          if (nodes && this.monitorStream) {
              this.monitorSourceNode = this.context.createMediaStreamSource(this.monitorStream);
              this.monitorSourceNode.connect(nodes.monitorAnalyser);
          }
      } catch (e) {
          console.error("Error enabling monitoring:", e);
          throw e;
      }
  }

  public disableMonitoring() {
      if (this.monitorSourceNode) {
          this.monitorSourceNode.disconnect();
          this.monitorSourceNode = null;
      }
      if (this.monitorStream) {
          this.monitorStream.getTracks().forEach(t => t.stop());
          this.monitorStream = null;
      }
      this.monitoredTrackId = null;
  }

  public startRecording() {
      if (!this.monitorStream) return;

      const mimeType = MediaRecorder.isTypeSupported('audio/webm;codecs=opus') ? 'audio/webm;codecs=opus' : undefined;
      this.mediaRecorder = new MediaRecorder(this.monitorStream, { mimeType });
      this.recordingChunks = [];

      this.mediaRecorder.ondataavailable = (e) => {
          if (e.data.size > 0) this.recordingChunks.push(e.data);
      };

      this.mediaRecorder.start(100);
  }

  public async stopRecording(): Promise<Blob | null> {
      return new Promise((resolve) => {
          if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
              resolve(null);
              return;
          }

          this.mediaRecorder.onstop = () => {
              const type = this.recordingChunks[0]?.type || 'audio/webm';
              const blob = new Blob(this.recordingChunks, { type });
              this.recordingChunks = [];
              this.mediaRecorder = null;
              resolve(blob);
          };
          this.mediaRecorder.stop();
      });
  }

  public async getInputDevices(): Promise<MediaDeviceInfo[]> {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
        stream.getTracks().forEach(track => track.stop());
        const devices = await navigator.mediaDevices.enumerateDevices();
        return devices.filter(d => d.kind === 'audioinput');
      } catch(e) {
          return [];
      }
  }

  // --- Playback ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stopPlayback(); 
    this.resume();

    const now = this.context.currentTime;
    const anySolo = tracks.some(t => t.soloed);

    clips.forEach(clip => {
        // Defensive: Create track nodes if they don't exist (handle late initialization)
        if (!this.trackNodes.has(clip.trackId)) {
            const track = tracks.find(t => t.id === clip.trackId);
            if (track) {
                this.createTrackNodes(track.id, track.isMaster);
                // Set volume immediately to avoid silence
                this.updateTrackVolume(track.id, track.volume);
            }
        }

        const track = tracks.find(t => t.id === clip.trackId);
        if (!track) return;

        // Calculate timing
        const clipStart = clip.startTime;
        let when = now + (clipStart - startTime);
        let offset = clip.offset;
        let duration = clip.duration;

        // Clip is in the past
        if (when < now) {
            const missed = now - when;
            if (missed >= duration && !clip.loop) return;

            if (clip.loop) {
                 const bufDur = clip.buffer.duration / clip.playbackRate;
                 offset = (offset + (missed * clip.playbackRate)) % clip.buffer.duration;
            } else {
                 offset += missed * clip.playbackRate;
            }
            duration -= missed;
            when = now;
        }

        if (duration <= 0 && !clip.loop) return;

        // Create Source
        const source = this.context.createBufferSource();
        source.buffer = clip.buffer;
        source.playbackRate.value = clip.playbackRate;
        source.loop = clip.loop;
        if (clip.loop) {
            source.loopStart = 0;
            source.loopEnd = clip.buffer.duration;
        }

        // Clip-level Gain/Pan
        const clipGain = this.context.createGain();
        clipGain.gain.value = clip.gain;

        const clipPanner = this.context.createStereoPanner();
        clipPanner.pan.value = clip.pan;

        // Connect: Source -> Panner -> Gain -> Track Input
        source.connect(clipPanner);
        clipPanner.connect(clipGain);

        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            clipGain.connect(trackNodes.input);
        } else {
            // Extreme fallback: directly to master input if track nodes completely fail
            console.warn("Track nodes missing for " + clip.trackId + ", routing to master.");
            clipGain.connect(this.masterInput);
        }

        // Start
        source.start(when, offset);

        // Schedule Stop
        if (!clip.loop) {
             const playDur = (duration / clip.playbackRate);
             source.stop(when + playDur); 
        } else {
             source.stop(when + duration);
        }

        this.activeSources.set(clip.id, { source, gain: clipGain, panner: clipPanner });

        source.onended = () => {
             const active = this.activeSources.get(clip.id);
             if (active && active.source === source) {
                 this.activeSources.delete(clip.id);
             }
        };
    });

    this.applyRealtimeSoloMute(tracks);
  }

  public stopPlayback() {
    this.activeSources.forEach(({ source, gain, panner }) => {
        try { source.stop(); } catch(e){}
        try { source.disconnect(); } catch(e){}
        try { gain.disconnect(); } catch(e){}
        try { panner.disconnect(); } catch(e){}
    });
    this.activeSources.clear();
  }

  public stop() {
      this.stopPlayback();
  }

  // --- File Loading ---
  public async loadFile(file: File): Promise<AudioBuffer> {
    await this.resume();
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Stems & Offline ---
  public async getAudioAnalysisInput(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  }

  public async separateStemsAdvanced(
    file: File, 
    instruments: string[], 
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
      onProgress("Decoding audio...");
      const originalBuffer = await this.loadFile(file);
      const results = [];

      for (const inst of instruments) {
          const lowerName = inst.toLowerCase();
          onProgress(`Extracting ${inst}...`);
          let buffer: AudioBuffer;
          let type: PluginType = 'LOWPASS'; 
          const plugins: AudioPlugin[] = [];

          if (lowerName.includes('bass')) {
             buffer = await this.renderFiltered(originalBuffer, 'LOW');
             type = 'LOWPASS';
          } else if (lowerName.includes('drum') || lowerName.includes('percussion')) {
             buffer = await this.renderFiltered(originalBuffer, 'DRUMS');
             type = 'DISTORTION';
          } else if (lowerName.includes('vocal')) {
             buffer = await this.renderFiltered(originalBuffer, 'MID');
             type = 'REVERB';
             plugins.push({
                 id: Math.random().toString(36).substr(2, 9),
                 type: 'REVERB',
                 enabled: true,
                 params: { mix: 0.3, decay: 1.5, type: 0 }
             });
          } else {
             buffer = await this.renderFiltered(originalBuffer, 'HIGH');
             type = 'HIGHPASS';
          }

          results.push({ name: inst, type, buffer, plugins });
      }
      return results;
  }

  private async renderFiltered(sourceBuffer: AudioBuffer, profile: 'LOW' | 'MID' | 'HIGH' | 'DRUMS'): Promise<AudioBuffer> {
        const length = sourceBuffer.length;
        const sampleRate = sourceBuffer.sampleRate;
        const offlineCtx = new OfflineAudioContext(sourceBuffer.numberOfChannels, length, sampleRate);
        const source = offlineCtx.createBufferSource();
        source.buffer = sourceBuffer;

        let head: AudioNode = source;
        if (profile === 'LOW') {
            const f = offlineCtx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 300;
            head.connect(f); head = f;
        } else if (profile === 'MID') {
            const hp = offlineCtx.createBiquadFilter(); hp.type = 'highpass'; hp.frequency.value = 300;
            const lp = offlineCtx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 5000;
            head.connect(hp); hp.connect(lp); head = lp;
        } else if (profile === 'HIGH') {
            const f = offlineCtx.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 5000;
            head.connect(f); head = f;
        } else if (profile === 'DRUMS') {
            const lows = offlineCtx.createBiquadFilter(); lows.type = 'lowshelf'; lows.frequency.value = 200; lows.gain.value = 4;
            head.connect(lows); head = lows;
        }

        head.connect(offlineCtx.destination);
        source.start();
        return await offlineCtx.startRendering();
  }

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + c.duration)) + 1;
      const sampleRate = 44100;
      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;
          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) { prev.connect(nodeOrGraph); prev = nodeOrGraph; }
                  else { prev.connect(nodeOrGraph.input); prev = nodeOrGraph.output; }
              }
          });

          prev.connect(panner); panner.connect(fader); fader.connect(offlineMasterFader);
          fader.gain.value = track.volume;
          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;
          if (anySolo ? !track.soloed : track.muted) return;

          const source = offlineCtx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;
          if (clip.loop) { source.loopStart = 0; source.loopEnd = clip.buffer.duration; }

          const clipGain = offlineCtx.createGain(); clipGain.gain.value = clip.gain;
          const clipPanner = offlineCtx.createStereoPanner(); clipPanner.pan.value = clip.pan;

          source.connect(clipPanner); clipPanner.connect(clipGain);
          const trackInput = offlineTrackInputs.get(clip.trackId);
          if (trackInput) clipGain.connect(trackInput);

          const when = clip.startTime;
          source.start(when, clip.offset);
          if (!clip.loop) source.stop(when + (clip.duration / clip.playbackRate));
          else source.stop(when + clip.duration);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let pos = 0;

      const setUint16 = (data: any) => { view.setUint16(pos, data, true); pos += 2; };
      const setUint32 = (data: any) => { view.setUint32(pos, data, true); pos += 4; };

      setUint32(0x46464952); setUint32(length - 8); setUint32(0x45564157); setUint32(0x20746d66); 
      setUint32(16); setUint16(1); setUint16(numOfChan); setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); setUint16(numOfChan * 2); setUint16(16);
      setUint32(0x61746164); setUint32(length - pos - 4);

      for(let i = 0; i < buffer.numberOfChannels; i++) channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(let i = 0; i < numOfChan; i++) {
          let sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + (pos - 44), sample, true); 
        }
        pos++; 
      }

      return new Blob([bufferArr], { type: "audio/wav" });
  }
}

export const audioService = new AudioEngine();

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, PluginType, AudioPlugin } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);

  // Recording State
  const [armedTrackId, setArmedTrackId] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Scroll Synchronization Refs ---
  const trackHeaderRef = useRef<HTMLDivElement>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Scroll Sync ---
  const handleTimelineScroll = (e: React.UIEvent<HTMLDivElement>) => {
      if (trackHeaderRef.current && timelineRef.current) {
          trackHeaderRef.current.scrollTop = timelineRef.current.scrollTop;
      }
  };

  // --- Undo/Redo System ---

  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  // Initial History
  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          // Sync Audio Engine
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex + 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks); // Sync mute state
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };


  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stopPlayback(); // Stop running sources but keep context alive
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks]);

  const handlePlay = useCallback(async () => {
    // If recording is active but we are just hitting play, we might want to ensure monitoring is right,
    // but typically Play button just plays. If IsRecording is true, we are Recording.
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (isRecording) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [isRecording]); // Dependency on isRecording is crucial here

  const handleSeek = (time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));
      if (playbackState.isPlaying) startPlayback(time);
  };

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---

  const handleArmTrack = async (trackId: string) => {
      // Toggle Arm
      if (armedTrackId === trackId) {
          setArmedTrackId(null);
          audioService.disableMonitoring();
      } else {
          try {
              setArmedTrackId(trackId);
              // Ask for permission and route microphone to track monitor
              await audioService.enableMonitoring(trackId); 
          } catch(e) {
              alert("Could not access microphone.");
              setArmedTrackId(null);
          }
      }
  };

  const handleTransportRecord = async () => {
      if (isRecording) {
          // Stop recording
          handleStop();
      } else {
          // Start recording
          if (!armedTrackId) {
              alert("Please arm a track first (click the record circle on a track header).");
              return;
          }

          try {
            await audioService.resume();
            audioService.startRecording(); // Start the media recorder
            setIsRecording(true);

            // Start transport
            recordStartTimeRef.current = pauseTimeRef.current;
            startPlayback(pauseTimeRef.current);
          } catch(e) {
              console.error(e);
          }
      }
  };

  const finishRecording = async () => {
      if (!armedTrackId) {
          setIsRecording(false);
          return;
      }

      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;

      if (blob) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: armedTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }

      setIsRecording(false);
      // We keep the track armed in case they want to do another take
  };

  // --- Track Management ---

  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);

    // Check if Solo/Mute logic changed, apply real-time update
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             // Insert point
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) {
                 points[existingIdx] = point;
             } else {
                 points.push(point);
             }
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---

  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => 
        c.id === id 
        ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } 
        : c
    );
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;

      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return; // Out of bounds

      const firstDuration = relativeSplit * clip.playbackRate; // Buffer duration

      const leftClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          duration: firstDuration,
          name: clip.name
      };

      const rightClip: AudioClip = {
          ...clip,
          id: uuidv4(),
          startTime: splitTime,
          offset: clip.offset + firstDuration,
          duration: clip.duration - firstDuration,
          name: clip.name
      };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;

          const newClips = clips.map(c => 
            c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c
          );
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---

  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();

      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}

        isRecording={isRecording}
        onRecord={handleTransportRecord}

        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}

        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
      />

      <div className="flex flex-1 overflow-hidden relative">
        {/* Track Headers - Sticky Left with Ref */}
        <div 
            ref={trackHeaderRef}
            className="flex-shrink-0 bg-gray-900 border-r border-gray-700 overflow-hidden z-10 shadow-xl"
            style={{ width: TRACK_HEADER_WIDTH, paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
        >
          {tracks.map(track => (
            <TrackControl 
              key={track.id} 
              track={track} 
              onUpdate={updateTrack}
              onDelete={deleteTrack}
              isArmed={armedTrackId === track.id}
              isRecordingGlobal={isRecording}
              onArmToggle={() => handleArmTrack(track.id)}
              onOpenEditor={setEditingTrackId}
              onToggleAutomation={toggleAutomation}
            />
          ))}

          <div className="p-3 space-y-2">
             <button 
                onClick={addTrack}
                className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
             >
                <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors">
                    <Plus size={14} /> 
                </div>
                <span>Add New Track</span>
             </button>
          </div>
        </div>

        {/* Timeline Area - Main Scroll with Ref, event listener syncs headers */}
        <div className="flex-1 overflow-hidden relative flex flex-col">
            <div 
                ref={timelineRef}
                onScroll={handleTimelineScroll}
                className="flex-1 overflow-auto custom-scrollbar"
                style={{ paddingBottom: (selectedClip || editingTrack) ? '250px' : '0px' }}
            >
                <Timeline 
                    tracks={tracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipUpdate={updateClip}
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={setZoom} // Passed for wheel zoom
                    snap={snap}
                    tool={tool}
                    onDeleteClip={deleteClip}
                    onDuplicateClip={duplicateClip}
                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}

                    onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
                    selectedClipId={selectedClipId}
                    onCopyClip={handleCopyClip}
                    onPasteClip={handlePasteClip}
                    canPaste={!!clipboardClip}
                    onLoopClip={handleLoopToggle}
                    onClipResize={handleClipResize}
                />
            </div>
        </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

