interface TransportProps {
  isPlaying: boolean;
  onPlay: () => void;
  onStop: () => void;
  onRewind: () => void;
  onFastForward: () => void;

  isRecording: boolean;
  onRecord: () => void;

  currentTime: number;
  bpm: number;
  setBpm: (bpm: number) => void;

  tool: ToolType;
  setTool: (t: ToolType) => void;
  zoom: number;
  setZoom: (z: number) => void;
  snap: boolean;
  setSnap: (s: boolean) => void;
