                <div style={{ width: timelineWidth + TRACK_HEADER_WIDTH, height: '1px' }}></div>
             </div>
         </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

export default App;

import { AudioClip, Track, AudioPlugin, AutomationPoint, PluginType } from '../types';

interface ActiveSource {
  source: AudioBufferSourceNode;
  gain: GainNode;
  panner: StereoPannerNode;
}

interface TrackNodes {
  input: GainNode;     
  output: GainNode;    
  panner: StereoPannerNode;
  fader: GainNode;     
  analyser: AnalyserNode; 
  pluginNodes: AudioNode[];
  pluginMap: Map<string, AudioNode | any>; 
}

class AudioEngine {
  private context: AudioContext;

  private masterInput: GainNode;
  private masterFader: GainNode;
  private masterAnalyser: AnalyserNode;
  private masterPluginNodes: AudioNode[] = [];

  private activeSources: Map<string, ActiveSource> = new Map();
  private trackNodes: Map<string, TrackNodes> = new Map();
  private metronomeNodes: AudioNode[] = [];

  private mediaRecorder: MediaRecorder | null = null;
  private recordingChunks: Blob[] = [];
  private recordingStream: MediaStream | null = null;

  // Monitoring
  private monitorStream: MediaStream | null = null;
  private monitorSource: MediaStreamAudioSourceNode | null = null;
  private monitorAnalyser: AnalyserNode | null = null;
  private monitorGain: GainNode | null = null;
  private monitorTrackId: string | null = null;

  constructor() {
    this.context = new (window.AudioContext || (window as any).webkitAudioContext)();

    this.masterFader = this.context.createGain();
    this.masterAnalyser = this.context.createAnalyser();
    this.masterAnalyser.fftSize = 256;
    this.masterAnalyser.smoothingTimeConstant = 0.8;

    this.masterFader.connect(this.masterAnalyser);
    this.masterAnalyser.connect(this.context.destination);

    this.masterInput = this.context.createGain();
    this.masterInput.connect(this.masterFader);
  }

  public getContext() {
    return this.context;
  }

  public async resume() {
    if (this.context.state === 'suspended') {
      await this.context.resume();
    }
  }

  public async loadFile(file: File): Promise<AudioBuffer> {
    const arrayBuffer = await file.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  public async decodeBlob(blob: Blob): Promise<AudioBuffer> {
    const arrayBuffer = await blob.arrayBuffer();
    return await this.context.decodeAudioData(arrayBuffer);
  }

  // --- Metronome ---
  public scheduleMetronome(bpm: number, startTime: number, duration: number = 600) {
      const beatDuration = 60 / bpm;
      const totalBeats = Math.floor(duration / beatDuration);

      const metronomeGain = this.context.createGain();
      metronomeGain.gain.value = 0.3;
      metronomeGain.connect(this.context.destination);
      this.metronomeNodes.push(metronomeGain);

      for(let i = 0; i < totalBeats; i++) {
          const time = startTime + (i * beatDuration);
          const isDownbeat = i % 4 === 0;

          const osc = this.context.createOscillator();
          osc.type = 'sine';
          osc.frequency.value = isDownbeat ? 1000 : 800;

          const envelope = this.context.createGain();
          envelope.gain.setValueAtTime(1, time);
          envelope.gain.exponentialRampToValueAtTime(0.001, time + 0.1);

          osc.connect(envelope);
          envelope.connect(metronomeGain);

          osc.start(time);
          osc.stop(time + 0.1);

          this.metronomeNodes.push(osc);
          this.metronomeNodes.push(envelope);
      }
  }

  public playCountIn(bpm: number, measures: number): Promise<void> {
      return new Promise((resolve) => {
          const now = this.context.currentTime;
          const beatDuration = 60 / bpm;
          const totalBeats = measures * 4;

          this.scheduleMetronome(bpm, now, totalBeats * beatDuration + 0.1);

          setTimeout(() => {
              resolve();
          }, totalBeats * beatDuration * 1000);
      });
  }

  // --- Track Node Management ---

  public createTrackNodes(trackId: string, isMaster: boolean = false) {
    if (this.trackNodes.has(trackId)) return;

    if (isMaster) return; 

    const input = this.context.createGain();
    const output = this.context.createGain();
    const panner = this.context.createStereoPanner();
    const fader = this.context.createGain();
    const analyser = this.context.createAnalyser();
    analyser.fftSize = 256;
    analyser.smoothingTimeConstant = 0.8;

    input.connect(output);
    output.connect(panner);
    panner.connect(fader);
    fader.connect(analyser);
    analyser.connect(this.masterInput);

    this.trackNodes.set(trackId, { 
      input, 
      output, 
      panner, 
      fader, 
      analyser,
      pluginNodes: [],
      pluginMap: new Map()
    });
  }

  public removeTrackNodes(trackId: string) {
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.input.disconnect();
      nodes.output.disconnect();
      nodes.panner.disconnect();
      nodes.fader.disconnect();
      nodes.analyser.disconnect();
      nodes.pluginNodes.forEach(n => {
         if (n instanceof AudioNode) n.disconnect();
         else (n as any).output.disconnect();
      });
      this.trackNodes.delete(trackId);
    }
  }

  public getTrackAnalyser(trackId: string): AnalyserNode | null {
      if (trackId === 'master') return this.masterAnalyser;
      return this.trackNodes.get(trackId)?.analyser || null;
  }

  public getTrackMonitorAnalyser(trackId: string): AnalyserNode | null {
      if (this.monitorTrackId === trackId) {
          return this.monitorAnalyser;
      }
      return null;
  }

  public async enableMonitoring(trackId: string) {
      if (this.monitorStream) {
          this.disableMonitoring();
      }

      try {
          this.monitorStream = await navigator.mediaDevices.getUserMedia({ 
              audio: { 
                  echoCancellation: false, 
                  autoGainControl: false, 
                  noiseSuppression: false,
                  latency: 0 
              } as any
          });

          this.monitorSource = this.context.createMediaStreamSource(this.monitorStream);
          this.monitorAnalyser = this.context.createAnalyser();
          this.monitorAnalyser.fftSize = 256;
          this.monitorAnalyser.smoothingTimeConstant = 0.8;

          // Create a mute gain node to keep the graph active without feedback
          this.monitorGain = this.context.createGain();
          this.monitorGain.gain.value = 0;

          this.monitorSource.connect(this.monitorAnalyser);
          this.monitorAnalyser.connect(this.monitorGain);
          this.monitorGain.connect(this.context.destination);

          this.monitorTrackId = trackId;
      } catch (err) {
          console.error("Error enabling monitoring:", err);
          throw err;
      }
  }

  public disableMonitoring() {
      if (this.monitorSource) {
          this.monitorSource.disconnect();
          this.monitorSource = null;
      }
      if (this.monitorAnalyser) {
          this.monitorAnalyser.disconnect();
          this.monitorAnalyser = null;
      }
      if (this.monitorGain) {
          this.monitorGain.disconnect();
          this.monitorGain = null;
      }
      if (this.monitorStream) {
          this.monitorStream.getTracks().forEach(t => t.stop());
          this.monitorStream = null;
      }
      this.monitorTrackId = null;
  }

  public updateTrackVolume(trackId: string, volume: number) {
    if (trackId === 'master') {
      this.masterFader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
      return;
    }
    const nodes = this.trackNodes.get(trackId);
    if (nodes) {
      nodes.fader.gain.setTargetAtTime(volume, this.context.currentTime, 0.02);
    }
  }

  public applyRealtimeSoloMute(tracks: Track[]) {
      const anySolo = tracks.some(t => t.soloed);
      const now = this.context.currentTime;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          const isAudible = anySolo ? track.soloed : !track.muted;
          const targetGain = isAudible ? track.volume : 0;

          nodes.fader.gain.cancelScheduledValues(now);
          nodes.fader.gain.setTargetAtTime(targetGain, now, 0.01);
      });
  }

  public updateTrackPlugins(trackId: string, plugins: AudioPlugin[]) {
    if (trackId === 'master') {
      this.rebuildMasterChain(plugins);
    } else {
      this.rebuildTrackChain(trackId, plugins);
    }
  }

  // --- Plugin Factory ---

  private createPluginNode(context: BaseAudioContext, plugin: AudioPlugin): AudioNode | { input: AudioNode, output: AudioNode, [key: string]: any } {
    switch (plugin.type) {
      case 'DELAY':
        const delay = context.createDelay();
        delay.delayTime.value = plugin.params.time || 0.3;
        (delay as any)._time = delay.delayTime;
        return delay;

      case 'DISTORTION':
        const waveShaper = context.createWaveShaper();
        waveShaper.curve = this.makeDistortionCurve(plugin.params.drive || 0);
        waveShaper.oversample = '4x';
        return waveShaper;

      case 'HIGHPASS':
        const hp = context.createBiquadFilter();
        hp.type = 'highpass';
        hp.frequency.value = plugin.params.frequency || 1000;
        (hp as any)._frequency = hp.frequency;
        return hp;

      case 'LOWPASS':
        const lp = context.createBiquadFilter();
        lp.type = 'lowpass';
        lp.frequency.value = plugin.params.frequency || 1000;
        (lp as any)._frequency = lp.frequency;
        return lp;

      case 'REVERB':
         const inputNode = context.createGain();
         const outputNode = context.createGain();
         const dryGain = context.createGain();
         const wetGain = context.createGain();
         const convolver = context.createConvolver();

         const mix = plugin.params.mix ?? 0.5;
         const type = plugin.params.type ?? 0;
         const decay = plugin.params.decay || 2.0;

         dryGain.gain.value = 1 - mix;
         wetGain.gain.value = mix;

         convolver.buffer = this.getReverbBuffer(context, type, decay);

         inputNode.connect(dryGain);
         dryGain.connect(outputNode);

         inputNode.connect(convolver);
         convolver.connect(wetGain);
         wetGain.connect(outputNode);

         return { 
             input: inputNode, 
             output: outputNode, 
             _mix: wetGain.gain, 
             _dry: dryGain.gain
         };

      default:
        return context.createGain();
    }
  }

  private rebuildTrackChain(trackId: string, plugins: AudioPlugin[]) {
    const nodes = this.trackNodes.get(trackId);
    if (!nodes) return;

    nodes.input.disconnect();
    nodes.pluginNodes.forEach(n => {
        if (n instanceof AudioNode) n.disconnect();
        else { (n as any).output.disconnect(); }
    });
    nodes.pluginNodes = [];
    nodes.pluginMap.clear();

    let previousOutput: AudioNode = nodes.input;

    plugins.forEach(plugin => {
        if (!plugin.enabled) return;
        const nodeOrGraph = this.createPluginNode(this.context, plugin);

        let input: AudioNode;
        let output: AudioNode;

        if (nodeOrGraph instanceof AudioNode) {
            input = nodeOrGraph;
            output = nodeOrGraph;
            nodes.pluginNodes.push(input);
        } else {
            input = nodeOrGraph.input;
            output = nodeOrGraph.output;
            nodes.pluginNodes.push(output); 
        }

        nodes.pluginMap.set(plugin.id, nodeOrGraph);
        previousOutput.connect(input);
        previousOutput = output;
    });

    previousOutput.connect(nodes.output);
  }

  private rebuildMasterChain(plugins: AudioPlugin[]) {
      this.masterInput.disconnect();
      this.masterPluginNodes.forEach(n => {
          if (n instanceof AudioNode) n.disconnect();
          else { (n as any).output.disconnect(); }
      });
      this.masterPluginNodes = [];

      let previousOutput: AudioNode = this.masterInput;

      plugins.forEach(plugin => {
          if (!plugin.enabled) return;
          const nodeOrGraph = this.createPluginNode(this.context, plugin);

          let input: AudioNode;
          let output: AudioNode;

          if (nodeOrGraph instanceof AudioNode) {
              input = nodeOrGraph;
              output = nodeOrGraph;
              this.masterPluginNodes.push(input);
          } else {
              input = nodeOrGraph.input;
              output = nodeOrGraph.output;
              this.masterPluginNodes.push(output);
          }

          previousOutput.connect(input);
          previousOutput = output;
      });

      previousOutput.connect(this.masterFader);
  }

  // --- DSP Utilities ---

  private makeDistortionCurve(amount: number) {
    const k = typeof amount === 'number' ? amount : 50;
    const n_samples = 44100;
    const curve = new Float32Array(n_samples);
    const deg = Math.PI / 180;
    for (let i = 0; i < n_samples; ++i) {
      const x = (i * 2) / n_samples - 1;
      curve[i] = ((3 + k) * x * 20 * deg) / (Math.PI + k * Math.abs(x));
    }
    return curve;
  }

  private getReverbBuffer(context: BaseAudioContext, type: number, decayTime: number) {
      const sampleRate = context.sampleRate;
      const length = sampleRate * decayTime;
      const impulse = context.createBuffer(2, length, sampleRate);
      const left = impulse.getChannelData(0);
      const right = impulse.getChannelData(1);

      for (let i = 0; i < length; i++) {
          let decay = 0;
          if (type === 0) decay = Math.pow(1 - i / length, decayTime * 1.5);
          else if (type === 1) decay = Math.pow(1 - i / length, decayTime * 4);
          else decay = Math.pow(1 - i / length, decayTime * 2);

          left[i] = (Math.random() * 2 - 1) * decay;
          right[i] = (Math.random() * 2 - 1) * decay;
      }
      return impulse;
  }

  // --- Playback & Automation ---

  public play(clips: AudioClip[], tracks: Track[], startTime: number) {
    this.stop(); 
    this.resume();
    const now = this.context.currentTime;

    const anySolo = tracks.some(t => t.soloed);

    this.scheduleClips(this.context, clips, tracks, startTime, now, anySolo, (clip, source, gain, panner) => {
        const trackNodes = this.trackNodes.get(clip.trackId);
        if (trackNodes) {
            gain.connect(trackNodes.input);
        } else {
            gain.connect(this.masterInput);
        }

        this.activeSources.set(clip.id, { source, gain, panner });
        source.onended = () => {
             const current = this.activeSources.get(clip.id);
             if (current && current.source === source) {
                  this.activeSources.delete(clip.id);
             }
        };
    });

    this.scheduleAutomation(tracks, startTime, now);
  }

  private scheduleAutomation(tracks: Track[], startTime: number, now: number) {
      tracks.forEach(track => {
          if (!track.automation) return;
          const nodes = this.trackNodes.get(track.id);
          if (!nodes) return;

          Object.keys(track.automation).forEach(paramId => {
              const points = track.automation[paramId];
              if (!points || points.length === 0) return;

              let param: AudioParam | null = null;

              if (paramId === 'volume') {
                  param = nodes.fader.gain;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(track.volume, now);
              } else if (paramId === 'pan') {
                  param = nodes.panner.pan;
                  param.cancelScheduledValues(now);
                  param.setValueAtTime(0, now);
              } else if (paramId.includes(':')) {
                  const [pluginId, paramName] = paramId.split(':');
                  const pluginNode = nodes.pluginMap.get(pluginId);
                  const internalProp = `_${paramName}`;
                  if (pluginNode && pluginNode[internalProp]) {
                      param = pluginNode[internalProp] as AudioParam;
                      param.cancelScheduledValues(now);
                      param.setValueAtTime(param.value, now);
                  }
              }

              if (param) {
                  points.forEach(point => {
                      const absoluteTime = now + (point.time - startTime);
                      if (absoluteTime >= now) {
                          const scaledValue = this.scaleAutomationValue(paramId, point.value);
                          // Use exponential ramp for natural sounding filter sweeps, linear for volume
                          if (paramId.includes('frequency')) {
                              param!.exponentialRampToValueAtTime(Math.max(0.01, scaledValue), absoluteTime);
                          } else {
                              param!.linearRampToValueAtTime(scaledValue, absoluteTime);
                          }
                      }
                  });
              }
          });
      });
  }

  private scaleAutomationValue(paramId: string, normalizedValue: number): number {
      if (paramId === 'volume') return normalizedValue; // 0 to 1
      if (paramId === 'pan') return (normalizedValue * 2) - 1; // -1 to 1

      const paramName = paramId.split(':')[1];
      if (!paramName) return normalizedValue;

      if (paramName === 'frequency') {
          // Logarithmic mapping 20Hz -> 20kHz
          const min = 20;
          const max = 20000;
          // Math.pow(max/min, normalized) * min
          return min * Math.pow(max / min, normalizedValue);
      }
      if (paramName === 'mix') return normalizedValue;
      if (paramName === 'time') return normalizedValue * 1.0; 
      if (paramName === 'drive') return normalizedValue * 100;
      if (paramName === 'decay') return normalizedValue * 10;

      return normalizedValue;
  }

  private scheduleClips(
      ctx: BaseAudioContext, 
      clips: AudioClip[], 
      tracks: Track[], 
      transportStart: number, 
      now: number,
      anySolo: boolean,
      onNodeCreated: (clip: AudioClip, source: AudioBufferSourceNode, gain: GainNode, panner: StereoPannerNode) => void
  ) {
      clips.forEach(clip => {
          const track = tracks.find(t => t.id === clip.trackId);
          if (!track) return;

          const isAudible = anySolo ? track.soloed : !track.muted;

          const clipStartAbsolute = clip.startTime;
          let whenToPlay = now + (clipStartAbsolute - transportStart);
          let offset = clip.offset;

          // CRITICAL: use the timeline duration for playback stopping, but buffer logic for looping
          let playDuration = clip.duration; 

          if (whenToPlay < now) {
            const timePassed = now - whenToPlay;
            if (timePassed > playDuration && !clip.loop) return;

            // Adjust offset for start
            // Note: For looped clips, we need to mod the offset by buffer duration
            if (clip.loop) {
                 const bufferDur = clip.buffer.duration / clip.playbackRate;
                 offset = (offset + (timePassed * clip.playbackRate)) % clip.buffer.duration;
            } else {
                 offset += timePassed * clip.playbackRate;
            }

            playDuration -= timePassed;
            whenToPlay = now;
          }

          if (playDuration <= 0 && !clip.loop) return;

          const source = ctx.createBufferSource();
          source.buffer = clip.buffer;
          source.playbackRate.value = clip.playbackRate;
          source.loop = clip.loop;

          if (clip.loop) {
              source.loopStart = 0;
              source.loopEnd = clip.buffer.duration;
          }

          const clipGain = ctx.createGain();
          clipGain.gain.value = clip.gain;
          const clipPanner = ctx.createStereoPanner();
          clipPanner.pan.value = clip.pan;

          source.connect(clipPanner);
          clipPanner.connect(clipGain);

          if (clip.loop) {
              // Play indefinitely (looping) but stop exactly at clip duration end
              source.start(whenToPlay, offset);
              // Stop it when the timeline block ends
              source.stop(whenToPlay + playDuration);
          } else {
              if (playDuration > 0) source.start(whenToPlay, offset, playDuration * clip.playbackRate); // playDuration is in timeline time, start() duration arg is somewhat tricky with playbackRate, but usually safe to omit if not looping or rely on stop()
          }

          const nodes = this.trackNodes.get(track.id);
          if (nodes) {
              nodes.fader.gain.value = isAudible ? track.volume : 0;
          }

          onNodeCreated(clip, source, clipGain, clipPanner);
      });
  }

  public stop() {
    this.activeSources.forEach(({ source, gain, panner }) => {
      try {
        source.stop();
        source.disconnect();
        gain.disconnect();
        panner.disconnect();
      } catch (e) { }
    });
    this.activeSources.clear();

    // Stop Metronome
    this.metronomeNodes.forEach(node => {
        try {
            node.disconnect();
            if (node instanceof OscillatorNode) node.stop();
        } catch(e) {}
    });
    this.metronomeNodes = [];

    this.trackNodes.forEach(nodes => {
        nodes.fader.gain.cancelScheduledValues(this.context.currentTime);
        nodes.panner.pan.cancelScheduledValues(this.context.currentTime);
        nodes.pluginMap.forEach(node => {
            ['_frequency', '_mix', '_time', '_decay', '_dry'].forEach(p => {
                if (node[p]) (node[p] as AudioParam).cancelScheduledValues(this.context.currentTime);
            });
        });
    });
  }

  public stopPlayback() {
      this.stop();
  }

  // --- Export / Render ---

  public async renderOffline(clips: AudioClip[], tracks: Track[]): Promise<Blob> {
      const totalDuration = Math.max(...clips.map(c => c.startTime + c.duration)) + 1;
      const sampleRate = 44100;

      const offlineCtx = new OfflineAudioContext(2, totalDuration * sampleRate, sampleRate);

      const offlineTrackInputs = new Map<string, GainNode>();
      const offlineMasterFader = offlineCtx.createGain();
      offlineMasterFader.connect(offlineCtx.destination);

      const masterTrack = tracks.find(t => t.isMaster);
      offlineMasterFader.gain.value = masterTrack ? masterTrack.volume : 1.0;

      tracks.forEach(track => {
          if (track.isMaster) return;

          const input = offlineCtx.createGain();
          const panner = offlineCtx.createStereoPanner();
          const fader = offlineCtx.createGain();

          let prev: AudioNode = input;
          track.plugins.forEach(p => {
              if (p.enabled) {
                  const nodeOrGraph = this.createPluginNode(offlineCtx, p);
                  if (nodeOrGraph instanceof AudioNode) {
                    prev.connect(nodeOrGraph);
                    prev = nodeOrGraph;
                  } else {
                    prev.connect(nodeOrGraph.input);
                    prev = nodeOrGraph.output;
                  }
              }
          });

          prev.connect(panner);
          panner.connect(fader);
          fader.connect(offlineMasterFader);

          fader.gain.value = track.volume;

          offlineTrackInputs.set(track.id, input);
      });

      const anySolo = tracks.some(t => t.soloed);

      this.scheduleClips(offlineCtx, clips, tracks, 0, 0, anySolo, (clip, source, gain, panner) => {
          const input = offlineTrackInputs.get(clip.trackId);
          if (input) gain.connect(input);
      });

      const renderedBuffer = await offlineCtx.startRendering();
      return this.bufferToWav(renderedBuffer);
  }

  private bufferToWav(buffer: AudioBuffer): Blob {
      const numOfChan = buffer.numberOfChannels;
      const length = buffer.length * numOfChan * 2 + 44;
      const bufferArr = new ArrayBuffer(length);
      const view = new DataView(bufferArr);
      const channels = [];
      let i;
      let sample;
      let offset = 0;
      let pos = 0;

      setUint32(0x46464952); // "RIFF"
      setUint32(length - 8); // file length - 8
      setUint32(0x45564157); // "WAVE"

      setUint32(0x20746d66); // "fmt " chunk
      setUint32(16); // length = 16
      setUint16(1); // PCM
      setUint16(numOfChan);
      setUint32(buffer.sampleRate);
      setUint32(buffer.sampleRate * 2 * numOfChan); // avg. bytes/sec
      setUint16(numOfChan * 2); // block-align
      setUint16(16); // 16-bit

      setUint32(0x61746164); // "data"
      setUint32(length - pos - 4); // chunk length

      for(i = 0; i < buffer.numberOfChannels; i++)
        channels.push(buffer.getChannelData(i));

      while(pos < buffer.length) {
        for(i = 0; i < numOfChan; i++) {
          sample = Math.max(-1, Math.min(1, channels[i][pos])); 
          sample = (0.5 + sample < 0 ? sample * 32768 : sample * 32767)|0; 
          view.setInt16(44 + offset, sample, true);
          offset += 2;
        }
        pos++;
      }

      return new Blob([bufferArr], { type: "audio/wav" });

      function setUint16(data: any) {
        view.setUint16(pos, data, true);
        pos += 2;
      }
      function setUint32(data: any) {
        view.setUint32(pos, data, true);
        pos += 4;
      }
  }

  // --- Recording ---

  public async startRecording(): Promise<void> {
    try {
        // Reuse monitor stream if available to avoid hardware conflict
        let stream = this.monitorStream;

        if (!stream) {
            console.log("No monitor stream found, requesting new stream");
            this.recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
            stream = this.recordingStream;
        }

        this.mediaRecorder = new MediaRecorder(stream);
        this.recordingChunks = [];
        this.mediaRecorder.ondataavailable = (e) => {
            if (e.data.size > 0) this.recordingChunks.push(e.data);
        };
        this.mediaRecorder.start();
    } catch (err) {
        console.error("Error starting recording:", err);
        throw err;
    }
  }

  public async stopRecording(): Promise<Blob | null> {
    return new Promise((resolve) => {
        if (!this.mediaRecorder || this.mediaRecorder.state === 'inactive') {
            resolve(null);
            return;
        }
        this.mediaRecorder.onstop = () => {
            const blob = new Blob(this.recordingChunks, { type: 'audio/webm' });
            this.recordingChunks = [];

            // Only stop the stream if we created it locally (not monitoring)
            if (this.recordingStream) {
                this.recordingStream.getTracks().forEach(track => track.stop());
                this.recordingStream = null;
            }
            this.mediaRecorder = null;
            resolve(blob);
        };
        this.mediaRecorder.stop();
    });
  }

  // --- Analysis & Stem Splitting ---

  public async getAudioAnalysisInput(file: File): Promise<string> {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result as string);
        reader.onerror = reject;
        reader.readAsDataURL(file);
    });
  }

  public async separateStemsAdvanced(
    file: File, 
    instruments: string[], 
    onProgress: (msg: string) => void
  ): Promise<{name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[]> {
      onProgress("Decoding audio for processing...");
      const originalBuffer = await this.loadFile(file);

      const results: {name: string, type: PluginType, buffer: AudioBuffer, plugins: AudioPlugin[]}[] = [];

      for (const inst of instruments) {
          const lowerName = inst.toLowerCase();
          onProgress(`Extracting ${inst}...`);

          let buffer: AudioBuffer;
          let type: PluginType = 'LOWPASS'; 
          const plugins: AudioPlugin[] = [];

          if (lowerName.includes('bass')) {
             buffer = await this.renderFiltered(originalBuffer, 'LOW');
             type = 'LOWPASS';
          } else if (lowerName.includes('drum') || lowerName.includes('percussion')) {
             buffer = await this.renderFiltered(originalBuffer, 'DRUMS');
             type = 'DISTORTION'; // Just using as a placeholder for track type or similar
          } else if (lowerName.includes('vocal')) {
             buffer = await this.renderFiltered(originalBuffer, 'MID');
             type = 'REVERB';
             plugins.push({
                 id: Math.random().toString(36).substr(2, 9),
                 type: 'REVERB',
                 enabled: true,
                 params: { mix: 0.3, decay: 1.5, type: 0 }
             });
          } else {
             buffer = await this.renderFiltered(originalBuffer, 'HIGH');
             type = 'HIGHPASS';
          }

          results.push({
              name: inst,
              type: type,
              buffer: buffer,
              plugins: plugins
          });
      }

      return results;
  }

  private async renderFiltered(sourceBuffer: AudioBuffer, profile: 'LOW' | 'MID' | 'HIGH' | 'DRUMS'): Promise<AudioBuffer> {
        const length = sourceBuffer.length;
        const sampleRate = sourceBuffer.sampleRate;
        const offlineCtx = new OfflineAudioContext(sourceBuffer.numberOfChannels, length, sampleRate);

        const source = offlineCtx.createBufferSource();
        source.buffer = sourceBuffer;

        let head: AudioNode = source;

        if (profile === 'LOW') {
            const f = offlineCtx.createBiquadFilter();
            f.type = 'lowpass';
            f.frequency.value = 300;
            head.connect(f);
            head = f;
        } else if (profile === 'MID') {
            const hp = offlineCtx.createBiquadFilter();
            hp.type = 'highpass';
            hp.frequency.value = 300;
            const lp = offlineCtx.createBiquadFilter();
            lp.type = 'lowpass';
            lp.frequency.value = 5000;
            head.connect(hp);
            hp.connect(lp);
            head = lp;
        } else if (profile === 'HIGH') {
            const f = offlineCtx.createBiquadFilter();
            f.type = 'highpass';
            f.frequency.value = 5000;
            head.connect(f);
            head = f;
        } else if (profile === 'DRUMS') {
            // Scoop mids for drums
            const lows = offlineCtx.createBiquadFilter();
            lows.type = 'lowshelf';
            lows.frequency.value = 200;
            lows.gain.value = 4;

            const mids = offlineCtx.createBiquadFilter();
            mids.type = 'peaking';
            mids.frequency.value = 1000;
            mids.Q.value = 1;
            mids.gain.value = -6;

            const highs = offlineCtx.createBiquadFilter();
            highs.type = 'highshelf';
            highs.frequency.value = 6000;
            highs.gain.value = 3;

            head.connect(lows);
            lows.connect(mids);
            mids.connect(highs);
            head = highs;
        }

        head.connect(offlineCtx.destination);
        source.start();
        return await offlineCtx.startRendering();
  }
}

export const audioService = new AudioEngine();

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint, LoopRegion } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, Scissors, GripVertical, Upload, Youtube } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipUpdate: (id: string, newTime: number, newTrackId?: string) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;
  onDeleteClip: (id: string) => void;
  onDuplicateClip: (id: string) => void;
  onRenameClip: (id: string, newName: string) => void;

  onSelectClip: (id: string | null) => void;
  selectedClipId: string | null;
  onCopyClip: (id: string) => void;
  onPasteClip: (time: number, trackId: string) => void;
  canPaste: boolean;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;

  loopRegion: LoopRegion;
  setLoopRegion: (region: LoopRegion) => void;

  onImportAudio: (file: File, trackId: string, time: number) => void;
  onImportYoutube: (url: string, trackId: string, time: number) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND';
    targetId?: string; 
    time?: number; 
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipUpdate, 
  onFileDrop,
  onSeek,
  onDeleteClip,
  onDuplicateClip,
  onRenameClip,
  onSelectClip,
  selectedClipId,
  onCopyClip,
  onPasteClip,
  canPaste,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize,
  loopRegion,
  setLoopRegion,
  onImportAudio,
  onImportYoutube
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<number>(0);
  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  // Loop Dragging State
  const [loopDragType, setLoopDragType] = useState<'START' | 'END' | 'MOVE' | null>(null);
  const [loopDragStartX, setLoopDragStartX] = useState<number>(0);
  const [loopDragStartValues, setLoopDragStartValues] = useState<{start: number, end: number}>({start:0, end:0});

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // Ref for the hidden file input
  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      return Math.round(time / beat) * beat;
  };

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) setDraggedClipId(null);
           if (resizingClipId) setResizingClipId(null);
           if (loopDragType) setLoopDragType(null);
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId, loopDragType]);

  // Global Mouse Move
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;

          if (loopDragType) {
              const diffPixels = e.clientX - loopDragStartX;
              const diffSeconds = diffPixels / zoom;

              let newStart = loopDragStartValues.start;
              let newEnd = loopDragStartValues.end;

              if (loopDragType === 'START') {
                  newStart = Math.min(newEnd - 0.25, Math.max(0, loopDragStartValues.start + diffSeconds));
              } else if (loopDragType === 'END') {
                  newEnd = Math.max(newStart + 0.25, loopDragStartValues.end + diffSeconds);
              } else if (loopDragType === 'MOVE') {
                  const duration = loopDragStartValues.end - loopDragStartValues.start;
                  newStart = Math.max(0, loopDragStartValues.start + diffSeconds);
                  newEnd = newStart + duration;
              }

              if (snap) {
                  newStart = snapToGrid(newStart);
                  newEnd = snapToGrid(newEnd);
                  if (newEnd <= newStart) newEnd = newStart + secondsPerBeat;
              }

              setLoopRegion({ ...loopRegion, start: newStart, end: newEnd });
              return;
          }

          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); 
             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;
             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId || loopDragType) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize, loopDragType, loopDragStartX, loopDragStartValues, loopRegion, setLoopRegion, bpm]);

  // Wheel Zoom
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom));
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId || loopDragType) return;

    const target = e.target as HTMLElement;
    if (target.closest('.loop-region-handle')) return;

    const clipElement = target.closest('[data-clip-id]');

    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const clickX = e.clientX - rect.left;
                 const time = Math.max(0, clickX / zoom);

                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));
                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const clickX = e.clientX - rect.left;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        onSelectClip(null);
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;
        const clickX = e.clientX - rect.left;
        const seekTime = Math.max(0, (clickX / zoom));
        onSeek(snapToGrid(seekTime));
    }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const clickX = e.clientX - rect.left;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        if (file.type.startsWith('audio/')) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const adjustedTime = Math.max(0, (clickX / zoom) - dragOffset);
        onClipUpdate(draggedClipId, snapToGrid(adjustedTime), trackId);
        setDraggedClipId(null);
        setDragOffset(0);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }
     onSelectClip(clip.id);
     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     setDragOffset(offsetTime);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      onSelectClip(clip.id);
  };

  const handleLoopDragStart = (e: React.MouseEvent, type: 'START' | 'END' | 'MOVE') => {
      e.stopPropagation();
      e.preventDefault();
      setLoopDragType(type);
      setLoopDragStartX(e.clientX);
      setLoopDragStartValues({ start: loopRegion.start, end: loopRegion.end });
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      onSelectClip(clipId);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0);
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP' && contextMenu.targetId) {
           switch(action) {
              case 'delete': onDeleteClip(contextMenu.targetId); break;
              case 'duplicate': onDuplicateClip(contextMenu.targetId); break;
              case 'rename': 
                  const clip = clips.find(c => c.id === contextMenu.targetId);
                  if (clip) {
                      const newName = prompt("Rename clip:", clip.name);
                      if (newName) onRenameClip(contextMenu.targetId, newName);
                  }
                  break;
              case 'copy': onCopyClip(contextMenu.targetId); break;
              case 'loop': onLoopClip(contextMenu.targetId); break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClip(contextMenu.time, contextMenu.targetId);
           } else if (action === 'import-file') {
               if (fileInputRef.current) {
                   fileInputRef.current.click();
               }
           } else if (action === 'import-youtube') {
               const url = prompt("Enter YouTube URL (Experiment Feature):");
               if (url) {
                   onImportYoutube(url, contextMenu.targetId, contextMenu.time);
               }
           }
      }
      setContextMenu(null);
  };

  // Handle file selection from the hidden input
  const handleHiddenFileInputChange = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files.length > 0 && contextMenu && contextMenu.targetId && contextMenu.time !== undefined) {
          onImportAudio(e.target.files[0], contextMenu.targetId, contextMenu.time);
      }
      // Reset input so same file can be selected again if needed
      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];
      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);
      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ left: i * singleLoopWidth, width: singleLoopWidth }}
                 >
                     <Waveform clip={clip} width={singleLoopWidth} height={TRACK_HEIGHT - 10} color={i === 0 ? "#ffffff" : "#ffffffaa"} />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <>
      <div 
        className={`flex-1 relative flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
        ref={timelineRef}
        onClick={handleTimelineClick}
      >
        <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="audio/*"
            onChange={handleHiddenFileInputChange}
        />

        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler - Now with sticky top-0 to stick inside the App-level scroll container */}
        <div 
          className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex" 
          style={{ width: `${totalBars * pixelsPerBar}px`, height: `${TIMELINE_RULER_HEIGHT}px` }}
        >
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}

             {/* Loop Region Overlay */}
             {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 h-full bg-yellow-400/20 border-l border-r border-yellow-400/50 group loop-region-handle cursor-move"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                    onMouseDown={(e) => handleLoopDragStart(e, 'MOVE')}
                 >
                     <div className="absolute top-0 left-0 w-full h-1 bg-yellow-400/50"></div>

                     {/* Handles */}
                     <div 
                        className="absolute top-0 left-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'START')}
                     />
                     <div 
                        className="absolute top-0 right-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'END')}
                     />
                 </div>
             )}
        </div>

        <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
          {/* Loop Region Background Highlight (Extends down tracks) */}
          {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 bottom-0 bg-white/5 pointer-events-none z-0"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                 />
          )}

          {tracks.map(track => {
            return (
                <div key={track.id} className="flex flex-col z-10">
                  <div 
                      className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                      onDragOver={handleDragOver}
                      onDrop={(e) => handleDrop(e, track.id)}
                      onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                      style={{ 
                          height: `${TRACK_HEIGHT}px`,
                          backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                          backgroundSize: `${pixelsPerBar}px 100%`,
                          backgroundPosition: '0 0'
                      }}
                  >
                      <div 
                          className="absolute inset-0 pointer-events-none" 
                          style={{ backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)', backgroundSize: `${pixelsPerBeat}px 100%`, opacity: 0.1 }}
                      />

                      {clips.filter(c => c.trackId === track.id).map(clip => (
                      <div
                          key={clip.id}
                          data-clip-id={clip.id}
                          draggable={tool === 'MOVE'}
                          onDragStart={(e) => handleDragStart(e, clip)}
                          onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                          onClick={(e) => e.stopPropagation()} 
                          onMouseDown={(e) => { if (tool === 'MOVE') onSelectClip(clip.id); }}
                          className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                          ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                          ${selectedClipId === clip.id ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                          style={{ left: `${clip.startTime * zoom}px`, width: `${clip.duration * zoom}px` }}
                      >
                          <div className="absolute inset-0 opacity-60" style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}></div>
                          {clip.loop && <div className="absolute top-0 right-4 p-1 text-white/70 z-30"><RotateCw size={10} /></div>}
                          <div className="absolute inset-0 z-10">{renderClipContent(clip, track)}</div>
                          <div className="absolute top-1 left-1 z-20 max-w-full"><div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">{clip.name}</div></div>
                          {tool === 'MOVE' && <div className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle" onMouseDown={(e) => handleResizeStart(e, clip)}><GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" /></div>}
                      </div>
                      ))}
                  </div>

                  {track.showAutomation && (
                      <div 
                          className="bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair box-border"
                          data-automation-track-id={track.id}
                          style={{ minWidth: `${totalBars * pixelsPerBar}px`, height: `${AUTOMATION_HEIGHT}px` }}
                      >
                          <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                          <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">{track.selectedAutomationId === 'pan' ? 'Pan' : track.selectedAutomationId === 'volume' ? 'Vol' : track.selectedAutomationId?.split(':')[1].toUpperCase()}</div>
                          <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>{renderAutomationPoints(track)}</svg>
                      </div>
                  )}
                </div>
            );
          })}
          <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">End of tracks</div>
        </div>

        {contextMenu && (
            <div 
                className="fixed z-50 w-56 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
                style={{ top: contextMenu.y, left: contextMenu.x }}
            >
                {contextMenu.type === 'CLIP' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Copy</button>
                      <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><RotateCw size={14} /> Toggle Loop</button>
                      <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Pencil size={14} /> Rename</button>
                      <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Duplicate</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2"><Trash2 size={14} /> Delete</button>
                    </>
                ) : (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'paste')} disabled={!canPaste} className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}><ClipboardPaste size={14} /> Paste</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'import-file')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Upload size={14} className="text-blue-400" /> Import Audio File</button>
                      <button onClick={(e) => handleMenuAction(e, 'import-youtube')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Youtube size={14} className="text-red-500" /> Import from YouTube</button>
                    </>
                )}
            </div>
        )}
      </div>
    </>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { MasterVisualizer } from './components/MasterVisualizer';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, LoopRegion } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);

  // Metronome State
  const [isMetronomeOn, setIsMetronomeOn] = useState(false);
  const [countInMeasures, setCountInMeasures] = useState(1);

  // Loop State (Default measures 1-4 -> 0s to 8s at 120bpm)
  const [loopRegion, setLoopRegion] = useState<LoopRegion>({ start: 0, end: 8, enabled: false });
  // Ref for loop region to access in RAF without re-binding
  const loopRegionRef = useRef(loopRegion);

  useEffect(() => {
      loopRegionRef.current = loopRegion;
  }, [loopRegion]);

  // Recording State
  const [armedTrackId, setArmedTrackId] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Refs ---
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const navigatorRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Navigator Scroll Sync ---
  const handleMainScroll = () => {
      if (scrollContainerRef.current && navigatorRef.current) {
          navigatorRef.current.scrollLeft = scrollContainerRef.current.scrollLeft;
      }
  };

  const handleNavigatorScroll = (e: React.UIEvent<HTMLDivElement>) => {
      const target = e.target as HTMLDivElement;
      if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollLeft = target.scrollLeft;
      }
  };

  // --- Undo/Redo System ---
  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks);
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex - 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks);
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };

  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stopPlayback(); 
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    // Schedule metronome if enabled
    if (isMetronomeOn) {
        audioService.scheduleMetronome(bpm, audioService.getContext().currentTime, 300); // Schedule 5 mins of clicks
    }

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true, currentTime: startAt }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      // Loop Check using REF to avoid closure staleness
      if (loopRegionRef.current.enabled && newTime >= loopRegionRef.current.end) {
          startPlayback(loopRegionRef.current.start);
          return; 
      }

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks, bpm, isMetronomeOn]); 

  const handleSeek = useCallback((time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));

      // If playing, we need to restart playback at new position
      if (playbackState.isPlaying) {
           startPlayback(time);
      }
  }, [playbackState.isPlaying, startPlayback]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (isRecording) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [isRecording]);

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---
  const handleArmTrack = async (trackId: string) => {
      if (armedTrackId === trackId) {
          setArmedTrackId(null);
          audioService.disableMonitoring();
      } else {
          try {
              // Critical: Await monitoring setup BEFORE updating state to ensure visualizer is ready
              await audioService.enableMonitoring(trackId); 
              setArmedTrackId(trackId);
          } catch(e) {
              alert("Could not access microphone.");
              setArmedTrackId(null);
          }
      }
  };

  const handleTransportRecord = async () => {
      if (isRecording) {
          handleStop();
      } else {
          if (!armedTrackId) {
              alert("Please arm a track first.");
              return;
          }
          try {
            await audioService.resume();

            // Count-In Logic
            if (countInMeasures > 0) {
                 await audioService.playCountIn(bpm, countInMeasures);
            }

            // Await the recording start! This ensures permissions are granted and stream is active before UI updates
            await audioService.startRecording();

            setIsRecording(true);
            recordStartTimeRef.current = pauseTimeRef.current;
            startPlayback(pauseTimeRef.current);
          } catch(e) {
              console.error("Recording failed to start", e);
              alert("Failed to start recording. Please check microphone permissions.");
          }
      }
  };

  const finishRecording = async () => {
      if (!armedTrackId) {
          setIsRecording(false);
          return;
      }
      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;
      if (blob && blob.size > 0) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: armedTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }
      setIsRecording(false);
  };

  // --- Track Management ---
  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) points[existingIdx] = point;
             else points.push(point);
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---
  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  const handleImportAudio = (file: File, trackId: string, time: number) => {
      handleFileDrop(file, trackId, time);
  };

  const handleImportYoutube = async (url: string, trackId: string, time: number) => {
      // In a real production app, this would hit a backend API to download the video.
      // Since this is a frontend-only environment, we will fetch a sample "demo" loop
      // to demonstrate functionality and provide a good user experience.
      try {
          alert("Note: Actual YouTube downloading requires a backend server. Importing a demo loop instead to demonstrate functionality.");
          const response = await fetch('https://cdn.pixabay.com/download/audio/2022/03/15/audio_c8c8a73467.mp3?filename=funky-beat-113978.mp3');
          const blob = await response.blob();
          const file = new File([blob], `YouTube_Import_${Date.now()}.mp3`, { type: 'audio/mp3' });
          handleFileDrop(file, trackId, time);
      } catch (e) {
          console.error("Failed to import youtube demo", e);
          alert("Failed to import.");
      }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => c.id === id ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } : c);
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;
      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return;

      const firstDuration = relativeSplit * clip.playbackRate;
      const leftClip: AudioClip = { ...clip, id: uuidv4(), duration: firstDuration, name: clip.name };
      const rightClip: AudioClip = { ...clip, id: uuidv4(), startTime: splitTime, offset: clip.offset + firstDuration, duration: clip.duration - firstDuration, name: clip.name };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);
      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;
          const newClips = clips.map(c => c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---
  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  // --- Derived State & Variables ---
  const regularTracks = tracks.filter(t => !t.isMaster);
  const masterTrack = tracks.find(t => t.isMaster) || MASTER_TRACK;
  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration));
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const pixelsPerBar = secondsPerBar * zoom;
  const timelineWidth = totalBars * pixelsPerBar;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        isRecording={isRecording}
        onRecord={handleTransportRecord}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}
        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
        loopRegion={loopRegion}
        setLoopRegion={setLoopRegion}
        isMetronomeOn={isMetronomeOn}
        toggleMetronome={() => setIsMetronomeOn(!isMetronomeOn)}
        countInMeasures={countInMeasures}
        setCountInMeasures={setCountInMeasures}
      />

      {/* Main Workspace: Single Unified Scroll Container */}
      <div 
        className="flex-1 overflow-auto relative" 
        ref={scrollContainerRef}
        onScroll={handleMainScroll}
      >
        <div className="flex min-w-max">
            {/* Sticky Left Column (Headers) */}
            <div 
                className="sticky left-0 z-30 bg-gray-900 border-r border-gray-700 flex flex-col flex-shrink-0 shadow-lg"
                style={{ width: TRACK_HEADER_WIDTH }}
            >
                 {/* Sticky Top-Left Corner */}
                 <div 
                    className="sticky top-0 z-40 bg-gray-900 border-b border-gray-700 flex-shrink-0"
                    style={{ height: TIMELINE_RULER_HEIGHT }}
                 />

                 {/* Track Headers List */}
                 {regularTracks.map(track => (
                    <TrackControl 
                        key={track.id} 
                        track={track} 
                        onUpdate={updateTrack}
                        onDelete={deleteTrack}
                        isArmed={armedTrackId === track.id}
                        isRecordingGlobal={isRecording}
                        onArmToggle={() => handleArmTrack(track.id)}
                        onOpenEditor={setEditingTrackId}
                        onToggleAutomation={toggleAutomation}
                    />
                 ))}

                 <div className="p-3">
                     <button 
                        onClick={addTrack}
                        className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                        title="Add a new audio track"
                     >
                        <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors"><Plus size={14} /></div>
                        <span>Add Track</span>
                     </button>
                 </div>

                 {/* Bottom Spacer */}
                 <div className="h-64 bg-gray-900" />
            </div>

            {/* Main Timeline Area (Scrolls with parent) */}
            <div className="flex flex-col flex-1">
                {/* Timeline Component - renders Ruler (sticky inside) and Tracks */}
                <Timeline 
                    tracks={regularTracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipUpdate={updateClip}
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={setZoom}
                    snap={snap}
                    tool={tool}
                    onDeleteClip={deleteClip}
                    onDuplicateClip={duplicateClip}
                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}
                    onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
                    selectedClipId={selectedClipId}
                    onCopyClip={handleCopyClip}
                    onPasteClip={handlePasteClip}
                    canPaste={!!clipboardClip}
                    onLoopClip={handleLoopToggle}
                    onClipResize={handleClipResize}
                    loopRegion={loopRegion}
                    setLoopRegion={setLoopRegion}
                    onImportAudio={handleImportAudio}
                    onImportYoutube={handleImportYoutube}
                />
            </div>
        </div>
      </div>

      {/* Fixed Bottom Master Section */}
      <div className="h-44 bg-gray-900 border-t-2 border-gray-800 flex flex-col z-50 shadow-[0_-5px_15px_rgba(0,0,0,0.5)]">
         {/* Master Row */}
         <div className="flex flex-1 overflow-hidden">
             {/* Master Control (Left) */}
             <div className="flex-shrink-0 border-r border-gray-800" style={{ width: TRACK_HEADER_WIDTH }}>
                <TrackControl 
                  track={masterTrack}
                  onUpdate={updateTrack}
                  onDelete={() => {}}
                  isArmed={false}
                  isRecordingGlobal={false}
                  onArmToggle={() => {}}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={() => {}}
                />
             </div>
             {/* Master Visualizer (Right) */}
             <div className="flex-1 p-2 bg-gray-900 flex items-center justify-center">
                 <MasterVisualizer isPlaying={playbackState.isPlaying} />
             </div>
         </div>

         {/* Navigator / Scrollbar (Bottom Fixed) */}
         <div className="h-5 bg-gray-950 border-t border-gray-800">
             <div 
                ref={navigatorRef}
                onScroll={handleNavigatorScroll}
                className="w-full h-full overflow-x-auto overflow-y-hidden custom-scrollbar"
                title="Timeline Navigator"
             >
                <div style={{ width: timelineWidth + TRACK_HEADER_WIDTH, height: '1px' }}></div>
             </div>
         </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint, LoopRegion } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, Scissors, GripVertical, Upload, Youtube } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipUpdate: (id: string, newTime: number, newTrackId?: string) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;
  onDeleteClip: (id: string) => void;
  onDuplicateClip: (id: string) => void;
  onRenameClip: (id: string, newName: string) => void;

  onSelectClip: (id: string | null) => void;
  selectedClipId: string | null;
  onCopyClip: (id: string) => void;
  onPasteClip: (time: number, trackId: string) => void;
  canPaste: boolean;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;

  loopRegion: LoopRegion;
  setLoopRegion: (region: LoopRegion) => void;

  onImportAudio: (file: File, trackId: string, time: number) => void;
  onImportYoutube: (url: string, trackId: string, time: number) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND';
    targetId?: string; 
    time?: number; 
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipUpdate, 
  onFileDrop,
  onSeek,
  onDeleteClip,
  onDuplicateClip,
  onRenameClip,
  onSelectClip,
  selectedClipId,
  onCopyClip,
  onPasteClip,
  canPaste,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize,
  loopRegion,
  setLoopRegion,
  onImportAudio,
  onImportYoutube
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<number>(0);
  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  // Loop Dragging State
  const [loopDragType, setLoopDragType] = useState<'START' | 'END' | 'MOVE' | null>(null);
  const [loopDragStartX, setLoopDragStartX] = useState<number>(0);
  const [loopDragStartValues, setLoopDragStartValues] = useState<{start: number, end: number}>({start:0, end:0});

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // Refs for File Import
  const fileInputRef = useRef<HTMLInputElement>(null);
  const importTargetRef = useRef<{trackId: string, time: number} | null>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      return Math.round(time / beat) * beat;
  };

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) setDraggedClipId(null);
           if (resizingClipId) setResizingClipId(null);
           if (loopDragType) setLoopDragType(null);
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId, loopDragType]);

  // Global Mouse Move
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;

          if (loopDragType) {
              const diffPixels = e.clientX - loopDragStartX;
              const diffSeconds = diffPixels / zoom;

              let newStart = loopDragStartValues.start;
              let newEnd = loopDragStartValues.end;

              if (loopDragType === 'START') {
                  newStart = Math.min(newEnd - 0.25, Math.max(0, loopDragStartValues.start + diffSeconds));
              } else if (loopDragType === 'END') {
                  newEnd = Math.max(newStart + 0.25, loopDragStartValues.end + diffSeconds);
              } else if (loopDragType === 'MOVE') {
                  const duration = loopDragStartValues.end - loopDragStartValues.start;
                  newStart = Math.max(0, loopDragStartValues.start + diffSeconds);
                  newEnd = newStart + duration;
              }

              if (snap) {
                  newStart = snapToGrid(newStart);
                  newEnd = snapToGrid(newEnd);
                  if (newEnd <= newStart) newEnd = newStart + secondsPerBeat;
              }

              setLoopRegion({ ...loopRegion, start: newStart, end: newEnd });
              return;
          }

          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); 
             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;
             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId || loopDragType) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize, loopDragType, loopDragStartX, loopDragStartValues, loopRegion, setLoopRegion, bpm]);

  // Wheel Zoom
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom));
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId || loopDragType) return;

    const target = e.target as HTMLElement;
    if (target.closest('.loop-region-handle')) return;

    const clipElement = target.closest('[data-clip-id]');

    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const clickX = e.clientX - rect.left;
                 const time = Math.max(0, clickX / zoom);

                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));
                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const clickX = e.clientX - rect.left;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        onSelectClip(null);
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;
        const clickX = e.clientX - rect.left;
        const seekTime = Math.max(0, (clickX / zoom));
        onSeek(snapToGrid(seekTime));
    }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const clickX = e.clientX - rect.left;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        if (file.type.startsWith('audio/')) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const adjustedTime = Math.max(0, (clickX / zoom) - dragOffset);
        onClipUpdate(draggedClipId, snapToGrid(adjustedTime), trackId);
        setDraggedClipId(null);
        setDragOffset(0);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }
     onSelectClip(clip.id);
     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     setDragOffset(offsetTime);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      onSelectClip(clip.id);
  };

  const handleLoopDragStart = (e: React.MouseEvent, type: 'START' | 'END' | 'MOVE') => {
      e.stopPropagation();
      e.preventDefault();
      setLoopDragType(type);
      setLoopDragStartX(e.clientX);
      setLoopDragStartValues({ start: loopRegion.start, end: loopRegion.end });
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      onSelectClip(clipId);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0);
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP' && contextMenu.targetId) {
           switch(action) {
              case 'delete': onDeleteClip(contextMenu.targetId); break;
              case 'duplicate': onDuplicateClip(contextMenu.targetId); break;
              case 'rename': 
                  const clip = clips.find(c => c.id === contextMenu.targetId);
                  if (clip) {
                      const newName = prompt("Rename clip:", clip.name);
                      if (newName) onRenameClip(contextMenu.targetId, newName);
                  }
                  break;
              case 'copy': onCopyClip(contextMenu.targetId); break;
              case 'loop': onLoopClip(contextMenu.targetId); break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClip(contextMenu.time, contextMenu.targetId);
           } else if (action === 'import-file') {
               // CRITICAL: Persist target info to ref because contextMenu will be nullified
               importTargetRef.current = { trackId: contextMenu.targetId, time: contextMenu.time };
               fileInputRef.current?.click();
           } else if (action === 'import-youtube') {
               const url = prompt("Enter YouTube URL:");
               if (url) {
                   onImportYoutube(url, contextMenu.targetId, contextMenu.time);
               }
           }
      }
      setContextMenu(null);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0] && importTargetRef.current) {
          const { trackId, time } = importTargetRef.current;
          onImportAudio(e.target.files[0], trackId, time);
      }
      // Reset input value so the same file can be selected again
      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];
      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);
      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ left: i * singleLoopWidth, width: singleLoopWidth }}
                 >
                     <Waveform clip={clip} width={singleLoopWidth} height={TRACK_HEIGHT - 10} color={i === 0 ? "#ffffff" : "#ffffffaa"} />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <>
      <div 
        className={`flex-1 relative flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
        ref={timelineRef}
        onClick={handleTimelineClick}
      >
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileSelect}
            className="hidden" 
            accept="audio/*" 
        />

        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler - Now with sticky top-0 to stick inside the App-level scroll container */}
        <div 
          className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex" 
          style={{ width: `${totalBars * pixelsPerBar}px`, height: `${TIMELINE_RULER_HEIGHT}px` }}
        >
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}

             {/* Loop Region Overlay */}
             {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 h-full bg-yellow-400/20 border-l border-r border-yellow-400/50 group loop-region-handle cursor-move"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                    onMouseDown={(e) => handleLoopDragStart(e, 'MOVE')}
                 >
                     <div className="absolute top-0 left-0 w-full h-1 bg-yellow-400/50"></div>

                     {/* Handles */}
                     <div 
                        className="absolute top-0 left-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'START')}
                     />
                     <div 
                        className="absolute top-0 right-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'END')}
                     />
                 </div>
             )}
        </div>

        <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
          {/* Loop Region Background Highlight (Extends down tracks) */}
          {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 bottom-0 bg-white/5 pointer-events-none z-0"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                 />
          )}

          {tracks.map(track => {
            return (
                <div key={track.id} className="flex flex-col z-10">
                  <div 
                      className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                      onDragOver={handleDragOver}
                      onDrop={(e) => handleDrop(e, track.id)}
                      onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                      style={{ 
                          height: `${TRACK_HEIGHT}px`,
                          backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                          backgroundSize: `${pixelsPerBar}px 100%`,
                          backgroundPosition: '0 0'
                      }}
                  >
                      <div 
                          className="absolute inset-0 pointer-events-none" 
                          style={{ backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)', backgroundSize: `${pixelsPerBeat}px 100%`, opacity: 0.1 }}
                      />

                      {clips.filter(c => c.trackId === track.id).map(clip => (
                      <div
                          key={clip.id}
                          data-clip-id={clip.id}
                          draggable={tool === 'MOVE'}
                          onDragStart={(e) => handleDragStart(e, clip)}
                          onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                          onClick={(e) => e.stopPropagation()} 
                          onMouseDown={(e) => { if (tool === 'MOVE') onSelectClip(clip.id); }}
                          className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                          ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                          ${selectedClipId === clip.id ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                          style={{ left: `${clip.startTime * zoom}px`, width: `${clip.duration * zoom}px` }}
                      >
                          <div className="absolute inset-0 opacity-60" style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}></div>
                          {clip.loop && <div className="absolute top-0 right-4 p-1 text-white/70 z-30"><RotateCw size={10} /></div>}
                          <div className="absolute inset-0 z-10">{renderClipContent(clip, track)}</div>
                          <div className="absolute top-1 left-1 z-20 max-w-full"><div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">{clip.name}</div></div>
                          {tool === 'MOVE' && <div className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle" onMouseDown={(e) => handleResizeStart(e, clip)}><GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" /></div>}
                      </div>
                      ))}
                  </div>

                  {track.showAutomation && (
                      <div 
                          className="bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair box-border"
                          data-automation-track-id={track.id}
                          style={{ minWidth: `${totalBars * pixelsPerBar}px`, height: `${AUTOMATION_HEIGHT}px` }}
                      >
                          <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                          <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">{track.selectedAutomationId === 'pan' ? 'Pan' : track.selectedAutomationId === 'volume' ? 'Vol' : track.selectedAutomationId?.split(':')[1].toUpperCase()}</div>
                          <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>{renderAutomationPoints(track)}</svg>
                      </div>
                  )}
                </div>
            );
          })}
          <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">End of tracks</div>
        </div>

        {contextMenu && (
            <div 
                className="fixed z-50 w-56 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
                style={{ top: contextMenu.y, left: contextMenu.x }}
            >
                {contextMenu.type === 'CLIP' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Copy</button>
                      <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><RotateCw size={14} /> Toggle Loop</button>
                      <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Pencil size={14} /> Rename</button>
                      <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Duplicate</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2"><Trash2 size={14} /> Delete</button>
                    </>
                ) : (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'paste')} disabled={!canPaste} className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}><ClipboardPaste size={14} /> Paste</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'import-file')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Upload size={14} className="text-blue-400" /> Import Audio File</button>
                      <button onClick={(e) => handleMenuAction(e, 'import-youtube')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Youtube size={14} className="text-red-500" /> Import from YouTube</button>
                    </>
                )}
            </div>
        )}
      </div>
    </>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { MasterVisualizer } from './components/MasterVisualizer';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, LoopRegion } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);

  // Metronome State
  const [isMetronomeOn, setIsMetronomeOn] = useState(false);
  const [countInMeasures, setCountInMeasures] = useState(1);

  // Loop State (Default measures 1-4 -> 0s to 8s at 120bpm)
  const [loopRegion, setLoopRegion] = useState<LoopRegion>({ start: 0, end: 8, enabled: false });
  // Ref for loop region to access in RAF without re-binding
  const loopRegionRef = useRef(loopRegion);

  useEffect(() => {
      loopRegionRef.current = loopRegion;
  }, [loopRegion]);

  // Recording State
  const [armedTrackId, setArmedTrackId] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Refs ---
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const navigatorRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Navigator Scroll Sync ---
  const handleMainScroll = () => {
      if (scrollContainerRef.current && navigatorRef.current) {
          navigatorRef.current.scrollLeft = scrollContainerRef.current.scrollLeft;
      }
  };

  const handleNavigatorScroll = (e: React.UIEvent<HTMLDivElement>) => {
      const target = e.target as HTMLDivElement;
      if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollLeft = target.scrollLeft;
      }
  };

  // --- Undo/Redo System ---
  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks);
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex - 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks);
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };

  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stopPlayback(); 
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    // Schedule metronome if enabled
    if (isMetronomeOn) {
        audioService.scheduleMetronome(bpm, audioService.getContext().currentTime, 300); // Schedule 5 mins of clicks
    }

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true, currentTime: startAt }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      // Loop Check using REF to avoid closure staleness
      if (loopRegionRef.current.enabled && newTime >= loopRegionRef.current.end) {
          startPlayback(loopRegionRef.current.start);
          return; 
      }

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks, bpm, isMetronomeOn]); 

  const handleSeek = useCallback((time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));

      // If playing, we need to restart playback at new position
      if (playbackState.isPlaying) {
           startPlayback(time);
      }
  }, [playbackState.isPlaying, startPlayback]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (isRecording) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [isRecording]);

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---
  const handleArmTrack = async (trackId: string) => {
      if (armedTrackId === trackId) {
          setArmedTrackId(null);
          audioService.disableMonitoring();
      } else {
          try {
              // Critical: Await monitoring setup BEFORE updating state to ensure visualizer is ready
              await audioService.enableMonitoring(trackId); 
              setArmedTrackId(trackId);
          } catch(e) {
              alert("Could not access microphone.");
              setArmedTrackId(null);
          }
      }
  };

  const handleTransportRecord = async () => {
      if (isRecording) {
          handleStop();
      } else {
          if (!armedTrackId) {
              alert("Please arm a track first.");
              return;
          }
          try {
            await audioService.resume();

            // Count-In Logic
            if (countInMeasures > 0) {
                 await audioService.playCountIn(bpm, countInMeasures);
            }

            // Await the recording start! This ensures permissions are granted and stream is active before UI updates
            await audioService.startRecording();

            setIsRecording(true);
            recordStartTimeRef.current = pauseTimeRef.current;
            startPlayback(pauseTimeRef.current);
          } catch(e) {
              console.error("Recording failed to start", e);
              alert("Failed to start recording. Please check microphone permissions.");
          }
      }
  };

  const finishRecording = async () => {
      if (!armedTrackId) {
          setIsRecording(false);
          return;
      }
      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;
      if (blob && blob.size > 0) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: armedTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }
      setIsRecording(false);
  };

  // --- Track Management ---
  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) points[existingIdx] = point;
             else points.push(point);
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---
  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  // Context Menu Helpers
  const handleImportAudio = (file: File, trackId: string, time: number) => {
      handleFileDrop(file, trackId, time);
  };

  const handleImportYoutube = async (url: string, trackId: string, time: number) => {
      // In a real production app, this would hit a backend API to download the video.
      // Since this is a frontend-only environment, we will fetch a sample "demo" loop
      // to demonstrate functionality and provide a good user experience.
      try {
          alert("Note: Actual YouTube downloading requires a backend server. Importing a demo loop instead to demonstrate functionality.");
          const response = await fetch('https://cdn.pixabay.com/download/audio/2022/03/15/audio_c8c8a73467.mp3?filename=funky-beat-113978.mp3');
          const blob = await response.blob();
          const file = new File([blob], `YouTube_Import_${Date.now()}.mp3`, { type: 'audio/mp3' });
          handleFileDrop(file, trackId, time);
      } catch (e) {
          console.error("Failed to import youtube demo", e);
          alert("Failed to import.");
      }
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => c.id === id ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } : c);
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;
      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return;

      const firstDuration = relativeSplit * clip.playbackRate;
      const leftClip: AudioClip = { ...clip, id: uuidv4(), duration: firstDuration, name: clip.name };
      const rightClip: AudioClip = { ...clip, id: uuidv4(), startTime: splitTime, offset: clip.offset + firstDuration, duration: clip.duration - firstDuration, name: clip.name };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);
      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;
          const newClips = clips.map(c => c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---
  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  // --- Derived State & Variables ---
  const regularTracks = tracks.filter(t => !t.isMaster);
  const masterTrack = tracks.find(t => t.isMaster) || MASTER_TRACK;
  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration));
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const pixelsPerBar = secondsPerBar * zoom;
  const timelineWidth = totalBars * pixelsPerBar;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        isRecording={isRecording}
        onRecord={handleTransportRecord}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}
        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
        loopRegion={loopRegion}
        setLoopRegion={setLoopRegion}
        isMetronomeOn={isMetronomeOn}
        toggleMetronome={() => setIsMetronomeOn(!isMetronomeOn)}
        countInMeasures={countInMeasures}
        setCountInMeasures={setCountInMeasures}
      />

      {/* Main Workspace: Single Unified Scroll Container */}
      <div 
        className="flex-1 overflow-auto relative" 
        ref={scrollContainerRef}
        onScroll={handleMainScroll}
      >
        <div className="flex min-w-max">
            {/* Sticky Left Column (Headers) */}
            <div 
                className="sticky left-0 z-30 bg-gray-900 border-r border-gray-700 flex flex-col flex-shrink-0 shadow-lg"
                style={{ width: TRACK_HEADER_WIDTH }}
            >
                 {/* Sticky Top-Left Corner */}
                 <div 
                    className="sticky top-0 z-40 bg-gray-900 border-b border-gray-700 flex-shrink-0"
                    style={{ height: TIMELINE_RULER_HEIGHT }}
                 />

                 {/* Track Headers List */}
                 {regularTracks.map(track => (
                    <TrackControl 
                        key={track.id} 
                        track={track} 
                        onUpdate={updateTrack}
                        onDelete={deleteTrack}
                        isArmed={armedTrackId === track.id}
                        isRecordingGlobal={isRecording}
                        onArmToggle={() => handleArmTrack(track.id)}
                        onOpenEditor={setEditingTrackId}
                        onToggleAutomation={toggleAutomation}
                    />
                 ))}

                 <div className="p-3">
                     <button 
                        onClick={addTrack}
                        className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                        title="Add a new audio track"
                     >
                        <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors"><Plus size={14} /></div>
                        <span>Add Track</span>
                     </button>
                 </div>

                 {/* Bottom Spacer */}
                 <div className="h-64 bg-gray-900" />
            </div>

            {/* Main Timeline Area (Scrolls with parent) */}
            <div className="flex flex-col flex-1">
                {/* Timeline Component - renders Ruler (sticky inside) and Tracks */}
                <Timeline 
                    tracks={regularTracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipUpdate={updateClip}
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={setZoom}
                    snap={snap}
                    tool={tool}
                    onDeleteClip={deleteClip}
                    onDuplicateClip={duplicateClip}
                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}
                    onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
                    selectedClipId={selectedClipId}
                    onCopyClip={handleCopyClip}
                    onPasteClip={handlePasteClip}
                    canPaste={!!clipboardClip}
                    onLoopClip={handleLoopToggle}
                    onClipResize={handleClipResize}
                    loopRegion={loopRegion}
                    setLoopRegion={setLoopRegion}
                    onImportAudio={handleImportAudio}
                    onImportYoutube={handleImportYoutube}
                />
            </div>
        </div>
      </div>

      {/* Fixed Bottom Master Section */}
      <div className="h-44 bg-gray-900 border-t-2 border-gray-800 flex flex-col z-50 shadow-[0_-5px_15px_rgba(0,0,0,0.5)]">
         {/* Master Row */}
         <div className="flex flex-1 overflow-hidden">
             {/* Master Control (Left) */}
             <div className="flex-shrink-0 border-r border-gray-800" style={{ width: TRACK_HEADER_WIDTH }}>
                <TrackControl 
                  track={masterTrack}
                  onUpdate={updateTrack}
                  onDelete={() => {}}
                  isArmed={false}
                  isRecordingGlobal={false}
                  onArmToggle={() => {}}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={() => {}}
                />
             </div>
             {/* Master Visualizer (Right) */}
             <div className="flex-1 p-2 bg-gray-900 flex items-center justify-center">
                 <MasterVisualizer isPlaying={playbackState.isPlaying} />
             </div>
         </div>

         {/* Navigator / Scrollbar (Bottom Fixed) */}
         <div className="h-5 bg-gray-950 border-t border-gray-800">
             <div 
                ref={navigatorRef}
                onScroll={handleNavigatorScroll}
                className="w-full h-full overflow-x-auto overflow-y-hidden custom-scrollbar"
                title="Timeline Navigator"
             >
                <div style={{ width: timelineWidth + TRACK_HEADER_WIDTH, height: '1px' }}></div>
             </div>
         </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint, LoopRegion } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, GripVertical, Upload } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipUpdate: (id: string, newTime: number, newTrackId?: string) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;
  onDeleteClip: (id: string) => void;
  onDuplicateClip: (id: string) => void;
  onRenameClip: (id: string, newName: string) => void;

  onSelectClip: (id: string | null) => void;
  selectedClipId: string | null;
  onCopyClip: (id: string) => void;
  onPasteClip: (time: number, trackId: string) => void;
  canPaste: boolean;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;

  loopRegion: LoopRegion;
  setLoopRegion: (region: LoopRegion) => void;

  onImportAudio: (file: File, trackId: string, time: number) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND';
    targetId?: string; 
    time?: number; 
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipUpdate, 
  onFileDrop,
  onSeek,
  onDeleteClip,
  onDuplicateClip,
  onRenameClip,
  onSelectClip,
  selectedClipId,
  onCopyClip,
  onPasteClip,
  canPaste,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize,
  loopRegion,
  setLoopRegion,
  onImportAudio
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  const [dragOffset, setDragOffset] = useState<number>(0);
  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  // Loop Dragging State
  const [loopDragType, setLoopDragType] = useState<'START' | 'END' | 'MOVE' | null>(null);
  const [loopDragStartX, setLoopDragStartX] = useState<number>(0);
  const [loopDragStartValues, setLoopDragStartValues] = useState<{start: number, end: number}>({start:0, end:0});

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // Refs for File Import
  const fileInputRef = useRef<HTMLInputElement>(null);
  const importTargetRef = useRef<{trackId: string, time: number} | null>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      return Math.round(time / beat) * beat;
  };

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) setDraggedClipId(null);
           if (resizingClipId) setResizingClipId(null);
           if (loopDragType) setLoopDragType(null);
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId, loopDragType]);

  // Global Mouse Move
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;

          if (loopDragType) {
              const diffPixels = e.clientX - loopDragStartX;
              const diffSeconds = diffPixels / zoom;

              let newStart = loopDragStartValues.start;
              let newEnd = loopDragStartValues.end;

              if (loopDragType === 'START') {
                  newStart = Math.min(newEnd - 0.25, Math.max(0, loopDragStartValues.start + diffSeconds));
              } else if (loopDragType === 'END') {
                  newEnd = Math.max(newStart + 0.25, loopDragStartValues.end + diffSeconds);
              } else if (loopDragType === 'MOVE') {
                  const duration = loopDragStartValues.end - loopDragStartValues.start;
                  newStart = Math.max(0, loopDragStartValues.start + diffSeconds);
                  newEnd = newStart + duration;
              }

              if (snap) {
                  newStart = snapToGrid(newStart);
                  newEnd = snapToGrid(newEnd);
                  if (newEnd <= newStart) newEnd = newStart + secondsPerBeat;
              }

              setLoopRegion({ ...loopRegion, start: newStart, end: newEnd });
              return;
          }

          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); 
             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;
             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId || loopDragType) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize, loopDragType, loopDragStartX, loopDragStartValues, loopRegion, setLoopRegion, bpm]);

  // Wheel Zoom
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom));
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId || loopDragType) return;

    const target = e.target as HTMLElement;
    if (target.closest('.loop-region-handle')) return;

    const clipElement = target.closest('[data-clip-id]');

    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const clickX = e.clientX - rect.left;
                 const time = Math.max(0, clickX / zoom);

                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));
                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const clickX = e.clientX - rect.left;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        onSelectClip(null);
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;
        const clickX = e.clientX - rect.left;
        const seekTime = Math.max(0, (clickX / zoom));
        onSeek(snapToGrid(seekTime));
    }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const clickX = e.clientX - rect.left;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        if (file.type.startsWith('audio/')) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const adjustedTime = Math.max(0, (clickX / zoom) - dragOffset);
        onClipUpdate(draggedClipId, snapToGrid(adjustedTime), trackId);
        setDraggedClipId(null);
        setDragOffset(0);
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }
     onSelectClip(clip.id);
     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     setDragOffset(offsetTime);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      onSelectClip(clip.id);
  };

  const handleLoopDragStart = (e: React.MouseEvent, type: 'START' | 'END' | 'MOVE') => {
      e.stopPropagation();
      e.preventDefault();
      setLoopDragType(type);
      setLoopDragStartX(e.clientX);
      setLoopDragStartValues({ start: loopRegion.start, end: loopRegion.end });
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      onSelectClip(clipId);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0);
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP' && contextMenu.targetId) {
           switch(action) {
              case 'delete': onDeleteClip(contextMenu.targetId); break;
              case 'duplicate': onDuplicateClip(contextMenu.targetId); break;
              case 'rename': 
                  const clip = clips.find(c => c.id === contextMenu.targetId);
                  if (clip) {
                      const newName = prompt("Rename clip:", clip.name);
                      if (newName) onRenameClip(contextMenu.targetId, newName);
                  }
                  break;
              case 'copy': onCopyClip(contextMenu.targetId); break;
              case 'loop': onLoopClip(contextMenu.targetId); break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClip(contextMenu.time, contextMenu.targetId);
           } else if (action === 'import-file') {
               // CRITICAL: Persist target info to ref because contextMenu will be nullified
               importTargetRef.current = { trackId: contextMenu.targetId, time: contextMenu.time };
               fileInputRef.current?.click();
           }
      }
      setContextMenu(null);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0] && importTargetRef.current) {
          const { trackId, time } = importTargetRef.current;
          onImportAudio(e.target.files[0], trackId, time);
      }
      // Reset input value so the same file can be selected again
      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];
      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);
      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ left: i * singleLoopWidth, width: singleLoopWidth }}
                 >
                     <Waveform clip={clip} width={singleLoopWidth} height={TRACK_HEIGHT - 10} color={i === 0 ? "#ffffff" : "#ffffffaa"} />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <>
      <div 
        className={`flex-1 relative flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
        ref={timelineRef}
        onClick={handleTimelineClick}
      >
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileSelect}
            className="hidden" 
            accept="audio/*" 
        />

        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler - Now with sticky top-0 to stick inside the App-level scroll container */}
        <div 
          className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex" 
          style={{ width: `${totalBars * pixelsPerBar}px`, height: `${TIMELINE_RULER_HEIGHT}px` }}
        >
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}

             {/* Loop Region Overlay */}
             {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 h-full bg-yellow-400/20 border-l border-r border-yellow-400/50 group loop-region-handle cursor-move"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                    onMouseDown={(e) => handleLoopDragStart(e, 'MOVE')}
                 >
                     <div className="absolute top-0 left-0 w-full h-1 bg-yellow-400/50"></div>

                     {/* Handles */}
                     <div 
                        className="absolute top-0 left-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'START')}
                     />
                     <div 
                        className="absolute top-0 right-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'END')}
                     />
                 </div>
             )}
        </div>

        <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
          {/* Loop Region Background Highlight (Extends down tracks) */}
          {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 bottom-0 bg-white/5 pointer-events-none z-0"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                 />
          )}

          {tracks.map(track => {
            return (
                <div key={track.id} className="flex flex-col z-10">
                  <div 
                      className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                      onDragOver={handleDragOver}
                      onDrop={(e) => handleDrop(e, track.id)}
                      onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                      style={{ 
                          height: `${TRACK_HEIGHT}px`,
                          backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                          backgroundSize: `${pixelsPerBar}px 100%`,
                          backgroundPosition: '0 0'
                      }}
                  >
                      <div 
                          className="absolute inset-0 pointer-events-none" 
                          style={{ backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)', backgroundSize: `${pixelsPerBeat}px 100%`, opacity: 0.1 }}
                      />

                      {clips.filter(c => c.trackId === track.id).map(clip => (
                      <div
                          key={clip.id}
                          data-clip-id={clip.id}
                          draggable={tool === 'MOVE'}
                          onDragStart={(e) => handleDragStart(e, clip)}
                          onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                          onClick={(e) => e.stopPropagation()} 
                          onMouseDown={(e) => { if (tool === 'MOVE') onSelectClip(clip.id); }}
                          className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                          ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                          ${selectedClipId === clip.id ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                          style={{ left: `${clip.startTime * zoom}px`, width: `${clip.duration * zoom}px` }}
                      >
                          <div className="absolute inset-0 opacity-60" style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}></div>
                          {clip.loop && <div className="absolute top-0 right-4 p-1 text-white/70 z-30"><RotateCw size={10} /></div>}
                          <div className="absolute inset-0 z-10">{renderClipContent(clip, track)}</div>
                          <div className="absolute top-1 left-1 z-20 max-w-full"><div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">{clip.name}</div></div>
                          {tool === 'MOVE' && <div className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle" onMouseDown={(e) => handleResizeStart(e, clip)}><GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" /></div>}
                      </div>
                      ))}
                  </div>

                  {track.showAutomation && (
                      <div 
                          className="bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair box-border"
                          data-automation-track-id={track.id}
                          style={{ minWidth: `${totalBars * pixelsPerBar}px`, height: `${AUTOMATION_HEIGHT}px` }}
                      >
                          <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                          <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">{track.selectedAutomationId === 'pan' ? 'Pan' : track.selectedAutomationId === 'volume' ? 'Vol' : track.selectedAutomationId?.split(':')[1].toUpperCase()}</div>
                          <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>{renderAutomationPoints(track)}</svg>
                      </div>
                  )}
                </div>
            );
          })}
          <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">End of tracks</div>
        </div>

        {contextMenu && (
            <div 
                className="fixed z-50 w-56 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
                style={{ top: contextMenu.y, left: contextMenu.x }}
            >
                {contextMenu.type === 'CLIP' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Copy</button>
                      <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><RotateCw size={14} /> Toggle Loop</button>
                      <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Pencil size={14} /> Rename</button>
                      <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Duplicate</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2"><Trash2 size={14} /> Delete</button>
                    </>
                ) : (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'paste')} disabled={!canPaste} className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}><ClipboardPaste size={14} /> Paste</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'import-file')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Upload size={14} className="text-blue-400" /> Import Audio File</button>
                    </>
                )}
            </div>
        )}
      </div>
    </>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { MasterVisualizer } from './components/MasterVisualizer';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, LoopRegion } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);

  // Metronome State
  const [isMetronomeOn, setIsMetronomeOn] = useState(false);
  const [countInMeasures, setCountInMeasures] = useState(1);

  // Loop State (Default measures 1-4 -> 0s to 8s at 120bpm)
  const [loopRegion, setLoopRegion] = useState<LoopRegion>({ start: 0, end: 8, enabled: false });
  // Ref for loop region to access in RAF without re-binding
  const loopRegionRef = useRef(loopRegion);

  useEffect(() => {
      loopRegionRef.current = loopRegion;
  }, [loopRegion]);

  // Recording State
  const [armedTrackId, setArmedTrackId] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  const [selectedClipId, setSelectedClipId] = useState<string | null>(null);
  const [clipboardClip, setClipboardClip] = useState<AudioClip | null>(null);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Refs ---
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const navigatorRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Navigator Scroll Sync ---
  const handleMainScroll = () => {
      if (scrollContainerRef.current && navigatorRef.current) {
          navigatorRef.current.scrollLeft = scrollContainerRef.current.scrollLeft;
      }
  };

  const handleNavigatorScroll = (e: React.UIEvent<HTMLDivElement>) => {
      const target = e.target as HTMLDivElement;
      if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollLeft = target.scrollLeft;
      }
  };

  // --- Undo/Redo System ---
  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks);
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex - 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks);
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };

  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stopPlayback(); 
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    // Schedule metronome if enabled
    if (isMetronomeOn) {
        audioService.scheduleMetronome(bpm, audioService.getContext().currentTime, 300); // Schedule 5 mins of clicks
    }

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true, currentTime: startAt }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      // Loop Check using REF to avoid closure staleness
      if (loopRegionRef.current.enabled && newTime >= loopRegionRef.current.end) {
          startPlayback(loopRegionRef.current.start);
          return; 
      }

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks, bpm, isMetronomeOn]); 

  const handleSeek = useCallback((time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));

      // If playing, we need to restart playback at new position
      if (playbackState.isPlaying) {
           startPlayback(time);
      }
  }, [playbackState.isPlaying, startPlayback]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (isRecording) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [isRecording]);

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---
  const handleArmTrack = async (trackId: string) => {
      if (armedTrackId === trackId) {
          setArmedTrackId(null);
          audioService.disableMonitoring();
      } else {
          try {
              // Critical: Await monitoring setup BEFORE updating state to ensure visualizer is ready
              await audioService.enableMonitoring(trackId); 
              setArmedTrackId(trackId);
          } catch(e) {
              alert("Could not access microphone.");
              setArmedTrackId(null);
          }
      }
  };

  const handleTransportRecord = async () => {
      if (isRecording) {
          handleStop();
      } else {
          if (!armedTrackId) {
              alert("Please arm a track first.");
              return;
          }
          try {
            await audioService.resume();

            // Count-In Logic
            if (countInMeasures > 0) {
                 await audioService.playCountIn(bpm, countInMeasures);
            }

            // Await the recording start! This ensures permissions are granted and stream is active before UI updates
            await audioService.startRecording();

            setIsRecording(true);
            recordStartTimeRef.current = pauseTimeRef.current;
            startPlayback(pauseTimeRef.current);
          } catch(e) {
              console.error("Recording failed to start", e);
              alert("Failed to start recording. Please check microphone permissions.");
          }
      }
  };

  const finishRecording = async () => {
      if (!armedTrackId) {
          setIsRecording(false);
          return;
      }
      const blob = await audioService.stopRecording();
      const startTime = recordStartTimeRef.current;
      if (blob && blob.size > 0) {
          try {
              const buffer = await audioService.decodeBlob(blob);
              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: armedTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: startTime,
                  duration: buffer.duration,
                  offset: 0,
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };
              updateStateWithHistory(tracks, [...clips, newClip]);
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }
      setIsRecording(false);
  };

  // --- Track Management ---
  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) points[existingIdx] = point;
             else points.push(point);
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---
  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  // Context Menu Helpers
  const handleImportAudio = (file: File, trackId: string, time: number) => {
      handleFileDrop(file, trackId, time);
  };

  const updateClip = (id: string, newTime: number, newTrackId?: string) => {
    if (newTrackId === 'master') return;
    const newClips = clips.map(c => c.id === id ? { ...c, startTime: newTime, trackId: newTrackId || c.trackId } : c);
    setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  const deleteClip = (id: string) => {
      const newClips = clips.filter(c => c.id !== id);
      if (selectedClipId === id) setSelectedClipId(null);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClip = (id: string) => {
      const original = clips.find(c => c.id === id);
      if (!original) return;
      const newClip: AudioClip = {
          ...original,
          id: uuidv4(),
          startTime: original.startTime + original.duration,
          name: `${original.name} (Copy)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;
      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return;

      const firstDuration = relativeSplit * clip.playbackRate;
      const leftClip: AudioClip = { ...clip, id: uuidv4(), duration: firstDuration, name: clip.name };
      const rightClip: AudioClip = { ...clip, id: uuidv4(), startTime: splitTime, offset: clip.offset + firstDuration, duration: clip.duration - firstDuration, name: clip.name };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);
      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClip = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) setClipboardClip(clip);
  };

  const handlePasteClip = (time: number, trackId: string) => {
      if (!clipboardClip || trackId === 'master') return;
      const newClip: AudioClip = {
          ...clipboardClip,
          id: uuidv4(),
          startTime: time,
          trackId: trackId,
          name: `${clipboardClip.name} (Paste)`
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;
          const newClips = clips.map(c => c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---
  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  // --- Derived State & Variables ---
  const regularTracks = tracks.filter(t => !t.isMaster);
  const masterTrack = tracks.find(t => t.isMaster) || MASTER_TRACK;
  const selectedClip = clips.find(c => c.id === selectedClipId) || null;
  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration));
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const pixelsPerBar = secondsPerBar * zoom;
  const timelineWidth = totalBars * pixelsPerBar;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        isRecording={isRecording}
        onRecord={handleTransportRecord}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={setBpm}
        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={setZoom}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
        loopRegion={loopRegion}
        setLoopRegion={setLoopRegion}
        isMetronomeOn={isMetronomeOn}
        toggleMetronome={() => setIsMetronomeOn(!isMetronomeOn)}
        countInMeasures={countInMeasures}
        setCountInMeasures={setCountInMeasures}
      />

      {/* Main Workspace: Single Unified Scroll Container */}
      <div 
        className="flex-1 overflow-auto relative" 
        ref={scrollContainerRef}
        onScroll={handleMainScroll}
      >
        <div className="flex min-w-max">
            {/* Sticky Left Column (Headers) */}
            <div 
                className="sticky left-0 z-30 bg-gray-900 border-r border-gray-700 flex flex-col flex-shrink-0 shadow-lg"
                style={{ width: TRACK_HEADER_WIDTH }}
            >
                 {/* Sticky Top-Left Corner */}
                 <div 
                    className="sticky top-0 z-40 bg-gray-900 border-b border-gray-700 flex-shrink-0"
                    style={{ height: TIMELINE_RULER_HEIGHT }}
                 />

                 {/* Track Headers List */}
                 {regularTracks.map(track => (
                    <TrackControl 
                        key={track.id} 
                        track={track} 
                        onUpdate={updateTrack}
                        onDelete={deleteTrack}
                        isArmed={armedTrackId === track.id}
                        isRecordingGlobal={isRecording}
                        onArmToggle={() => handleArmTrack(track.id)}
                        onOpenEditor={setEditingTrackId}
                        onToggleAutomation={toggleAutomation}
                    />
                 ))}

                 <div className="p-3">
                     <button 
                        onClick={addTrack}
                        className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                        title="Add a new audio track"
                     >
                        <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors"><Plus size={14} /></div>
                        <span>Add Track</span>
                     </button>
                 </div>

                 {/* Bottom Spacer */}
                 <div className="h-64 bg-gray-900" />
            </div>

            {/* Main Timeline Area (Scrolls with parent) */}
            <div className="flex flex-col flex-1">
                {/* Timeline Component - renders Ruler (sticky inside) and Tracks */}
                <Timeline 
                    tracks={regularTracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipUpdate={updateClip}
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={setZoom}
                    snap={snap}
                    tool={tool}
                    onDeleteClip={deleteClip}
                    onDuplicateClip={duplicateClip}
                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}
                    onSelectClip={(id) => { setSelectedClipId(id); if (id) setEditingTrackId(null); }}
                    selectedClipId={selectedClipId}
                    onCopyClip={handleCopyClip}
                    onPasteClip={handlePasteClip}
                    canPaste={!!clipboardClip}
                    onLoopClip={handleLoopToggle}
                    onClipResize={handleClipResize}
                    loopRegion={loopRegion}
                    setLoopRegion={setLoopRegion}
                    onImportAudio={handleImportAudio}
                />
            </div>
        </div>
      </div>

      {/* Fixed Bottom Master Section */}
      <div className="h-44 bg-gray-900 border-t-2 border-gray-800 flex flex-col z-50 shadow-[0_-5px_15px_rgba(0,0,0,0.5)]">
         {/* Master Row */}
         <div className="flex flex-1 overflow-hidden">
             {/* Master Control (Left) */}
             <div className="flex-shrink-0 border-r border-gray-800" style={{ width: TRACK_HEADER_WIDTH }}>
                <TrackControl 
                  track={masterTrack}
                  onUpdate={updateTrack}
                  onDelete={() => {}}
                  isArmed={false}
                  isRecordingGlobal={false}
                  onArmToggle={() => {}}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={() => {}}
                />
             </div>
             {/* Master Visualizer (Right) */}
             <div className="flex-1 p-2 bg-gray-900 flex items-center justify-center">
                 <MasterVisualizer isPlaying={playbackState.isPlaying} />
             </div>
         </div>

         {/* Navigator / Scrollbar (Bottom Fixed) */}
         <div className="h-5 bg-gray-950 border-t border-gray-800">
             <div 
                ref={navigatorRef}
                onScroll={handleNavigatorScroll}
                className="w-full h-full overflow-x-auto overflow-y-hidden custom-scrollbar"
                title="Timeline Navigator"
             >
                <div style={{ width: timelineWidth + TRACK_HEADER_WIDTH, height: '1px' }}></div>
             </div>
         </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipId(null)}
          />
      )}
    </div>
  );
}

