  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [timeMarkers, setTimeMarkers] = useState<{time: number, label: string}[]>([]);

  // Metronome State
  const [isMetronomeOn, setIsMetronomeOn] = useState(false);
  const [countInMeasures, setCountInMeasures] = useState(1);

  // Loop State (Default measures 1-4 -> 0s to 8s at 120bpm)
  const [loopRegion, setLoopRegion] = useState<LoopRegion>({ start: 0, end: 8, enabled: false });
  // Ref for loop region to access in RAF without re-binding
  const loopRegionRef = useRef(loopRegion);

  useEffect(() => {
      loopRegionRef.current = loopRegion;
  }, [loopRegion]);

  // Recording State
  const [armedTrackId, setArmedTrackId] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  // Selection State (Multi-select)
  const [selectedClipIds, setSelectedClipIds] = useState<string[]>([]);
  const [clipboardClips, setClipboardClips] = useState<AudioClip[]>([]);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Refs ---
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const navigatorRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0); // Timeline position where recording block starts
  const recordPreRollRef = useRef<number>(0); // How much physical audio was captured BEFORE timeline start

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Navigator Scroll Sync ---
  const handleMainScroll = () => {
      if (scrollContainerRef.current && navigatorRef.current) {
          navigatorRef.current.scrollLeft = scrollContainerRef.current.scrollLeft;
      }
  };

  const handleNavigatorScroll = (e: React.UIEvent<HTMLDivElement>) => {
      const target = e.target as HTMLDivElement;
      if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollLeft = target.scrollLeft;
      }
  };

  // --- Smart Zoom Handling ---
  const handleZoomChange = useCallback((newZoom: number) => {
      const clampedZoom = Math.max(10, Math.min(500, newZoom));
      setZoom(clampedZoom);

      // Center playhead logic
      if (scrollContainerRef.current) {
          requestAnimationFrame(() => {
              if (scrollContainerRef.current) {
                  const containerWidth = scrollContainerRef.current.clientWidth;
                  const playheadX = playbackState.currentTime * clampedZoom;
                  // Center playhead: target scroll is playheadX - halfWidth
                  const targetScroll = Math.max(0, playheadX - (containerWidth / 2));
                  scrollContainerRef.current.scrollLeft = targetScroll;
              }
          });
      }
  }, [playbackState.currentTime]);

  // --- Undo/Redo System ---
  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks);
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex - 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks);
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };

  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stopPlayback(); 
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    // Schedule metronome if enabled
    if (isMetronomeOn) {
        audioService.scheduleMetronome(bpm, audioService.getContext().currentTime, 300); // Schedule 5 mins of clicks
    }

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true, currentTime: startAt }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      // Loop Check using REF to avoid closure staleness
      if (loopRegionRef.current.enabled && newTime >= loopRegionRef.current.end) {
          startPlayback(loopRegionRef.current.start);
          return; 
      }

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks, bpm, isMetronomeOn]); 

  const handleSeek = useCallback((time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));

      // If playing, we need to restart playback at new position
      if (playbackState.isPlaying) {
           startPlayback(time);
      }
  }, [playbackState.isPlaying, startPlayback]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (isRecording) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [isRecording]);

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---
  const handleArmTrack = async (trackId: string) => {
      if (armedTrackId === trackId) {
          setArmedTrackId(null);
          audioService.disableMonitoring();
      } else {
          try {
              // Critical: Await monitoring setup BEFORE updating state to ensure visualizer is ready
              await audioService.enableMonitoring(trackId); 
              setArmedTrackId(trackId);
          } catch(e) {
              alert("Could not access microphone.");
              setArmedTrackId(null);
          }
      }
  };

  const handleTransportRecord = async () => {
      if (isRecording) {
          handleStop();
      } else {
          if (!armedTrackId) {
              alert("Please arm a track first.");
              return;
          }
          try {
            await audioService.resume();

            // 1. Start Recording Physically FIRST to capture pre-roll/setup
            await audioService.startRecording();
            const sysRecordStart = audioService.getContext().currentTime;

            // 2. Count-In Logic (if enabled)
            if (countInMeasures > 0) {
                 await audioService.playCountIn(bpm, countInMeasures);
            } else {
                 // Even without count-in, wait a tiny bit to ensure we capture the transient of the first beat
                 await new Promise(r => setTimeout(r, 100));
            }

            // 3. Start Playback Transport
            const sysPlaybackStart = audioService.getContext().currentTime;

            // Calculate how much audio we captured before the transport actually started
            const preRollDuration = sysPlaybackStart - sysRecordStart;

            setIsRecording(true);
            recordStartTimeRef.current = pauseTimeRef.current;
            recordPreRollRef.current = preRollDuration;

            startPlayback(pauseTimeRef.current);
          } catch(e) {
              console.error("Recording failed to start", e);
              alert("Failed to start recording. Please check microphone permissions.");
          }
      }
  };

  const finishRecording = async () => {
      if (!armedTrackId) {
          setIsRecording(false);
          return;
      }
      const blob = await audioService.stopRecording();
      const timelineStart = recordStartTimeRef.current;
      const preRoll = recordPreRollRef.current;

      if (blob && blob.size > 0) {
          try {
              const buffer = await audioService.decodeBlob(blob);

              // --- Latency Compensation & Placement ---
              const latency = audioService.latencySeconds;

              // The buffer contains [PreRoll] + [Performance].
              // The Performance started at buffer time = preRoll + latency (approx).
              // We want this point to align with `timelineStart`.

              // Theoretical Offset into buffer for T=timelineStart
              let targetOffset = preRoll + latency;

              // Safety: Reveal a bit of the pre-roll to catch early transients (rushing).
              // We shift the clip START TIME back by `safetyMargin` and reduce OFFSET by same amount.
              const safetyMargin = Math.min(preRoll, 0.2); // Up to 200ms

              const finalClipStart = timelineStart - safetyMargin;
              const finalClipOffset = targetOffset - safetyMargin;

              // Duration needs to be calculated based on what's left in the buffer
              // Buffer Duration - Offset = Playable Length
              // But we added safetyMargin to length by reducing offset.
              const finalDuration = Math.max(0, buffer.duration - finalClipOffset);

              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: armedTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: finalClipStart, // Can be negative or < timelineStart
                  duration: finalDuration,
                  offset: Math.max(0, finalClipOffset),
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };

              if (finalDuration > 0) {
                  updateStateWithHistory(tracks, [...clips, newClip]);
              }
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }
      setIsRecording(false);
  };

  // --- Track Management ---
  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) points[existingIdx] = point;
             else points.push(point);
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---
  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  // Batch Update for moving multiple clips
  const updateClips = (updates: { id: string, startTime: number, trackId?: string }[]) => {
      const newClips = clips.map(c => {
          const update = updates.find(u => u.id === c.id);
          if (update) {
              // Prevent moving to master track
              if (update.trackId === 'master') return c;
              return { ...c, startTime: update.startTime, trackId: update.trackId || c.trackId };
          }
          return c;
      });
      setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  // --- Batch Operations (Delete, Duplicate, Copy, Paste) ---

  const deleteClips = (ids: string[]) => {
      const newClips = clips.filter(c => !ids.includes(c.id));
      setSelectedClipIds([]);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClips = (ids: string[]) => {
      const clipsToDuplicate = clips.filter(c => ids.includes(c.id));
      if (clipsToDuplicate.length === 0) return;

      // Find the range of the selection to determine offset
      const startTimes = clipsToDuplicate.map(c => c.startTime);
      const endTimes = clipsToDuplicate.map(c => c.startTime + c.duration);
      const minStart = Math.min(...startTimes);
      const maxEnd = Math.max(...endTimes);
      const selectionDuration = maxEnd - minStart;

      const newClips = [...clips];
      const newIds: string[] = [];

      clipsToDuplicate.forEach(original => {
          const newId = uuidv4();
          newIds.push(newId);
          newClips.push({
              ...original,
              id: newId,
              // Place duplicates immediately after the selection group
              startTime: original.startTime + selectionDuration, 
              name: `${original.name} (Copy)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleFlattenClip = async (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (!clip) return;

      try {
          const newBuffer = await audioService.bounceClip(clip);
          const newClip: AudioClip = {
              ...clip,
              buffer: newBuffer,
              offset: 0,
              duration: clip.duration, 
              playbackRate: 1, 
              name: `${clip.name} (Flattened)`,
              loop: false 
          };

          const newClips = clips.map(c => c.id === id ? newClip : c);
          updateStateWithHistory(tracks, newClips);
          // Keep selection
          if (selectedClipIds.includes(id)) {
              // no-op, still selected
          }
      } catch (e) {
          console.error("Flatten failed", e);
          alert("Could not flatten clip.");
      }
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;
      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return;

      const firstDuration = relativeSplit * clip.playbackRate;
      const leftClip: AudioClip = { ...clip, id: uuidv4(), duration: firstDuration, name: clip.name };
      const rightClip: AudioClip = { ...clip, id: uuidv4(), startTime: splitTime, offset: clip.offset + firstDuration, duration: clip.duration - firstDuration, name: clip.name };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      // Update selection to the new clips if original was selected
      if (selectedClipIds.includes(clipId)) {
          setSelectedClipIds([leftClip.id, rightClip.id]);
      }

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClips = (ids: string[]) => {
      const selected = clips.filter(c => ids.includes(c.id));
      if (selected.length > 0) setClipboardClips(selected);
  };

  const handlePasteClips = (time: number, targetTrackId: string) => {
      if (clipboardClips.length === 0 || targetTrackId === 'master') return;

      // Calculate relative offsets based on the earliest clip in clipboard
      const minStartTime = Math.min(...clipboardClips.map(c => c.startTime));
      // Identify the "primary" track (e.g., the top-most track in the selection) to map relative track offsets
      // For simplicity in this version, we paste EVERYTHING starting at the targetTrackId
      // But if clips are on different tracks, we should try to preserve relative track spacing if possible.
      // Simpler approach: Flatten vertical structure or paste all to target track?
      // Let's paste all to target track but preserve Time offsets.

      const newClips = [...clips];
      const newIds: string[] = [];

      clipboardClips.forEach(clip => {
          const relativeTime = clip.startTime - minStartTime;
          const newId = uuidv4();
          newIds.push(newId);

          newClips.push({
              ...clip,
              id: newId,
              startTime: time + relativeTime,
              trackId: targetTrackId, // Collapse to the track where user right-clicked for now
              name: `${clip.name} (Paste)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;
          const newClips = clips.map(c => c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---
  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const handleExportStems = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          for (const track of tracks) {
             if (track.isMaster) continue;
             const trackClips = clips.filter(c => c.trackId === track.id);
             if (trackClips.length === 0) continue;

             const blob = await audioService.renderOffline(trackClips, [track, MASTER_TRACK]);

             const url = URL.createObjectURL(blob);
             const a = document.createElement('a');
             a.href = url;
             a.download = `${track.name}_Stem.wav`;
             a.click();
             URL.revokeObjectURL(url);

             await new Promise(r => setTimeout(r, 500));
          }
      } catch (e) {
          console.error("Stem Export failed", e);
          alert("Stem Export failed.");
      } finally {
          setIsExporting(false);
          setIsSettingsOpen(false);
      }
  };

  // --- Derived State & Variables ---
  const regularTracks = tracks.filter(t => !t.isMaster);
  const masterTrack = tracks.find(t => t.isMaster) || MASTER_TRACK;

  // Only show editor if exactly one clip is selected
  const selectedClip = selectedClipIds.length === 1 
      ? clips.find(c => c.id === selectedClipIds[0]) || null
      : null;

  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration));
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const pixelsPerBar = secondsPerBar * zoom;
  const timelineWidth = totalBars * pixelsPerBar;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <SettingsModal 
          isOpen={isSettingsOpen} 
          onClose={() => setIsSettingsOpen(false)}
          onExportStems={handleExportStems}
      />

      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        isRecording={isRecording}
        onRecord={handleTransportRecord}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={(newBpm) => {
            setBpm(newBpm);
        }}
        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={handleZoomChange}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
        loopRegion={loopRegion}
        setLoopRegion={setLoopRegion}
        isMetronomeOn={isMetronomeOn}
        toggleMetronome={() => setIsMetronomeOn(!isMetronomeOn)}
        countInMeasures={countInMeasures}
        setCountInMeasures={setCountInMeasures}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      {/* Main Workspace: Single Unified Scroll Container */}
      <div 
        className="flex-1 overflow-auto relative" 
        ref={scrollContainerRef}
        onScroll={handleMainScroll}
      >
        <div className="flex min-w-max">
            {/* Sticky Left Column (Headers) */}
            <div 
                className="sticky left-0 z-30 bg-gray-900 border-r border-gray-700 flex flex-col flex-shrink-0 shadow-lg"
                style={{ width: TRACK_HEADER_WIDTH }}
            >
                 {/* Sticky Top-Left Corner */}
                 <div 
                    className="sticky top-0 z-40 bg-gray-900 border-b border-gray-700 flex-shrink-0"
                    style={{ height: TIMELINE_RULER_HEIGHT }}
                 />

                 {/* Track Headers List */}
                 {regularTracks.map(track => (
                    <TrackControl 
                        key={track.id} 
                        track={track} 
                        onUpdate={updateTrack}
                        onDelete={deleteTrack}
                        isArmed={armedTrackId === track.id}
                        isRecordingGlobal={isRecording}
                        onArmToggle={() => handleArmTrack(track.id)}
                        onOpenEditor={setEditingTrackId}
                        onToggleAutomation={toggleAutomation}
                    />
                 ))}

                 <div className="p-3">
                     <button 
                        onClick={addTrack}
                        className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                        title="Add a new audio track"
                     >
                        <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors"><Plus size={14} /></div>
                        <span>Add Track</span>
                     </button>
                 </div>

                 {/* Bottom Spacer */}
                 <div className="h-64 bg-gray-900" />
            </div>

            {/* Main Timeline Area (Scrolls with parent) */}
            <div className="flex flex-col flex-1">
                {/* Timeline Component - renders Ruler (sticky inside) and Tracks */}
                <Timeline 
                    tracks={regularTracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipsUpdate={updateClips} // Batch update
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={handleZoomChange}
                    snap={snap}
                    tool={tool}

                    selectedClipIds={selectedClipIds}
                    setSelectedClipIds={setSelectedClipIds}

                    onDeleteClips={deleteClips}
                    onDuplicateClips={duplicateClips}
                    onCopyClips={handleCopyClips}
                    onPasteClips={handlePasteClips}
                    canPaste={clipboardClips.length > 0}

                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}
                    onClipResize={handleClipResize}
                    onLoopClip={handleLoopToggle}
                    onFlattenClip={handleFlattenClip}

                    loopRegion={loopRegion}
                    setLoopRegion={setLoopRegion}
                    onImportAudio={handleImportAudio}
                    markers={timeMarkers}
                    onAddMarker={(time, label) => setTimeMarkers([...timeMarkers, {time, label}])}
                    setBpm={setBpm}
                />
            </div>
        </div>
      </div>

      {/* Fixed Bottom Master Section */}
      <div className="h-44 bg-gray-900 border-t-2 border-gray-800 flex flex-col z-50 shadow-[0_-5px_15px_rgba(0,0,0,0.5)]">
         {/* Master Row */}
         <div className="flex flex-1 overflow-hidden">
             {/* Master Control (Left) */}
             <div className="flex-shrink-0 border-r border-gray-800" style={{ width: TRACK_HEADER_WIDTH }}>
                <TrackControl 
                  track={masterTrack}
                  onUpdate={updateTrack}
                  onDelete={() => {}}
                  isArmed={false}
                  isRecordingGlobal={false}
                  onArmToggle={() => {}}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={() => {}}
                />
             </div>
             {/* Master Visualizer (Right) */}
             <div className="flex-1 p-2 bg-gray-900 flex items-center justify-center">
                 <MasterVisualizer isPlaying={playbackState.isPlaying} />
             </div>
         </div>

         {/* Navigator / Scrollbar (Bottom Fixed) */}
         <div className="h-5 bg-gray-950 border-t border-gray-800">
             <div 
                ref={navigatorRef}
                onScroll={handleNavigatorScroll}
                className="w-full h-full overflow-x-auto overflow-y-hidden custom-scrollbar"
                title="Timeline Navigator"
             >
                <div style={{ width: timelineWidth + TRACK_HEADER_WIDTH, height: '1px' }}></div>
             </div>
         </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipIds([])}
            projectBpm={bpm}
          />
      )}
    </div>
  );
}

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint, LoopRegion } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, GripVertical, Upload, Clock, Activity, FileStack } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipsUpdate: (updates: { id: string, startTime: number, trackId?: string }[]) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;

  // Selection & Batch Ops
  selectedClipIds: string[];
  setSelectedClipIds: (ids: string[]) => void;
  onDeleteClips: (ids: string[]) => void;
  onDuplicateClips: (ids: string[]) => void;
  onCopyClips: (ids: string[]) => void;
  onPasteClips: (time: number, trackId: string) => void;
  canPaste: boolean;

  onRenameClip: (id: string, newName: string) => void;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;

  loopRegion: LoopRegion;
  setLoopRegion: (region: LoopRegion) => void;

  onImportAudio: (file: File, trackId: string, time: number) => void;

  markers?: {time: number, label: string}[];
  onAddMarker?: (time: number, label: string) => void;
  setBpm?: (bpm: number) => void;

  onFlattenClip?: (id: string) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND' | 'RULER';
    targetId?: string; // ClipId or TrackId
    time?: number; 
}

interface MarqueeState {
    startX: number;
    startY: number;
    currentX: number;
    currentY: number;
    active: boolean;
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipsUpdate, 
  onFileDrop,
  onSeek,
  selectedClipIds,
  setSelectedClipIds,
  onDeleteClips,
  onDuplicateClips,
  onCopyClips,
  onPasteClips,
  canPaste,
  onRenameClip,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize,
  loopRegion,
  setLoopRegion,
  onImportAudio,
  markers = [],
  onAddMarker,
  setBpm,
  onFlattenClip
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  // Keep track of the initial offset for ALL selected clips during a drag
  const [dragOffsets, setDragOffsets] = useState<{ [id: string]: number }>({});

  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  // Marquee State
  const [marquee, setMarquee] = useState<MarqueeState | null>(null);

  // Loop Dragging State
  const [loopDragType, setLoopDragType] = useState<'START' | 'END' | 'MOVE' | null>(null);
  const [loopDragStartX, setLoopDragStartX] = useState<number>(0);
  const [loopDragStartValues, setLoopDragStartValues] = useState<{start: number, end: number}>({start:0, end:0});

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // Refs for File Import
  const fileInputRef = useRef<HTMLInputElement>(null);
  const importTargetRef = useRef<{trackId: string, time: number} | null>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      return Math.round(time / beat) * beat;
  };

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) {
               setDraggedClipId(null);
               setDragOffsets({});
           }
           if (resizingClipId) setResizingClipId(null);
           if (loopDragType) setLoopDragType(null);
           if (marquee?.active) {
               setMarquee(null);
           }
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId, loopDragType, marquee]);

  // Global Mouse Move (for operations like resizing, box select, etc that extend beyond the div)
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;
          const rect = timelineRef.current.getBoundingClientRect();
          const relativeX = e.clientX - rect.left + timelineRef.current.scrollLeft;
          const relativeY = e.clientY - rect.top + timelineRef.current.scrollTop;

          if (marquee?.active) {
              setMarquee(prev => prev ? { ...prev, currentX: relativeX, currentY: relativeY } : null);

              // Calculate Selection Logic
              // Define Marquee Box
              const mX = Math.min(marquee.startX, relativeX);
              const mY = Math.min(marquee.startY, relativeY);
              const mW = Math.abs(relativeX - marquee.startX);
              const mH = Math.abs(relativeY - marquee.startY);

              // Iterate Clips to find intersection
              const newSelectedIds: string[] = [];

              tracks.forEach((track, trackIndex) => {
                  // Calculate Track Y Bounds (rough estimate, assumes fixed height)
                  // We need to account for hidden automation lanes or scroll offsets if tracks are virtualized,
                  // but here we render all tracks.
                  // Note: Logic here assumes direct DOM mapping or calculated layout.
                  // Let's use calculated layout:
                  // Track Y starts at TIMELINE_RULER_HEIGHT + (sum of previous track heights)
                  // For simplicity in this demo, let's assume standard TRACK_HEIGHT if automation is off.
                  // Actually, getting DOM elements is safer for Y collisions.

                  // Simplified approach: Filter clips based on X first, then check track Index?
                  // Better: Iterate all visible clip DOM elements.
              });

              // DOM-based collision for accuracy
              const clipElements = timelineRef.current.querySelectorAll('[data-clip-id]');
              clipElements.forEach(el => {
                  const clipRect = el.getBoundingClientRect();
                  // Convert clip rect to relative coordinates within timelineRef
                  const clipRelX = clipRect.left - rect.left + timelineRef.current!.scrollLeft;
                  const clipRelY = clipRect.top - rect.top + timelineRef.current!.scrollTop;

                  // AABB Collision
                  if (mX < clipRelX + clipRect.width &&
                      mX + mW > clipRelX &&
                      mY < clipRelY + clipRect.height &&
                      mY + mH > clipRelY) {
                          const id = el.getAttribute('data-clip-id');
                          if (id) newSelectedIds.push(id);
                      }
              });
              setSelectedClipIds(newSelectedIds);
              return;
          }

          if (loopDragType) {
              const diffPixels = e.clientX - loopDragStartX;
              const diffSeconds = diffPixels / zoom;

              let newStart = loopDragStartValues.start;
              let newEnd = loopDragStartValues.end;

              if (loopDragType === 'START') {
                  newStart = Math.min(newEnd - 0.25, Math.max(0, loopDragStartValues.start + diffSeconds));
              } else if (loopDragType === 'END') {
                  newEnd = Math.max(newStart + 0.25, loopDragStartValues.end + diffSeconds);
              } else if (loopDragType === 'MOVE') {
                  const duration = loopDragStartValues.end - loopDragStartValues.start;
                  newStart = Math.max(0, loopDragStartValues.start + diffSeconds);
                  newEnd = newStart + duration;
              }

              if (snap) {
                  newStart = snapToGrid(newStart);
                  newEnd = snapToGrid(newEnd);
                  if (newEnd <= newStart) newEnd = newStart + secondsPerBeat;
              }

              setLoopRegion({ ...loopRegion, start: newStart, end: newEnd });
              return;
          }

          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); 
             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;
             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId || loopDragType || marquee?.active) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize, loopDragType, loopDragStartX, loopDragStartValues, loopRegion, setLoopRegion, bpm, marquee]);

  // Wheel Zoom
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom));
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId || loopDragType) return;

    // If marquee just finished (active was true on mouseup), don't deselect or seek
    // Logic handled in global mouseup/click handlers usually, but here we check target

    const target = e.target as HTMLElement;
    if (target.closest('.loop-region-handle')) return;

    const clipElement = target.closest('[data-clip-id]');

    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
                 const time = Math.max(0, clickX / zoom);

                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));
                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    // Background Click: Start Marquee if not on clip/automation
    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        // If simply clicking (not dragging), deselect all and seek
        // We distinguish drag vs click via MouseDown/Up logic mostly
        // But for seek:
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;

        // Only seek if we didn't just drag a marquee
        if (!marquee?.active) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const seekTime = Math.max(0, (clickX / zoom));
             onSeek(snapToGrid(seekTime));
             setSelectedClipIds([]); // Clear selection
        }
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      // Check if clicking on background to start marquee
      const target = e.target as HTMLElement;
      if (!target.closest('[data-clip-id]') && !target.closest('.loop-region-handle') && !target.closest('[data-automation-track-id]')) {
          if (tool === 'MOVE') {
              const rect = timelineRef.current!.getBoundingClientRect();
              const x = e.clientX - rect.left + timelineRef.current!.scrollLeft;
              const y = e.clientY - rect.top + timelineRef.current!.scrollTop;

              setMarquee({
                  startX: x,
                  startY: y,
                  currentX: x,
                  currentY: y,
                  active: true
              });
          }
      }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        const isAudio = file.type.startsWith('audio/') || 
                        file.type === 'video/mp4' || 
                        file.name.toLowerCase().endsWith('.m4a');
        if (isAudio) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        // Multi-clip move logic
        const draggedClip = clips.find(c => c.id === draggedClipId);
        if (!draggedClip) return;

        // Determine if we are moving a group or single
        const movingIds = selectedClipIds.includes(draggedClipId) ? selectedClipIds : [draggedClipId];

        // Calculate the delta for the PRIMARY dragged clip
        // Logic: dropTime is where the mouse released. 
        // We want to calculate the new start time for the dragged clip relative to where we grabbed it.
        // Simplified: The new start time of the dragged clip is `dropTime - dragOffset` (but we need to handle specific dragOffsets for group)

        const primaryOffset = dragOffsets[draggedClipId] || 0;
        const newPrimaryTime = Math.max(0, dropTime - primaryOffset);
        const timeDelta = newPrimaryTime - draggedClip.startTime; // How much it moved

        const updates = movingIds.map(id => {
            const clip = clips.find(c => c.id === id);
            if (!clip) return null;

            // For the clip actually under the mouse, we use the specific track dropped on
            // For others, we keep their track OR shift relative?
            // Standard DAW: If moving group vertically, they all shift relative tracks.
            // Complex to implement vertical relative shift without strict track indexing.
            // FALLBACK: Only change track for the dragged clip, others stay on their tracks but move in Time.
            // IMPROVEMENT: If dragging PRIMARY clip to a new track, others stay on their tracks unless we calculate track delta.
            // Let's implement Time Shift for all, Track Shift only for primary (or simple vertical block shift if feasible).

            // Current simple implementation: Time shift all, Track shift only Primary (dragged) clip
            // Actually, usually you want to move the block. 
            // Let's stick to Time-Shift ALL, Track-Shift PRIMARY only for now to avoid track index math bugs.

            return {
                id: clip.id,
                startTime: Math.max(0, clip.startTime + timeDelta),
                trackId: id === draggedClipId ? trackId : clip.trackId 
            };
        }).filter(Boolean) as { id: string, startTime: number, trackId?: string }[];

        onClipsUpdate(updates);
        setDraggedClipId(null);
        setDragOffsets({});
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }

     // If the clicked clip is NOT in the selection, clear selection and select it
     let currentSelection = selectedClipIds;
     if (!selectedClipIds.includes(clip.id)) {
         setSelectedClipIds([clip.id]);
         currentSelection = [clip.id];
     }

     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     // Store offsets for all selected clips to ensure smooth dragging if we enhanced visual drag preview
     // For now, mostly needed for the primary dragged clip calculation logic
     const offsets: {[id:string]: number} = {};
     currentSelection.forEach(id => {
         offsets[id] = offsetTime; // This is actually relative to the clip start.
     });

     setDragOffsets(offsets);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";

     // Optional: Set custom drag image
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      if (!selectedClipIds.includes(clip.id)) {
          setSelectedClipIds([clip.id]);
      }
  };

  const handleLoopDragStart = (e: React.MouseEvent, type: 'START' | 'END' | 'MOVE') => {
      e.stopPropagation();
      e.preventDefault();
      setLoopDragType(type);
      setLoopDragStartX(e.clientX);
      setLoopDragStartValues({ start: loopRegion.start, end: loopRegion.end });
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();

      if (!selectedClipIds.includes(clipId)) {
          setSelectedClipIds([clipId]);
      }

      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleRulerContextMenu = (e: React.MouseEvent) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'RULER',
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP') {
           // Apply to ALL selected clips if target is in selection, else just target
           const targetIsSelected = contextMenu.targetId && selectedClipIds.includes(contextMenu.targetId);
           const idsToActOn = targetIsSelected ? selectedClipIds : (contextMenu.targetId ? [contextMenu.targetId] : []);

           switch(action) {
              case 'delete': onDeleteClips(idsToActOn); break;
              case 'duplicate': onDuplicateClips(idsToActOn); break;
              case 'rename': 
                  if (idsToActOn.length === 1) {
                      const clip = clips.find(c => c.id === idsToActOn[0]);
                      if (clip) {
                          const newName = prompt("Rename clip:", clip.name);
                          if (newName) onRenameClip(idsToActOn[0], newName);
                      }
                  } else {
                      alert("Can only rename one clip at a time.");
                  }
                  break;
              case 'copy': onCopyClips(idsToActOn); break;
              case 'loop': idsToActOn.forEach(id => onLoopClip(id)); break;
              case 'flatten': 
                  if (idsToActOn.length === 1 && onFlattenClip) onFlattenClip(idsToActOn[0]); 
                  else if (idsToActOn.length > 1) alert("Flattening multiple clips not supported yet.");
                  break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClips(contextMenu.time, contextMenu.targetId);
           } else if (action === 'import-file') {
               importTargetRef.current = { trackId: contextMenu.targetId, time: contextMenu.time };
               fileInputRef.current?.click();
           }
      } else if (contextMenu.type === 'RULER' && contextMenu.time !== undefined) {
           if (action === 'set-bpm') {
                const val = prompt("Set Tempo (BPM) at this spot:", bpm.toString());
                if (val && !isNaN(parseInt(val))) {
                    const newBpm = parseInt(val);
                    if (setBpm) setBpm(newBpm);
                    if (onAddMarker) onAddMarker(contextMenu.time, `${newBpm} BPM`);
                }
           } else if (action === 'set-signature') {
                const val = prompt("Set Time Signature:", "4/4");
                if (val && onAddMarker) {
                    onAddMarker(contextMenu.time, val);
                }
           }
      }
      setContextMenu(null);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0] && importTargetRef.current) {
          const { trackId, time } = importTargetRef.current;
          onImportAudio(e.target.files[0], trackId, time);
      }
      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];
      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);
      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ left: i * singleLoopWidth, width: singleLoopWidth }}
                 >
                     <Waveform clip={clip} width={singleLoopWidth} height={TRACK_HEIGHT - 10} color={i === 0 ? "#ffffff" : "#ffffffaa"} />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <>
      <div 
        className={`flex-1 relative flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
        ref={timelineRef}
        onClick={handleTimelineClick}
        onMouseDown={handleMouseDown}
      >
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileSelect}
            className="hidden" 
            accept="audio/*,.m4a,.mp4" 
        />

        {/* Marquee Box */}
        {marquee?.active && (
            <div 
                className="absolute bg-blue-500/20 border border-blue-400 z-50 pointer-events-none"
                style={{
                    left: Math.min(marquee.startX, marquee.currentX),
                    top: Math.min(marquee.startY, marquee.currentY),
                    width: Math.abs(marquee.currentX - marquee.startX),
                    height: Math.abs(marquee.currentY - marquee.startY)
                }}
            />
        )}

        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler - Now with sticky top-0 to stick inside the App-level scroll container */}
        <div 
          className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex cursor-context-menu" 
          style={{ width: `${totalBars * pixelsPerBar}px`, height: `${TIMELINE_RULER_HEIGHT}px` }}
          onContextMenu={handleRulerContextMenu}
          title="Right-click to add Tempo or Time Signature changes"
        >
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}

             {/* Markers */}
             {markers.map((m, i) => (
                 <div key={i} className="absolute top-0 h-full border-l border-blue-500/50 flex flex-col justify-end" style={{ left: m.time * zoom }}>
                     <span className="bg-blue-600 text-white text-[9px] px-1 rounded-r shadow">{m.label}</span>
                 </div>
             ))}

             {/* Loop Region Overlay */}
             {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 h-full bg-yellow-400/20 border-l border-r border-yellow-400/50 group loop-region-handle cursor-move"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                    onMouseDown={(e) => handleLoopDragStart(e, 'MOVE')}
                 >
                     <div className="absolute top-0 left-0 w-full h-1 bg-yellow-400/50"></div>

                     {/* Handles */}
                     <div 
                        className="absolute top-0 left-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'START')}
                     />
                     <div 
                        className="absolute top-0 right-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'END')}
                     />
                 </div>
             )}
        </div>

        <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
          {/* Loop Region Background Highlight (Extends down tracks) */}
          {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 bottom-0 bg-white/5 pointer-events-none z-0"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                 />
          )}

          {tracks.map(track => {
            return (
                <div key={track.id} className="flex flex-col z-10">
                  <div 
                      className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                      onDragOver={handleDragOver}
                      onDrop={(e) => handleDrop(e, track.id)}
                      onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                      style={{ 
                          height: `${TRACK_HEIGHT}px`,
                          backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                          backgroundSize: `${pixelsPerBar}px 100%`,
                          backgroundPosition: '0 0'
                      }}
                  >
                      <div 
                          className="absolute inset-0 pointer-events-none" 
                          style={{ backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)', backgroundSize: `${pixelsPerBeat}px 100%`, opacity: 0.1 }}
                      />

                      {clips.filter(c => c.trackId === track.id).map(clip => {
                          const isSelected = selectedClipIds.includes(clip.id);
                          return (
                          <div
                              key={clip.id}
                              data-clip-id={clip.id}
                              draggable={tool === 'MOVE'}
                              onDragStart={(e) => handleDragStart(e, clip)}
                              onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                              onClick={(e) => e.stopPropagation()} 
                              onMouseDown={(e) => { if (tool === 'MOVE' && !isSelected && !e.shiftKey) setSelectedClipIds([clip.id]); }}
                              className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                              ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                              ${isSelected ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                              style={{ left: `${clip.startTime * zoom}px`, width: `${clip.duration * zoom}px` }}
                          >
                              <div className="absolute inset-0 opacity-60" style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}></div>
                              {clip.loop && <div className="absolute top-0 right-4 p-1 text-white/70 z-30"><RotateCw size={10} /></div>}
                              <div className="absolute inset-0 z-10">{renderClipContent(clip, track)}</div>
                              <div className="absolute top-1 left-1 z-20 max-w-full"><div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">{clip.name}</div></div>
                              {tool === 'MOVE' && isSelected && selectedClipIds.length === 1 && <div className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle" onMouseDown={(e) => handleResizeStart(e, clip)}><GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" /></div>}
                          </div>
                      )})}
                  </div>

                  {track.showAutomation && (
                      <div 
                          className="bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair box-border"
                          data-automation-track-id={track.id}
                          style={{ minWidth: `${totalBars * pixelsPerBar}px`, height: `${AUTOMATION_HEIGHT}px` }}
                      >
                          <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                          <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">{track.selectedAutomationId === 'pan' ? 'Pan' : track.selectedAutomationId === 'volume' ? 'Vol' : track.selectedAutomationId?.split(':')[1].toUpperCase()}</div>
                          <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>{renderAutomationPoints(track)}</svg>
                      </div>
                  )}
                </div>
            );
          })}
          <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">End of tracks</div>
        </div>

        {contextMenu && (
            <div 
                className="fixed z-50 w-56 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
                style={{ top: contextMenu.y, left: contextMenu.x }}
            >
                {contextMenu.type === 'CLIP' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Copy</button>
                      <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><RotateCw size={14} /> Toggle Loop</button>
                      <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Pencil size={14} /> Rename</button>
                      <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Duplicate</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'flatten')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2 text-blue-400"><FileStack size={14} /> Flatten Clip</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2"><Trash2 size={14} /> Delete</button>
                    </>
                ) : contextMenu.type === 'BACKGROUND' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'paste')} disabled={!canPaste} className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}><ClipboardPaste size={14} /> Paste</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'import-file')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Upload size={14} className="text-blue-400" /> Import Audio File</button>
                    </>
                ) : (
                    <>
                        <div className="px-4 py-2 text-xs font-bold text-gray-500 uppercase">Marker Options</div>
                        <button onClick={(e) => handleMenuAction(e, 'set-bpm')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Activity size={14} className="text-green-400" /> Set Global Tempo</button>
                        <button onClick={(e) => handleMenuAction(e, 'set-signature')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Clock size={14} className="text-purple-400" /> Set Time Signature</button>
                    </>
                )}
            </div>
        )}
      </div>
    </>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { MasterVisualizer } from './components/MasterVisualizer';
import { SettingsModal } from './components/SettingsModal';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, LoopRegion } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [timeMarkers, setTimeMarkers] = useState<{time: number, label: string}[]>([]);

  // Metronome State
  const [isMetronomeOn, setIsMetronomeOn] = useState(false);
  const [countInMeasures, setCountInMeasures] = useState(1);

  // Loop State (Default measures 1-4 -> 0s to 8s at 120bpm)
  const [loopRegion, setLoopRegion] = useState<LoopRegion>({ start: 0, end: 8, enabled: false });
  // Ref for loop region to access in RAF without re-binding
  const loopRegionRef = useRef(loopRegion);

  useEffect(() => {
      loopRegionRef.current = loopRegion;
  }, [loopRegion]);

  // Recording State
  const [armedTrackId, setArmedTrackId] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  // Selection State (Multi-select)
  const [selectedClipIds, setSelectedClipIds] = useState<string[]>([]);
  const [clipboardClips, setClipboardClips] = useState<AudioClip[]>([]);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Refs ---
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const navigatorRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0); // Timeline position where recording block starts
  const recordPreRollRef = useRef<number>(0); // How much physical audio was captured BEFORE timeline start

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Navigator Scroll Sync ---
  const handleMainScroll = () => {
      if (scrollContainerRef.current && navigatorRef.current) {
          navigatorRef.current.scrollLeft = scrollContainerRef.current.scrollLeft;
      }
  };

  const handleNavigatorScroll = (e: React.UIEvent<HTMLDivElement>) => {
      const target = e.target as HTMLDivElement;
      if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollLeft = target.scrollLeft;
      }
  };

  // --- Smart Zoom Handling ---
  const handleZoomChange = useCallback((newZoom: number) => {
      const clampedZoom = Math.max(10, Math.min(500, newZoom));
      setZoom(clampedZoom);

      // Center playhead logic
      if (scrollContainerRef.current) {
          requestAnimationFrame(() => {
              if (scrollContainerRef.current) {
                  const containerWidth = scrollContainerRef.current.clientWidth;
                  const playheadX = playbackState.currentTime * clampedZoom;
                  // Center playhead: target scroll is playheadX - halfWidth
                  const targetScroll = Math.max(0, playheadX - (containerWidth / 2));
                  scrollContainerRef.current.scrollLeft = targetScroll;
              }
          });
      }
  }, [playbackState.currentTime]);

  // --- Undo/Redo System ---
  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks);
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex - 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks);
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };

  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stopPlayback(); 
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    // Schedule metronome if enabled
    if (isMetronomeOn) {
        audioService.scheduleMetronome(bpm, audioService.getContext().currentTime, 300); // Schedule 5 mins of clicks
    }

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true, currentTime: startAt }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      // Loop Check using REF to avoid closure staleness
      if (loopRegionRef.current.enabled && newTime >= loopRegionRef.current.end) {
          startPlayback(loopRegionRef.current.start);
          return; 
      }

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks, bpm, isMetronomeOn]); 

  const handleSeek = useCallback((time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));

      // If playing, we need to restart playback at new position
      if (playbackState.isPlaying) {
           startPlayback(time);
      }
  }, [playbackState.isPlaying, startPlayback]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (isRecording) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [isRecording]);

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---
  const handleArmTrack = async (trackId: string) => {
      if (armedTrackId === trackId) {
          setArmedTrackId(null);
          audioService.disableMonitoring();
      } else {
          try {
              // Critical: Await monitoring setup BEFORE updating state to ensure visualizer is ready
              await audioService.enableMonitoring(trackId); 
              setArmedTrackId(trackId);
          } catch(e) {
              alert("Could not access microphone.");
              setArmedTrackId(null);
          }
      }
  };

  const handleTransportRecord = async () => {
      if (isRecording) {
          handleStop();
      } else {
          if (!armedTrackId) {
              alert("Please arm a track first.");
              return;
          }
          try {
            await audioService.resume();

            // 1. Start Recording Physically FIRST to capture pre-roll/setup
            await audioService.startRecording();
            const sysRecordStart = audioService.getContext().currentTime;

            // 2. Count-In Logic (if enabled)
            if (countInMeasures > 0) {
                 await audioService.playCountIn(bpm, countInMeasures);
            } else {
                 // Even without count-in, wait a tiny bit to ensure we capture the transient of the first beat
                 await new Promise(r => setTimeout(r, 100));
            }

            // 3. Start Playback Transport
            const sysPlaybackStart = audioService.getContext().currentTime;

            // Calculate how much audio we captured before the transport actually started
            const preRollDuration = sysPlaybackStart - sysRecordStart;

            setIsRecording(true);
            recordStartTimeRef.current = pauseTimeRef.current;
            recordPreRollRef.current = preRollDuration;

            startPlayback(pauseTimeRef.current);
          } catch(e) {
              console.error("Recording failed to start", e);
              alert("Failed to start recording. Please check microphone permissions.");
          }
      }
  };

  const finishRecording = async () => {
      if (!armedTrackId) {
          setIsRecording(false);
          return;
      }
      const blob = await audioService.stopRecording();
      const timelineStart = recordStartTimeRef.current;
      const preRoll = recordPreRollRef.current;

      if (blob && blob.size > 0) {
          try {
              const buffer = await audioService.decodeBlob(blob);

              // --- Latency Compensation & Placement ---
              const latency = audioService.latencySeconds;

              // The buffer contains [PreRoll] + [Performance].
              // The Performance started at buffer time = preRoll + latency (approx).
              // We want this point to align with `timelineStart`.

              // Theoretical Offset into buffer for T=timelineStart
              let targetOffset = preRoll + latency;

              // Safety: Reveal a bit of the pre-roll to catch early transients (rushing).
              // We shift the clip START TIME back by `safetyMargin` and reduce OFFSET by same amount.
              const safetyMargin = Math.min(preRoll, 0.2); // Up to 200ms

              const finalClipStart = timelineStart - safetyMargin;
              const finalClipOffset = targetOffset - safetyMargin;

              // Duration needs to be calculated based on what's left in the buffer
              // Buffer Duration - Offset = Playable Length
              // But we added safetyMargin to length by reducing offset.
              const finalDuration = Math.max(0, buffer.duration - finalClipOffset);

              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: armedTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: finalClipStart, // Can be negative or < timelineStart
                  duration: finalDuration,
                  offset: Math.max(0, finalClipOffset),
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };

              if (finalDuration > 0) {
                  updateStateWithHistory(tracks, [...clips, newClip]);
              }
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }
      setIsRecording(false);
  };

  // --- Track Management ---
  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) points[existingIdx] = point;
             else points.push(point);
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---
  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  // Batch Update for moving multiple clips
  const updateClips = (updates: { id: string, startTime: number, trackId?: string }[]) => {
      const newClips = clips.map(c => {
          const update = updates.find(u => u.id === c.id);
          if (update) {
              // Prevent moving to master track
              if (update.trackId === 'master') return c;
              return { ...c, startTime: update.startTime, trackId: update.trackId || c.trackId };
          }
          return c;
      });
      setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  // --- Batch Operations (Delete, Duplicate, Copy, Paste) ---

  const deleteClips = (ids: string[]) => {
      const newClips = clips.filter(c => !ids.includes(c.id));
      setSelectedClipIds([]);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClips = (ids: string[]) => {
      const clipsToDuplicate = clips.filter(c => ids.includes(c.id));
      if (clipsToDuplicate.length === 0) return;

      // Find the range of the selection to determine offset
      const startTimes = clipsToDuplicate.map(c => c.startTime);
      const endTimes = clipsToDuplicate.map(c => c.startTime + c.duration);
      const minStart = Math.min(...startTimes);
      const maxEnd = Math.max(...endTimes);
      const selectionDuration = maxEnd - minStart;

      const newClips = [...clips];
      const newIds: string[] = [];

      clipsToDuplicate.forEach(original => {
          const newId = uuidv4();
          newIds.push(newId);
          newClips.push({
              ...original,
              id: newId,
              // Place duplicates immediately after the selection group
              startTime: original.startTime + selectionDuration, 
              name: `${original.name} (Copy)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleFlattenClip = async (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (!clip) return;

      try {
          const newBuffer = await audioService.bounceClip(clip);
          const newClip: AudioClip = {
              ...clip,
              buffer: newBuffer,
              offset: 0,
              duration: clip.duration, 
              playbackRate: 1, 
              name: `${clip.name} (Flattened)`,
              loop: false 
          };

          const newClips = clips.map(c => c.id === id ? newClip : c);
          updateStateWithHistory(tracks, newClips);
          // Keep selection
          if (selectedClipIds.includes(id)) {
              // no-op, still selected
          }
      } catch (e) {
          console.error("Flatten failed", e);
          alert("Could not flatten clip.");
      }
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;
      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return;

      const firstDuration = relativeSplit * clip.playbackRate;
      const leftClip: AudioClip = { ...clip, id: uuidv4(), duration: firstDuration, name: clip.name };
      const rightClip: AudioClip = { ...clip, id: uuidv4(), startTime: splitTime, offset: clip.offset + firstDuration, duration: clip.duration - firstDuration, name: clip.name };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      // Update selection to the new clips if original was selected
      if (selectedClipIds.includes(clipId)) {
          setSelectedClipIds([leftClip.id, rightClip.id]);
      }

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClips = (ids: string[]) => {
      const selected = clips.filter(c => ids.includes(c.id));
      if (selected.length > 0) setClipboardClips(selected);
  };

  const handlePasteClips = (time: number, targetTrackId: string) => {
      if (clipboardClips.length === 0 || targetTrackId === 'master') return;

      // Calculate relative offsets based on the earliest clip in clipboard
      const minStartTime = Math.min(...clipboardClips.map(c => c.startTime));
      // Identify the "primary" track (e.g., the top-most track in the selection) to map relative track offsets
      // For simplicity in this version, we paste EVERYTHING starting at the targetTrackId
      // But if clips are on different tracks, we should try to preserve relative track spacing if possible.
      // Simpler approach: Flatten vertical structure or paste all to target track?
      // Let's paste all to target track but preserve Time offsets.

      const newClips = [...clips];
      const newIds: string[] = [];

      clipboardClips.forEach(clip => {
          const relativeTime = clip.startTime - minStartTime;
          const newId = uuidv4();
          newIds.push(newId);

          newClips.push({
              ...clip,
              id: newId,
              startTime: time + relativeTime,
              trackId: targetTrackId, // Collapse to the track where user right-clicked for now
              name: `${clip.name} (Paste)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;
          const newClips = clips.map(c => c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---
  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const handleExportStems = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          for (const track of tracks) {
             if (track.isMaster) continue;
             const trackClips = clips.filter(c => c.trackId === track.id);
             if (trackClips.length === 0) continue;

             const blob = await audioService.renderOffline(trackClips, [track, MASTER_TRACK]);

             const url = URL.createObjectURL(blob);
             const a = document.createElement('a');
             a.href = url;
             a.download = `${track.name}_Stem.wav`;
             a.click();
             URL.revokeObjectURL(url);

             await new Promise(r => setTimeout(r, 500));
          }
      } catch (e) {
          console.error("Stem Export failed", e);
          alert("Stem Export failed.");
      } finally {
          setIsExporting(false);
          setIsSettingsOpen(false);
      }
  };

  // --- Derived State & Variables ---
  const regularTracks = tracks.filter(t => !t.isMaster);
  const masterTrack = tracks.find(t => t.isMaster) || MASTER_TRACK;

  // Only show editor if exactly one clip is selected
  const selectedClip = selectedClipIds.length === 1 
      ? clips.find(c => c.id === selectedClipIds[0]) || null
      : null;

  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration));
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const pixelsPerBar = secondsPerBar * zoom;
  const timelineWidth = totalBars * pixelsPerBar;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <SettingsModal 
          isOpen={isSettingsOpen} 
          onClose={() => setIsSettingsOpen(false)}
          onExportStems={handleExportStems}
      />

      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        isRecording={isRecording}
        onRecord={handleTransportRecord}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={(newBpm) => {
            setBpm(newBpm);
        }}
        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={handleZoomChange}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
        loopRegion={loopRegion}
        setLoopRegion={setLoopRegion}
        isMetronomeOn={isMetronomeOn}
        toggleMetronome={() => setIsMetronomeOn(!isMetronomeOn)}
        countInMeasures={countInMeasures}
        setCountInMeasures={setCountInMeasures}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      {/* Main Workspace: Single Unified Scroll Container */}
      <div 
        className="flex-1 overflow-auto relative" 
        ref={scrollContainerRef}
        onScroll={handleMainScroll}
      >
        <div className="flex min-w-max">
            {/* Sticky Left Column (Headers) */}
            <div 
                className="sticky left-0 z-30 bg-gray-900 border-r border-gray-700 flex flex-col flex-shrink-0 shadow-lg"
                style={{ width: TRACK_HEADER_WIDTH }}
            >
                 {/* Sticky Top-Left Corner */}
                 <div 
                    className="sticky top-0 z-40 bg-gray-900 border-b border-gray-700 flex-shrink-0"
                    style={{ height: TIMELINE_RULER_HEIGHT }}
                 />

                 {/* Track Headers List */}
                 {regularTracks.map(track => (
                    <TrackControl 
                        key={track.id} 
                        track={track} 
                        onUpdate={updateTrack}
                        onDelete={deleteTrack}
                        isArmed={armedTrackId === track.id}
                        isRecordingGlobal={isRecording}
                        onArmToggle={() => handleArmTrack(track.id)}
                        onOpenEditor={setEditingTrackId}
                        onToggleAutomation={toggleAutomation}
                    />
                 ))}

                 <div className="p-3">
                     <button 
                        onClick={addTrack}
                        className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                        title="Add a new audio track"
                     >
                        <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors"><Plus size={14} /></div>
                        <span>Add Track</span>
                     </button>
                 </div>

                 {/* Bottom Spacer */}
                 <div className="h-64 bg-gray-900" />
            </div>

            {/* Main Timeline Area (Scrolls with parent) */}
            <div className="flex flex-col flex-1">
                {/* Timeline Component - renders Ruler (sticky inside) and Tracks */}
                <Timeline 
                    tracks={regularTracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipsUpdate={updateClips} // Batch update
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={handleZoomChange}
                    snap={snap}
                    tool={tool}

                    selectedClipIds={selectedClipIds}
                    setSelectedClipIds={setSelectedClipIds}

                    onDeleteClips={deleteClips}
                    onDuplicateClips={duplicateClips}
                    onCopyClips={handleCopyClips}
                    onPasteClips={handlePasteClips}
                    canPaste={clipboardClips.length > 0}

                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}
                    onClipResize={handleClipResize}
                    onLoopClip={handleLoopToggle}
                    onFlattenClip={handleFlattenClip}

                    loopRegion={loopRegion}
                    setLoopRegion={setLoopRegion}
                    onImportAudio={handleFileDrop}
                    markers={timeMarkers}
                    onAddMarker={(time, label) => setTimeMarkers([...timeMarkers, {time, label}])}
                    setBpm={setBpm}
                />
            </div>
        </div>
      </div>

      {/* Fixed Bottom Master Section */}
      <div className="h-44 bg-gray-900 border-t-2 border-gray-800 flex flex-col z-50 shadow-[0_-5px_15px_rgba(0,0,0,0.5)]">
         {/* Master Row */}
         <div className="flex flex-1 overflow-hidden">
             {/* Master Control (Left) */}
             <div className="flex-shrink-0 border-r border-gray-800" style={{ width: TRACK_HEADER_WIDTH }}>
                <TrackControl 
                  track={masterTrack}
                  onUpdate={updateTrack}
                  onDelete={() => {}}
                  isArmed={false}
                  isRecordingGlobal={false}
                  onArmToggle={() => {}}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={() => {}}
                />
             </div>
             {/* Master Visualizer (Right) */}
             <div className="flex-1 p-2 bg-gray-900 flex items-center justify-center">
                 <MasterVisualizer isPlaying={playbackState.isPlaying} />
             </div>
         </div>

         {/* Navigator / Scrollbar (Bottom Fixed) */}
         <div className="h-5 bg-gray-950 border-t border-gray-800">
             <div 
                ref={navigatorRef}
                onScroll={handleNavigatorScroll}
                className="w-full h-full overflow-x-auto overflow-y-hidden custom-scrollbar"
                title="Timeline Navigator"
             >
                <div style={{ width: timelineWidth + TRACK_HEADER_WIDTH, height: '1px' }}></div>
             </div>
         </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipIds([])}
            projectBpm={bpm}
          />
      )}
    </div>
  );
}

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint, LoopRegion } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, GripVertical, Upload, Clock, Activity, FileStack } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipsUpdate: (updates: { id: string, startTime: number, trackId?: string }[]) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;

  // Selection & Batch Ops
  selectedClipIds: string[];
  setSelectedClipIds: (ids: string[]) => void;
  onDeleteClips: (ids: string[]) => void;
  onDuplicateClips: (ids: string[]) => void;
  onCopyClips: (ids: string[]) => void;
  onPasteClips: (time: number, trackId: string) => void;
  canPaste: boolean;

  onRenameClip: (id: string, newName: string) => void;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;

  loopRegion: LoopRegion;
  setLoopRegion: (region: LoopRegion) => void;

  onImportAudio: (file: File, trackId: string, time: number) => void;

  markers?: {time: number, label: string}[];
  onAddMarker?: (time: number, label: string) => void;
  setBpm?: (bpm: number) => void;

  onFlattenClip?: (id: string) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND' | 'RULER';
    targetId?: string; // ClipId or TrackId
    time?: number; 
}

interface MarqueeState {
    startX: number;
    startY: number;
    currentX: number;
    currentY: number;
    active: boolean;
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipsUpdate, 
  onFileDrop,
  onSeek,
  selectedClipIds,
  setSelectedClipIds,
  onDeleteClips,
  onDuplicateClips,
  onCopyClips,
  onPasteClips,
  canPaste,
  onRenameClip,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize,
  loopRegion,
  setLoopRegion,
  onImportAudio,
  markers = [],
  onAddMarker,
  setBpm,
  onFlattenClip
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  // Keep track of the initial offset for ALL selected clips during a drag
  const [dragOffsets, setDragOffsets] = useState<{ [id: string]: number }>({});

  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  // Marquee State
  const [marquee, setMarquee] = useState<MarqueeState | null>(null);
  const justFinishedMarqueeRef = useRef(false);

  // Loop Dragging State
  const [loopDragType, setLoopDragType] = useState<'START' | 'END' | 'MOVE' | null>(null);
  const [loopDragStartX, setLoopDragStartX] = useState<number>(0);
  const [loopDragStartValues, setLoopDragStartValues] = useState<{start: number, end: number}>({start:0, end:0});

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // Refs for File Import
  const fileInputRef = useRef<HTMLInputElement>(null);
  const importTargetRef = useRef<{trackId: string, time: number} | null>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      return Math.round(time / beat) * beat;
  };

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) {
               setDraggedClipId(null);
               setDragOffsets({});
           }
           if (resizingClipId) setResizingClipId(null);
           if (loopDragType) setLoopDragType(null);
           if (marquee?.active) {
               setMarquee(null);
               // Set a flag to prevent the subsequent 'click' event from clearing selection
               justFinishedMarqueeRef.current = true;
               setTimeout(() => { justFinishedMarqueeRef.current = false; }, 100);
           }
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId, loopDragType, marquee]);

  // Global Mouse Move (for operations like resizing, box select, etc that extend beyond the div)
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;
          const rect = timelineRef.current.getBoundingClientRect();
          const relativeX = e.clientX - rect.left + timelineRef.current.scrollLeft;
          const relativeY = e.clientY - rect.top + timelineRef.current.scrollTop;

          if (marquee?.active) {
              setMarquee(prev => prev ? { ...prev, currentX: relativeX, currentY: relativeY } : null);

              // Calculate Selection Logic
              // Define Marquee Box
              const mX = Math.min(marquee.startX, relativeX);
              const mY = Math.min(marquee.startY, relativeY);
              const mW = Math.abs(relativeX - marquee.startX);
              const mH = Math.abs(relativeY - marquee.startY);

              // DOM-based collision for accuracy
              const newSelectedIds: string[] = [];
              const clipElements = timelineRef.current.querySelectorAll('[data-clip-id]');

              clipElements.forEach(el => {
                  const clipRect = el.getBoundingClientRect();
                  // Convert clip rect to relative coordinates within timelineRef
                  const clipRelX = clipRect.left - rect.left + timelineRef.current!.scrollLeft;
                  const clipRelY = clipRect.top - rect.top + timelineRef.current!.scrollTop;

                  // AABB Collision
                  if (mX < clipRelX + clipRect.width &&
                      mX + mW > clipRelX &&
                      mY < clipRelY + clipRect.height &&
                      mY + mH > clipRelY) {
                          const id = el.getAttribute('data-clip-id');
                          if (id) newSelectedIds.push(id);
                      }
              });

              // Only update if changed to avoid unnecessary re-renders
              // Note: Using JSON stringify for simple array comparison
              setSelectedClipIds(newSelectedIds);
              return;
          }

          if (loopDragType) {
              const diffPixels = e.clientX - loopDragStartX;
              const diffSeconds = diffPixels / zoom;

              let newStart = loopDragStartValues.start;
              let newEnd = loopDragStartValues.end;

              if (loopDragType === 'START') {
                  newStart = Math.min(newEnd - 0.25, Math.max(0, loopDragStartValues.start + diffSeconds));
              } else if (loopDragType === 'END') {
                  newEnd = Math.max(newStart + 0.25, loopDragStartValues.end + diffSeconds);
              } else if (loopDragType === 'MOVE') {
                  const duration = loopDragStartValues.end - loopDragStartValues.start;
                  newStart = Math.max(0, loopDragStartValues.start + diffSeconds);
                  newEnd = newStart + duration;
              }

              if (snap) {
                  newStart = snapToGrid(newStart);
                  newEnd = snapToGrid(newEnd);
                  if (newEnd <= newStart) newEnd = newStart + secondsPerBeat;
              }

              setLoopRegion({ ...loopRegion, start: newStart, end: newEnd });
              return;
          }

          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); 
             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;
             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId || loopDragType || marquee?.active) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize, loopDragType, loopDragStartX, loopDragStartValues, loopRegion, setLoopRegion, bpm, marquee]);

  // Wheel Zoom
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom));
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId || loopDragType) return;

    // If we just finished a marquee selection, DO NOT clear the selection.
    if (justFinishedMarqueeRef.current) {
        justFinishedMarqueeRef.current = false;
        return;
    }

    const target = e.target as HTMLElement;
    if (target.closest('.loop-region-handle')) return;

    const clipElement = target.closest('[data-clip-id]');

    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
                 const time = Math.max(0, clickX / zoom);

                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));
                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    // Background Click
    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        // If clicking (not dragging), deselect all and seek
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;

        if (!marquee?.active) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const seekTime = Math.max(0, (clickX / zoom));
             onSeek(snapToGrid(seekTime));
             setSelectedClipIds([]); // Clear selection on explicit background click
        }
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      // Check if clicking on background to start marquee
      const target = e.target as HTMLElement;
      if (!target.closest('[data-clip-id]') && !target.closest('.loop-region-handle') && !target.closest('[data-automation-track-id]')) {
          if (tool === 'MOVE') {
              const rect = timelineRef.current!.getBoundingClientRect();
              const x = e.clientX - rect.left + timelineRef.current!.scrollLeft;
              const y = e.clientY - rect.top + timelineRef.current!.scrollTop;

              setMarquee({
                  startX: x,
                  startY: y,
                  currentX: x,
                  currentY: y,
                  active: true
              });
          }
      }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        const isAudio = file.type.startsWith('audio/') || 
                        file.type === 'video/mp4' || 
                        file.name.toLowerCase().endsWith('.m4a');
        if (isAudio) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        // Multi-clip move logic
        const draggedClip = clips.find(c => c.id === draggedClipId);
        if (!draggedClip) return;

        // Determine if we are moving a group or single
        const movingIds = selectedClipIds.includes(draggedClipId) ? selectedClipIds : [draggedClipId];

        // Calculate the delta for the PRIMARY dragged clip
        const primaryOffset = dragOffsets[draggedClipId] || 0;
        const newPrimaryTime = Math.max(0, dropTime - primaryOffset);
        const timeDelta = newPrimaryTime - draggedClip.startTime; // How much it moved

        const updates = movingIds.map(id => {
            const clip = clips.find(c => c.id === id);
            if (!clip) return null;

            return {
                id: clip.id,
                startTime: Math.max(0, clip.startTime + timeDelta),
                trackId: id === draggedClipId ? trackId : clip.trackId 
            };
        }).filter(Boolean) as { id: string, startTime: number, trackId?: string }[];

        onClipsUpdate(updates);
        setDraggedClipId(null);
        setDragOffsets({});
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }

     // If the clicked clip is NOT in the selection, clear selection and select it
     let currentSelection = selectedClipIds;
     if (!selectedClipIds.includes(clip.id)) {
         setSelectedClipIds([clip.id]);
         currentSelection = [clip.id];
     }

     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     const offsets: {[id:string]: number} = {};
     currentSelection.forEach(id => {
         offsets[id] = offsetTime; 
     });

     setDragOffsets(offsets);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      if (!selectedClipIds.includes(clip.id)) {
          setSelectedClipIds([clip.id]);
      }
  };

  const handleLoopDragStart = (e: React.MouseEvent, type: 'START' | 'END' | 'MOVE') => {
      e.stopPropagation();
      e.preventDefault();
      setLoopDragType(type);
      setLoopDragStartX(e.clientX);
      setLoopDragStartValues({ start: loopRegion.start, end: loopRegion.end });
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();

      // If we are right-clicking a selected item, keep selection.
      // If we are right-clicking an unselected item, select only that item.
      if (!selectedClipIds.includes(clipId)) {
          setSelectedClipIds([clipId]);
      }

      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleRulerContextMenu = (e: React.MouseEvent) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'RULER',
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP') {
           const targetIsSelected = contextMenu.targetId && selectedClipIds.includes(contextMenu.targetId);
           const idsToActOn = targetIsSelected ? selectedClipIds : (contextMenu.targetId ? [contextMenu.targetId] : []);

           switch(action) {
              case 'delete': onDeleteClips(idsToActOn); break;
              case 'duplicate': onDuplicateClips(idsToActOn); break;
              case 'rename': 
                  if (idsToActOn.length === 1) {
                      const clip = clips.find(c => c.id === idsToActOn[0]);
                      if (clip) {
                          const newName = prompt("Rename clip:", clip.name);
                          if (newName) onRenameClip(idsToActOn[0], newName);
                      }
                  } else {
                      alert("Can only rename one clip at a time.");
                  }
                  break;
              case 'copy': onCopyClips(idsToActOn); break;
              case 'loop': idsToActOn.forEach(id => onLoopClip(id)); break;
              case 'flatten': 
                  if (idsToActOn.length === 1 && onFlattenClip) onFlattenClip(idsToActOn[0]); 
                  else if (idsToActOn.length > 1) alert("Flattening multiple clips not supported yet.");
                  break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClips(contextMenu.time, contextMenu.targetId);
           } else if (action === 'import-file') {
               importTargetRef.current = { trackId: contextMenu.targetId, time: contextMenu.time };
               fileInputRef.current?.click();
           }
      } else if (contextMenu.type === 'RULER' && contextMenu.time !== undefined) {
           if (action === 'set-bpm') {
                const val = prompt("Set Tempo (BPM) at this spot:", bpm.toString());
                if (val && !isNaN(parseInt(val))) {
                    const newBpm = parseInt(val);
                    if (setBpm) setBpm(newBpm);
                    if (onAddMarker) onAddMarker(contextMenu.time, `${newBpm} BPM`);
                }
           } else if (action === 'set-signature') {
                const val = prompt("Set Time Signature:", "4/4");
                if (val && onAddMarker) {
                    onAddMarker(contextMenu.time, val);
                }
           }
      }
      setContextMenu(null);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0] && importTargetRef.current) {
          const { trackId, time } = importTargetRef.current;
          onImportAudio(e.target.files[0], trackId, time);
      }
      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];
      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);
      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ left: i * singleLoopWidth, width: singleLoopWidth }}
                 >
                     <Waveform clip={clip} width={singleLoopWidth} height={TRACK_HEIGHT - 10} color={i === 0 ? "#ffffff" : "#ffffffaa"} />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <>
      <div 
        className={`flex-1 relative flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
        ref={timelineRef}
        onClick={handleTimelineClick}
        onMouseDown={handleMouseDown}
      >
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileSelect}
            className="hidden" 
            accept="audio/*,.m4a,.mp4" 
        />

        {/* Marquee Box */}
        {marquee?.active && (
            <div 
                className="absolute bg-blue-500/20 border border-blue-400 z-50 pointer-events-none"
                style={{
                    left: Math.min(marquee.startX, marquee.currentX),
                    top: Math.min(marquee.startY, marquee.currentY),
                    width: Math.abs(marquee.currentX - marquee.startX),
                    height: Math.abs(marquee.currentY - marquee.startY)
                }}
            />
        )}

        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler - Now with sticky top-0 to stick inside the App-level scroll container */}
        <div 
          className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex cursor-context-menu" 
          style={{ width: `${totalBars * pixelsPerBar}px`, height: `${TIMELINE_RULER_HEIGHT}px` }}
          onContextMenu={handleRulerContextMenu}
          title="Right-click to add Tempo or Time Signature changes"
        >
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}

             {/* Markers */}
             {markers.map((m, i) => (
                 <div key={i} className="absolute top-0 h-full border-l border-blue-500/50 flex flex-col justify-end" style={{ left: m.time * zoom }}>
                     <span className="bg-blue-600 text-white text-[9px] px-1 rounded-r shadow">{m.label}</span>
                 </div>
             ))}

             {/* Loop Region Overlay */}
             {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 h-full bg-yellow-400/20 border-l border-r border-yellow-400/50 group loop-region-handle cursor-move"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                    onMouseDown={(e) => handleLoopDragStart(e, 'MOVE')}
                 >
                     <div className="absolute top-0 left-0 w-full h-1 bg-yellow-400/50"></div>

                     {/* Handles */}
                     <div 
                        className="absolute top-0 left-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'START')}
                     />
                     <div 
                        className="absolute top-0 right-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'END')}
                     />
                 </div>
             )}
        </div>

        <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
          {/* Loop Region Background Highlight (Extends down tracks) */}
          {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 bottom-0 bg-white/5 pointer-events-none z-0"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                 />
          )}

          {tracks.map(track => {
            return (
                <div key={track.id} className="flex flex-col z-10">
                  <div 
                      className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                      onDragOver={handleDragOver}
                      onDrop={(e) => handleDrop(e, track.id)}
                      onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                      style={{ 
                          height: `${TRACK_HEIGHT}px`,
                          backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                          backgroundSize: `${pixelsPerBar}px 100%`,
                          backgroundPosition: '0 0'
                      }}
                  >
                      <div 
                          className="absolute inset-0 pointer-events-none" 
                          style={{ backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)', backgroundSize: `${pixelsPerBeat}px 100%`, opacity: 0.1 }}
                      />

                      {clips.filter(c => c.trackId === track.id).map(clip => {
                          const isSelected = selectedClipIds.includes(clip.id);
                          return (
                          <div
                              key={clip.id}
                              data-clip-id={clip.id}
                              draggable={tool === 'MOVE'}
                              onDragStart={(e) => handleDragStart(e, clip)}
                              onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                              onClick={(e) => e.stopPropagation()} 
                              onMouseDown={(e) => { if (tool === 'MOVE' && !isSelected && !e.shiftKey) setSelectedClipIds([clip.id]); }}
                              className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                              ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                              ${isSelected ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                              style={{ left: `${clip.startTime * zoom}px`, width: `${clip.duration * zoom}px` }}
                          >
                              <div className="absolute inset-0 opacity-60" style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}></div>
                              {clip.loop && <div className="absolute top-0 right-4 p-1 text-white/70 z-30"><RotateCw size={10} /></div>}
                              <div className="absolute inset-0 z-10">{renderClipContent(clip, track)}</div>
                              <div className="absolute top-1 left-1 z-20 max-w-full"><div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">{clip.name}</div></div>
                              {tool === 'MOVE' && isSelected && selectedClipIds.length === 1 && <div className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle" onMouseDown={(e) => handleResizeStart(e, clip)}><GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" /></div>}
                          </div>
                      )})}
                  </div>

                  {track.showAutomation && (
                      <div 
                          className="bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair box-border"
                          data-automation-track-id={track.id}
                          style={{ minWidth: `${totalBars * pixelsPerBar}px`, height: `${AUTOMATION_HEIGHT}px` }}
                      >
                          <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                          <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">{track.selectedAutomationId === 'pan' ? 'Pan' : track.selectedAutomationId === 'volume' ? 'Vol' : track.selectedAutomationId?.split(':')[1].toUpperCase()}</div>
                          <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>{renderAutomationPoints(track)}</svg>
                      </div>
                  )}
                </div>
            );
          })}
          <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">End of tracks</div>
        </div>

        {contextMenu && (
            <div 
                className="fixed z-50 w-56 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
                style={{ top: contextMenu.y, left: contextMenu.x }}
            >
                {contextMenu.type === 'CLIP' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Copy</button>
                      <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><RotateCw size={14} /> Toggle Loop</button>
                      <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Pencil size={14} /> Rename</button>
                      <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Duplicate</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'flatten')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2 text-blue-400"><FileStack size={14} /> Flatten Clip</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2"><Trash2 size={14} /> Delete</button>
                    </>
                ) : contextMenu.type === 'BACKGROUND' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'paste')} disabled={!canPaste} className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}><ClipboardPaste size={14} /> Paste</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'import-file')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Upload size={14} className="text-blue-400" /> Import Audio File</button>
                    </>
                ) : (
                    <>
                        <div className="px-4 py-2 text-xs font-bold text-gray-500 uppercase">Marker Options</div>
                        <button onClick={(e) => handleMenuAction(e, 'set-bpm')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Activity size={14} className="text-green-400" /> Set Global Tempo</button>
                        <button onClick={(e) => handleMenuAction(e, 'set-signature')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Clock size={14} className="text-purple-400" /> Set Time Signature</button>
                    </>
                )}
            </div>
        )}
      </div>
    </>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { MasterVisualizer } from './components/MasterVisualizer';
import { SettingsModal } from './components/SettingsModal';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, LoopRegion } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [timeMarkers, setTimeMarkers] = useState<{time: number, label: string}[]>([]);

  // Metronome State
  const [isMetronomeOn, setIsMetronomeOn] = useState(false);
  const [countInMeasures, setCountInMeasures] = useState(1);

  // Loop State (Default measures 1-4 -> 0s to 8s at 120bpm)
  const [loopRegion, setLoopRegion] = useState<LoopRegion>({ start: 0, end: 8, enabled: false });
  // Ref for loop region to access in RAF without re-binding
  const loopRegionRef = useRef(loopRegion);

  useEffect(() => {
      loopRegionRef.current = loopRegion;
  }, [loopRegion]);

  // Recording State
  const [armedTrackId, setArmedTrackId] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  // Selection State (Multi-select)
  const [selectedClipIds, setSelectedClipIds] = useState<string[]>([]);
  const [clipboardClips, setClipboardClips] = useState<AudioClip[]>([]);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Refs ---
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const navigatorRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0); // Timeline position where recording block starts
  const recordPreRollRef = useRef<number>(0); // How much physical audio was captured BEFORE timeline start

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Navigator Scroll Sync ---
  const handleMainScroll = () => {
      if (scrollContainerRef.current && navigatorRef.current) {
          navigatorRef.current.scrollLeft = scrollContainerRef.current.scrollLeft;
      }
  };

  const handleNavigatorScroll = (e: React.UIEvent<HTMLDivElement>) => {
      const target = e.target as HTMLDivElement;
      if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollLeft = target.scrollLeft;
      }
  };

  // --- Smart Zoom Handling ---
  const handleZoomChange = useCallback((newZoom: number) => {
      const clampedZoom = Math.max(10, Math.min(500, newZoom));
      setZoom(clampedZoom);

      // Center playhead logic
      if (scrollContainerRef.current) {
          requestAnimationFrame(() => {
              if (scrollContainerRef.current) {
                  const containerWidth = scrollContainerRef.current.clientWidth;
                  const playheadX = playbackState.currentTime * clampedZoom;
                  // Center playhead: target scroll is playheadX - halfWidth
                  const targetScroll = Math.max(0, playheadX - (containerWidth / 2));
                  scrollContainerRef.current.scrollLeft = targetScroll;
              }
          });
      }
  }, [playbackState.currentTime]);

  // --- Undo/Redo System ---
  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks);
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex - 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks);
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };

  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stopPlayback(); 
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    // Schedule metronome if enabled
    if (isMetronomeOn) {
        audioService.scheduleMetronome(bpm, audioService.getContext().currentTime, 300); // Schedule 5 mins of clicks
    }

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true, currentTime: startAt }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      // Loop Check using REF to avoid closure staleness
      if (loopRegionRef.current.enabled && newTime >= loopRegionRef.current.end) {
          startPlayback(loopRegionRef.current.start);
          return; 
      }

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks, bpm, isMetronomeOn]); 

  const handleSeek = useCallback((time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));

      // If playing, we need to restart playback at new position
      if (playbackState.isPlaying) {
           startPlayback(time);
      }
  }, [playbackState.isPlaying, startPlayback]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (isRecording) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [isRecording]);

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---
  const handleArmTrack = async (trackId: string) => {
      if (armedTrackId === trackId) {
          setArmedTrackId(null);
          audioService.disableMonitoring();
      } else {
          try {
              // Critical: Await monitoring setup BEFORE updating state to ensure visualizer is ready
              await audioService.enableMonitoring(trackId); 
              setArmedTrackId(trackId);
          } catch(e) {
              alert("Could not access microphone.");
              setArmedTrackId(null);
          }
      }
  };

  const handleTransportRecord = async () => {
      if (isRecording) {
          handleStop();
      } else {
          if (!armedTrackId) {
              alert("Please arm a track first.");
              return;
          }
          try {
            await audioService.resume();

            // 1. Start Recording Physically FIRST to capture pre-roll/setup
            await audioService.startRecording();
            const sysRecordStart = audioService.getContext().currentTime;

            // 2. Count-In Logic (if enabled)
            if (countInMeasures > 0) {
                 await audioService.playCountIn(bpm, countInMeasures);
            } else {
                 // Even without count-in, wait a tiny bit to ensure we capture the transient of the first beat
                 await new Promise(r => setTimeout(r, 100));
            }

            // 3. Start Playback Transport
            const sysPlaybackStart = audioService.getContext().currentTime;

            // Calculate how much audio we captured before the transport actually started
            const preRollDuration = sysPlaybackStart - sysRecordStart;

            setIsRecording(true);
            recordStartTimeRef.current = pauseTimeRef.current;
            recordPreRollRef.current = preRollDuration;

            startPlayback(pauseTimeRef.current);
          } catch(e) {
              console.error("Recording failed to start", e);
              alert("Failed to start recording. Please check microphone permissions.");
          }
      }
  };

  const finishRecording = async () => {
      if (!armedTrackId) {
          setIsRecording(false);
          return;
      }
      const blob = await audioService.stopRecording();
      const timelineStart = recordStartTimeRef.current;
      const preRoll = recordPreRollRef.current;

      if (blob && blob.size > 0) {
          try {
              const buffer = await audioService.decodeBlob(blob);

              // --- Latency Compensation & Placement ---
              const latency = audioService.latencySeconds;

              // The buffer contains [PreRoll] + [Performance].
              // The Performance started at buffer time = preRoll + latency (approx).
              // We want this point to align with `timelineStart`.

              // Theoretical Offset into buffer for T=timelineStart
              let targetOffset = preRoll + latency;

              // Safety: Reveal a bit of the pre-roll to catch early transients (rushing).
              // We shift the clip START TIME back by `safetyMargin` and reduce OFFSET by same amount.
              const safetyMargin = Math.min(preRoll, 0.2); // Up to 200ms

              const finalClipStart = timelineStart - safetyMargin;
              const finalClipOffset = targetOffset - safetyMargin;

              // Duration needs to be calculated based on what's left in the buffer
              // Buffer Duration - Offset = Playable Length
              // But we added safetyMargin to length by reducing offset.
              const finalDuration = Math.max(0, buffer.duration - finalClipOffset);

              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: armedTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: finalClipStart, // Can be negative or < timelineStart
                  duration: finalDuration,
                  offset: Math.max(0, finalClipOffset),
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };

              if (finalDuration > 0) {
                  updateStateWithHistory(tracks, [...clips, newClip]);
              }
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }
      setIsRecording(false);
  };

  // --- Track Management ---
  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) points[existingIdx] = point;
             else points.push(point);
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---
  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  // Batch Update for moving multiple clips
  const updateClips = (updates: { id: string, startTime: number, trackId?: string }[]) => {
      const newClips = clips.map(c => {
          const update = updates.find(u => u.id === c.id);
          if (update) {
              // Prevent moving to master track
              if (update.trackId === 'master') return c;
              return { ...c, startTime: update.startTime, trackId: update.trackId || c.trackId };
          }
          return c;
      });
      setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  // --- Batch Operations (Delete, Duplicate, Copy, Paste) ---

  const deleteClips = (ids: string[]) => {
      const newClips = clips.filter(c => !ids.includes(c.id));
      setSelectedClipIds([]);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClips = (ids: string[]) => {
      const clipsToDuplicate = clips.filter(c => ids.includes(c.id));
      if (clipsToDuplicate.length === 0) return;

      const newClips = [...clips];
      const newIds: string[] = [];

      clipsToDuplicate.forEach(original => {
          const newId = uuidv4();
          newIds.push(newId);
          newClips.push({
              ...original,
              id: newId,
              // Per user request: Place immediately after original
              startTime: original.startTime + original.duration, 
              name: `${original.name} (Copy)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleFlattenClip = async (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (!clip) return;

      try {
          const newBuffer = await audioService.bounceClip(clip);
          const newClip: AudioClip = {
              ...clip,
              buffer: newBuffer,
              offset: 0,
              duration: clip.duration, 
              playbackRate: 1, 
              name: `${clip.name} (Flattened)`,
              loop: false 
          };

          const newClips = clips.map(c => c.id === id ? newClip : c);
          updateStateWithHistory(tracks, newClips);
          // Keep selection
          if (selectedClipIds.includes(id)) {
              // no-op, still selected
          }
      } catch (e) {
          console.error("Flatten failed", e);
          alert("Could not flatten clip.");
      }
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;
      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return;

      const firstDuration = relativeSplit * clip.playbackRate;
      const leftClip: AudioClip = { ...clip, id: uuidv4(), duration: firstDuration, name: clip.name };
      const rightClip: AudioClip = { ...clip, id: uuidv4(), startTime: splitTime, offset: clip.offset + firstDuration, duration: clip.duration - firstDuration, name: clip.name };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      // Update selection to the new clips if original was selected
      if (selectedClipIds.includes(clipId)) {
          setSelectedClipIds([leftClip.id, rightClip.id]);
      }

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClips = (ids: string[]) => {
      const selected = clips.filter(c => ids.includes(c.id));
      if (selected.length > 0) setClipboardClips(selected);
  };

  const handlePasteClips = (time: number, targetTrackId: string) => {
      if (clipboardClips.length === 0 || targetTrackId === 'master') return;

      // Calculate relative offsets based on the earliest clip in clipboard
      const minStartTime = Math.min(...clipboardClips.map(c => c.startTime));

      const newClips = [...clips];
      const newIds: string[] = [];

      clipboardClips.forEach(clip => {
          const relativeTime = clip.startTime - minStartTime;
          const newId = uuidv4();
          newIds.push(newId);

          newClips.push({
              ...clip,
              id: newId,
              startTime: time + relativeTime,
              trackId: targetTrackId, // Collapse to the track where user right-clicked for now
              name: `${clip.name} (Paste)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;
          const newClips = clips.map(c => c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---
  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const handleExportStems = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          for (const track of tracks) {
             if (track.isMaster) continue;
             const trackClips = clips.filter(c => c.trackId === track.id);
             if (trackClips.length === 0) continue;

             const blob = await audioService.renderOffline(trackClips, [track, MASTER_TRACK]);

             const url = URL.createObjectURL(blob);
             const a = document.createElement('a');
             a.href = url;
             a.download = `${track.name}_Stem.wav`;
             a.click();
             URL.revokeObjectURL(url);

             await new Promise(r => setTimeout(r, 500));
          }
      } catch (e) {
          console.error("Stem Export failed", e);
          alert("Stem Export failed.");
      } finally {
          setIsExporting(false);
          setIsSettingsOpen(false);
      }
  };

  // --- Derived State & Variables ---
  const regularTracks = tracks.filter(t => !t.isMaster);
  const masterTrack = tracks.find(t => t.isMaster) || MASTER_TRACK;

  // Only show editor if exactly one clip is selected
  const selectedClip = selectedClipIds.length === 1 
      ? clips.find(c => c.id === selectedClipIds[0]) || null
      : null;

  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration));
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const pixelsPerBar = secondsPerBar * zoom;
  const timelineWidth = totalBars * pixelsPerBar;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <SettingsModal 
          isOpen={isSettingsOpen} 
          onClose={() => setIsSettingsOpen(false)}
          onExportStems={handleExportStems}
      />

      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        isRecording={isRecording}
        onRecord={handleTransportRecord}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={(newBpm) => {
            setBpm(newBpm);
        }}
        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={handleZoomChange}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
        loopRegion={loopRegion}
        setLoopRegion={setLoopRegion}
        isMetronomeOn={isMetronomeOn}
        toggleMetronome={() => setIsMetronomeOn(!isMetronomeOn)}
        countInMeasures={countInMeasures}
        setCountInMeasures={setCountInMeasures}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      {/* Main Workspace: Single Unified Scroll Container */}
      <div 
        className="flex-1 overflow-auto relative" 
        ref={scrollContainerRef}
        onScroll={handleMainScroll}
      >
        <div className="flex min-w-max">
            {/* Sticky Left Column (Headers) */}
            <div 
                className="sticky left-0 z-30 bg-gray-900 border-r border-gray-700 flex flex-col flex-shrink-0 shadow-lg"
                style={{ width: TRACK_HEADER_WIDTH }}
            >
                 {/* Sticky Top-Left Corner */}
                 <div 
                    className="sticky top-0 z-40 bg-gray-900 border-b border-gray-700 flex-shrink-0"
                    style={{ height: TIMELINE_RULER_HEIGHT }}
                 />

                 {/* Track Headers List */}
                 {regularTracks.map(track => (
                    <TrackControl 
                        key={track.id} 
                        track={track} 
                        onUpdate={updateTrack}
                        onDelete={deleteTrack}
                        isArmed={armedTrackId === track.id}
                        isRecordingGlobal={isRecording}
                        onArmToggle={() => handleArmTrack(track.id)}
                        onOpenEditor={setEditingTrackId}
                        onToggleAutomation={toggleAutomation}
                    />
                 ))}

                 <div className="p-3">
                     <button 
                        onClick={addTrack}
                        className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                        title="Add a new audio track"
                     >
                        <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors"><Plus size={14} /></div>
                        <span>Add Track</span>
                     </button>
                 </div>

                 {/* Bottom Spacer */}
                 <div className="h-64 bg-gray-900" />
            </div>

            {/* Main Timeline Area (Scrolls with parent) */}
            <div className="flex flex-col flex-1">
                {/* Timeline Component - renders Ruler (sticky inside) and Tracks */}
                <Timeline 
                    tracks={regularTracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipsUpdate={updateClips} // Batch update
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={handleZoomChange}
                    snap={snap}
                    tool={tool}

                    selectedClipIds={selectedClipIds}
                    setSelectedClipIds={setSelectedClipIds}

                    onDeleteClips={deleteClips}
                    onDuplicateClips={duplicateClips}
                    onCopyClips={handleCopyClips}
                    onPasteClips={handlePasteClips}
                    canPaste={clipboardClips.length > 0}

                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}
                    onClipResize={handleClipResize}
                    onLoopClip={handleLoopToggle}
                    onFlattenClip={handleFlattenClip}

                    loopRegion={loopRegion}
                    setLoopRegion={setLoopRegion}
                    onImportAudio={handleFileDrop}
                    markers={timeMarkers}
                    onAddMarker={(time, label) => setTimeMarkers([...timeMarkers, {time, label}])}
                    setBpm={setBpm}
                />
            </div>
        </div>
      </div>

      {/* Fixed Bottom Master Section */}
      <div className="h-44 bg-gray-900 border-t-2 border-gray-800 flex flex-col z-50 shadow-[0_-5px_15px_rgba(0,0,0,0.5)]">
         {/* Master Row */}
         <div className="flex flex-1 overflow-hidden">
             {/* Master Control (Left) */}
             <div className="flex-shrink-0 border-r border-gray-800" style={{ width: TRACK_HEADER_WIDTH }}>
                <TrackControl 
                  track={masterTrack}
                  onUpdate={updateTrack}
                  onDelete={() => {}}
                  isArmed={false}
                  isRecordingGlobal={false}
                  onArmToggle={() => {}}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={() => {}}
                />
             </div>
             {/* Master Visualizer (Right) */}
             <div className="flex-1 p-2 bg-gray-900 flex items-center justify-center">
                 <MasterVisualizer isPlaying={playbackState.isPlaying} />
             </div>
         </div>

         {/* Navigator / Scrollbar (Bottom Fixed) */}
         <div className="h-5 bg-gray-950 border-t border-gray-800">
             <div 
                ref={navigatorRef}
                onScroll={handleNavigatorScroll}
                className="w-full h-full overflow-x-auto overflow-y-hidden custom-scrollbar"
                title="Timeline Navigator"
             >
                <div style={{ width: timelineWidth + TRACK_HEADER_WIDTH, height: '1px' }}></div>
             </div>
         </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipIds([])}
            projectBpm={bpm}
          />
      )}
    </div>
  );
}

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint, LoopRegion } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, GripVertical, Upload, Clock, Activity, FileStack, Flag } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipsUpdate: (updates: { id: string, startTime: number, trackId?: string }[]) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;

  // Selection & Batch Ops
  selectedClipIds: string[];
  setSelectedClipIds: (ids: string[]) => void;
  onDeleteClips: (ids: string[]) => void;
  onDuplicateClips: (ids: string[]) => void;
  onCopyClips: (ids: string[]) => void;
  onPasteClips: (time: number, trackId: string) => void;
  canPaste: boolean;

  onRenameClip: (id: string, newName: string) => void;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;

  loopRegion: LoopRegion;
  setLoopRegion: (region: LoopRegion) => void;

  onImportAudio: (file: File, trackId: string, time: number) => void;

  markers?: {time: number, label: string, type?: 'BPM' | 'TS', value?: number | string}[];
  onAddMarker?: (time: number, label: string, type?: 'BPM' | 'TS', value?: number | string) => void;
  setBpm?: (bpm: number) => void;

  onFlattenClip?: (id: string) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND' | 'RULER';
    targetId?: string; // ClipId or TrackId
    time?: number; 
}

interface MarqueeState {
    startX: number;
    startY: number;
    currentX: number;
    currentY: number;
    active: boolean;
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipsUpdate, 
  onFileDrop,
  onSeek,
  selectedClipIds,
  setSelectedClipIds,
  onDeleteClips,
  onDuplicateClips,
  onCopyClips,
  onPasteClips,
  canPaste,
  onRenameClip,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize,
  loopRegion,
  setLoopRegion,
  onImportAudio,
  markers = [],
  onAddMarker,
  setBpm,
  onFlattenClip
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  // Keep track of the initial offset for ALL selected clips during a drag
  const [dragOffsets, setDragOffsets] = useState<{ [id: string]: number }>({});

  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  // Marquee State
  const [marquee, setMarquee] = useState<MarqueeState | null>(null);
  const justFinishedMarqueeRef = useRef(false);

  // Loop Dragging State
  const [loopDragType, setLoopDragType] = useState<'START' | 'END' | 'MOVE' | null>(null);
  const [loopDragStartX, setLoopDragStartX] = useState<number>(0);
  const [loopDragStartValues, setLoopDragStartValues] = useState<{start: number, end: number}>({start:0, end:0});

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const timelineRef = useRef<HTMLDivElement>(null);

  // Refs for File Import
  const fileInputRef = useRef<HTMLInputElement>(null);
  const importTargetRef = useRef<{trackId: string, time: number} | null>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      return Math.round(time / beat) * beat;
  };

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) {
               setDraggedClipId(null);
               setDragOffsets({});
           }
           if (resizingClipId) setResizingClipId(null);
           if (loopDragType) setLoopDragType(null);
           if (marquee?.active) {
               setMarquee(null);
               // Set a flag to prevent the subsequent 'click' event from clearing selection
               justFinishedMarqueeRef.current = true;
               setTimeout(() => { justFinishedMarqueeRef.current = false; }, 100);
           }
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId, loopDragType, marquee]);

  // Global Mouse Move (for operations like resizing, box select, etc that extend beyond the div)
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;
          const rect = timelineRef.current.getBoundingClientRect();
          const relativeX = e.clientX - rect.left + timelineRef.current.scrollLeft;
          const relativeY = e.clientY - rect.top + timelineRef.current.scrollTop;

          if (marquee?.active) {
              setMarquee(prev => prev ? { ...prev, currentX: relativeX, currentY: relativeY } : null);

              // Calculate Selection Logic
              // Define Marquee Box
              const mX = Math.min(marquee.startX, relativeX);
              const mY = Math.min(marquee.startY, relativeY);
              const mW = Math.abs(relativeX - marquee.startX);
              const mH = Math.abs(relativeY - marquee.startY);

              // DOM-based collision for accuracy
              const newSelectedIds: string[] = [];
              const clipElements = timelineRef.current.querySelectorAll('[data-clip-id]');

              clipElements.forEach(el => {
                  const clipRect = el.getBoundingClientRect();
                  // Convert clip rect to relative coordinates within timelineRef
                  const clipRelX = clipRect.left - rect.left + timelineRef.current!.scrollLeft;
                  const clipRelY = clipRect.top - rect.top + timelineRef.current!.scrollTop;

                  // AABB Collision
                  if (mX < clipRelX + clipRect.width &&
                      mX + mW > clipRelX &&
                      mY < clipRelY + clipRect.height &&
                      mY + mH > clipRelY) {
                          const id = el.getAttribute('data-clip-id');
                          if (id) newSelectedIds.push(id);
                      }
              });

              setSelectedClipIds(newSelectedIds);
              return;
          }

          if (loopDragType) {
              const diffPixels = e.clientX - loopDragStartX;
              const diffSeconds = diffPixels / zoom;

              let newStart = loopDragStartValues.start;
              let newEnd = loopDragStartValues.end;

              if (loopDragType === 'START') {
                  newStart = Math.min(newEnd - 0.25, Math.max(0, loopDragStartValues.start + diffSeconds));
              } else if (loopDragType === 'END') {
                  newEnd = Math.max(newStart + 0.25, loopDragStartValues.end + diffSeconds);
              } else if (loopDragType === 'MOVE') {
                  const duration = loopDragStartValues.end - loopDragStartValues.start;
                  newStart = Math.max(0, loopDragStartValues.start + diffSeconds);
                  newEnd = newStart + duration;
              }

              if (snap) {
                  newStart = snapToGrid(newStart);
                  newEnd = snapToGrid(newEnd);
                  if (newEnd <= newStart) newEnd = newStart + secondsPerBeat;
              }

              setLoopRegion({ ...loopRegion, start: newStart, end: newEnd });
              return;
          }

          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); 
             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;
             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId || loopDragType || marquee?.active) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize, loopDragType, loopDragStartX, loopDragStartValues, loopRegion, setLoopRegion, bpm, marquee]);

  // Wheel Zoom
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom));
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);

  const handleRulerClick = (e: React.MouseEvent) => {
      // Don't seek if we are right-clicking or dragging loop handles
      if (e.button === 2) return;
      if ((e.target as HTMLElement).closest('.loop-region-handle')) return;

      const rect = timelineRef.current?.getBoundingClientRect();
      if (!rect) return;

      const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
      const seekTime = Math.max(0, (clickX / zoom));

      onSeek(snapToGrid(seekTime));
  };

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId || loopDragType) return;

    if (justFinishedMarqueeRef.current) {
        justFinishedMarqueeRef.current = false;
        return;
    }

    const target = e.target as HTMLElement;
    if (target.closest('.loop-region-handle')) return;
    if (target.closest('.ruler-track')) return; // Handled by handleRulerClick

    const clipElement = target.closest('[data-clip-id]');

    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
                 const time = Math.max(0, clickX / zoom);

                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));
                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    // Background Click
    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        // If clicking (not dragging), deselect all and seek
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;

        if (!marquee?.active) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const seekTime = Math.max(0, (clickX / zoom));
             onSeek(snapToGrid(seekTime));
             setSelectedClipIds([]); // Clear selection on explicit background click
        }
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      // Check if clicking on background to start marquee
      const target = e.target as HTMLElement;
      if (!target.closest('[data-clip-id]') && !target.closest('.loop-region-handle') && !target.closest('[data-automation-track-id]') && !target.closest('.ruler-track')) {
          if (tool === 'MOVE') {
              const rect = timelineRef.current!.getBoundingClientRect();
              const x = e.clientX - rect.left + timelineRef.current!.scrollLeft;
              const y = e.clientY - rect.top + timelineRef.current!.scrollTop;

              setMarquee({
                  startX: x,
                  startY: y,
                  currentX: x,
                  currentY: y,
                  active: true
              });
          }
      }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        const isAudio = file.type.startsWith('audio/') || 
                        file.type === 'video/mp4' || 
                        file.name.toLowerCase().endsWith('.m4a');
        if (isAudio) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        // Multi-clip move logic
        const draggedClip = clips.find(c => c.id === draggedClipId);
        if (!draggedClip) return;

        const movingIds = selectedClipIds.includes(draggedClipId) ? selectedClipIds : [draggedClipId];
        const primaryOffset = dragOffsets[draggedClipId] || 0;
        const newPrimaryTime = Math.max(0, dropTime - primaryOffset);
        const timeDelta = newPrimaryTime - draggedClip.startTime; 

        const updates = movingIds.map(id => {
            const clip = clips.find(c => c.id === id);
            if (!clip) return null;

            return {
                id: clip.id,
                startTime: Math.max(0, clip.startTime + timeDelta),
                trackId: id === draggedClipId ? trackId : clip.trackId 
            };
        }).filter(Boolean) as { id: string, startTime: number, trackId?: string }[];

        onClipsUpdate(updates);
        setDraggedClipId(null);
        setDragOffsets({});
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }

     let currentSelection = selectedClipIds;
     if (!selectedClipIds.includes(clip.id)) {
         setSelectedClipIds([clip.id]);
         currentSelection = [clip.id];
     }

     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     const offsets: {[id:string]: number} = {};
     currentSelection.forEach(id => {
         offsets[id] = offsetTime; 
     });

     setDragOffsets(offsets);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      if (!selectedClipIds.includes(clip.id)) {
          setSelectedClipIds([clip.id]);
      }
  };

  const handleLoopDragStart = (e: React.MouseEvent, type: 'START' | 'END' | 'MOVE') => {
      e.stopPropagation();
      e.preventDefault();
      setLoopDragType(type);
      setLoopDragStartX(e.clientX);
      setLoopDragStartValues({ start: loopRegion.start, end: loopRegion.end });
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      if (!selectedClipIds.includes(clipId)) {
          setSelectedClipIds([clipId]);
      }
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleRulerContextMenu = (e: React.MouseEvent) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'RULER',
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP') {
           const targetIsSelected = contextMenu.targetId && selectedClipIds.includes(contextMenu.targetId);
           const idsToActOn = targetIsSelected ? selectedClipIds : (contextMenu.targetId ? [contextMenu.targetId] : []);

           switch(action) {
              case 'delete': onDeleteClips(idsToActOn); break;
              case 'duplicate': onDuplicateClips(idsToActOn); break;
              case 'rename': 
                  if (idsToActOn.length === 1) {
                      const clip = clips.find(c => c.id === idsToActOn[0]);
                      if (clip) {
                          const newName = prompt("Rename clip:", clip.name);
                          if (newName) onRenameClip(idsToActOn[0], newName);
                      }
                  } else {
                      alert("Can only rename one clip at a time.");
                  }
                  break;
              case 'copy': onCopyClips(idsToActOn); break;
              case 'loop': idsToActOn.forEach(id => onLoopClip(id)); break;
              case 'flatten': 
                  if (idsToActOn.length === 1 && onFlattenClip) onFlattenClip(idsToActOn[0]); 
                  else if (idsToActOn.length > 1) alert("Flattening multiple clips not supported yet.");
                  break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClips(contextMenu.time, contextMenu.targetId);
           } else if (action === 'import-file') {
               importTargetRef.current = { trackId: contextMenu.targetId, time: contextMenu.time };
               fileInputRef.current?.click();
           }
      } else if (contextMenu.type === 'RULER' && contextMenu.time !== undefined) {
           if (action === 'set-bpm') {
                const val = prompt("Enter new Tempo (BPM) at this marker:", bpm.toString());
                if (val && !isNaN(parseInt(val))) {
                    const newBpm = parseInt(val);
                    if (onAddMarker) onAddMarker(contextMenu.time, `${newBpm} BPM`, 'BPM', newBpm);
                }
           } else if (action === 'set-signature') {
                const val = prompt("Set Time Signature (e.g. 4/4):", "4/4");
                if (val && onAddMarker) {
                    onAddMarker(contextMenu.time, val, 'TS', val);
                }
           }
      }
      setContextMenu(null);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0] && importTargetRef.current) {
          const { trackId, time } = importTargetRef.current;
          onImportAudio(e.target.files[0], trackId, time);
      }
      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];
      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);
      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ left: i * singleLoopWidth, width: singleLoopWidth }}
                 >
                     <Waveform clip={clip} width={singleLoopWidth} height={TRACK_HEIGHT - 10} color={i === 0 ? "#ffffff" : "#ffffffaa"} />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <>
      <div 
        className={`flex-1 relative flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
        ref={timelineRef}
        onClick={handleTimelineClick}
        onMouseDown={handleMouseDown}
      >
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileSelect}
            className="hidden" 
            accept="audio/*,.m4a,.mp4" 
        />

        {/* Marquee Box */}
        {marquee?.active && (
            <div 
                className="absolute bg-blue-500/20 border border-blue-400 z-50 pointer-events-none"
                style={{
                    left: Math.min(marquee.startX, marquee.currentX),
                    top: Math.min(marquee.startY, marquee.currentY),
                    width: Math.abs(marquee.currentX - marquee.startX),
                    height: Math.abs(marquee.currentY - marquee.startY)
                }}
            />
        )}

        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler - Now with sticky top-0 to stick inside the App-level scroll container */}
        <div 
          className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex cursor-context-menu ruler-track" 
          style={{ width: `${totalBars * pixelsPerBar}px`, height: `${TIMELINE_RULER_HEIGHT}px` }}
          onContextMenu={handleRulerContextMenu}
          onClick={handleRulerClick}
          title="Left-click to seek. Right-click to add Tempo or Time Signature changes"
        >
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50 pointer-events-none" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}

             {/* Markers */}
             {markers.map((m, i) => (
                 <div key={i} className="absolute top-0 h-full border-l border-blue-500 group z-20" style={{ left: m.time * zoom }}>
                     {/* Marker Line */}
                     <div className="absolute top-8 w-px h-[2000px] bg-blue-500/20 pointer-events-none"></div>
                     {/* Marker Label */}
                     <div className="flex items-center bg-blue-600 text-white text-[9px] px-1 rounded-r shadow cursor-pointer hover:bg-blue-500 transition-colors">
                        {m.type === 'BPM' ? <Activity size={8} className="mr-1" /> : m.type === 'TS' ? <Clock size={8} className="mr-1" /> : <Flag size={8} className="mr-1" />}
                        {m.label}
                     </div>
                 </div>
             ))}

             {/* Loop Region Overlay */}
             {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 h-full bg-yellow-400/20 border-l border-r border-yellow-400/50 group loop-region-handle cursor-move"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                    onMouseDown={(e) => handleLoopDragStart(e, 'MOVE')}
                    onClick={(e) => e.stopPropagation()}
                 >
                     <div className="absolute top-0 left-0 w-full h-1 bg-yellow-400/50"></div>

                     {/* Handles */}
                     <div 
                        className="absolute top-0 left-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'START')}
                     />
                     <div 
                        className="absolute top-0 right-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'END')}
                     />
                 </div>
             )}
        </div>

        <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
          {/* Loop Region Background Highlight (Extends down tracks) */}
          {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 bottom-0 bg-white/5 pointer-events-none z-0"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                 />
          )}

          {tracks.map(track => {
            return (
                <div key={track.id} className="flex flex-col z-10">
                  <div 
                      className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                      onDragOver={handleDragOver}
                      onDrop={(e) => handleDrop(e, track.id)}
                      onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                      style={{ 
                          height: `${TRACK_HEIGHT}px`,
                          backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                          backgroundSize: `${pixelsPerBar}px 100%`,
                          backgroundPosition: '0 0'
                      }}
                  >
                      <div 
                          className="absolute inset-0 pointer-events-none" 
                          style={{ backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)', backgroundSize: `${pixelsPerBeat}px 100%`, opacity: 0.1 }}
                      />

                      {clips.filter(c => c.trackId === track.id).map(clip => {
                          const isSelected = selectedClipIds.includes(clip.id);
                          return (
                          <div
                              key={clip.id}
                              data-clip-id={clip.id}
                              draggable={tool === 'MOVE'}
                              onDragStart={(e) => handleDragStart(e, clip)}
                              onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                              onClick={(e) => e.stopPropagation()} 
                              onMouseDown={(e) => { if (tool === 'MOVE' && !isSelected && !e.shiftKey) setSelectedClipIds([clip.id]); }}
                              className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                              ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                              ${isSelected ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                              style={{ left: `${clip.startTime * zoom}px`, width: `${clip.duration * zoom}px` }}
                          >
                              <div className="absolute inset-0 opacity-60" style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}></div>
                              {clip.loop && <div className="absolute top-0 right-4 p-1 text-white/70 z-30"><RotateCw size={10} /></div>}
                              <div className="absolute inset-0 z-10">{renderClipContent(clip, track)}</div>
                              <div className="absolute top-1 left-1 z-20 max-w-full"><div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">{clip.name}</div></div>
                              {tool === 'MOVE' && isSelected && selectedClipIds.length === 1 && <div className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle" onMouseDown={(e) => handleResizeStart(e, clip)}><GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" /></div>}
                          </div>
                      )})}
                  </div>

                  {track.showAutomation && (
                      <div 
                          className="bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair box-border"
                          data-automation-track-id={track.id}
                          style={{ minWidth: `${totalBars * pixelsPerBar}px`, height: `${AUTOMATION_HEIGHT}px` }}
                      >
                          <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                          <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">{track.selectedAutomationId === 'pan' ? 'Pan' : track.selectedAutomationId === 'volume' ? 'Vol' : track.selectedAutomationId?.split(':')[1].toUpperCase()}</div>
                          <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>{renderAutomationPoints(track)}</svg>
                      </div>
                  )}
                </div>
            );
          })}
          <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">End of tracks</div>
        </div>

        {contextMenu && (
            <div 
                className="fixed z-50 w-56 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
                style={{ top: contextMenu.y, left: contextMenu.x }}
            >
                {contextMenu.type === 'CLIP' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Copy</button>
                      <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><RotateCw size={14} /> Toggle Loop</button>
                      <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Pencil size={14} /> Rename</button>
                      <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Duplicate</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'flatten')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2 text-blue-400"><FileStack size={14} /> Flatten Clip</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2"><Trash2 size={14} /> Delete</button>
                    </>
                ) : contextMenu.type === 'BACKGROUND' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'paste')} disabled={!canPaste} className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}><ClipboardPaste size={14} /> Paste</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'import-file')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Upload size={14} className="text-blue-400" /> Import Audio File</button>
                    </>
                ) : (
                    <>
                        <div className="px-4 py-2 text-xs font-bold text-gray-500 uppercase">Marker Options</div>
                        <button onClick={(e) => handleMenuAction(e, 'set-bpm')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Activity size={14} className="text-green-400" /> Insert Tempo Change</button>
                        <button onClick={(e) => handleMenuAction(e, 'set-signature')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Clock size={14} className="text-purple-400" /> Insert Time Signature</button>
                    </>
                )}
            </div>
        )}
      </div>
    </>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { MasterVisualizer } from './components/MasterVisualizer';
import { SettingsModal } from './components/SettingsModal';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, LoopRegion } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [timeMarkers, setTimeMarkers] = useState<{time: number, label: string, type?: 'BPM' | 'TS', value?: number | string}[]>([]);

  // Metronome State
  const [isMetronomeOn, setIsMetronomeOn] = useState(false);
  const [countInMeasures, setCountInMeasures] = useState(1);

  // Loop State (Default measures 1-4 -> 0s to 8s at 120bpm)
  const [loopRegion, setLoopRegion] = useState<LoopRegion>({ start: 0, end: 8, enabled: false });
  // Ref for loop region to access in RAF without re-binding
  const loopRegionRef = useRef(loopRegion);
  const markersRef = useRef(timeMarkers);

  useEffect(() => {
      loopRegionRef.current = loopRegion;
  }, [loopRegion]);

  useEffect(() => {
      markersRef.current = timeMarkers;
  }, [timeMarkers]);

  // Recording State
  const [armedTrackId, setArmedTrackId] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  // Selection State (Multi-select)
  const [selectedClipIds, setSelectedClipIds] = useState<string[]>([]);
  const [clipboardClips, setClipboardClips] = useState<AudioClip[]>([]);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Refs ---
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const navigatorRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0); // Timeline position where recording block starts
  const recordPreRollRef = useRef<number>(0); // How much physical audio was captured BEFORE timeline start
  const lastMarkerCheckRef = useRef<number>(0);

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Navigator Scroll Sync ---
  const handleMainScroll = () => {
      if (scrollContainerRef.current && navigatorRef.current) {
          navigatorRef.current.scrollLeft = scrollContainerRef.current.scrollLeft;
      }
  };

  const handleNavigatorScroll = (e: React.UIEvent<HTMLDivElement>) => {
      const target = e.target as HTMLDivElement;
      if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollLeft = target.scrollLeft;
      }
  };

  // --- Smart Zoom Handling ---
  const handleZoomChange = useCallback((newZoom: number) => {
      const clampedZoom = Math.max(10, Math.min(500, newZoom));
      setZoom(clampedZoom);

      // Center playhead logic
      if (scrollContainerRef.current) {
          requestAnimationFrame(() => {
              if (scrollContainerRef.current) {
                  const containerWidth = scrollContainerRef.current.clientWidth;
                  const playheadX = playbackState.currentTime * clampedZoom;
                  // Center playhead: target scroll is playheadX - halfWidth
                  const targetScroll = Math.max(0, playheadX - (containerWidth / 2));
                  scrollContainerRef.current.scrollLeft = targetScroll;
              }
          });
      }
  }, [playbackState.currentTime]);

  // --- Undo/Redo System ---
  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks);
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex - 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks);
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };

  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stopPlayback(); 
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    // Schedule metronome if enabled
    if (isMetronomeOn) {
        audioService.scheduleMetronome(bpm, audioService.getContext().currentTime, 300); // Schedule 5 mins of clicks
    }

    startTimeRef.current = audioService.getContext().currentTime;
    lastMarkerCheckRef.current = startAt;
    setPlaybackState(prev => ({ ...prev, isPlaying: true, currentTime: startAt }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      // Check for Tempo/Marker updates (Simulation of automation)
      // Check markers between last checked time and newTime
      const crossedMarkers = markersRef.current.filter(m => 
          m.time > lastMarkerCheckRef.current && m.time <= newTime
      );

      crossedMarkers.forEach(marker => {
          if (marker.type === 'BPM' && typeof marker.value === 'number') {
              setBpm(marker.value);
              // Note: Realtime metronome updating would require stopping/restarting schedule logic here
          }
      });
      lastMarkerCheckRef.current = newTime;

      // Loop Check using REF to avoid closure staleness
      if (loopRegionRef.current.enabled && newTime >= loopRegionRef.current.end) {
          startPlayback(loopRegionRef.current.start);
          return; 
      }

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks, bpm, isMetronomeOn]); 

  const handleSeek = useCallback((time: number) => {
      pauseTimeRef.current = time;
      lastMarkerCheckRef.current = time;

      // Update BPM if we seek past a marker (find the latest marker before time)
      const prevBpmMarker = [...timeMarkers]
          .sort((a,b) => b.time - a.time)
          .find(m => m.type === 'BPM' && m.time <= time);

      if (prevBpmMarker && typeof prevBpmMarker.value === 'number') {
          setBpm(prevBpmMarker.value);
      }

      setPlaybackState(prev => ({ ...prev, currentTime: time }));

      // If playing, we need to restart playback at new position
      if (playbackState.isPlaying) {
           startPlayback(time);
      }
  }, [playbackState.isPlaying, startPlayback, timeMarkers]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (isRecording) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [isRecording]);

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---
  const handleArmTrack = async (trackId: string) => {
      if (armedTrackId === trackId) {
          setArmedTrackId(null);
          audioService.disableMonitoring();
      } else {
          try {
              // Critical: Await monitoring setup BEFORE updating state to ensure visualizer is ready
              await audioService.enableMonitoring(trackId); 
              setArmedTrackId(trackId);
          } catch(e) {
              alert("Could not access microphone.");
              setArmedTrackId(null);
          }
      }
  };

  const handleTransportRecord = async () => {
      if (isRecording) {
          handleStop();
      } else {
          if (!armedTrackId) {
              alert("Please arm a track first.");
              return;
          }
          try {
            await audioService.resume();

            // 1. Start Recording Physically FIRST to capture pre-roll/setup
            await audioService.startRecording();
            const sysRecordStart = audioService.getContext().currentTime;

            // 2. Count-In Logic (if enabled)
            if (countInMeasures > 0) {
                 await audioService.playCountIn(bpm, countInMeasures);
            } else {
                 // Even without count-in, wait a tiny bit to ensure we capture the transient of the first beat
                 await new Promise(r => setTimeout(r, 100));
            }

            // 3. Start Playback Transport
            const sysPlaybackStart = audioService.getContext().currentTime;

            // Calculate how much audio we captured before the transport actually started
            const preRollDuration = sysPlaybackStart - sysRecordStart;

            setIsRecording(true);
            recordStartTimeRef.current = pauseTimeRef.current;
            recordPreRollRef.current = preRollDuration;

            startPlayback(pauseTimeRef.current);
          } catch(e) {
              console.error("Recording failed to start", e);
              alert("Failed to start recording. Please check microphone permissions.");
          }
      }
  };

  const finishRecording = async () => {
      if (!armedTrackId) {
          setIsRecording(false);
          return;
      }
      const blob = await audioService.stopRecording();
      const timelineStart = recordStartTimeRef.current;
      const preRoll = recordPreRollRef.current;

      if (blob && blob.size > 0) {
          try {
              const buffer = await audioService.decodeBlob(blob);

              // --- Latency Compensation & Placement ---
              const latency = audioService.latencySeconds;

              // The buffer contains [PreRoll] + [Performance].
              // The Performance started at buffer time = preRoll + latency (approx).
              // We want this point to align with `timelineStart`.

              // Theoretical Offset into buffer for T=timelineStart
              let targetOffset = preRoll + latency;

              // Safety: Reveal a bit of the pre-roll to catch early transients (rushing).
              // We shift the clip START TIME back by `safetyMargin` and reduce OFFSET by same amount.
              const safetyMargin = Math.min(preRoll, 0.2); // Up to 200ms

              const finalClipStart = timelineStart - safetyMargin;
              const finalClipOffset = targetOffset - safetyMargin;

              // Duration needs to be calculated based on what's left in the buffer
              // Buffer Duration - Offset = Playable Length
              // But we added safetyMargin to length by reducing offset.
              const finalDuration = Math.max(0, buffer.duration - finalClipOffset);

              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: armedTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: finalClipStart, // Can be negative or < timelineStart
                  duration: finalDuration,
                  offset: Math.max(0, finalClipOffset),
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };

              if (finalDuration > 0) {
                  updateStateWithHistory(tracks, [...clips, newClip]);
              }
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }
      setIsRecording(false);
  };

  // --- Track Management ---
  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) points[existingIdx] = point;
             else points.push(point);
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---
  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  // Batch Update for moving multiple clips
  const updateClips = (updates: { id: string, startTime: number, trackId?: string }[]) => {
      const newClips = clips.map(c => {
          const update = updates.find(u => u.id === c.id);
          if (update) {
              // Prevent moving to master track
              if (update.trackId === 'master') return c;
              return { ...c, startTime: update.startTime, trackId: update.trackId || c.trackId };
          }
          return c;
      });
      setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  // --- Batch Operations (Delete, Duplicate, Copy, Paste) ---

  const deleteClips = (ids: string[]) => {
      const newClips = clips.filter(c => !ids.includes(c.id));
      setSelectedClipIds([]);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClips = (ids: string[]) => {
      const clipsToDuplicate = clips.filter(c => ids.includes(c.id));
      if (clipsToDuplicate.length === 0) return;

      const newClips = [...clips];
      const newIds: string[] = [];

      clipsToDuplicate.forEach(original => {
          const newId = uuidv4();
          newIds.push(newId);
          newClips.push({
              ...original,
              id: newId,
              // Per user request: Place immediately after original
              startTime: original.startTime + original.duration, 
              name: `${original.name} (Copy)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleFlattenClip = async (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (!clip) return;

      try {
          const newBuffer = await audioService.bounceClip(clip);
          const newClip: AudioClip = {
              ...clip,
              buffer: newBuffer,
              offset: 0,
              duration: clip.duration, 
              playbackRate: 1, 
              name: `${clip.name} (Flattened)`,
              loop: false 
          };

          const newClips = clips.map(c => c.id === id ? newClip : c);
          updateStateWithHistory(tracks, newClips);
          // Keep selection
          if (selectedClipIds.includes(id)) {
              // no-op, still selected
          }
      } catch (e) {
          console.error("Flatten failed", e);
          alert("Could not flatten clip.");
      }
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;
      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return;

      const firstDuration = relativeSplit * clip.playbackRate;
      const leftClip: AudioClip = { ...clip, id: uuidv4(), duration: firstDuration, name: clip.name };
      const rightClip: AudioClip = { ...clip, id: uuidv4(), startTime: splitTime, offset: clip.offset + firstDuration, duration: clip.duration - firstDuration, name: clip.name };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      // Update selection to the new clips if original was selected
      if (selectedClipIds.includes(clipId)) {
          setSelectedClipIds([leftClip.id, rightClip.id]);
      }

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClips = (ids: string[]) => {
      const selected = clips.filter(c => ids.includes(c.id));
      if (selected.length > 0) setClipboardClips(selected);
  };

  const handlePasteClips = (time: number, targetTrackId: string) => {
      if (clipboardClips.length === 0 || targetTrackId === 'master') return;

      // Calculate relative offsets based on the earliest clip in clipboard
      const minStartTime = Math.min(...clipboardClips.map(c => c.startTime));

      const newClips = [...clips];
      const newIds: string[] = [];

      clipboardClips.forEach(clip => {
          const relativeTime = clip.startTime - minStartTime;
          const newId = uuidv4();
          newIds.push(newId);

          newClips.push({
              ...clip,
              id: newId,
              startTime: time + relativeTime,
              trackId: targetTrackId, // Collapse to the track where user right-clicked for now
              name: `${clip.name} (Paste)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;
          const newClips = clips.map(c => c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---
  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const handleExportStems = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          for (const track of tracks) {
             if (track.isMaster) continue;
             const trackClips = clips.filter(c => c.trackId === track.id);
             if (trackClips.length === 0) continue;

             const blob = await audioService.renderOffline(trackClips, [track, MASTER_TRACK]);

             const url = URL.createObjectURL(blob);
             const a = document.createElement('a');
             a.href = url;
             a.download = `${track.name}_Stem.wav`;
             a.click();
             URL.revokeObjectURL(url);

             await new Promise(r => setTimeout(r, 500));
          }
      } catch (e) {
          console.error("Stem Export failed", e);
          alert("Stem Export failed.");
      } finally {
          setIsExporting(false);
          setIsSettingsOpen(false);
      }
  };

  // --- Derived State & Variables ---
  const regularTracks = tracks.filter(t => !t.isMaster);
  const masterTrack = tracks.find(t => t.isMaster) || MASTER_TRACK;

  // Only show editor if exactly one clip is selected
  const selectedClip = selectedClipIds.length === 1 
      ? clips.find(c => c.id === selectedClipIds[0]) || null
      : null;

  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration));
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const pixelsPerBar = secondsPerBar * zoom;
  const timelineWidth = totalBars * pixelsPerBar;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <SettingsModal 
          isOpen={isSettingsOpen} 
          onClose={() => setIsSettingsOpen(false)}
          onExportStems={handleExportStems}
      />

      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        isRecording={isRecording}
        onRecord={handleTransportRecord}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={(newBpm) => {
            setBpm(newBpm);
        }}
        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={handleZoomChange}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
        loopRegion={loopRegion}
        setLoopRegion={setLoopRegion}
        isMetronomeOn={isMetronomeOn}
        toggleMetronome={() => setIsMetronomeOn(!isMetronomeOn)}
        countInMeasures={countInMeasures}
        setCountInMeasures={setCountInMeasures}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      {/* Main Workspace: Single Unified Scroll Container */}
      <div 
        className="flex-1 overflow-auto relative" 
        ref={scrollContainerRef}
        onScroll={handleMainScroll}
      >
        <div className="flex min-w-max">
            {/* Sticky Left Column (Headers) */}
            <div 
                className="sticky left-0 z-30 bg-gray-900 border-r border-gray-700 flex flex-col flex-shrink-0 shadow-lg"
                style={{ width: TRACK_HEADER_WIDTH }}
            >
                 {/* Sticky Top-Left Corner */}
                 <div 
                    className="sticky top-0 z-40 bg-gray-900 border-b border-gray-700 flex-shrink-0"
                    style={{ height: TIMELINE_RULER_HEIGHT }}
                 />

                 {/* Track Headers List */}
                 {regularTracks.map(track => (
                    <TrackControl 
                        key={track.id} 
                        track={track} 
                        onUpdate={updateTrack}
                        onDelete={deleteTrack}
                        isArmed={armedTrackId === track.id}
                        isRecordingGlobal={isRecording}
                        onArmToggle={() => handleArmTrack(track.id)}
                        onOpenEditor={setEditingTrackId}
                        onToggleAutomation={toggleAutomation}
                    />
                 ))}

                 <div className="p-3">
                     <button 
                        onClick={addTrack}
                        className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                        title="Add a new audio track"
                     >
                        <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors"><Plus size={14} /></div>
                        <span>Add Track</span>
                     </button>
                 </div>

                 {/* Bottom Spacer */}
                 <div className="h-64 bg-gray-900" />
            </div>

            {/* Main Timeline Area (Scrolls with parent) */}
            <div className="flex flex-col flex-1">
                {/* Timeline Component - renders Ruler (sticky inside) and Tracks */}
                <Timeline 
                    tracks={regularTracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipsUpdate={updateClips} // Batch update
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={handleZoomChange}
                    snap={snap}
                    tool={tool}

                    selectedClipIds={selectedClipIds}
                    setSelectedClipIds={setSelectedClipIds}

                    onDeleteClips={deleteClips}
                    onDuplicateClips={duplicateClips}
                    onCopyClips={handleCopyClips}
                    onPasteClips={handlePasteClips}
                    canPaste={clipboardClips.length > 0}

                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}
                    onClipResize={handleClipResize}
                    onLoopClip={handleLoopToggle}
                    onFlattenClip={handleFlattenClip}

                    loopRegion={loopRegion}
                    setLoopRegion={setLoopRegion}
                    onImportAudio={handleFileDrop}
                    markers={timeMarkers}
                    onAddMarker={(time, label, type, value) => setTimeMarkers([...timeMarkers, {time, label, type, value}])}
                    setBpm={setBpm}
                />
            </div>
        </div>
      </div>

      {/* Fixed Bottom Master Section */}
      <div className="h-44 bg-gray-900 border-t-2 border-gray-800 flex flex-col z-50 shadow-[0_-5px_15px_rgba(0,0,0,0.5)]">
         {/* Master Row */}
         <div className="flex flex-1 overflow-hidden">
             {/* Master Control (Left) */}
             <div className="flex-shrink-0 border-r border-gray-800" style={{ width: TRACK_HEADER_WIDTH }}>
                <TrackControl 
                  track={masterTrack}
                  onUpdate={updateTrack}
                  onDelete={() => {}}
                  isArmed={false}
                  isRecordingGlobal={false}
                  onArmToggle={() => {}}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={() => {}}
                />
             </div>
             {/* Master Visualizer (Right) */}
             <div className="flex-1 p-2 bg-gray-900 flex items-center justify-center">
                 <MasterVisualizer isPlaying={playbackState.isPlaying} />
             </div>
         </div>

         {/* Navigator / Scrollbar (Bottom Fixed) */}
         <div className="h-5 bg-gray-950 border-t border-gray-800">
             <div 
                ref={navigatorRef}
                onScroll={handleNavigatorScroll}
                className="w-full h-full overflow-x-auto overflow-y-hidden custom-scrollbar"
                title="Timeline Navigator"
             >
                <div style={{ width: timelineWidth + TRACK_HEADER_WIDTH, height: '1px' }}></div>
             </div>
         </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipIds([])}
            projectBpm={bpm}
          />
      )}
    </div>
  );
}

export default App;

import React, { useState, useEffect, useRef } from 'react';
import { Play, Square, FastForward, Rewind, Activity, Scissors, MousePointer2, ZoomIn, ZoomOut, Grid, Undo, Redo, Download, Circle, Repeat, Timer, Settings } from 'lucide-react';
import { LoopRegion, ToolType } from '../types';

interface TransportProps {
  isPlaying: boolean;
  onPlay: () => void;
  onStop: () => void;
  onRewind: () => void;
  onFastForward: () => void;

  isRecording: boolean;
  onRecord: () => void;

  currentTime: number;
  bpm: number;
  setBpm: (bpm: number) => void;

  tool: ToolType;
  setTool: (t: ToolType) => void;
  zoom: number;
  setZoom: (z: number) => void;
  snap: boolean;
  setSnap: (s: boolean) => void;
  onUndo: () => void;
  onRedo: () => void;
  canUndo: boolean;
  canRedo: boolean;
  onExport: () => void;
  isExporting: boolean;

  loopRegion: LoopRegion;
  setLoopRegion: (region: LoopRegion) => void;

  isMetronomeOn: boolean;
  toggleMetronome: () => void;
  countInMeasures: number;
  setCountInMeasures: (n: number) => void;

  onOpenSettings: () => void;
}

const formatTime = (seconds: number) => {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  const ms = Math.floor((seconds % 1) * 100);
  return `${m.toString().padStart(2, '0')}:${s.toString().padStart(2, '0')}.${ms.toString().padStart(2, '0')}`;
};

export const Transport: React.FC<TransportProps> = ({ 
    isPlaying, 
    onPlay, 
    onStop, 
    onRewind,
    onFastForward,
    isRecording,
    onRecord,
    currentTime, 
    bpm, 
    setBpm,
    tool,
    setTool,
    zoom,
    setZoom,
    snap,
    setSnap,
    onUndo,
    onRedo,
    canUndo,
    canRedo,
    onExport,
    isExporting,
    loopRegion,
    setLoopRegion,
    isMetronomeOn,
    toggleMetronome,
    countInMeasures,
    setCountInMeasures,
    onOpenSettings
}) => {
  const [showCountInMenu, setShowCountInMenu] = useState(false);

  // Tap Tempo State
  const tapTimesRef = useRef<number[]>([]);

  useEffect(() => {
      const closeMenu = () => setShowCountInMenu(false);
      if (showCountInMenu) window.addEventListener('click', closeMenu);
      return () => window.removeEventListener('click', closeMenu);
  }, [showCountInMenu]);

  const handleMetronomeClick = (e: React.MouseEvent) => {
      // Toggle logic first
      toggleMetronome();

      // Tap Tempo Logic
      const now = Date.now();
      const times = tapTimesRef.current;

      // Filter clicks older than 2 seconds
      const recentTimes = times.filter(t => now - t < 2000);
      recentTimes.push(now);
      tapTimesRef.current = recentTimes;

      if (recentTimes.length >= 4) {
          // Calculate BPM
          let sumIntervals = 0;
          for(let i=1; i<recentTimes.length; i++) {
              sumIntervals += (recentTimes[i] - recentTimes[i-1]);
          }
          const avgInterval = sumIntervals / (recentTimes.length - 1);
          const newBpm = Math.round(60000 / avgInterval);

          if (newBpm >= 30 && newBpm <= 300) {
              setBpm(newBpm);
          }
      }
  };

  return (
    <div className="h-16 bg-gray-900 border-b border-gray-700 flex items-center z-30 shadow-lg select-none overflow-x-auto custom-scrollbar-hidden">
      <div className="flex items-center justify-between px-4 min-w-max w-full gap-4">
          <div className="flex items-center gap-4">
            <div className="text-2xl font-bold bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-500 mr-2 flex-shrink-0" title="ISL Digital Audio Workstation">
                ISLdaw
            </div>

            {/* File Actions */}
            <div className="flex items-center gap-1 bg-gray-800 rounded-lg p-1 border border-gray-700 flex-shrink-0">
                <button 
                    onClick={onUndo} disabled={!canUndo}
                    className="p-1.5 text-gray-400 hover:text-white disabled:opacity-30 rounded hover:bg-gray-700" 
                    title="Undo (Ctrl+Z)"
                >
                    <Undo size={16} />
                </button>
                <button 
                    onClick={onRedo} disabled={!canRedo}
                    className="p-1.5 text-gray-400 hover:text-white disabled:opacity-30 rounded hover:bg-gray-700" 
                    title="Redo (Ctrl+Y)"
                >
                    <Redo size={16} />
                </button>
            </div>

            {/* Tools */}
            <div className="flex items-center gap-1 bg-gray-800 rounded-lg p-1 border border-gray-700 flex-shrink-0">
                <button 
                    onClick={() => setTool('MOVE')}
                    className={`p-1.5 rounded transition-all ${tool === 'MOVE' ? 'bg-blue-500 text-white shadow-sm' : 'text-gray-400 hover:text-white hover:bg-gray-700'}`}
                    title="Move Tool (Select, Move, Resize Clips)"
                >
                    <MousePointer2 size={16} />
                </button>
                <button 
                    onClick={() => setTool('BLADE')}
                    className={`p-1.5 rounded transition-all ${tool === 'BLADE' ? 'bg-blue-500 text-white shadow-sm' : 'text-gray-400 hover:text-white hover:bg-gray-700'}`}
                    title="Blade Tool (Split Clips)"
                >
                    <Scissors size={16} />
                </button>
            </div>

            <div className="w-px h-8 bg-gray-700 mx-1 flex-shrink-0"></div>

            {/* Transport */}
            <div className="flex bg-gray-800 rounded-lg p-1 gap-1 border border-gray-700 flex-shrink-0">
                <button 
                    onClick={() => setLoopRegion({ ...loopRegion, enabled: !loopRegion.enabled })}
                    className={`p-2 rounded transition-all active:scale-95 ${loopRegion.enabled ? 'text-yellow-400 bg-yellow-400/10' : 'text-gray-400 hover:text-white hover:bg-gray-700'}`}
                    title="Toggle Loop Mode"
                >
                    <Repeat size={18} />
                </button>
                <div className="w-px h-full bg-gray-700 mx-1"></div>
                <button 
                    onClick={onRewind}
                    className="p-2 text-gray-400 hover:text-white rounded hover:bg-gray-700 active:scale-95 transition-transform"
                    title="Rewind 5s"
                >
                    <Rewind size={18} />
                </button>
                <button 
                    onClick={isPlaying ? onStop : onPlay}
                    className={`p-2 rounded transition-all active:scale-95 ${isPlaying ? 'text-yellow-400 bg-yellow-400/10' : 'text-green-400 hover:bg-green-400/10 hover:text-green-300'}`}
                    title={isPlaying ? "Stop (Space)" : "Play (Space)"}
                >
                    {isPlaying ? <Square size={18} fill="currentColor" /> : <Play size={18} fill="currentColor" />}
                </button>
                <button 
                    onClick={onRecord}
                    className={`p-2 rounded transition-all active:scale-95 ${isRecording ? 'text-red-500 bg-red-500/20 shadow-[0_0_10px_rgba(239,68,68,0.5)]' : 'text-gray-400 hover:text-red-400 hover:bg-gray-700'}`}
                    title="Global Record (Requires Armed Track)"
                >
                    <div className={`w-4 h-4 rounded-full ${isRecording ? 'bg-red-500 animate-pulse' : 'bg-current'}`} />
                </button>
                <button 
                    onClick={onFastForward}
                    className="p-2 text-gray-400 hover:text-white rounded hover:bg-gray-700 active:scale-95 transition-transform"
                    title="Fast Forward 5s"
                >
                    <FastForward size={18} />
                </button>
            </div>

            {/* Time Display */}
            <div className="bg-black/40 px-3 py-1.5 rounded text-blue-400 font-mono text-lg min-w-[100px] text-center border border-blue-500/20 shadow-inner flex-shrink-0" title="Current Playhead Position">
                {formatTime(currentTime)}
            </div>
          </div>

          <div className="flex items-center gap-4">

            {/* BPM & Metronome */}
            <div className="flex items-center gap-2 bg-gray-800 rounded-lg p-1.5 border border-gray-700 group focus-within:border-blue-500/50 flex-shrink-0" title="Tempo (Beats Per Minute)">
                <div className="relative">
                    <button 
                        onClick={handleMetronomeClick}
                        onContextMenu={(e) => { e.preventDefault(); setShowCountInMenu(true); }}
                        className={`p-1 rounded transition-colors ${isMetronomeOn ? 'text-blue-400 bg-blue-500/10 shadow-[0_0_8px_rgba(59,130,246,0.5)]' : 'text-gray-500 hover:text-gray-300'}`}
                        title="Metronome (Click repeatedly to Tap Tempo, Right Click for Settings)"
                    >
                        <Timer size={16} className={isMetronomeOn ? "animate-pulse" : ""} />
                    </button>
                    {showCountInMenu && (
                        <div className="absolute top-full left-0 mt-2 bg-gray-800 border border-gray-600 rounded-lg shadow-xl z-50 w-32 py-1 text-xs">
                            <div className="px-2 py-1 text-gray-500 font-bold uppercase border-b border-gray-700 mb-1">Count In</div>
                            {[0, 1, 2, 4].map(measures => (
                                <button
                                    key={measures}
                                    onClick={() => setCountInMeasures(measures)}
                                    className={`w-full text-left px-2 py-1.5 hover:bg-gray-700 ${countInMeasures === measures ? 'text-blue-400 font-bold' : 'text-gray-300'}`}
                                >
                                    {measures === 0 ? 'None' : `${measures} Bar${measures > 1 ? 's' : ''}`}
                                </button>
                            ))}
                        </div>
                    )}
                </div>

                <div className="flex flex-col items-start mr-1">
                    <span className="text-[9px] text-gray-500 font-bold leading-none uppercase">BPM</span>
                    <input 
                        type="number" 
                        value={bpm}
                        onChange={(e) => setBpm(Math.max(1, Math.min(999, Number(e.target.value))))}
                        className="w-12 bg-transparent text-sm font-mono text-blue-400 outline-none p-0 leading-none"
                        title="Tempo"
                    />
                </div>
            </div>

            {/* Zoom & Snap */}
            <div className="flex items-center gap-2 bg-gray-800 rounded-lg p-1.5 border border-gray-700 flex-shrink-0">
                <button onClick={() => setSnap(!snap)} className={`p-1 rounded ${snap ? 'text-blue-400 bg-blue-500/20' : 'text-gray-500 hover:text-gray-300'}`} title="Snap to Grid (Quantize)">
                    <Grid size={16} />
                </button>
                <div className="w-px h-4 bg-gray-600 mx-1"></div>

                <button 
                    onClick={() => setZoom(Math.max(10, zoom - 10))}
                    className="text-gray-500 hover:text-white transition-colors"
                    title="Zoom Out"
                >
                    <ZoomOut size={14} />
                </button>

                <input 
                    type="range" min="10" max="500" step="10"
                    value={zoom}
                    onChange={(e) => setZoom(Number(e.target.value))}
                    className="w-24 h-1 bg-gray-600 rounded-lg appearance-none cursor-pointer accent-blue-500"
                    title="Horizontal Zoom"
                />

                <button 
                    onClick={() => setZoom(Math.min(500, zoom + 10))}
                    className="text-gray-500 hover:text-white transition-colors"
                    title="Zoom In"
                >
                    <ZoomIn size={14} />
                </button>
            </div>

            <button 
                onClick={onExport}
                disabled={isExporting}
                className="flex items-center gap-2 bg-purple-600 hover:bg-purple-500 text-white px-4 py-2 rounded-lg text-sm font-medium transition-colors disabled:opacity-50 flex-shrink-0"
                title="Export project to WAV file"
            >
                <Download size={16} />
                {isExporting ? 'Exporting...' : 'Export'}
            </button>

            <button 
                onClick={onOpenSettings}
                className="p-2 ml-2 text-gray-400 hover:text-white rounded hover:bg-gray-700 transition-colors flex-shrink-0"
                title="Settings (Audio I/O, Calibration, Export Stems)"
            >
                <Settings size={18} />
            </button>
          </div>
      </div>
    </div>
  );
};

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint, LoopRegion } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, GripVertical, Upload, Clock, Activity, FileStack, Flag, X, Check } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipsUpdate: (updates: { id: string, startTime: number, trackId?: string }[]) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;

  // Selection & Batch Ops
  selectedClipIds: string[];
  setSelectedClipIds: (ids: string[]) => void;
  onDeleteClips: (ids: string[]) => void;
  onDuplicateClips: (ids: string[]) => void;
  onCopyClips: (ids: string[]) => void;
  onPasteClips: (time: number, trackId: string) => void;
  canPaste: boolean;

  onRenameClip: (id: string, newName: string) => void;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;

  loopRegion: LoopRegion;
  setLoopRegion: (region: LoopRegion) => void;

  onImportAudio: (file: File, trackId: string, time: number) => void;

  markers?: {time: number, label: string, type?: 'BPM' | 'TS', value?: number | string}[];
  onAddMarker?: (time: number, label: string, type?: 'BPM' | 'TS', value?: number | string) => void;
  setBpm?: (bpm: number) => void;

  onFlattenClip?: (id: string) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND' | 'RULER';
    targetId?: string; // ClipId or TrackId
    time?: number; 
}

interface MarqueeState {
    startX: number;
    startY: number;
    currentX: number;
    currentY: number;
    active: boolean;
}

interface MarkerModalState {
    isOpen: boolean;
    type: 'BPM' | 'TS' | 'MARKER';
    time: number;
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipsUpdate, 
  onFileDrop,
  onSeek,
  selectedClipIds,
  setSelectedClipIds,
  onDeleteClips,
  onDuplicateClips,
  onCopyClips,
  onPasteClips,
  canPaste,
  onRenameClip,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize,
  loopRegion,
  setLoopRegion,
  onImportAudio,
  markers = [],
  onAddMarker,
  setBpm,
  onFlattenClip
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  // Keep track of the initial offset for ALL selected clips during a drag
  const [dragOffsets, setDragOffsets] = useState<{ [id: string]: number }>({});

  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  // Marquee State
  const [marquee, setMarquee] = useState<MarqueeState | null>(null);
  const justFinishedMarqueeRef = useRef(false);

  // Loop Dragging State
  const [loopDragType, setLoopDragType] = useState<'START' | 'END' | 'MOVE' | null>(null);
  const [loopDragStartX, setLoopDragStartX] = useState<number>(0);
  const [loopDragStartValues, setLoopDragStartValues] = useState<{start: number, end: number}>({start:0, end:0});

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const [markerModal, setMarkerModal] = useState<MarkerModalState | null>(null);
  const [markerInputValue, setMarkerInputValue] = useState("");

  const timelineRef = useRef<HTMLDivElement>(null);

  // Refs for File Import
  const fileInputRef = useRef<HTMLInputElement>(null);
  const importTargetRef = useRef<{trackId: string, time: number} | null>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      return Math.round(time / beat) * beat;
  };

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) {
               setDraggedClipId(null);
               setDragOffsets({});
           }
           if (resizingClipId) setResizingClipId(null);
           if (loopDragType) setLoopDragType(null);
           if (marquee?.active) {
               setMarquee(null);
               // Set a flag to prevent the subsequent 'click' event from clearing selection
               justFinishedMarqueeRef.current = true;
               setTimeout(() => { justFinishedMarqueeRef.current = false; }, 100);
           }
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId, loopDragType, marquee]);

  // Global Mouse Move
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;
          const rect = timelineRef.current.getBoundingClientRect();
          const relativeX = e.clientX - rect.left + timelineRef.current.scrollLeft;
          const relativeY = e.clientY - rect.top + timelineRef.current.scrollTop;

          if (marquee?.active) {
              setMarquee(prev => prev ? { ...prev, currentX: relativeX, currentY: relativeY } : null);

              const mX = Math.min(marquee.startX, relativeX);
              const mY = Math.min(marquee.startY, relativeY);
              const mW = Math.abs(relativeX - marquee.startX);
              const mH = Math.abs(relativeY - marquee.startY);

              const newSelectedIds: string[] = [];
              const clipElements = timelineRef.current.querySelectorAll('[data-clip-id]');

              clipElements.forEach(el => {
                  const clipRect = el.getBoundingClientRect();
                  const clipRelX = clipRect.left - rect.left + timelineRef.current!.scrollLeft;
                  const clipRelY = clipRect.top - rect.top + timelineRef.current!.scrollTop;

                  if (mX < clipRelX + clipRect.width &&
                      mX + mW > clipRelX &&
                      mY < clipRelY + clipRect.height &&
                      mY + mH > clipRelY) {
                          const id = el.getAttribute('data-clip-id');
                          if (id) newSelectedIds.push(id);
                      }
              });

              setSelectedClipIds(newSelectedIds);
              return;
          }

          if (loopDragType) {
              const diffPixels = e.clientX - loopDragStartX;
              const diffSeconds = diffPixels / zoom;

              let newStart = loopDragStartValues.start;
              let newEnd = loopDragStartValues.end;

              if (loopDragType === 'START') {
                  newStart = Math.min(newEnd - 0.25, Math.max(0, loopDragStartValues.start + diffSeconds));
              } else if (loopDragType === 'END') {
                  newEnd = Math.max(newStart + 0.25, loopDragStartValues.end + diffSeconds);
              } else if (loopDragType === 'MOVE') {
                  const duration = loopDragStartValues.end - loopDragStartValues.start;
                  newStart = Math.max(0, loopDragStartValues.start + diffSeconds);
                  newEnd = newStart + duration;
              }

              if (snap) {
                  newStart = snapToGrid(newStart);
                  newEnd = snapToGrid(newEnd);
                  if (newEnd <= newStart) newEnd = newStart + secondsPerBeat;
              }

              setLoopRegion({ ...loopRegion, start: newStart, end: newEnd });
              return;
          }

          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); 
             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;
             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId || loopDragType || marquee?.active) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize, loopDragType, loopDragStartX, loopDragStartValues, loopRegion, setLoopRegion, bpm, marquee]);

  // Wheel Zoom
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom));
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);

  const handleRulerClick = (e: React.MouseEvent) => {
      if (e.button === 2) return;
      if ((e.target as HTMLElement).closest('.loop-region-handle')) return;

      const rect = timelineRef.current?.getBoundingClientRect();
      if (!rect) return;

      const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
      const seekTime = Math.max(0, (clickX / zoom));

      onSeek(snapToGrid(seekTime));
  };

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId || loopDragType) return;

    if (justFinishedMarqueeRef.current) {
        justFinishedMarqueeRef.current = false;
        return;
    }

    const target = e.target as HTMLElement;
    if (target.closest('.loop-region-handle')) return;
    if (target.closest('.ruler-track')) return; 

    const clipElement = target.closest('[data-clip-id]');

    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
                 const time = Math.max(0, clickX / zoom);

                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));
                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;

        if (!marquee?.active) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const seekTime = Math.max(0, (clickX / zoom));
             onSeek(snapToGrid(seekTime));
             setSelectedClipIds([]); 
        }
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      const target = e.target as HTMLElement;
      if (!target.closest('[data-clip-id]') && !target.closest('.loop-region-handle') && !target.closest('[data-automation-track-id]') && !target.closest('.ruler-track')) {
          if (tool === 'MOVE') {
              const rect = timelineRef.current!.getBoundingClientRect();
              const x = e.clientX - rect.left + timelineRef.current!.scrollLeft;
              const y = e.clientY - rect.top + timelineRef.current!.scrollTop;

              setMarquee({
                  startX: x,
                  startY: y,
                  currentX: x,
                  currentY: y,
                  active: true
              });
          }
      }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        const isAudio = file.type.startsWith('audio/') || 
                        file.type === 'video/mp4' || 
                        file.name.toLowerCase().endsWith('.m4a');
        if (isAudio) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const draggedClip = clips.find(c => c.id === draggedClipId);
        if (!draggedClip) return;

        const movingIds = selectedClipIds.includes(draggedClipId) ? selectedClipIds : [draggedClipId];
        const primaryOffset = dragOffsets[draggedClipId] || 0;
        const newPrimaryTime = Math.max(0, dropTime - primaryOffset);
        const timeDelta = newPrimaryTime - draggedClip.startTime; 

        const updates = movingIds.map(id => {
            const clip = clips.find(c => c.id === id);
            if (!clip) return null;

            return {
                id: clip.id,
                startTime: Math.max(0, clip.startTime + timeDelta),
                trackId: id === draggedClipId ? trackId : clip.trackId 
            };
        }).filter(Boolean) as { id: string, startTime: number, trackId?: string }[];

        onClipsUpdate(updates);
        setDraggedClipId(null);
        setDragOffsets({});
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }

     let currentSelection = selectedClipIds;
     if (!selectedClipIds.includes(clip.id)) {
         setSelectedClipIds([clip.id]);
         currentSelection = [clip.id];
     }

     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     const offsets: {[id:string]: number} = {};
     currentSelection.forEach(id => {
         offsets[id] = offsetTime; 
     });

     setDragOffsets(offsets);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      if (!selectedClipIds.includes(clip.id)) {
          setSelectedClipIds([clip.id]);
      }
  };

  const handleLoopDragStart = (e: React.MouseEvent, type: 'START' | 'END' | 'MOVE') => {
      e.stopPropagation();
      e.preventDefault();
      setLoopDragType(type);
      setLoopDragStartX(e.clientX);
      setLoopDragStartValues({ start: loopRegion.start, end: loopRegion.end });
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      if (!selectedClipIds.includes(clipId)) {
          setSelectedClipIds([clipId]);
      }
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleRulerContextMenu = (e: React.MouseEvent) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'RULER',
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP') {
           const targetIsSelected = contextMenu.targetId && selectedClipIds.includes(contextMenu.targetId);
           const idsToActOn = targetIsSelected ? selectedClipIds : (contextMenu.targetId ? [contextMenu.targetId] : []);

           switch(action) {
              case 'delete': onDeleteClips(idsToActOn); break;
              case 'duplicate': onDuplicateClips(idsToActOn); break;
              case 'rename': 
                  if (idsToActOn.length === 1) {
                      const clip = clips.find(c => c.id === idsToActOn[0]);
                      if (clip) {
                          const newName = prompt("Rename clip:", clip.name);
                          if (newName) onRenameClip(idsToActOn[0], newName);
                      }
                  } else {
                      alert("Can only rename one clip at a time.");
                  }
                  break;
              case 'copy': onCopyClips(idsToActOn); break;
              case 'loop': idsToActOn.forEach(id => onLoopClip(id)); break;
              case 'flatten': 
                  if (idsToActOn.length === 1 && onFlattenClip) onFlattenClip(idsToActOn[0]); 
                  else if (idsToActOn.length > 1) alert("Flattening multiple clips not supported yet.");
                  break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClips(contextMenu.time, contextMenu.targetId);
           } else if (action === 'import-file') {
               importTargetRef.current = { trackId: contextMenu.targetId, time: contextMenu.time };
               fileInputRef.current?.click();
           }
      } else if (contextMenu.type === 'RULER' && contextMenu.time !== undefined) {
           if (action === 'set-bpm') {
                setMarkerModal({ isOpen: true, type: 'BPM', time: contextMenu.time });
                setMarkerInputValue(bpm.toString());
           } else if (action === 'set-signature') {
                setMarkerModal({ isOpen: true, type: 'TS', time: contextMenu.time });
                setMarkerInputValue("4/4");
           } else if (action === 'add-marker') {
                setMarkerModal({ isOpen: true, type: 'MARKER', time: contextMenu.time });
                setMarkerInputValue("Verse 1");
           }
      }
      setContextMenu(null);
  };

  const handleMarkerSubmit = () => {
      if (!markerModal || !onAddMarker) return;
      const { type, time } = markerModal;

      if (type === 'BPM') {
          const val = parseInt(markerInputValue);
          if (!isNaN(val)) onAddMarker(time, `${val} BPM`, 'BPM', val);
      } else if (type === 'TS') {
          onAddMarker(time, markerInputValue, 'TS', markerInputValue);
      } else {
          onAddMarker(time, markerInputValue, undefined, undefined);
      }

      setMarkerModal(null);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0] && importTargetRef.current) {
          const { trackId, time } = importTargetRef.current;
          onImportAudio(e.target.files[0], trackId, time);
      }
      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];
      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);
      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ left: i * singleLoopWidth, width: singleLoopWidth }}
                 >
                     <Waveform clip={clip} width={singleLoopWidth} height={TRACK_HEIGHT - 10} color={i === 0 ? "#ffffff" : "#ffffffaa"} />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <>
      <div 
        className={`flex-1 relative flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
        ref={timelineRef}
        onClick={handleTimelineClick}
        onMouseDown={handleMouseDown}
      >
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileSelect}
            className="hidden" 
            accept="audio/*,.m4a,.mp4" 
        />

        {/* Marquee Box */}
        {marquee?.active && (
            <div 
                className="absolute bg-blue-500/20 border border-blue-400 z-50 pointer-events-none"
                style={{
                    left: Math.min(marquee.startX, marquee.currentX),
                    top: Math.min(marquee.startY, marquee.currentY),
                    width: Math.abs(marquee.currentX - marquee.startX),
                    height: Math.abs(marquee.currentY - marquee.startY)
                }}
            />
        )}

        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler - Now with sticky top-0 to stick inside the App-level scroll container */}
        <div 
          className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex cursor-context-menu ruler-track" 
          style={{ width: `${totalBars * pixelsPerBar}px`, height: `${TIMELINE_RULER_HEIGHT}px` }}
          onContextMenu={handleRulerContextMenu}
          onClick={handleRulerClick}
          title="Left-click to seek. Right-click to add Tempo or Time Signature changes"
        >
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50 pointer-events-none" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}

             {/* Markers */}
             {markers.map((m, i) => (
                 <div key={i} className="absolute top-0 h-full border-l border-blue-500 group z-20" style={{ left: m.time * zoom }}>
                     {/* Marker Line */}
                     <div className="absolute top-8 w-px h-[2000px] bg-blue-500/20 pointer-events-none"></div>
                     {/* Marker Label */}
                     <div className="flex items-center bg-blue-600 text-white text-[9px] px-1 rounded-r shadow cursor-pointer hover:bg-blue-500 transition-colors">
                        {m.type === 'BPM' ? <Activity size={8} className="mr-1" /> : m.type === 'TS' ? <Clock size={8} className="mr-1" /> : <Flag size={8} className="mr-1" />}
                        {m.label}
                     </div>
                 </div>
             ))}

             {/* Loop Region Overlay */}
             {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 h-full bg-yellow-400/20 border-l border-r border-yellow-400/50 group loop-region-handle cursor-move"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                    onMouseDown={(e) => handleLoopDragStart(e, 'MOVE')}
                    onClick={(e) => e.stopPropagation()}
                 >
                     <div className="absolute top-0 left-0 w-full h-1 bg-yellow-400/50"></div>

                     {/* Handles */}
                     <div 
                        className="absolute top-0 left-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'START')}
                     />
                     <div 
                        className="absolute top-0 right-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'END')}
                     />
                 </div>
             )}
        </div>

        <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
          {/* Loop Region Background Highlight (Extends down tracks) */}
          {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 bottom-0 bg-white/5 pointer-events-none z-0"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                 />
          )}

          {tracks.map(track => {
            return (
                <div key={track.id} className="flex flex-col z-10">
                  <div 
                      className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                      onDragOver={handleDragOver}
                      onDrop={(e) => handleDrop(e, track.id)}
                      onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                      style={{ 
                          height: `${TRACK_HEIGHT}px`,
                          backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                          backgroundSize: `${pixelsPerBar}px 100%`,
                          backgroundPosition: '0 0'
                      }}
                  >
                      <div 
                          className="absolute inset-0 pointer-events-none" 
                          style={{ backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)', backgroundSize: `${pixelsPerBeat}px 100%`, opacity: 0.1 }}
                      />

                      {clips.filter(c => c.trackId === track.id).map(clip => {
                          const isSelected = selectedClipIds.includes(clip.id);
                          return (
                          <div
                              key={clip.id}
                              data-clip-id={clip.id}
                              draggable={tool === 'MOVE'}
                              onDragStart={(e) => handleDragStart(e, clip)}
                              onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                              onClick={(e) => e.stopPropagation()} 
                              onMouseDown={(e) => { if (tool === 'MOVE' && !isSelected && !e.shiftKey) setSelectedClipIds([clip.id]); }}
                              className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                              ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                              ${isSelected ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                              style={{ left: `${clip.startTime * zoom}px`, width: `${clip.duration * zoom}px` }}
                          >
                              <div className="absolute inset-0 opacity-60" style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}></div>
                              {clip.loop && <div className="absolute top-0 right-4 p-1 text-white/70 z-30"><RotateCw size={10} /></div>}
                              <div className="absolute inset-0 z-10">{renderClipContent(clip, track)}</div>
                              <div className="absolute top-1 left-1 z-20 max-w-full"><div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">{clip.name}</div></div>
                              {tool === 'MOVE' && isSelected && selectedClipIds.length === 1 && <div className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle" onMouseDown={(e) => handleResizeStart(e, clip)}><GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" /></div>}
                          </div>
                      )})}
                  </div>

                  {track.showAutomation && (
                      <div 
                          className="bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair box-border"
                          data-automation-track-id={track.id}
                          style={{ minWidth: `${totalBars * pixelsPerBar}px`, height: `${AUTOMATION_HEIGHT}px` }}
                      >
                          <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                          <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">{track.selectedAutomationId === 'pan' ? 'Pan' : track.selectedAutomationId === 'volume' ? 'Vol' : track.selectedAutomationId?.split(':')[1].toUpperCase()}</div>
                          <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>{renderAutomationPoints(track)}</svg>
                      </div>
                  )}
                </div>
            );
          })}
          <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">End of tracks</div>
        </div>

        {/* Marker Modal Dialog */}
        {markerModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4" onClick={() => setMarkerModal(null)}>
                <div 
                    className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl p-6 w-full max-w-sm" 
                    onClick={e => e.stopPropagation()}
                >
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            {markerModal.type === 'BPM' ? <Activity size={20} className="text-green-400" /> : 
                             markerModal.type === 'TS' ? <Clock size={20} className="text-purple-400" /> : 
                             <Flag size={20} className="text-blue-400" />}
                            {markerModal.type === 'BPM' ? 'Tempo Change' : 
                             markerModal.type === 'TS' ? 'Time Signature' : 
                             'Add Marker'}
                        </h3>
                        <button onClick={() => setMarkerModal(null)} className="text-gray-400 hover:text-white">
                            <X size={20} />
                        </button>
                    </div>

                    <div className="space-y-4">
                        <div>
                            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">
                                {markerModal.type === 'BPM' ? 'New BPM' : 
                                 markerModal.type === 'TS' ? 'Signature (e.g. 3/4)' : 
                                 'Label Name'}
                            </label>
                            <input 
                                type={markerModal.type === 'BPM' ? 'number' : 'text'} 
                                className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:border-blue-500 outline-none transition-colors"
                                value={markerInputValue}
                                onChange={(e) => setMarkerInputValue(e.target.value)}
                                autoFocus
                                onKeyDown={(e) => e.key === 'Enter' && handleMarkerSubmit()}
                            />
                        </div>

                        <div className="flex gap-2">
                            <button 
                                onClick={() => setMarkerModal(null)}
                                className="flex-1 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 rounded-lg transition-colors font-medium text-sm"
                            >
                                Cancel
                            </button>
                            <button 
                                onClick={handleMarkerSubmit}
                                className="flex-1 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg transition-colors font-medium text-sm flex items-center justify-center gap-1"
                            >
                                <Check size={16} /> Confirm
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {contextMenu && (
            <div 
                className="fixed z-50 w-56 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
                style={{ top: contextMenu.y, left: contextMenu.x }}
            >
                {contextMenu.type === 'CLIP' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Copy</button>
                      <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><RotateCw size={14} /> Toggle Loop</button>
                      <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Pencil size={14} /> Rename</button>
                      <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Duplicate</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'flatten')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2 text-blue-400"><FileStack size={14} /> Flatten Clip</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2"><Trash2 size={14} /> Delete</button>
                    </>
                ) : contextMenu.type === 'BACKGROUND' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'paste')} disabled={!canPaste} className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}><ClipboardPaste size={14} /> Paste</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'import-file')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Upload size={14} className="text-blue-400" /> Import Audio File</button>
                    </>
                ) : (
                    <>
                        <div className="px-4 py-2 text-xs font-bold text-gray-500 uppercase">Marker Options</div>
                        <button onClick={(e) => handleMenuAction(e, 'add-marker')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Flag size={14} className="text-blue-400" /> Place Marker</button>
                        <button onClick={(e) => handleMenuAction(e, 'set-bpm')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Activity size={14} className="text-green-400" /> Insert Tempo Change</button>
                        <button onClick={(e) => handleMenuAction(e, 'set-signature')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Clock size={14} className="text-purple-400" /> Insert Time Signature</button>
                    </>
                )}
            </div>
        )}
      </div>
    </>
  );
};

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint, LoopRegion } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, GripVertical, Upload, FileStack, Flag, X, Check } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipsUpdate: (updates: { id: string, startTime: number, trackId?: string }[]) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;

  // Selection & Batch Ops
  selectedClipIds: string[];
  setSelectedClipIds: (ids: string[]) => void;
  onDeleteClips: (ids: string[]) => void;
  onDuplicateClips: (ids: string[]) => void;
  onCopyClips: (ids: string[]) => void;
  onPasteClips: (time: number, trackId: string) => void;
  canPaste: boolean;

  onRenameClip: (id: string, newName: string) => void;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;

  loopRegion: LoopRegion;
  setLoopRegion: (region: LoopRegion) => void;

  onImportAudio: (file: File, trackId: string, time: number) => void;

  markers?: {time: number, label: string}[];
  onAddMarker?: (time: number, label: string) => void;
  setBpm?: (bpm: number) => void;

  onFlattenClip?: (id: string) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND' | 'RULER';
    targetId?: string; // ClipId or TrackId
    time?: number; 
}

interface MarqueeState {
    startX: number;
    startY: number;
    currentX: number;
    currentY: number;
    active: boolean;
}

interface MarkerModalState {
    isOpen: boolean;
    time: number;
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipsUpdate, 
  onFileDrop,
  onSeek,
  selectedClipIds,
  setSelectedClipIds,
  onDeleteClips,
  onDuplicateClips,
  onCopyClips,
  onPasteClips,
  canPaste,
  onRenameClip,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize,
  loopRegion,
  setLoopRegion,
  onImportAudio,
  markers = [],
  onAddMarker,
  setBpm,
  onFlattenClip
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  // Keep track of the initial offset for ALL selected clips during a drag
  const [dragOffsets, setDragOffsets] = useState<{ [id: string]: number }>({});

  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  // Marquee State
  const [marquee, setMarquee] = useState<MarqueeState | null>(null);
  const justFinishedMarqueeRef = useRef(false);

  // Loop Dragging State
  const [loopDragType, setLoopDragType] = useState<'START' | 'END' | 'MOVE' | null>(null);
  const [loopDragStartX, setLoopDragStartX] = useState<number>(0);
  const [loopDragStartValues, setLoopDragStartValues] = useState<{start: number, end: number}>({start:0, end:0});

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const [markerModal, setMarkerModal] = useState<MarkerModalState | null>(null);
  const [markerInputValue, setMarkerInputValue] = useState("");

  const timelineRef = useRef<HTMLDivElement>(null);

  // Refs for File Import
  const fileInputRef = useRef<HTMLInputElement>(null);
  const importTargetRef = useRef<{trackId: string, time: number} | null>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      return Math.round(time / beat) * beat;
  };

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) {
               setDraggedClipId(null);
               setDragOffsets({});
           }
           if (resizingClipId) setResizingClipId(null);
           if (loopDragType) setLoopDragType(null);
           if (marquee?.active) {
               setMarquee(null);
               // Set a flag to prevent the subsequent 'click' event from clearing selection
               justFinishedMarqueeRef.current = true;
               setTimeout(() => { justFinishedMarqueeRef.current = false; }, 100);
           }
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId, loopDragType, marquee]);

  // Global Mouse Move
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;
          const rect = timelineRef.current.getBoundingClientRect();
          const relativeX = e.clientX - rect.left + timelineRef.current.scrollLeft;
          const relativeY = e.clientY - rect.top + timelineRef.current.scrollTop;

          if (marquee?.active) {
              setMarquee(prev => prev ? { ...prev, currentX: relativeX, currentY: relativeY } : null);

              const mX = Math.min(marquee.startX, relativeX);
              const mY = Math.min(marquee.startY, relativeY);
              const mW = Math.abs(relativeX - marquee.startX);
              const mH = Math.abs(relativeY - marquee.startY);

              const newSelectedIds: string[] = [];
              const clipElements = timelineRef.current.querySelectorAll('[data-clip-id]');

              clipElements.forEach(el => {
                  const clipRect = el.getBoundingClientRect();
                  const clipRelX = clipRect.left - rect.left + timelineRef.current!.scrollLeft;
                  const clipRelY = clipRect.top - rect.top + timelineRef.current!.scrollTop;

                  if (mX < clipRelX + clipRect.width &&
                      mX + mW > clipRelX &&
                      mY < clipRelY + clipRect.height &&
                      mY + mH > clipRelY) {
                          const id = el.getAttribute('data-clip-id');
                          if (id) newSelectedIds.push(id);
                      }
              });

              setSelectedClipIds(newSelectedIds);
              return;
          }

          if (loopDragType) {
              const diffPixels = e.clientX - loopDragStartX;
              const diffSeconds = diffPixels / zoom;

              let newStart = loopDragStartValues.start;
              let newEnd = loopDragStartValues.end;

              if (loopDragType === 'START') {
                  newStart = Math.min(newEnd - 0.25, Math.max(0, loopDragStartValues.start + diffSeconds));
              } else if (loopDragType === 'END') {
                  newEnd = Math.max(newStart + 0.25, loopDragStartValues.end + diffSeconds);
              } else if (loopDragType === 'MOVE') {
                  const duration = loopDragStartValues.end - loopDragStartValues.start;
                  newStart = Math.max(0, loopDragStartValues.start + diffSeconds);
                  newEnd = newStart + duration;
              }

              if (snap) {
                  newStart = snapToGrid(newStart);
                  newEnd = snapToGrid(newEnd);
                  if (newEnd <= newStart) newEnd = newStart + secondsPerBeat;
              }

              setLoopRegion({ ...loopRegion, start: newStart, end: newEnd });
              return;
          }

          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); 
             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;
             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId || loopDragType || marquee?.active) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize, loopDragType, loopDragStartX, loopDragStartValues, loopRegion, setLoopRegion, bpm, marquee]);

  // Wheel Zoom
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom));
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);

  const handleRulerClick = (e: React.MouseEvent) => {
      if (e.button === 2) return;
      if ((e.target as HTMLElement).closest('.loop-region-handle')) return;

      const rect = timelineRef.current?.getBoundingClientRect();
      if (!rect) return;

      const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
      const seekTime = Math.max(0, (clickX / zoom));

      onSeek(snapToGrid(seekTime));
  };

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId || loopDragType) return;

    if (justFinishedMarqueeRef.current) {
        justFinishedMarqueeRef.current = false;
        return;
    }

    const target = e.target as HTMLElement;
    if (target.closest('.loop-region-handle')) return;
    if (target.closest('.ruler-track')) return; 

    const clipElement = target.closest('[data-clip-id]');

    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
                 const time = Math.max(0, clickX / zoom);

                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));
                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;

        if (!marquee?.active) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const seekTime = Math.max(0, (clickX / zoom));
             onSeek(snapToGrid(seekTime));
             setSelectedClipIds([]); 
        }
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      const target = e.target as HTMLElement;
      if (!target.closest('[data-clip-id]') && !target.closest('.loop-region-handle') && !target.closest('[data-automation-track-id]') && !target.closest('.ruler-track')) {
          if (tool === 'MOVE') {
              const rect = timelineRef.current!.getBoundingClientRect();
              const x = e.clientX - rect.left + timelineRef.current!.scrollLeft;
              const y = e.clientY - rect.top + timelineRef.current!.scrollTop;

              setMarquee({
                  startX: x,
                  startY: y,
                  currentX: x,
                  currentY: y,
                  active: true
              });
          }
      }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        const isAudio = file.type.startsWith('audio/') || 
                        file.type === 'video/mp4' || 
                        file.name.toLowerCase().endsWith('.m4a');
        if (isAudio) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const draggedClip = clips.find(c => c.id === draggedClipId);
        if (!draggedClip) return;

        const movingIds = selectedClipIds.includes(draggedClipId) ? selectedClipIds : [draggedClipId];
        const primaryOffset = dragOffsets[draggedClipId] || 0;
        const newPrimaryTime = Math.max(0, dropTime - primaryOffset);
        const timeDelta = newPrimaryTime - draggedClip.startTime; 

        const updates = movingIds.map(id => {
            const clip = clips.find(c => c.id === id);
            if (!clip) return null;

            return {
                id: clip.id,
                startTime: Math.max(0, clip.startTime + timeDelta),
                trackId: id === draggedClipId ? trackId : clip.trackId 
            };
        }).filter(Boolean) as { id: string, startTime: number, trackId?: string }[];

        onClipsUpdate(updates);
        setDraggedClipId(null);
        setDragOffsets({});
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }

     let currentSelection = selectedClipIds;
     if (!selectedClipIds.includes(clip.id)) {
         setSelectedClipIds([clip.id]);
         currentSelection = [clip.id];
     }

     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     const offsets: {[id:string]: number} = {};
     currentSelection.forEach(id => {
         offsets[id] = offsetTime; 
     });

     setDragOffsets(offsets);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      if (!selectedClipIds.includes(clip.id)) {
          setSelectedClipIds([clip.id]);
      }
  };

  const handleLoopDragStart = (e: React.MouseEvent, type: 'START' | 'END' | 'MOVE') => {
      e.stopPropagation();
      e.preventDefault();
      setLoopDragType(type);
      setLoopDragStartX(e.clientX);
      setLoopDragStartValues({ start: loopRegion.start, end: loopRegion.end });
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      if (!selectedClipIds.includes(clipId)) {
          setSelectedClipIds([clipId]);
      }
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleRulerContextMenu = (e: React.MouseEvent) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'RULER',
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP') {
           const targetIsSelected = contextMenu.targetId && selectedClipIds.includes(contextMenu.targetId);
           const idsToActOn = targetIsSelected ? selectedClipIds : (contextMenu.targetId ? [contextMenu.targetId] : []);

           switch(action) {
              case 'delete': onDeleteClips(idsToActOn); break;
              case 'duplicate': onDuplicateClips(idsToActOn); break;
              case 'rename': 
                  if (idsToActOn.length === 1) {
                      const clip = clips.find(c => c.id === idsToActOn[0]);
                      if (clip) {
                          const newName = prompt("Rename clip:", clip.name);
                          if (newName) onRenameClip(idsToActOn[0], newName);
                      }
                  } else {
                      alert("Can only rename one clip at a time.");
                  }
                  break;
              case 'copy': onCopyClips(idsToActOn); break;
              case 'loop': idsToActOn.forEach(id => onLoopClip(id)); break;
              case 'flatten': 
                  if (idsToActOn.length === 1 && onFlattenClip) onFlattenClip(idsToActOn[0]); 
                  else if (idsToActOn.length > 1) alert("Flattening multiple clips not supported yet.");
                  break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClips(contextMenu.time, contextMenu.targetId);
           } else if (action === 'import-file') {
               importTargetRef.current = { trackId: contextMenu.targetId, time: contextMenu.time };
               fileInputRef.current?.click();
           }
      } else if (contextMenu.type === 'RULER' && contextMenu.time !== undefined) {
           if (action === 'add-marker') {
                setMarkerModal({ isOpen: true, time: contextMenu.time });
                setMarkerInputValue("Verse 1");
           }
      }
      setContextMenu(null);
  };

  const handleMarkerSubmit = () => {
      if (!markerModal || !onAddMarker) return;
      const { time } = markerModal;

      onAddMarker(time, markerInputValue);

      setMarkerModal(null);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0] && importTargetRef.current) {
          const { trackId, time } = importTargetRef.current;
          onImportAudio(e.target.files[0], trackId, time);
      }
      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];
      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);
      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ left: i * singleLoopWidth, width: singleLoopWidth }}
                 >
                     <Waveform clip={clip} width={singleLoopWidth} height={TRACK_HEIGHT - 10} color={i === 0 ? "#ffffff" : "#ffffffaa"} />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <>
      <div 
        className={`flex-1 relative flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
        ref={timelineRef}
        onClick={handleTimelineClick}
        onMouseDown={handleMouseDown}
      >
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileSelect}
            className="hidden" 
            accept="audio/*,.m4a,.mp4" 
        />

        {/* Marquee Box */}
        {marquee?.active && (
            <div 
                className="absolute bg-blue-500/20 border border-blue-400 z-50 pointer-events-none"
                style={{
                    left: Math.min(marquee.startX, marquee.currentX),
                    top: Math.min(marquee.startY, marquee.currentY),
                    width: Math.abs(marquee.currentX - marquee.startX),
                    height: Math.abs(marquee.currentY - marquee.startY)
                }}
            />
        )}

        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler - Now with sticky top-0 to stick inside the App-level scroll container */}
        <div 
          className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex cursor-context-menu ruler-track" 
          style={{ width: `${totalBars * pixelsPerBar}px`, height: `${TIMELINE_RULER_HEIGHT}px` }}
          onContextMenu={handleRulerContextMenu}
          onClick={handleRulerClick}
          title="Left-click to seek. Right-click to add Tempo or Time Signature changes"
        >
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50 pointer-events-none" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}

             {/* Markers */}
             {markers.map((m, i) => (
                 <div key={i} className="absolute top-0 h-full border-l border-blue-500 group z-20" style={{ left: m.time * zoom }}>
                     {/* Marker Line */}
                     <div className="absolute top-8 w-px h-[2000px] bg-blue-500/20 pointer-events-none"></div>
                     {/* Marker Label */}
                     <div className="flex items-center bg-blue-600 text-white text-[9px] px-1 rounded-r shadow cursor-pointer hover:bg-blue-500 transition-colors">
                        <Flag size={8} className="mr-1" />
                        {m.label}
                     </div>
                 </div>
             ))}

             {/* Loop Region Overlay */}
             {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 h-full bg-yellow-400/20 border-l border-r border-yellow-400/50 group loop-region-handle cursor-move"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                    onMouseDown={(e) => handleLoopDragStart(e, 'MOVE')}
                    onClick={(e) => e.stopPropagation()}
                 >
                     <div className="absolute top-0 left-0 w-full h-1 bg-yellow-400/50"></div>

                     {/* Handles */}
                     <div 
                        className="absolute top-0 left-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'START')}
                     />
                     <div 
                        className="absolute top-0 right-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'END')}
                     />
                 </div>
             )}
        </div>

        <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
          {/* Loop Region Background Highlight (Extends down tracks) */}
          {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 bottom-0 bg-white/5 pointer-events-none z-0"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                 />
          )}

          {tracks.map(track => {
            return (
                <div key={track.id} className="flex flex-col z-10">
                  <div 
                      className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                      onDragOver={handleDragOver}
                      onDrop={(e) => handleDrop(e, track.id)}
                      onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                      style={{ 
                          height: `${TRACK_HEIGHT}px`,
                          backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                          backgroundSize: `${pixelsPerBar}px 100%`,
                          backgroundPosition: '0 0'
                      }}
                  >
                      <div 
                          className="absolute inset-0 pointer-events-none" 
                          style={{ backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)', backgroundSize: `${pixelsPerBeat}px 100%`, opacity: 0.1 }}
                      />

                      {clips.filter(c => c.trackId === track.id).map(clip => {
                          const isSelected = selectedClipIds.includes(clip.id);
                          return (
                          <div
                              key={clip.id}
                              data-clip-id={clip.id}
                              draggable={tool === 'MOVE'}
                              onDragStart={(e) => handleDragStart(e, clip)}
                              onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                              onClick={(e) => e.stopPropagation()} 
                              onMouseDown={(e) => { if (tool === 'MOVE' && !isSelected && !e.shiftKey) setSelectedClipIds([clip.id]); }}
                              className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                              ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                              ${isSelected ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                              style={{ left: `${clip.startTime * zoom}px`, width: `${clip.duration * zoom}px` }}
                          >
                              <div className="absolute inset-0 opacity-60" style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}></div>
                              {clip.loop && <div className="absolute top-0 right-4 p-1 text-white/70 z-30"><RotateCw size={10} /></div>}
                              <div className="absolute inset-0 z-10">{renderClipContent(clip, track)}</div>
                              <div className="absolute top-1 left-1 z-20 max-w-full"><div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">{clip.name}</div></div>
                              {tool === 'MOVE' && isSelected && selectedClipIds.length === 1 && <div className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle" onMouseDown={(e) => handleResizeStart(e, clip)}><GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" /></div>}
                          </div>
                      )})}
                  </div>

                  {track.showAutomation && (
                      <div 
                          className="bg-gray-900/50 border-b border-gray-800 relative cursor-crosshair box-border"
                          data-automation-track-id={track.id}
                          style={{ minWidth: `${totalBars * pixelsPerBar}px`, height: `${AUTOMATION_HEIGHT}px` }}
                      >
                          <div className="absolute inset-0 pointer-events-none border-b border-dashed border-white/10 top-1/2"></div>
                          <div className="absolute top-1 left-1 text-[9px] text-blue-400 font-bold bg-black/50 px-1 rounded pointer-events-none">{track.selectedAutomationId === 'pan' ? 'Pan' : track.selectedAutomationId === 'volume' ? 'Vol' : track.selectedAutomationId?.split(':')[1].toUpperCase()}</div>
                          <svg className="absolute inset-0 w-full h-full pointer-events-none" style={{ overflow: 'visible' }}>{renderAutomationPoints(track)}</svg>
                      </div>
                  )}
                </div>
            );
          })}
          <div className="h-64 flex items-center justify-center text-gray-800 select-none pointer-events-none">End of tracks</div>
        </div>

        {/* Marker Modal Dialog */}
        {markerModal && (
            <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4" onClick={() => setMarkerModal(null)}>
                <div 
                    className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl p-6 w-full max-w-sm" 
                    onClick={e => e.stopPropagation()}
                >
                    <div className="flex justify-between items-center mb-4">
                        <h3 className="text-lg font-bold text-white flex items-center gap-2">
                            <Flag size={20} className="text-blue-400" />
                            Add Marker
                        </h3>
                        <button onClick={() => setMarkerModal(null)} className="text-gray-400 hover:text-white">
                            <X size={20} />
                        </button>
                    </div>

                    <div className="space-y-4">
                        <div>
                            <label className="block text-xs font-bold text-gray-400 uppercase mb-1">
                                Label Name
                            </label>
                            <input 
                                type='text' 
                                className="w-full bg-gray-800 border border-gray-700 rounded-lg px-3 py-2 text-white focus:border-blue-500 outline-none transition-colors"
                                value={markerInputValue}
                                onChange={(e) => setMarkerInputValue(e.target.value)}
                                autoFocus
                                onKeyDown={(e) => e.key === 'Enter' && handleMarkerSubmit()}
                            />
                        </div>

                        <div className="flex gap-2">
                            <button 
                                onClick={() => setMarkerModal(null)}
                                className="flex-1 py-2 bg-gray-800 hover:bg-gray-700 text-gray-300 rounded-lg transition-colors font-medium text-sm"
                            >
                                Cancel
                            </button>
                            <button 
                                onClick={handleMarkerSubmit}
                                className="flex-1 py-2 bg-blue-600 hover:bg-blue-500 text-white rounded-lg transition-colors font-medium text-sm flex items-center justify-center gap-1"
                            >
                                <Check size={16} /> Confirm
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}

        {contextMenu && (
            <div 
                className="fixed z-50 w-56 bg-gray-800 border border-gray-600 rounded-lg shadow-xl py-1 text-sm text-gray-200 animate-in fade-in zoom-in-95 duration-100"
                style={{ top: contextMenu.y, left: contextMenu.x }}
            >
                {contextMenu.type === 'CLIP' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'copy')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Copy</button>
                      <button onClick={(e) => handleMenuAction(e, 'loop')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><RotateCw size={14} /> Toggle Loop</button>
                      <button onClick={(e) => handleMenuAction(e, 'rename')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Pencil size={14} /> Rename</button>
                      <button onClick={(e) => handleMenuAction(e, 'duplicate')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Copy size={14} /> Duplicate</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'flatten')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2 text-blue-400"><FileStack size={14} /> Flatten Clip</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'delete')} className="w-full text-left px-4 py-2 hover:bg-red-900/50 text-red-400 hover:text-red-300 flex items-center gap-2"><Trash2 size={14} /> Delete</button>
                    </>
                ) : contextMenu.type === 'BACKGROUND' ? (
                    <>
                      <button onClick={(e) => handleMenuAction(e, 'paste')} disabled={!canPaste} className={`w-full text-left px-4 py-2 flex items-center gap-2 ${canPaste ? 'hover:bg-gray-700' : 'opacity-50 cursor-not-allowed'}`}><ClipboardPaste size={14} /> Paste</button>
                      <div className="h-px bg-gray-700 my-1" />
                      <button onClick={(e) => handleMenuAction(e, 'import-file')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Upload size={14} className="text-blue-400" /> Import Audio File</button>
                    </>
                ) : (
                    <>
                        <div className="px-4 py-2 text-xs font-bold text-gray-500 uppercase">Marker Options</div>
                        <button onClick={(e) => handleMenuAction(e, 'add-marker')} className="w-full text-left px-4 py-2 hover:bg-gray-700 flex items-center gap-2"><Flag size={14} className="text-blue-400" /> Place Marker</button>
                    </>
                )}
            </div>
        )}
      </div>
    </>
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { MasterVisualizer } from './components/MasterVisualizer';
import { SettingsModal } from './components/SettingsModal';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, LoopRegion } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(120);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [timeMarkers, setTimeMarkers] = useState<{time: number, label: string}[]>([]);

  // Metronome State
  const [isMetronomeOn, setIsMetronomeOn] = useState(false);
  const [countInMeasures, setCountInMeasures] = useState(1);

  // Loop State (Default measures 1-4 -> 0s to 8s at 120bpm)
  const [loopRegion, setLoopRegion] = useState<LoopRegion>({ start: 0, end: 8, enabled: false });
  // Ref for loop region to access in RAF without re-binding
  const loopRegionRef = useRef(loopRegion);
  const markersRef = useRef(timeMarkers);

  useEffect(() => {
      loopRegionRef.current = loopRegion;
  }, [loopRegion]);

  useEffect(() => {
      markersRef.current = timeMarkers;
  }, [timeMarkers]);

  // Recording State
  const [armedTrackId, setArmedTrackId] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  // Selection State (Multi-select)
  const [selectedClipIds, setSelectedClipIds] = useState<string[]>([]);
  const [clipboardClips, setClipboardClips] = useState<AudioClip[]>([]);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Refs ---
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const navigatorRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0); // Timeline position where recording block starts
  const recordPreRollRef = useRef<number>(0); // How much physical audio was captured BEFORE timeline start

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Navigator Scroll Sync ---
  const handleMainScroll = () => {
      if (scrollContainerRef.current && navigatorRef.current) {
          navigatorRef.current.scrollLeft = scrollContainerRef.current.scrollLeft;
      }
  };

  const handleNavigatorScroll = (e: React.UIEvent<HTMLDivElement>) => {
      const target = e.target as HTMLDivElement;
      if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollLeft = target.scrollLeft;
      }
  };

  // --- Smart Zoom Handling ---
  const handleZoomChange = useCallback((newZoom: number) => {
      const clampedZoom = Math.max(10, Math.min(500, newZoom));
      setZoom(clampedZoom);

      // Center playhead logic
      if (scrollContainerRef.current) {
          requestAnimationFrame(() => {
              if (scrollContainerRef.current) {
                  const containerWidth = scrollContainerRef.current.clientWidth;
                  const playheadX = playbackState.currentTime * clampedZoom;
                  // Center playhead: target scroll is playheadX - halfWidth
                  const targetScroll = Math.max(0, playheadX - (containerWidth / 2));
                  scrollContainerRef.current.scrollLeft = targetScroll;
              }
          });
      }
  }, [playbackState.currentTime]);

  // --- Undo/Redo System ---
  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks);
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex - 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks);
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };

  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stopPlayback(); 
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    // Schedule metronome if enabled
    if (isMetronomeOn) {
        audioService.scheduleMetronome(bpm, audioService.getContext().currentTime, 300); // Schedule 5 mins of clicks
    }

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true, currentTime: startAt }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      // Loop Check using REF to avoid closure staleness
      if (loopRegionRef.current.enabled && newTime >= loopRegionRef.current.end) {
          startPlayback(loopRegionRef.current.start);
          return; 
      }

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks, bpm, isMetronomeOn]); 

  const handleSeek = useCallback((time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));

      // If playing, we need to restart playback at new position
      if (playbackState.isPlaying) {
           startPlayback(time);
      }
  }, [playbackState.isPlaying, startPlayback]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (isRecording) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [isRecording]);

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---
  const handleArmTrack = async (trackId: string) => {
      if (armedTrackId === trackId) {
          setArmedTrackId(null);
          audioService.disableMonitoring();
      } else {
          try {
              // Critical: Await monitoring setup BEFORE updating state to ensure visualizer is ready
              await audioService.enableMonitoring(trackId); 
              setArmedTrackId(trackId);
          } catch(e) {
              alert("Could not access microphone.");
              setArmedTrackId(null);
          }
      }
  };

  const handleTransportRecord = async () => {
      if (isRecording) {
          handleStop();
      } else {
          if (!armedTrackId) {
              alert("Please arm a track first.");
              return;
          }
          try {
            await audioService.resume();

            // 1. Start Recording Physically FIRST to capture pre-roll/setup
            await audioService.startRecording();
            const sysRecordStart = audioService.getContext().currentTime;

            // 2. Count-In Logic (if enabled)
            if (countInMeasures > 0) {
                 await audioService.playCountIn(bpm, countInMeasures);
            } else {
                 // Even without count-in, wait a tiny bit to ensure we capture the transient of the first beat
                 await new Promise(r => setTimeout(r, 100));
            }

            // 3. Start Playback Transport
            const sysPlaybackStart = audioService.getContext().currentTime;

            // Calculate how much audio we captured before the transport actually started
            const preRollDuration = sysPlaybackStart - sysRecordStart;

            setIsRecording(true);
            recordStartTimeRef.current = pauseTimeRef.current;
            recordPreRollRef.current = preRollDuration;

            startPlayback(pauseTimeRef.current);
          } catch(e) {
              console.error("Recording failed to start", e);
              alert("Failed to start recording. Please check microphone permissions.");
          }
      }
  };

  const finishRecording = async () => {
      if (!armedTrackId) {
          setIsRecording(false);
          return;
      }
      const blob = await audioService.stopRecording();
      const timelineStart = recordStartTimeRef.current;
      const preRoll = recordPreRollRef.current;

      if (blob && blob.size > 0) {
          try {
              const buffer = await audioService.decodeBlob(blob);

              // --- Latency Compensation & Placement ---
              const latency = audioService.latencySeconds;

              // The buffer contains [PreRoll] + [Performance].
              // The Performance started at buffer time = preRoll + latency (approx).
              // We want this point to align with `timelineStart`.

              // Theoretical Offset into buffer for T=timelineStart
              let targetOffset = preRoll + latency;

              // Safety: Reveal a bit of the pre-roll to catch early transients (rushing).
              // We shift the clip START TIME back by `safetyMargin` and reduce OFFSET by same amount.
              const safetyMargin = Math.min(preRoll, 0.2); // Up to 200ms

              const finalClipStart = timelineStart - safetyMargin;
              const finalClipOffset = targetOffset - safetyMargin;

              // Duration needs to be calculated based on what's left in the buffer
              // Buffer Duration - Offset = Playable Length
              // But we added safetyMargin to length by reducing offset.
              const finalDuration = Math.max(0, buffer.duration - finalClipOffset);

              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: armedTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: finalClipStart, // Can be negative or < timelineStart
                  duration: finalDuration,
                  offset: Math.max(0, finalClipOffset),
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };

              if (finalDuration > 0) {
                  updateStateWithHistory(tracks, [...clips, newClip]);
              }
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }
      setIsRecording(false);
  };

  // --- Track Management ---
  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) points[existingIdx] = point;
             else points.push(point);
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---
  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  // Batch Update for moving multiple clips
  const updateClips = (updates: { id: string, startTime: number, trackId?: string }[]) => {
      const newClips = clips.map(c => {
          const update = updates.find(u => u.id === c.id);
          if (update) {
              // Prevent moving to master track
              if (update.trackId === 'master') return c;
              return { ...c, startTime: update.startTime, trackId: update.trackId || c.trackId };
          }
          return c;
      });
      setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  // --- Batch Operations (Delete, Duplicate, Copy, Paste) ---

  const deleteClips = (ids: string[]) => {
      const newClips = clips.filter(c => !ids.includes(c.id));
      setSelectedClipIds([]);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClips = (ids: string[]) => {
      const clipsToDuplicate = clips.filter(c => ids.includes(c.id));
      if (clipsToDuplicate.length === 0) return;

      const newClips = [...clips];
      const newIds: string[] = [];

      clipsToDuplicate.forEach(original => {
          const newId = uuidv4();
          newIds.push(newId);
          newClips.push({
              ...original,
              id: newId,
              // Per user request: Place immediately after original
              startTime: original.startTime + original.duration, 
              name: `${original.name} (Copy)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleFlattenClip = async (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (!clip) return;

      try {
          const newBuffer = await audioService.bounceClip(clip);
          const newClip: AudioClip = {
              ...clip,
              buffer: newBuffer,
              offset: 0,
              duration: clip.duration, 
              playbackRate: 1, 
              name: `${clip.name} (Flattened)`,
              loop: false 
          };

          const newClips = clips.map(c => c.id === id ? newClip : c);
          updateStateWithHistory(tracks, newClips);
          // Keep selection
          if (selectedClipIds.includes(id)) {
              // no-op, still selected
          }
      } catch (e) {
          console.error("Flatten failed", e);
          alert("Could not flatten clip.");
      }
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;
      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return;

      const firstDuration = relativeSplit * clip.playbackRate;
      const leftClip: AudioClip = { ...clip, id: uuidv4(), duration: firstDuration, name: clip.name };
      const rightClip: AudioClip = { ...clip, id: uuidv4(), startTime: splitTime, offset: clip.offset + firstDuration, duration: clip.duration - firstDuration, name: clip.name };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      // Update selection to the new clips if original was selected
      if (selectedClipIds.includes(clipId)) {
          setSelectedClipIds([leftClip.id, rightClip.id]);
      }

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClips = (ids: string[]) => {
      const selected = clips.filter(c => ids.includes(c.id));
      if (selected.length > 0) setClipboardClips(selected);
  };

  const handlePasteClips = (time: number, targetTrackId: string) => {
      if (clipboardClips.length === 0 || targetTrackId === 'master') return;

      // Calculate relative offsets based on the earliest clip in clipboard
      const minStartTime = Math.min(...clipboardClips.map(c => c.startTime));

      const newClips = [...clips];
      const newIds: string[] = [];

      clipboardClips.forEach(clip => {
          const relativeTime = clip.startTime - minStartTime;
          const newId = uuidv4();
          newIds.push(newId);

          newClips.push({
              ...clip,
              id: newId,
              startTime: time + relativeTime,
              trackId: targetTrackId, // Collapse to the track where user right-clicked for now
              name: `${clip.name} (Paste)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;
          const newClips = clips.map(c => c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---
  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const handleExportStems = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          for (const track of tracks) {
             if (track.isMaster) continue;
             const trackClips = clips.filter(c => c.trackId === track.id);
             if (trackClips.length === 0) continue;

             const blob = await audioService.renderOffline(trackClips, [track, MASTER_TRACK]);

             const url = URL.createObjectURL(blob);
             const a = document.createElement('a');
             a.href = url;
             a.download = `${track.name}_Stem.wav`;
             a.click();
             URL.revokeObjectURL(url);

             await new Promise(r => setTimeout(r, 500));
          }
      } catch (e) {
          console.error("Stem Export failed", e);
          alert("Stem Export failed.");
      } finally {
          setIsExporting(false);
          setIsSettingsOpen(false);
      }
  };

  // --- Derived State & Variables ---
  const regularTracks = tracks.filter(t => !t.isMaster);
  const masterTrack = tracks.find(t => t.isMaster) || MASTER_TRACK;

  // Only show editor if exactly one clip is selected
  const selectedClip = selectedClipIds.length === 1 
      ? clips.find(c => c.id === selectedClipIds[0]) || null
      : null;

  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration));
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const pixelsPerBar = secondsPerBar * zoom;
  const timelineWidth = totalBars * pixelsPerBar;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <SettingsModal 
          isOpen={isSettingsOpen} 
          onClose={() => setIsSettingsOpen(false)}
          onExportStems={handleExportStems}
      />

      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        isRecording={isRecording}
        onRecord={handleTransportRecord}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={(newBpm) => {
            setBpm(newBpm);
        }}
        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={handleZoomChange}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
        loopRegion={loopRegion}
        setLoopRegion={setLoopRegion}
        isMetronomeOn={isMetronomeOn}
        toggleMetronome={() => setIsMetronomeOn(!isMetronomeOn)}
        countInMeasures={countInMeasures}
        setCountInMeasures={setCountInMeasures}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      {/* Main Workspace: Single Unified Scroll Container */}
      <div 
        className="flex-1 overflow-auto relative" 
        ref={scrollContainerRef}
        onScroll={handleMainScroll}
      >
        <div className="flex min-w-max">
            {/* Sticky Left Column (Headers) */}
            <div 
                className="sticky left-0 z-30 bg-gray-900 border-r border-gray-700 flex flex-col flex-shrink-0 shadow-lg"
                style={{ width: TRACK_HEADER_WIDTH }}
            >
                 {/* Sticky Top-Left Corner */}
                 <div 
                    className="sticky top-0 z-40 bg-gray-900 border-b border-gray-700 flex-shrink-0"
                    style={{ height: TIMELINE_RULER_HEIGHT }}
                 />

                 {/* Track Headers List */}
                 {regularTracks.map(track => (
                    <TrackControl 
                        key={track.id} 
                        track={track} 
                        onUpdate={updateTrack}
                        onDelete={deleteTrack}
                        isArmed={armedTrackId === track.id}
                        isRecordingGlobal={isRecording}
                        onArmToggle={() => handleArmTrack(track.id)}
                        onOpenEditor={setEditingTrackId}
                        onToggleAutomation={toggleAutomation}
                    />
                 ))}

                 <div className="p-3">
                     <button 
                        onClick={addTrack}
                        className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                        title="Add a new audio track"
                     >
                        <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors"><Plus size={14} /></div>
                        <span>Add Track</span>
                     </button>
                 </div>

                 {/* Bottom Spacer */}
                 <div className="h-64 bg-gray-900" />
            </div>

            {/* Main Timeline Area (Scrolls with parent) */}
            <div className="flex flex-col flex-1">
                {/* Timeline Component - renders Ruler (sticky inside) and Tracks */}
                <Timeline 
                    tracks={regularTracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipsUpdate={updateClips} // Batch update
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={handleZoomChange}
                    snap={snap}
                    tool={tool}

                    selectedClipIds={selectedClipIds}
                    setSelectedClipIds={setSelectedClipIds}

                    onDeleteClips={deleteClips}
                    onDuplicateClips={duplicateClips}
                    onCopyClips={handleCopyClips}
                    onPasteClips={handlePasteClips}
                    canPaste={clipboardClips.length > 0}

                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}
                    onClipResize={handleClipResize}
                    onLoopClip={handleLoopToggle}
                    onFlattenClip={handleFlattenClip}

                    loopRegion={loopRegion}
                    setLoopRegion={setLoopRegion}
                    onImportAudio={handleFileDrop}
                    markers={timeMarkers}
                    onAddMarker={(time, label, type, value) => setTimeMarkers([...timeMarkers, {time, label, type, value}])}
                    setBpm={setBpm}
                />
            </div>
        </div>
      </div>

      {/* Fixed Bottom Master Section */}
      <div className="h-44 bg-gray-900 border-t-2 border-gray-800 flex flex-col z-50 shadow-[0_-5px_15px_rgba(0,0,0,0.5)]">
         {/* Master Row */}
         <div className="flex flex-1 overflow-hidden">
             {/* Master Control (Left) */}
             <div className="flex-shrink-0 border-r border-gray-800" style={{ width: TRACK_HEADER_WIDTH }}>
                <TrackControl 
                  track={masterTrack}
                  onUpdate={updateTrack}
                  onDelete={() => {}}
                  isArmed={false}
                  isRecordingGlobal={false}
                  onArmToggle={() => {}}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={() => {}}
                />
             </div>
             {/* Master Visualizer (Right) */}
             <div className="flex-1 p-2 bg-gray-900 flex items-center justify-center">
                 <MasterVisualizer isPlaying={playbackState.isPlaying} />
             </div>
         </div>

         {/* Navigator / Scrollbar (Bottom Fixed) */}
         <div className="h-5 bg-gray-950 border-t border-gray-800">
             <div 
                ref={navigatorRef}
                onScroll={handleNavigatorScroll}
                className="w-full h-full overflow-x-auto overflow-y-hidden custom-scrollbar"
                title="Timeline Navigator"
             >
                <div style={{ width: timelineWidth + TRACK_HEADER_WIDTH, height: '1px' }}></div>
             </div>
         </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipIds([])}
            projectBpm={bpm}
          />
      )}
    </div>
  );
}

export default App;

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { v4 as uuidv4 } from 'uuid';
import { TrackControl } from './components/TrackControl';
import { Timeline } from './components/Timeline';
import { Transport } from './components/Transport';
import { ClipEditor } from './components/ClipEditor';
import { TrackEditor } from './components/TrackEditor';
import { MasterVisualizer } from './components/MasterVisualizer';
import { SettingsModal } from './components/SettingsModal';
import { Track, AudioClip, PlaybackState, ToolType, HistoryState, AutomationPoint, LoopRegion } from './types';
import { TRACK_COLORS, TRACK_HEADER_WIDTH, TIMELINE_RULER_HEIGHT } from './constants';
import { audioService } from './services/audioEngine';
import { Plus } from 'lucide-react';

const INITIAL_TRACKS: Track[] = [
  { id: 'track-1', name: 'Drums', color: TRACK_COLORS[0], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-2', name: 'Bass', color: TRACK_COLORS[1], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-3', name: 'Melody', color: TRACK_COLORS[4], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
  { id: 'track-4', name: 'Vocals', color: TRACK_COLORS[5], volume: 0.8, muted: false, soloed: false, plugins: [], automation: { volume: [] }, showAutomation: false, selectedAutomationId: 'volume' },
];

const MASTER_TRACK: Track = {
    id: 'master',
    name: 'Master',
    color: '#1e293b',
    volume: 0.8,
    muted: false,
    soloed: false,
    plugins: [],
    isMaster: true,
    automation: { volume: [] },
    showAutomation: false,
    selectedAutomationId: 'volume'
};

function App() {
  // --- Core State ---
  const [tracks, setTracks] = useState<Track[]>([...INITIAL_TRACKS, MASTER_TRACK]);
  const [clips, setClips] = useState<AudioClip[]>([]);

  // --- UI/Tool State ---
  const [bpm, setBpm] = useState<number>(90);
  const [zoom, setZoom] = useState<number>(50); // Pixels per second
  const [snap, setSnap] = useState<boolean>(true);
  const [tool, setTool] = useState<ToolType>('MOVE');
  const [isExporting, setIsExporting] = useState(false);
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [timeMarkers, setTimeMarkers] = useState<{time: number, label: string}[]>([]);

  // Metronome State
  const [isMetronomeOn, setIsMetronomeOn] = useState(false);
  const [countInMeasures, setCountInMeasures] = useState(1);

  // Loop State (Default measures 1-4 -> 0s to 8s at 120bpm)
  const [loopRegion, setLoopRegion] = useState<LoopRegion>({ start: 0, end: 8, enabled: false });
  // Ref for loop region to access in RAF without re-binding
  const loopRegionRef = useRef(loopRegion);
  const markersRef = useRef(timeMarkers);

  useEffect(() => {
      loopRegionRef.current = loopRegion;
  }, [loopRegion]);

  useEffect(() => {
      markersRef.current = timeMarkers;
  }, [timeMarkers]);

  // Recording State
  const [armedTrackId, setArmedTrackId] = useState<string | null>(null);
  const [isRecording, setIsRecording] = useState(false);

  // Selection State (Multi-select)
  const [selectedClipIds, setSelectedClipIds] = useState<string[]>([]);
  const [clipboardClips, setClipboardClips] = useState<AudioClip[]>([]);
  const [editingTrackId, setEditingTrackId] = useState<string | null>(null);

  // --- Refs ---
  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const navigatorRef = useRef<HTMLDivElement>(null);

  // --- History State ---
  const [history, setHistory] = useState<HistoryState[]>([]);
  const [historyIndex, setHistoryIndex] = useState(-1);

  // --- Playback State ---
  const [playbackState, setPlaybackState] = useState<PlaybackState>({
    isPlaying: false,
    currentTime: 0
  });

  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number>(0); 
  const pauseTimeRef = useRef<number>(0); 
  const recordStartTimeRef = useRef<number>(0); // Timeline position where recording block starts
  const recordPreRollRef = useRef<number>(0); // How much physical audio was captured BEFORE timeline start

  // Initialize Audio Nodes
  useEffect(() => {
    tracks.forEach(track => {
      audioService.createTrackNodes(track.id, track.isMaster);
      audioService.updateTrackVolume(track.id, track.volume);
      audioService.updateTrackPlugins(track.id, track.plugins);
    });
  }, []); 

  // --- Navigator Scroll Sync ---
  const handleMainScroll = () => {
      if (scrollContainerRef.current && navigatorRef.current) {
          navigatorRef.current.scrollLeft = scrollContainerRef.current.scrollLeft;
      }
  };

  const handleNavigatorScroll = (e: React.UIEvent<HTMLDivElement>) => {
      const target = e.target as HTMLDivElement;
      if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollLeft = target.scrollLeft;
      }
  };

  // --- Smart Zoom Handling ---
  const handleZoomChange = useCallback((newZoom: number) => {
      const clampedZoom = Math.max(10, Math.min(500, newZoom));
      setZoom(clampedZoom);

      // Center playhead logic
      if (scrollContainerRef.current) {
          requestAnimationFrame(() => {
              if (scrollContainerRef.current) {
                  const containerWidth = scrollContainerRef.current.clientWidth;
                  const playheadX = playbackState.currentTime * clampedZoom;
                  // Center playhead: target scroll is playheadX - halfWidth
                  const targetScroll = Math.max(0, playheadX - (containerWidth / 2));
                  scrollContainerRef.current.scrollLeft = targetScroll;
              }
          });
      }
  }, [playbackState.currentTime]);

  // --- Undo/Redo System ---
  const pushHistory = useCallback((newTracks: Track[], newClips: AudioClip[]) => {
      const newState = { tracks: newTracks, clips: newClips };
      const currentHistory = history.slice(0, historyIndex + 1);
      setHistory([...currentHistory, newState]);
      setHistoryIndex(prev => prev + 1);
  }, [history, historyIndex]);

  useEffect(() => {
      if (history.length === 0) {
          pushHistory(tracks, clips);
      }
  }, []);

  const handleUndo = () => {
      if (historyIndex > 0) {
          const prevState = history[historyIndex - 1];
          setTracks(prevState.tracks);
          setClips(prevState.clips);
          setHistoryIndex(historyIndex - 1);
          prevState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(prevState.tracks);
          if (playbackState.isPlaying) handleStop(); 
      }
  };

  const handleRedo = () => {
      if (historyIndex < history.length - 1) {
          const nextState = history[historyIndex + 1];
          setTracks(nextState.tracks);
          setClips(nextState.clips);
          setHistoryIndex(historyIndex - 1);
          nextState.tracks.forEach(t => {
               audioService.updateTrackVolume(t.id, t.volume);
               audioService.updateTrackPlugins(t.id, t.plugins);
          });
          audioService.applyRealtimeSoloMute(nextState.tracks);
          if (playbackState.isPlaying) handleStop();
      }
  };

  const updateStateWithHistory = (newTracks: Track[], newClips: AudioClip[]) => {
      setTracks(newTracks);
      setClips(newClips);
      pushHistory(newTracks, newClips);
  };

  // --- Playback Logic ---

  const startPlayback = useCallback((startAt: number) => {
    audioService.stopPlayback(); 
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    audioService.play(clips, tracks, startAt);

    // Schedule metronome if enabled
    if (isMetronomeOn) {
        audioService.scheduleMetronome(bpm, audioService.getContext().currentTime, 300); // Schedule 5 mins of clicks
    }

    startTimeRef.current = audioService.getContext().currentTime;
    setPlaybackState(prev => ({ ...prev, isPlaying: true, currentTime: startAt }));

    const animate = () => {
      const now = audioService.getContext().currentTime;
      const elapsed = now - startTimeRef.current;
      const newTime = startAt + elapsed;

      // Loop Check using REF to avoid closure staleness
      if (loopRegionRef.current.enabled && newTime >= loopRegionRef.current.end) {
          startPlayback(loopRegionRef.current.start);
          return; 
      }

      setPlaybackState(prev => ({ ...prev, currentTime: newTime }));
      rafRef.current = requestAnimationFrame(animate);
    };

    rafRef.current = requestAnimationFrame(animate);
  }, [clips, tracks, bpm, isMetronomeOn]); 

  const handleSeek = useCallback((time: number) => {
      pauseTimeRef.current = time;
      setPlaybackState(prev => ({ ...prev, currentTime: time }));

      // If playing, we need to restart playback at new position
      if (playbackState.isPlaying) {
           startPlayback(time);
      }
  }, [playbackState.isPlaying, startPlayback]);

  const handlePlay = useCallback(async () => {
    await audioService.resume();
    startPlayback(pauseTimeRef.current);
  }, [startPlayback]);

  const handleStop = useCallback(async () => {
    audioService.stop();
    if (rafRef.current) cancelAnimationFrame(rafRef.current);

    if (isRecording) {
       await finishRecording();
    }

    setPlaybackState(prev => {
        pauseTimeRef.current = prev.currentTime; 
        return { ...prev, isPlaying: false };
    });
  }, [isRecording]);

  const handleRewind = () => {
      const newTime = Math.max(0, playbackState.currentTime - 5);
      handleSeek(newTime);
  };

  const handleFastForward = () => {
      const newTime = playbackState.currentTime + 5;
      handleSeek(newTime);
  };

  // --- Recording Logic ---
  const handleArmTrack = async (trackId: string) => {
      if (armedTrackId === trackId) {
          setArmedTrackId(null);
          audioService.disableMonitoring();
      } else {
          try {
              // Critical: Await monitoring setup BEFORE updating state to ensure visualizer is ready
              await audioService.enableMonitoring(trackId); 
              setArmedTrackId(trackId);
          } catch(e) {
              alert("Could not access microphone.");
              setArmedTrackId(null);
          }
      }
  };

  const handleTransportRecord = async () => {
      if (isRecording) {
          handleStop();
      } else {
          if (!armedTrackId) {
              alert("Please arm a track first.");
              return;
          }
          try {
            await audioService.resume();

            // 1. Start Recording Physically FIRST to capture pre-roll/setup
            await audioService.startRecording();
            const sysRecordStart = audioService.getContext().currentTime;

            // 2. Count-In Logic (if enabled)
            if (countInMeasures > 0) {
                 await audioService.playCountIn(bpm, countInMeasures);
            } else {
                 // Even without count-in, wait a tiny bit to ensure we capture the transient of the first beat
                 await new Promise(r => setTimeout(r, 100));
            }

            // 3. Start Playback Transport
            const sysPlaybackStart = audioService.getContext().currentTime;

            // Calculate how much audio we captured before the transport actually started
            const preRollDuration = sysPlaybackStart - sysRecordStart;

            setIsRecording(true);
            recordStartTimeRef.current = pauseTimeRef.current;
            recordPreRollRef.current = preRollDuration;

            startPlayback(pauseTimeRef.current);
          } catch(e) {
              console.error("Recording failed to start", e);
              alert("Failed to start recording. Please check microphone permissions.");
          }
      }
  };

  const finishRecording = async () => {
      if (!armedTrackId) {
          setIsRecording(false);
          return;
      }
      const blob = await audioService.stopRecording();
      const timelineStart = recordStartTimeRef.current;
      const preRoll = recordPreRollRef.current;

      if (blob && blob.size > 0) {
          try {
              const buffer = await audioService.decodeBlob(blob);

              // --- Latency Compensation & Placement ---
              const latency = audioService.latencySeconds;

              // The buffer contains [PreRoll] + [Performance].
              // The Performance started at buffer time = preRoll + latency (approx).
              // We want this point to align with `timelineStart`.

              // Theoretical Offset into buffer for T=timelineStart
              let targetOffset = preRoll + latency;

              // Safety: Reveal a bit of the pre-roll to catch early transients (rushing).
              // We shift the clip START TIME back by `safetyMargin` and reduce OFFSET by same amount.
              const safetyMargin = Math.min(preRoll, 0.2); // Up to 200ms

              const finalClipStart = timelineStart - safetyMargin;
              const finalClipOffset = targetOffset - safetyMargin;

              // Duration needs to be calculated based on what's left in the buffer
              // Buffer Duration - Offset = Playable Length
              // But we added safetyMargin to length by reducing offset.
              const finalDuration = Math.max(0, buffer.duration - finalClipOffset);

              const newClip: AudioClip = {
                  id: uuidv4(),
                  trackId: armedTrackId,
                  buffer: buffer,
                  name: 'Recording',
                  startTime: finalClipStart, // Can be negative or < timelineStart
                  duration: finalDuration,
                  offset: Math.max(0, finalClipOffset),
                  gain: 1,
                  pan: 0,
                  playbackRate: 1,
                  loop: false
              };

              if (finalDuration > 0) {
                  updateStateWithHistory(tracks, [...clips, newClip]);
              }
          } catch (e) {
              console.error("Failed to process recording", e);
          }
      }
      setIsRecording(false);
  };

  // --- Track Management ---
  const addTrack = () => {
    const newTrack: Track = {
      id: `track-${Date.now()}`,
      name: `Track ${tracks.length}`, 
      color: TRACK_COLORS[(tracks.length - 1) % TRACK_COLORS.length],
      volume: 0.8,
      muted: false,
      soloed: false,
      plugins: [],
      automation: { volume: [] },
      showAutomation: false,
      selectedAutomationId: 'volume'
    };

    const newTracks = [...tracks];
    const master = newTracks.pop();
    newTracks.push(newTrack);
    if (master) newTracks.push(master);

    audioService.createTrackNodes(newTrack.id);
    updateStateWithHistory(newTracks, clips);
  };

  const updateTrack = (id: string, updates: Partial<Track>) => {
    const newTracks = tracks.map(t => {
        if (t.id === id) {
            if (updates.volume !== undefined) audioService.updateTrackVolume(id, updates.volume);
            if (updates.plugins !== undefined) audioService.updateTrackPlugins(id, updates.plugins);
            return { ...t, ...updates };
        }
        return t;
    });
    setTracks(newTracks);
    if (updates.muted !== undefined || updates.soloed !== undefined) {
        audioService.applyRealtimeSoloMute(newTracks);
    }
  };

  const toggleAutomation = (trackId: string) => {
      const newTracks = tracks.map(t => t.id === trackId ? { ...t, showAutomation: !t.showAutomation } : t);
      setTracks(newTracks);
  };

  const handleAddAutomationPoint = (trackId: string, paramId: string, point: AutomationPoint) => {
      const newTracks = tracks.map(t => {
          if (t.id === trackId) {
             const points = t.automation?.[paramId] ? [...t.automation[paramId]] : [];
             const existingIdx = points.findIndex(p => Math.abs(p.time - point.time) < 0.1);
             if (existingIdx >= 0) points[existingIdx] = point;
             else points.push(point);
             return { ...t, automation: { ...t.automation, [paramId]: points } };
          }
          return t;
      });
      updateStateWithHistory(newTracks, clips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime);
  };

  const deleteTrack = (id: string) => {
    if (id === 'master') return;
    audioService.removeTrackNodes(id);
    const newTracks = tracks.filter(t => t.id !== id);
    const newClips = clips.filter(c => c.trackId !== id);
    if (editingTrackId === id) setEditingTrackId(null);
    updateStateWithHistory(newTracks, newClips);
  };

  // --- Clip Management ---
  const handleFileDrop = async (file: File, trackId: string, time: number) => {
    if (trackId === 'master') return;
    try {
      const buffer = await audioService.loadFile(file);
      const newClip: AudioClip = {
        id: uuidv4(),
        trackId,
        buffer,
        name: file.name,
        startTime: time,
        duration: buffer.duration,
        offset: 0,
        gain: 1,
        pan: 0,
        playbackRate: 1,
        loop: false
      };
      updateStateWithHistory(tracks, [...clips, newClip]);
    } catch (e) {
      console.error("Failed to load audio", e);
      alert("Could not load audio file.");
    }
  };

  // Batch Update for moving multiple clips
  const updateClips = (updates: { id: string, startTime: number, trackId?: string }[]) => {
      const newClips = clips.map(c => {
          const update = updates.find(u => u.id === c.id);
          if (update) {
              // Prevent moving to master track
              if (update.trackId === 'master') return c;
              return { ...c, startTime: update.startTime, trackId: update.trackId || c.trackId };
          }
          return c;
      });
      setClips(newClips);
  };

  const updateClipProps = (id: string, updates: Partial<AudioClip>) => {
      const newClips = clips.map(c => c.id === id ? { ...c, ...updates } : c);
      setClips(newClips);
      if (playbackState.isPlaying) startPlayback(playbackState.currentTime); 
  };

  const handleClipResize = (clipId: string, newDuration: number) => {
      const newClips = clips.map(c => c.id === clipId ? { ...c, duration: newDuration } : c);
      setClips(newClips);
  };

  // --- Batch Operations (Delete, Duplicate, Copy, Paste) ---

  const deleteClips = (ids: string[]) => {
      const newClips = clips.filter(c => !ids.includes(c.id));
      setSelectedClipIds([]);
      updateStateWithHistory(tracks, newClips);
  };

  const duplicateClips = (ids: string[]) => {
      const clipsToDuplicate = clips.filter(c => ids.includes(c.id));
      if (clipsToDuplicate.length === 0) return;

      const newClips = [...clips];
      const newIds: string[] = [];

      clipsToDuplicate.forEach(original => {
          const newId = uuidv4();
          newIds.push(newId);
          newClips.push({
              ...original,
              id: newId,
              // Per user request: Place immediately after original
              startTime: original.startTime + original.duration, 
              name: `${original.name} (Copy)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleFlattenClip = async (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (!clip) return;

      try {
          const newBuffer = await audioService.bounceClip(clip);
          const newClip: AudioClip = {
              ...clip,
              buffer: newBuffer,
              offset: 0,
              duration: clip.duration, 
              playbackRate: 1, 
              name: `${clip.name} (Flattened)`,
              loop: false 
          };

          const newClips = clips.map(c => c.id === id ? newClip : c);
          updateStateWithHistory(tracks, newClips);
          // Keep selection
          if (selectedClipIds.includes(id)) {
              // no-op, still selected
          }
      } catch (e) {
          console.error("Flatten failed", e);
          alert("Could not flatten clip.");
      }
  };

  const renameClip = (id: string, newName: string) => {
      const newClips = clips.map(c => c.id === id ? { ...c, name: newName } : c);
      updateStateWithHistory(tracks, newClips);
  };

  const handleSplitClip = (clipId: string, splitTime: number) => {
      const clip = clips.find(c => c.id === clipId);
      if (!clip) return;
      const relativeSplit = splitTime - clip.startTime;
      if (relativeSplit <= 0 || relativeSplit >= (clip.duration / clip.playbackRate)) return;

      const firstDuration = relativeSplit * clip.playbackRate;
      const leftClip: AudioClip = { ...clip, id: uuidv4(), duration: firstDuration, name: clip.name };
      const rightClip: AudioClip = { ...clip, id: uuidv4(), startTime: splitTime, offset: clip.offset + firstDuration, duration: clip.duration - firstDuration, name: clip.name };

      const newClips = clips.filter(c => c.id !== clipId);
      newClips.push(leftClip, rightClip);

      // Update selection to the new clips if original was selected
      if (selectedClipIds.includes(clipId)) {
          setSelectedClipIds([leftClip.id, rightClip.id]);
      }

      updateStateWithHistory(tracks, newClips);
  };

  const handleCopyClips = (ids: string[]) => {
      const selected = clips.filter(c => ids.includes(c.id));
      if (selected.length > 0) setClipboardClips(selected);
  };

  const handlePasteClips = (time: number, targetTrackId: string) => {
      if (clipboardClips.length === 0 || targetTrackId === 'master') return;

      // Calculate relative offsets based on the earliest clip in clipboard
      const minStartTime = Math.min(...clipboardClips.map(c => c.startTime));

      const newClips = [...clips];
      const newIds: string[] = [];

      clipboardClips.forEach(clip => {
          const relativeTime = clip.startTime - minStartTime;
          const newId = uuidv4();
          newIds.push(newId);

          newClips.push({
              ...clip,
              id: newId,
              startTime: time + relativeTime,
              trackId: targetTrackId, // Collapse to the track where user right-clicked for now
              name: `${clip.name} (Paste)`
          });
      });

      updateStateWithHistory(tracks, newClips);
      setSelectedClipIds(newIds);
  };

  const handleLoopToggle = (id: string) => {
      const clip = clips.find(c => c.id === id);
      if (clip) {
          const isLooping = !clip.loop;
          const baseDuration = clip.buffer.duration / clip.playbackRate;
          const newDuration = isLooping ? clip.duration + baseDuration : clip.duration;
          const newClips = clips.map(c => c.id === id ? { ...c, loop: isLooping, duration: newDuration } : c);
          updateStateWithHistory(tracks, newClips);
      }
  };

  // --- Export ---
  const handleExport = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          const blob = await audioService.renderOffline(clips, tracks);
          const url = URL.createObjectURL(blob);
          const a = document.createElement('a');
          a.href = url;
          a.download = `Project_${new Date().getTime()}.wav`;
          a.click();
          URL.revokeObjectURL(url);
      } catch (e) {
          console.error("Export failed", e);
          alert("Export failed. See console.");
      } finally {
          setIsExporting(false);
      }
  };

  const handleExportStems = async () => {
      setIsExporting(true);
      if (playbackState.isPlaying) handleStop();
      try {
          for (const track of tracks) {
             if (track.isMaster) continue;
             const trackClips = clips.filter(c => c.trackId === track.id);
             if (trackClips.length === 0) continue;

             const blob = await audioService.renderOffline(trackClips, [track, MASTER_TRACK]);

             const url = URL.createObjectURL(blob);
             const a = document.createElement('a');
             a.href = url;
             a.download = `${track.name}_Stem.wav`;
             a.click();
             URL.revokeObjectURL(url);

             await new Promise(r => setTimeout(r, 500));
          }
      } catch (e) {
          console.error("Stem Export failed", e);
          alert("Stem Export failed.");
      } finally {
          setIsExporting(false);
          setIsSettingsOpen(false);
      }
  };

  // --- Derived State & Variables ---
  const regularTracks = tracks.filter(t => !t.isMaster);
  const masterTrack = tracks.find(t => t.isMaster) || MASTER_TRACK;

  // Only show editor if exactly one clip is selected
  const selectedClip = selectedClipIds.length === 1 
      ? clips.find(c => c.id === selectedClipIds[0]) || null
      : null;

  const editingTrack = tracks.find(t => t.id === editingTrackId) || null;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration));
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const pixelsPerBar = secondsPerBar * zoom;
  const timelineWidth = totalBars * pixelsPerBar;

  return (
    <div className="flex flex-col h-screen overflow-hidden bg-gray-950 text-white font-sans selection:bg-purple-500/30">
      <SettingsModal 
          isOpen={isSettingsOpen} 
          onClose={() => setIsSettingsOpen(false)}
          onExportStems={handleExportStems}
      />

      <Transport 
        isPlaying={playbackState.isPlaying}
        onPlay={handlePlay}
        onStop={handleStop}
        onRewind={handleRewind}
        onFastForward={handleFastForward}
        isRecording={isRecording}
        onRecord={handleTransportRecord}
        currentTime={playbackState.currentTime}
        bpm={bpm}
        setBpm={(newBpm) => {
            setBpm(newBpm);
        }}
        tool={tool}
        setTool={setTool}
        zoom={zoom}
        setZoom={handleZoomChange}
        snap={snap}
        setSnap={setSnap}
        onUndo={handleUndo}
        onRedo={handleRedo}
        canUndo={historyIndex > 0}
        canRedo={historyIndex < history.length - 1}
        onExport={handleExport}
        isExporting={isExporting}
        loopRegion={loopRegion}
        setLoopRegion={setLoopRegion}
        isMetronomeOn={isMetronomeOn}
        toggleMetronome={() => setIsMetronomeOn(!isMetronomeOn)}
        countInMeasures={countInMeasures}
        setCountInMeasures={setCountInMeasures}
        onOpenSettings={() => setIsSettingsOpen(true)}
      />

      {/* Main Workspace: Single Unified Scroll Container */}
      <div 
        className="flex-1 overflow-auto relative" 
        ref={scrollContainerRef}
        onScroll={handleMainScroll}
      >
        <div className="flex min-w-max">
            {/* Sticky Left Column (Headers) */}
            <div 
                className="sticky left-0 z-30 bg-gray-900 border-r border-gray-700 flex flex-col flex-shrink-0 shadow-lg"
                style={{ width: TRACK_HEADER_WIDTH }}
            >
                 {/* Sticky Top-Left Corner */}
                 <div 
                    className="sticky top-0 z-40 bg-gray-900 border-b border-gray-700 flex-shrink-0"
                    style={{ height: TIMELINE_RULER_HEIGHT }}
                 />

                 {/* Track Headers List */}
                 {regularTracks.map(track => (
                    <TrackControl 
                        key={track.id} 
                        track={track} 
                        onUpdate={updateTrack}
                        onDelete={deleteTrack}
                        isArmed={armedTrackId === track.id}
                        isRecordingGlobal={isRecording}
                        onArmToggle={() => handleArmTrack(track.id)}
                        onOpenEditor={setEditingTrackId}
                        onToggleAutomation={toggleAutomation}
                    />
                 ))}

                 <div className="p-3">
                     <button 
                        onClick={addTrack}
                        className="w-full py-3 border border-dashed border-gray-700 rounded-lg text-gray-500 hover:text-white hover:border-gray-500 hover:bg-gray-800 flex items-center justify-center gap-2 text-sm transition-all group"
                        title="Add a new audio track"
                     >
                        <div className="p-1 rounded bg-gray-800 group-hover:bg-gray-700 transition-colors"><Plus size={14} /></div>
                        <span>Add Track</span>
                     </button>
                 </div>

                 {/* Bottom Spacer */}
                 <div className="h-64 bg-gray-900" />
            </div>

            {/* Main Timeline Area (Scrolls with parent) */}
            <div className="flex flex-col flex-1">
                {/* Timeline Component - renders Ruler (sticky inside) and Tracks */}
                <Timeline 
                    tracks={regularTracks}
                    clips={clips}
                    currentTime={playbackState.currentTime}
                    onClipsUpdate={updateClips} // Batch update
                    onFileDrop={handleFileDrop}
                    setClips={setClips}
                    onSeek={handleSeek}
                    bpm={bpm}
                    zoom={zoom}
                    setZoom={handleZoomChange}
                    snap={snap}
                    tool={tool}

                    selectedClipIds={selectedClipIds}
                    setSelectedClipIds={setSelectedClipIds}

                    onDeleteClips={deleteClips}
                    onDuplicateClips={duplicateClips}
                    onCopyClips={handleCopyClips}
                    onPasteClips={handlePasteClips}
                    canPaste={clipboardClips.length > 0}

                    onRenameClip={renameClip}
                    onSplitClip={handleSplitClip}
                    onAddAutomationPoint={handleAddAutomationPoint}
                    onClipResize={handleClipResize}
                    onLoopClip={handleLoopToggle}
                    onFlattenClip={handleFlattenClip}

                    loopRegion={loopRegion}
                    setLoopRegion={setLoopRegion}
                    onImportAudio={handleFileDrop}
                    markers={timeMarkers}
                    onAddMarker={(time, label, type, value) => setTimeMarkers([...timeMarkers, {time, label, type, value}])}
                    setBpm={setBpm}
                />
            </div>
        </div>
      </div>

      {/* Fixed Bottom Master Section */}
      <div className="h-44 bg-gray-900 border-t-2 border-gray-800 flex flex-col z-50 shadow-[0_-5px_15px_rgba(0,0,0,0.5)]">
         {/* Master Row */}
         <div className="flex flex-1 overflow-hidden">
             {/* Master Control (Left) */}
             <div className="flex-shrink-0 border-r border-gray-800" style={{ width: TRACK_HEADER_WIDTH }}>
                <TrackControl 
                  track={masterTrack}
                  onUpdate={updateTrack}
                  onDelete={() => {}}
                  isArmed={false}
                  isRecordingGlobal={false}
                  onArmToggle={() => {}}
                  onOpenEditor={setEditingTrackId}
                  onToggleAutomation={() => {}}
                />
             </div>
             {/* Master Visualizer (Right) */}
             <div className="flex-1 p-2 bg-gray-900 flex items-center justify-center">
                 <MasterVisualizer isPlaying={playbackState.isPlaying} />
             </div>
         </div>

         {/* Navigator / Scrollbar (Bottom Fixed) */}
         <div className="h-5 bg-gray-950 border-t border-gray-800">
             <div 
                ref={navigatorRef}
                onScroll={handleNavigatorScroll}
                className="w-full h-full overflow-x-auto overflow-y-hidden custom-scrollbar"
                title="Timeline Navigator"
             >
                <div style={{ width: timelineWidth + TRACK_HEADER_WIDTH, height: '1px' }}></div>
             </div>
         </div>
      </div>

      {/* Editors */}
      {editingTrack ? (
          <TrackEditor 
            track={editingTrack} 
            onUpdate={updateTrack} 
            onClose={() => setEditingTrackId(null)} 
          />
      ) : (
          <ClipEditor 
            clip={selectedClip} 
            onUpdate={updateClipProps} 
            onClose={() => setSelectedClipIds([])}
            projectBpm={bpm}
          />
      )}
    </div>
  );
}

export default App;

import React, { useRef, useState, useMemo, useEffect } from 'react';
import { Track, AudioClip, ToolType, AutomationPoint, LoopRegion } from '../types';
import { Waveform } from './Waveform';
import { Trash2, Copy, Pencil, RotateCw, ClipboardPaste, GripVertical, Upload, FileStack, Flag, X, Check } from 'lucide-react';
import { v4 as uuidv4 } from 'uuid';
import { TRACK_HEIGHT, AUTOMATION_HEIGHT, TIMELINE_RULER_HEIGHT } from '../constants';

interface TimelineProps {
  tracks: Track[];
  clips: AudioClip[];
  currentTime: number;
  bpm: number;
  zoom: number; // pixels per second
  snap: boolean;
  tool: ToolType;

  onClipsUpdate: (updates: { id: string, startTime: number, trackId?: string }[]) => void;
  onFileDrop: (file: File, trackId: string, time: number) => void;
  setClips: React.Dispatch<React.SetStateAction<AudioClip[]>>;
  onSeek: (time: number) => void;

  // Selection & Batch Ops
  selectedClipIds: string[];
  setSelectedClipIds: (ids: string[]) => void;
  onDeleteClips: (ids: string[]) => void;
  onDuplicateClips: (ids: string[]) => void;
  onCopyClips: (ids: string[]) => void;
  onPasteClips: (time: number, trackId: string) => void;
  canPaste: boolean;

  onRenameClip: (id: string, newName: string) => void;
  onLoopClip: (id: string) => void;

  onSplitClip: (clipId: string, splitTime: number) => void;
  onAddAutomationPoint: (trackId: string, paramId: string, point: AutomationPoint) => void;
  onClipResize: (clipId: string, newDuration: number) => void;

  setZoom?: (z: number) => void;

  loopRegion: LoopRegion;
  setLoopRegion: (region: LoopRegion) => void;

  onImportAudio: (file: File, trackId: string, time: number) => void;

  markers?: {time: number, label: string}[];
  onAddMarker?: (time: number, label: string) => void;
  setBpm?: (bpm: number) => void;

  onFlattenClip?: (id: string) => void;
  onClipDoubleClick?: (clipId: string) => void;
}

interface ContextMenuState {
    x: number;
    y: number;
    type: 'CLIP' | 'BACKGROUND' | 'RULER';
    targetId?: string; // ClipId or TrackId
    time?: number; 
}

interface MarqueeState {
    startX: number;
    startY: number;
    currentX: number;
    currentY: number;
    active: boolean;
}

interface MarkerModalState {
    isOpen: boolean;
    time: number;
}

export const Timeline: React.FC<TimelineProps> = ({ 
  tracks, 
  clips, 
  currentTime, 
  bpm,
  zoom,
  setZoom,
  snap,
  tool,
  onClipsUpdate, 
  onFileDrop,
  onSeek,
  selectedClipIds,
  setSelectedClipIds,
  onDeleteClips,
  onDuplicateClips,
  onCopyClips,
  onPasteClips,
  canPaste,
  onRenameClip,
  onLoopClip,
  onSplitClip,
  onAddAutomationPoint,
  onClipResize,
  loopRegion,
  setLoopRegion,
  onImportAudio,
  markers = [],
  onAddMarker,
  setBpm,
  onFlattenClip,
  onClipDoubleClick
}) => {
  const [draggedClipId, setDraggedClipId] = useState<string | null>(null);
  const [resizingClipId, setResizingClipId] = useState<string | null>(null);
  // Keep track of the initial offset for ALL selected clips during a drag
  const [dragOffsets, setDragOffsets] = useState<{ [id: string]: number }>({});

  const [resizeStartX, setResizeStartX] = useState<number>(0);
  const [resizeStartDuration, setResizeStartDuration] = useState<number>(0);

  // Marquee State
  const [marquee, setMarquee] = useState<MarqueeState | null>(null);
  const justFinishedMarqueeRef = useRef(false);

  // Loop Dragging State
  const [loopDragType, setLoopDragType] = useState<'START' | 'END' | 'MOVE' | null>(null);
  const [loopDragStartX, setLoopDragStartX] = useState<number>(0);
  const [loopDragStartValues, setLoopDragStartValues] = useState<{start: number, end: number}>({start:0, end:0});

  const [contextMenu, setContextMenu] = useState<ContextMenuState | null>(null);
  const [markerModal, setMarkerModal] = useState<MarkerModalState | null>(null);
  const [markerInputValue, setMarkerInputValue] = useState("");

  const timelineRef = useRef<HTMLDivElement>(null);

  // Refs for File Import
  const fileInputRef = useRef<HTMLInputElement>(null);
  const importTargetRef = useRef<{trackId: string, time: number} | null>(null);

  // --- Grid & Ruler Math ---
  const secondsPerBeat = 60 / bpm;
  const secondsPerBar = secondsPerBeat * 4; 
  const pixelsPerBar = secondsPerBar * zoom;
  const pixelsPerBeat = secondsPerBeat * zoom;

  const totalDuration = Math.max(300, ...clips.map(c => c.startTime + c.duration)); 
  const totalBars = Math.ceil(totalDuration / secondsPerBar) + 5;
  const barsArray = useMemo(() => Array.from({ length: totalBars }), [totalBars, zoom, bpm]);

  const snapToGrid = (time: number): number => {
      if (!snap) return time;
      const beat = 60 / bpm;
      return Math.round(time / beat) * beat;
  };

  useEffect(() => {
      const closeMenu = () => setContextMenu(null);
      const handleGlobalMouseUp = () => {
           if (draggedClipId) {
               setDraggedClipId(null);
               setDragOffsets({});
           }
           if (resizingClipId) setResizingClipId(null);
           if (loopDragType) setLoopDragType(null);
           if (marquee?.active) {
               setMarquee(null);
               // Set a flag to prevent the subsequent 'click' event from clearing selection
               justFinishedMarqueeRef.current = true;
               setTimeout(() => { justFinishedMarqueeRef.current = false; }, 100);
           }
      };

      window.addEventListener('click', closeMenu);
      window.addEventListener('mouseup', handleGlobalMouseUp);

      return () => {
          window.removeEventListener('click', closeMenu);
          window.removeEventListener('mouseup', handleGlobalMouseUp);
      };
  }, [draggedClipId, resizingClipId, loopDragType, marquee]);

  // Global Mouse Move
  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          if (!timelineRef.current) return;
          const rect = timelineRef.current.getBoundingClientRect();
          const relativeX = e.clientX - rect.left + timelineRef.current.scrollLeft;
          const relativeY = e.clientY - rect.top + timelineRef.current.scrollTop;

          if (marquee?.active) {
              setMarquee(prev => prev ? { ...prev, currentX: relativeX, currentY: relativeY } : null);

              const mX = Math.min(marquee.startX, relativeX);
              const mY = Math.min(marquee.startY, relativeY);
              const mW = Math.abs(relativeX - marquee.startX);
              const mH = Math.abs(relativeY - marquee.startY);

              const newSelectedIds: string[] = [];
              const clipElements = timelineRef.current.querySelectorAll('[data-clip-id]');

              clipElements.forEach(el => {
                  const clipRect = el.getBoundingClientRect();
                  const clipRelX = clipRect.left - rect.left + timelineRef.current!.scrollLeft;
                  const clipRelY = clipRect.top - rect.top + timelineRef.current!.scrollTop;

                  if (mX < clipRelX + clipRect.width &&
                      mX + mW > clipRelX &&
                      mY < clipRelY + clipRect.height &&
                      mY + mH > clipRelY) {
                          const id = el.getAttribute('data-clip-id');
                          if (id) newSelectedIds.push(id);
                      }
              });

              setSelectedClipIds(newSelectedIds);
              return;
          }

          if (loopDragType) {
              const diffPixels = e.clientX - loopDragStartX;
              const diffSeconds = diffPixels / zoom;

              let newStart = loopDragStartValues.start;
              let newEnd = loopDragStartValues.end;

              if (loopDragType === 'START') {
                  newStart = Math.min(newEnd - 0.25, Math.max(0, loopDragStartValues.start + diffSeconds));
              } else if (loopDragType === 'END') {
                  newEnd = Math.max(newStart + 0.25, loopDragStartValues.end + diffSeconds);
              } else if (loopDragType === 'MOVE') {
                  const duration = loopDragStartValues.end - loopDragStartValues.start;
                  newStart = Math.max(0, loopDragStartValues.start + diffSeconds);
                  newEnd = newStart + duration;
              }

              if (snap) {
                  newStart = snapToGrid(newStart);
                  newEnd = snapToGrid(newEnd);
                  if (newEnd <= newStart) newEnd = newStart + secondsPerBeat;
              }

              setLoopRegion({ ...loopRegion, start: newStart, end: newEnd });
              return;
          }

          if (resizingClipId) {
             const diffPixels = e.clientX - resizeStartX;
             const diffSeconds = diffPixels / zoom;
             const newDuration = Math.max(0.1, resizeStartDuration + diffSeconds); 
             const snappedDuration = snap ? snapToGrid(newDuration) : newDuration;
             onClipResize(resizingClipId, snappedDuration);
             return;
          }
      };

      if (resizingClipId || loopDragType || marquee?.active) {
          window.addEventListener('mousemove', handleMouseMove);
      }
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, [resizingClipId, resizeStartX, resizeStartDuration, zoom, snap, onClipResize, loopDragType, loopDragStartX, loopDragStartValues, loopRegion, setLoopRegion, bpm, marquee]);

  // Wheel Zoom
  useEffect(() => {
      const container = timelineRef.current;
      if (!container || !setZoom) return;

      const handleWheel = (e: WheelEvent) => {
          if (e.ctrlKey || e.metaKey) {
              e.preventDefault();
              const delta = -e.deltaY;
              const zoomFactor = delta > 0 ? 1.1 : 0.9;
              let newZoom = zoom * zoomFactor;
              newZoom = Math.max(10, Math.min(500, newZoom));
              setZoom(newZoom);
          }
      };

      container.addEventListener('wheel', handleWheel, { passive: false });
      return () => container.removeEventListener('wheel', handleWheel);
  }, [zoom, setZoom]);

  const handleRulerClick = (e: React.MouseEvent) => {
      if (e.button === 2) return;
      if ((e.target as HTMLElement).closest('.loop-region-handle')) return;

      const rect = timelineRef.current?.getBoundingClientRect();
      if (!rect) return;

      const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
      const seekTime = Math.max(0, (clickX / zoom));

      onSeek(snapToGrid(seekTime));
  };

  const handleTimelineClick = (e: React.MouseEvent) => {
    if (draggedClipId || resizingClipId || loopDragType) return;

    if (justFinishedMarqueeRef.current) {
        justFinishedMarqueeRef.current = false;
        return;
    }

    const target = e.target as HTMLElement;
    if (target.closest('.loop-region-handle')) return;
    if (target.closest('.ruler-track')) return; 

    const clipElement = target.closest('[data-clip-id]');

    const automationLane = target.closest('[data-automation-track-id]');
    if (automationLane) {
        const trackId = automationLane.getAttribute('data-automation-track-id');
        const track = tracks.find(t => t.id === trackId);

        if (track && trackId) {
             const rect = timelineRef.current?.getBoundingClientRect();
             if (rect) {
                 const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
                 const time = Math.max(0, clickX / zoom);

                 const laneRect = automationLane.getBoundingClientRect();
                 const clickY = e.clientY - laneRect.top;
                 const value = 1 - Math.max(0, Math.min(1, clickY / laneRect.height));
                 const paramId = track.selectedAutomationId || 'volume';

                 onAddAutomationPoint(trackId, paramId, {
                     id: uuidv4(),
                     time: time,
                     value: value
                 });
                 return; 
             }
        }
    }

    if (clipElement && tool === 'BLADE') {
         const clipId = clipElement.getAttribute('data-clip-id');
         const rect = timelineRef.current?.getBoundingClientRect();
         if (clipId && rect) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const clickTime = clickX / zoom;
             onSplitClip(clipId, clickTime);
             return;
         }
    }

    if (!clipElement && !automationLane && !target.classList.contains('resize-handle')) {
        const rect = timelineRef.current?.getBoundingClientRect();
        if (!rect) return;

        if (!marquee?.active) {
             const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
             const seekTime = Math.max(0, (clickX / zoom));
             onSeek(snapToGrid(seekTime));
             setSelectedClipIds([]); 
        }
    }
  };

  const handleMouseDown = (e: React.MouseEvent) => {
      const target = e.target as HTMLElement;
      if (!target.closest('[data-clip-id]') && !target.closest('.loop-region-handle') && !target.closest('[data-automation-track-id]') && !target.closest('.ruler-track')) {
          if (tool === 'MOVE') {
              const rect = timelineRef.current!.getBoundingClientRect();
              const x = e.clientX - rect.left + timelineRef.current!.scrollLeft;
              const y = e.clientY - rect.top + timelineRef.current!.scrollTop;

              setMarquee({
                  startX: x,
                  startY: y,
                  currentX: x,
                  currentY: y,
                  active: true
              });
          }
      }
  };

  const handleDrop = (e: React.DragEvent, trackId: string) => {
    e.preventDefault();
    const rect = timelineRef.current?.getBoundingClientRect();
    if (!rect) return;

    const clickX = e.clientX - rect.left + timelineRef.current!.scrollLeft;
    const rawTime = Math.max(0, (clickX / zoom));
    const dropTime = snapToGrid(rawTime);

    if (e.dataTransfer.files.length > 0) {
      const files = Array.from(e.dataTransfer.files) as File[];
      files.forEach(file => {
        const isAudio = file.type.startsWith('audio/') || 
                        file.type === 'video/mp4' || 
                        file.name.toLowerCase().endsWith('.m4a');
        if (isAudio) {
          onFileDrop(file, trackId, dropTime);
        }
      });
      return;
    }

    if (draggedClipId) {
        const draggedClip = clips.find(c => c.id === draggedClipId);
        if (!draggedClip) return;

        const movingIds = selectedClipIds.includes(draggedClipId) ? selectedClipIds : [draggedClipId];
        const primaryOffset = dragOffsets[draggedClipId] || 0;
        const newPrimaryTime = Math.max(0, dropTime - primaryOffset);
        const timeDelta = newPrimaryTime - draggedClip.startTime; 

        const updates = movingIds.map(id => {
            const clip = clips.find(c => c.id === id);
            if (!clip) return null;

            return {
                id: clip.id,
                startTime: Math.max(0, clip.startTime + timeDelta),
                trackId: id === draggedClipId ? trackId : clip.trackId 
            };
        }).filter(Boolean) as { id: string, startTime: number, trackId?: string }[];

        onClipsUpdate(updates);
        setDraggedClipId(null);
        setDragOffsets({});
    }
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
  };

  const handleDragStart = (e: React.DragEvent, clip: AudioClip) => {
     if (tool === 'BLADE' || resizingClipId) {
         e.preventDefault(); 
         return;
     }

     let currentSelection = selectedClipIds;
     if (!selectedClipIds.includes(clip.id)) {
         setSelectedClipIds([clip.id]);
         currentSelection = [clip.id];
     }

     const rect = (e.target as HTMLElement).getBoundingClientRect();
     const offsetX = e.clientX - rect.left;
     const offsetTime = offsetX / zoom;

     const offsets: {[id:string]: number} = {};
     currentSelection.forEach(id => {
         offsets[id] = offsetTime; 
     });

     setDragOffsets(offsets);
     setDraggedClipId(clip.id);
     e.dataTransfer.effectAllowed = "move";
  };

  const handleResizeStart = (e: React.MouseEvent, clip: AudioClip) => {
      e.stopPropagation();
      e.preventDefault();
      setResizingClipId(clip.id);
      setResizeStartX(e.clientX);
      setResizeStartDuration(clip.duration);
      if (!selectedClipIds.includes(clip.id)) {
          setSelectedClipIds([clip.id]);
      }
  };

  const handleLoopDragStart = (e: React.MouseEvent, type: 'START' | 'END' | 'MOVE') => {
      e.stopPropagation();
      e.preventDefault();
      setLoopDragType(type);
      setLoopDragStartX(e.clientX);
      setLoopDragStartValues({ start: loopRegion.start, end: loopRegion.end });
  };

  const handleClipContextMenu = (e: React.MouseEvent, clipId: string) => {
      e.preventDefault();
      e.stopPropagation();
      if (!selectedClipIds.includes(clipId)) {
          setSelectedClipIds([clipId]);
      }
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'CLIP',
          targetId: clipId
      });
  };

  const handleTrackContextMenu = (e: React.MouseEvent, trackId: string) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'BACKGROUND',
          targetId: trackId,
          time: snapToGrid(time)
      });
  };

  const handleRulerContextMenu = (e: React.MouseEvent) => {
      e.preventDefault();
      const rect = timelineRef.current?.getBoundingClientRect();
      const clickX = e.clientX - (rect?.left || 0) + timelineRef.current!.scrollLeft;
      const time = Math.max(0, clickX / zoom);
      setContextMenu({
          x: e.pageX,
          y: e.pageY,
          type: 'RULER',
          time: snapToGrid(time)
      });
  };

  const handleMenuAction = (e: React.MouseEvent, action: string) => {
      e.stopPropagation(); 
      if (!contextMenu) return;

      if (contextMenu.type === 'CLIP') {
           const targetIsSelected = contextMenu.targetId && selectedClipIds.includes(contextMenu.targetId);
           const idsToActOn = targetIsSelected ? selectedClipIds : (contextMenu.targetId ? [contextMenu.targetId] : []);

           switch(action) {
              case 'delete': onDeleteClips(idsToActOn); break;
              case 'duplicate': onDuplicateClips(idsToActOn); break;
              case 'rename': 
                  if (idsToActOn.length === 1) {
                      const clip = clips.find(c => c.id === idsToActOn[0]);
                      if (clip) {
                          const newName = prompt("Rename clip:", clip.name);
                          if (newName) onRenameClip(idsToActOn[0], newName);
                      }
                  } else {
                      alert("Can only rename one clip at a time.");
                  }
                  break;
              case 'copy': onCopyClips(idsToActOn); break;
              case 'loop': idsToActOn.forEach(id => onLoopClip(id)); break;
              case 'flatten': 
                  if (idsToActOn.length === 1 && onFlattenClip) onFlattenClip(idsToActOn[0]); 
                  else if (idsToActOn.length > 1) alert("Flattening multiple clips not supported yet.");
                  break;
          }
      } else if (contextMenu.type === 'BACKGROUND' && contextMenu.targetId && contextMenu.time !== undefined) {
           if (action === 'paste') {
               onPasteClips(contextMenu.time, contextMenu.targetId);
           } else if (action === 'import-file') {
               importTargetRef.current = { trackId: contextMenu.targetId, time: contextMenu.time };
               fileInputRef.current?.click();
           }
      } else if (contextMenu.type === 'RULER' && contextMenu.time !== undefined) {
           if (action === 'add-marker') {
                setMarkerModal({ isOpen: true, time: contextMenu.time });
                setMarkerInputValue("Verse 1");
           }
      }
      setContextMenu(null);
  };

  const handleMarkerSubmit = () => {
      if (!markerModal || !onAddMarker) return;
      const { time } = markerModal;

      onAddMarker(time, markerInputValue);

      setMarkerModal(null);
  };

  const handleFileSelect = (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files && e.target.files[0] && importTargetRef.current) {
          const { trackId, time } = importTargetRef.current;
          onImportAudio(e.target.files[0], trackId, time);
      }
      if (fileInputRef.current) {
          fileInputRef.current.value = '';
      }
  };

  const renderAutomationPoints = (track: Track) => {
      const activeParam = track.selectedAutomationId || 'volume';
      const points = track.automation?.[activeParam];
      if (!points || points.length === 0) return null;

      const sortedPoints = [...points].sort((a, b) => a.time - b.time);
      const pathData = sortedPoints.map((p, i) => {
          const x = p.time * zoom;
          const y = (1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8; 
          return `${i === 0 ? 'M' : 'L'} ${x} ${y}`;
      }).join(' ');

      return (
          <>
              <path d={pathData} stroke="#60a5fa" strokeWidth="2" fill="none" />
              {sortedPoints.map(p => (
                  <g key={p.id}>
                    <circle 
                      cx={p.time * zoom} 
                      cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                      r="12" 
                      fill="transparent"
                      className="cursor-pointer"
                    />
                    <circle 
                        cx={p.time * zoom} 
                        cy={(1 - p.value) * (AUTOMATION_HEIGHT - 16) + 8} 
                        r="4" 
                        fill="#3b82f6" 
                        className="pointer-events-none"
                    />
                  </g>
              ))}
          </>
      );
  };

  const renderClipContent = (clip: AudioClip, track: Track) => {
      const singleLoopDuration = clip.buffer.duration / clip.playbackRate;
      const singleLoopWidth = singleLoopDuration * zoom;
      const loops = clip.loop ? Math.ceil(clip.duration / singleLoopDuration) : 1;
      const isMuted = track.muted;

      return (
          <div className={`relative w-full h-full overflow-hidden ${isMuted ? 'opacity-40 grayscale' : ''}`}>
             {Array.from({ length: loops }).map((_, i) => (
                 <div 
                    key={i} 
                    className="absolute top-0 bottom-0 border-r border-dashed border-white/20"
                    style={{ left: i * singleLoopWidth, width: singleLoopWidth }}
                 >
                     <Waveform clip={clip} width={singleLoopWidth} height={TRACK_HEIGHT - 10} color={i === 0 ? "#ffffff" : "#ffffffaa"} />
                 </div>
             ))}
          </div>
      );
  };

  return (
    <>
      <div 
        className={`flex-1 relative flex flex-col select-none ${tool === 'BLADE' ? 'cursor-[url(https://cdn.custom-cursor.com/db/cursor/32/Scissors_Cursor.png),_auto]' : ''}`}
        ref={timelineRef}
        onClick={handleTimelineClick}
        onMouseDown={handleMouseDown}
      >
        <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileSelect}
            className="hidden" 
            accept="audio/*,.m4a,.mp4" 
        />

        {/* Marquee Box */}
        {marquee?.active && (
            <div 
                className="absolute bg-blue-500/20 border border-blue-400 z-50 pointer-events-none"
                style={{
                    left: Math.min(marquee.startX, marquee.currentX),
                    top: Math.min(marquee.startY, marquee.currentY),
                    width: Math.abs(marquee.currentX - marquee.startX),
                    height: Math.abs(marquee.currentY - marquee.startY)
                }}
            />
        )}

        <div 
            className="absolute top-0 bottom-0 w-0.5 bg-red-500 z-30 pointer-events-none"
            style={{ left: `${currentTime * zoom}px`, height: '100%' }}
        >
            <div className="w-3 h-3 -ml-1.5 bg-red-500 transform rotate-45 -mt-1.5" />
        </div>

        {/* Ruler - Now with sticky top-0 to stick inside the App-level scroll container */}
        <div 
          className="border-b border-gray-700 bg-gray-900 sticky top-0 z-20 flex cursor-context-menu ruler-track" 
          style={{ width: `${totalBars * pixelsPerBar}px`, height: `${TIMELINE_RULER_HEIGHT}px` }}
          onContextMenu={handleRulerContextMenu}
          onClick={handleRulerClick}
          title="Left-click to seek. Right-click to add Tempo or Time Signature changes"
        >
             {barsArray.map((_, i) => (
                 <div 
                    key={i} 
                    className="relative h-full border-l border-gray-600/50 pointer-events-none" 
                    style={{ width: `${pixelsPerBar}px` }}
                 >
                     <span className="absolute top-1 left-1 text-[10px] text-gray-500 font-mono select-none">{i + 1}</span>
                     <div className="absolute bottom-0 left-[25%] h-1 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[50%] h-1.5 w-px bg-gray-700" />
                     <div className="absolute bottom-0 left-[75%] h-1 w-px bg-gray-700" />
                 </div>
             ))}

             {/* Markers */}
             {markers.map((m, i) => (
                 <div key={i} className="absolute top-0 h-full border-l border-blue-500 group z-20" style={{ left: m.time * zoom }}>
                     {/* Marker Line */}
                     <div className="absolute top-8 w-px h-[2000px] bg-blue-500/20 pointer-events-none"></div>
                     {/* Marker Label */}
                     <div className="flex items-center bg-blue-600 text-white text-[9px] px-1 rounded-r shadow cursor-pointer hover:bg-blue-500 transition-colors">
                        <Flag size={8} className="mr-1" />
                        {m.label}
                     </div>
                 </div>
             ))}

             {/* Loop Region Overlay */}
             {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 h-full bg-yellow-400/20 border-l border-r border-yellow-400/50 group loop-region-handle cursor-move"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                    onMouseDown={(e) => handleLoopDragStart(e, 'MOVE')}
                    onClick={(e) => e.stopPropagation()}
                 >
                     <div className="absolute top-0 left-0 w-full h-1 bg-yellow-400/50"></div>

                     {/* Handles */}
                     <div 
                        className="absolute top-0 left-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'START')}
                     />
                     <div 
                        className="absolute top-0 right-0 w-2 h-full cursor-ew-resize hover:bg-yellow-400/50 z-10"
                        onMouseDown={(e) => handleLoopDragStart(e, 'END')}
                     />
                 </div>
             )}
        </div>

        <div className="flex flex-col relative" style={{ minWidth: `${totalBars * pixelsPerBar}px` }}>
          {/* Loop Region Background Highlight (Extends down tracks) */}
          {loopRegion.enabled && (
                 <div 
                    className="absolute top-0 bottom-0 bg-white/5 pointer-events-none z-0"
                    style={{ left: loopRegion.start * zoom, width: (loopRegion.end - loopRegion.start) * zoom }}
                 />
          )}

          {tracks.map(track => {
            return (
                <div key={track.id} className="flex flex-col z-10">
                  <div 
                      className="relative border-b border-gray-800 hover:bg-white/5 transition-colors box-border"
                      onDragOver={handleDragOver}
                      onDrop={(e) => handleDrop(e, track.id)}
                      onContextMenu={(e) => handleTrackContextMenu(e, track.id)}
                      style={{ 
                          height: `${TRACK_HEIGHT}px`,
                          backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)',
                          backgroundSize: `${pixelsPerBar}px 100%`,
                          backgroundPosition: '0 0'
                      }}
                  >
                      <div 
                          className="absolute inset-0 pointer-events-none" 
                          style={{ backgroundImage: 'linear-gradient(to right, #374151 1px, transparent 1px)', backgroundSize: `${pixelsPerBeat}px 100%`, opacity: 0.1 }}
                      />

                      {clips.filter(c => c.trackId === track.id).map(clip => {
                          const isSelected = selectedClipIds.includes(clip.id);
                          return (
                          <div
                              key={clip.id}
                              data-clip-id={clip.id}
                              draggable={tool === 'MOVE'}
                              onDragStart={(e) => handleDragStart(e, clip)}
                              onContextMenu={(e) => handleClipContextMenu(e, clip.id)}
                              onClick={(e) => e.stopPropagation()} 
                              onDoubleClick={(e) => { e.stopPropagation(); onClipDoubleClick?.(clip.id); }}
                              onMouseDown={(e) => { if (tool === 'MOVE' && !isSelected && !e.shiftKey) setSelectedClipIds([clip.id]); }}
                              className={`absolute top-2 bottom-2 rounded-md overflow-hidden border shadow-md group transition-all 
                              ${tool === 'MOVE' ? 'cursor-move' : 'cursor-text hover:brightness-110'} 
                              ${isSelected ? 'border-white ring-2 ring-blue-500/50 z-20' : 'border-white/20 bg-gray-800 hover:border-white/40 z-10'}`}
                              style={{ left: `${clip.startTime * zoom}px`, width: `${clip.duration * zoom}px` }}
                          >
                              <div className="absolute inset-0 opacity-60" style={{ backgroundColor: track.muted ? '#4b5563' : track.color }}></div>
                              {clip.loop && <div className="absolute top-0 right-4 p-1 text-white/70 z-30"><RotateCw size={10} /></div>}
                              <div className="absolute inset-0 z-10">{renderClipContent(clip, track)}</div>
                              <div className="absolute top-1 left-1 z-20 max-w-full"><div className="px-1 py-0.5 bg-black/40 rounded text-[10px] text-white truncate select-none font-medium flex items-center gap-1">{clip.name}</div></div>
                              {tool === 'MOVE' && isSelected && selectedClipIds.length === 1 && <div className="absolute top-0 bottom-0 right-0 w-3 cursor-col-resize hover:bg-white/30 z-40 flex items-center justify-center resize-handle group/handle" onMouseDown={(e) => handleResizeStart(e, clip)}><GripVertical size={10} className="text-white/0 group-hover/handle:text-white/80" /></div>}
